INSERT INTO `problem_solution` (`problem_id`,`language`,`code`,`note`,`verified`) VALUES
(1,'C','#include <stdio.h>\n\nint climbStairs(int n) {\n    if (n <= 2) {\n        return n;\n    }\n    int a = 1;\n    int b = 2;\n    for (int i = 3; i <= n; i++) {\n        int c = a + b;\n        a = b;\n        b = c;\n    }\n    return b;\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    printf(\"%d\\n\", climbStairs(n));\n    return 0;\n}',NULL,1),
(1,'CPP','#include <iostream>\nusing namespace std;\n\nint climbStairs(int n) {\n    if (n <= 2) {\n        return n;\n    }\n    int a = 1;\n    int b = 2;\n    for (int i = 3; i <= n; i++) {\n        int c = a + b;\n        a = b;\n        b = c;\n    }\n    return b;\n}\n\nint main() {\n    int n;\n    cin >> n;\n    cout << climbStairs(n) << endl;\n    return 0;\n}',NULL,1),
(1,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        if (n <= 2) {\n            System.out.println(n);\n            return;\n        }\n        int a = 1, b = 2;\n        for (int i = 3; i <= n; i++) {\n            int c = a + b;\n            a = b;\n            b = c;\n        }\n        System.out.println(b);\n    }\n}',NULL,1),
(1,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const n = parseInt(line.trim(), 10);\n    console.log(climbStairs(n));\n    rl.close();\n});\n\nfunction climbStairs(n) {\n    if (n <= 2) {\n        return n;\n    }\n    let a = 1;\n    let b = 2;\n    for (let i = 3; i <= n; i++) {\n        const c = a + b;\n        a = b;\n        b = c;\n    }\n    return b;\n}',NULL,1),
(1,'PYTHON','n = int(input())\nif n <= 2:\n    print(n)\nelse:\n    a, b = 1, 2\n    for i in range(3, n + 1):\n        a, b = b, a + b\n    print(b)',NULL,1),
(2,'C','#include <stdio.h>\n#include <string.h>\n#include <stdlib.h>\n\nint main(void) {\n    char text1[1005];\n    char text2[1005];\n    if (fgets(text1, sizeof(text1), stdin) == NULL) return 0;\n    if (fgets(text2, sizeof(text2), stdin) == NULL) return 0;\n\n    size_t len1 = strlen(text1);\n    size_t len2 = strlen(text2);\n    if (len1 > 0 && text1[len1 - 1] == \'\\n\') text1[--len1] = \'\\0\';\n    if (len2 > 0 && text2[len2 - 1] == \'\\n\') text2[--len2] = \'\\0\';\n\n    int m = (int)len1;\n    int n = (int)len2;\n\n    int *prev = (int *)calloc((size_t)n + 1, sizeof(int));\n    int *cur = (int *)calloc((size_t)n + 1, sizeof(int));\n    if (prev == NULL || cur == NULL) {\n        free(prev);\n        free(cur);\n        return 0;\n    }\n\n    for (int i = 1; i <= m; i++) {\n        for (int j = 1; j <= n; j++) {\n            if (text1[i - 1] == text2[j - 1]) {\n                cur[j] = prev[j - 1] + 1;\n            } else {\n                cur[j] = (prev[j] > cur[j - 1]) ? prev[j] : cur[j - 1];\n            }\n        }\n        int *tmp = prev;\n        prev = cur;\n        cur = tmp;\n        for (int j = 0; j <= n; j++) cur[j] = 0;\n    }\n\n    printf(\"%d\\n\", prev[n]);\n\n    free(prev);\n    free(cur);\n    return 0;\n}',NULL,1),
(2,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\n\nint main() {\n    std::string text1, text2;\n    std::getline(std::cin, text1);\n    std::getline(std::cin, text2);\n    int m = text1.length();\n    int n = text2.length();\n    std::vector<std::vector<int>> dp(m + 1, std::vector<int>(n + 1, 0));\n    for (int i = 1; i <= m; i++) {\n        for (int j = 1; j <= n; j++) {\n            if (text1[i - 1] == text2[j - 1]) {\n                dp[i][j] = dp[i - 1][j - 1] + 1;\n            } else {\n                dp[i][j] = std::max(dp[i - 1][j], dp[i][j - 1]);\n            }\n        }\n    }\n    std::cout << dp[m][n] << std::endl;\n    return 0;\n}',NULL,1),
(2,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        String text1 = scanner.nextLine();\n        String text2 = scanner.nextLine();\n        int m = text1.length();\n        int n = text2.length();\n        int[][] dp = new int[m + 1][n + 1];\n        for (int i = 1; i <= m; i++) {\n            for (int j = 1; j <= n; j++) {\n                if (text1.charAt(i - 1) == text2.charAt(j - 1)) {\n                    dp[i][j] = dp[i - 1][j - 1] + 1;\n                } else {\n                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);\n                }\n            }\n        }\n        System.out.println(dp[m][n]);\n    }\n}',NULL,1),
(2,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n    if (lines.length === 2) {\n        const text1 = lines[0];\n        const text2 = lines[1];\n        const m = text1.length;\n        const n = text2.length;\n        const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));\n        for (let i = 1; i <= m; i++) {\n            for (let j = 1; j <= n; j++) {\n                if (text1[i - 1] === text2[j - 1]) {\n                    dp[i][j] = dp[i - 1][j - 1] + 1;\n                } else {\n                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);\n                }\n            }\n        }\n        console.log(dp[m][n]);\n        rl.close();\n    }\n});',NULL,1),
(2,'PYTHON','text1 = input()\ntext2 = input()\nm = len(text1)\nn = len(text2)\ndp = [[0] * (n + 1) for _ in range(m + 1)]\nfor i in range(1, m + 1):\n    for j in range(1, n + 1):\n        if text1[i - 1] == text2[j - 1]:\n            dp[i][j] = dp[i - 1][j - 1] + 1\n        else:\n            dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])\nprint(dp[m][n])',NULL,1),
(3,'C','#include <stdio.h>\n\nint main() {\n    int n, W;\n    scanf(\"%d %d\", &n, &W);\n    int values[n], weights[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &values[i]);\n    }\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &weights[i]);\n    }\n    int dp[W + 1];\n    for (int i = 0; i <= W; i++) {\n        dp[i] = 0;\n    }\n    for (int i = 0; i < n; i++) {\n        for (int j = W; j >= weights[i]; j--) {\n            int candidate = dp[j - weights[i]] + values[i];\n            if (candidate > dp[j]) {\n                dp[j] = candidate;\n            }\n        }\n    }\n    printf(\"%d\\n\", dp[W]);\n    return 0;\n}',NULL,1),
(3,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n, W;\n    cin >> n >> W;\n    vector<int> values(n), weights(n);\n    for (int i = 0; i < n; i++) {\n        cin >> values[i];\n    }\n    for (int i = 0; i < n; i++) {\n        cin >> weights[i];\n    }\n    vector<int> dp(W + 1, 0);\n    for (int i = 0; i < n; i++) {\n        for (int j = W; j >= weights[i]; j--) {\n            dp[j] = max(dp[j], dp[j - weights[i]] + values[i]);\n        }\n    }\n    cout << dp[W] << endl;\n    return 0;\n}',NULL,1),
(3,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextInt()) return;\n        int n = sc.nextInt();\n        int W = sc.nextInt();\n        int[] values = new int[n];\n        int[] weights = new int[n];\n        for (int i = 0; i < n; i++) {\n            values[i] = sc.nextInt();\n        }\n        for (int i = 0; i < n; i++) {\n            weights[i] = sc.nextInt();\n        }\n        int[] dp = new int[W + 1];\n        for (int i = 0; i < n; i++) {\n            for (int j = W; j >= weights[i]; j--) {\n                dp[j] = Math.max(dp[j], dp[j - weights[i]] + values[i]);\n            }\n        }\n        System.out.println(dp[W]);\n    }\n}',NULL,1),
(3,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const first = lines[0].split(/\\s+/).map(Number);\n    const n = first[0];\n    const W = first[1];\n    const values = lines[1].split(/\\s+/).map(Number);\n    const weights = lines[2].split(/\\s+/).map(Number);\n\n    const dp = new Array(W + 1).fill(0);\n    for (let i = 0; i < n; i++) {\n        for (let j = W; j >= weights[i]; j--) {\n            dp[j] = Math.max(dp[j], dp[j - weights[i]] + values[i]);\n        }\n    }\n    console.log(dp[W]);\n});',NULL,1),
(3,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().split()\n    if not data:\n        return\n    n = int(data[0])\n    W = int(data[1])\n    values = list(map(int, data[2:2+n]))\n    weights = list(map(int, data[2+n:2+2*n]))\n    dp = [0] * (W + 1)\n    for i in range(n):\n        for j in range(W, weights[i] - 1, -1):\n            dp[j] = max(dp[j], dp[j - weights[i]] + values[i])\n    print(dp[W])\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(4,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    int tails[n];\n    int len = 0;\n\n    for (int i = 0; i < n; i++) {\n        int x = nums[i];\n        int left = 0, right = len;\n        while (left < right) {\n            int mid = left + (right - left) / 2;\n            if (tails[mid] < x) {\n                left = mid + 1;\n            } else {\n                right = mid;\n            }\n        }\n        tails[left] = x;\n        if (left == len) {\n            len++;\n        }\n    }\n\n    printf(\"%d\\n\", len);\n    return 0;\n}',NULL,1),
(4,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n\n    vector<int> tails(n);\n    int len = 0;\n\n    for (int x : nums) {\n        int left = 0, right = len;\n        while (left < right) {\n            int mid = left + (right - left) / 2;\n            if (tails[mid] < x) {\n                left = mid + 1;\n            } else {\n                right = mid;\n            }\n        }\n        tails[left] = x;\n        if (left == len) {\n            len++;\n        }\n    }\n\n    cout << len << endl;\n    return 0;\n}',NULL,1),
(4,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n\n        int[] tails = new int[n];\n        int size = 0;\n        for (int x : nums) {\n            int l = 0, r = size;\n            while (l < r) {\n                int mid = l + (r - l) / 2;\n                if (tails[mid] < x) {\n                    l = mid + 1;\n                } else {\n                    r = mid;\n                }\n            }\n            tails[l] = x;\n            if (l == size) {\n                size++;\n            }\n        }\n\n        System.out.println(size);\n    }\n}',NULL,1),
(4,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n\n    const tails = new Array(n);\n    let len = 0;\n\n    for (const x of nums) {\n        let left = 0, right = len;\n        while (left < right) {\n            const mid = left + Math.floor((right - left) / 2);\n            if (tails[mid] < x) {\n                left = mid + 1;\n            } else {\n                right = mid;\n            }\n        }\n        tails[left] = x;\n        if (left === len) {\n            len++;\n        }\n    }\n\n    console.log(len);\n});',NULL,1),
(4,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    nums = list(map(int, data[1:1+n]))\n\n    tails = [0] * n\n    length = 0\n\n    for x in nums:\n        left, right = 0, length\n        while left < right:\n            mid = left + (right - left) // 2\n            if tails[mid] < x:\n                left = mid + 1\n            else:\n                right = mid\n        tails[left] = x\n        if left == length:\n            length += 1\n\n    print(length)\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(5,'C','#include <stdio.h>\n#include <limits.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int prices[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &prices[i]);\n    }\n    int minPrice = INT_MAX;\n    int maxProfit = 0;\n    for (int i = 0; i < n; i++) {\n        int price = prices[i];\n        if (price < minPrice) {\n            minPrice = price;\n        } else if (price - minPrice > maxProfit) {\n            maxProfit = price - minPrice;\n        }\n    }\n    printf(\"%d\\n\", maxProfit);\n    return 0;\n}',NULL,1),
(5,'CPP','#include <iostream>\n#include <vector>\n#include <climits>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> prices(n);\n    for (int i = 0; i < n; i++) {\n        cin >> prices[i];\n    }\n    int minPrice = INT_MAX;\n    int maxProfit = 0;\n    for (int price : prices) {\n        if (price < minPrice) {\n            minPrice = price;\n        } else if (price - minPrice > maxProfit) {\n            maxProfit = price - minPrice;\n        }\n    }\n    cout << maxProfit << endl;\n    return 0;\n}',NULL,1),
(5,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] prices = new int[n];\n        for (int i = 0; i < n; i++) {\n            prices[i] = sc.nextInt();\n        }\n        int minPrice = Integer.MAX_VALUE;\n        int maxProfit = 0;\n        for (int price : prices) {\n            if (price < minPrice) {\n                minPrice = price;\n            } else if (price - minPrice > maxProfit) {\n                maxProfit = price - minPrice;\n            }\n        }\n        System.out.println(maxProfit);\n    }\n}',NULL,1),
(5,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const prices = lines[1].split(\' \').map(Number);\n    let minPrice = Infinity;\n    let maxProfit = 0;\n    for (let price of prices) {\n        if (price < minPrice) {\n            minPrice = price;\n        } else if (price - minPrice > maxProfit) {\n            maxProfit = price - minPrice;\n        }\n    }\n    console.log(maxProfit);\n});',NULL,1),
(5,'PYTHON','n = int(input())\nprices = list(map(int, input().split()))\nmin_price = float(\'inf\')\nmax_profit = 0\nfor price in prices:\n    if price < min_price:\n        min_price = price\n    elif price - min_price > max_profit:\n        max_profit = price - min_price\nprint(max_profit)',NULL,1),
(6,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int *nums = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    int target;\n    scanf(\"%d\", &target);\n\n    int left = 0, right = n - 1;\n    int result = -1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] == target) {\n            result = mid;\n            break;\n        } else if (nums[mid] < target) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n\n    printf(\"%d\\n\", result);\n    free(nums);\n    return 0;\n}',NULL,1),
(6,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    int target;\n    cin >> target;\n\n    int left = 0, right = n - 1;\n    int result = -1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] == target) {\n            result = mid;\n            break;\n        } else if (nums[mid] < target) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n\n    cout << result << endl;\n    return 0;\n}',NULL,1),
(6,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        int target = sc.nextInt();\n\n        int left = 0, right = n - 1;\n        int ans = -1;\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n            if (nums[mid] == target) {\n                ans = mid;\n                break;\n            } else if (nums[mid] < target) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n        System.out.println(ans);\n    }\n}',NULL,1),
(6,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    const target = parseInt(lines[2]);\n\n    let left = 0, right = n - 1;\n    let result = -1;\n    while (left <= right) {\n        const mid = left + Math.floor((right - left) / 2);\n        if (nums[mid] === target) {\n            result = mid;\n            break;\n        } else if (nums[mid] < target) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n\n    console.log(result);\n});',NULL,1),
(6,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\ntarget = int(input())\n\nleft, right = 0, n - 1\nresult = -1\nwhile left <= right:\n    mid = left + (right - left) // 2\n    if nums[mid] == target:\n        result = mid\n        break\n    elif nums[mid] < target:\n        left = mid + 1\n    else:\n        right = mid - 1\n\nprint(result)',NULL,1),
(7,'C','#include <stdio.h>\n\nint main() {\n    int n, target;\n    scanf(\"%d %d\", &n, &target);\n    int nums[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    int left = 0, right = n - 1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] == target) {\n            printf(\"%d\\n\", mid);\n            return 0;\n        } else if (nums[mid] < target) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    printf(\"%d\\n\", left);\n    return 0;\n}',NULL,1),
(7,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n, target;\n    cin >> n >> target;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    int left = 0, right = n - 1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] == target) {\n            cout << mid << endl;\n            return 0;\n        } else if (nums[mid] < target) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    cout << left << endl;\n    return 0;\n}',NULL,1),
(7,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int target = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        int left = 0, right = n - 1;\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n            if (nums[mid] == target) {\n                System.out.println(mid);\n                return;\n            } else if (nums[mid] < target) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n        System.out.println(left);\n    }\n}',NULL,1),
(7,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const [n, target] = lines[0].split(\' \').map(Number);\n        const nums = lines[1].split(\' \').map(Number);\n        let left = 0, right = n - 1;\n        while (left <= right) {\n            const mid = left + Math.floor((right - left) / 2);\n            if (nums[mid] === target) {\n                console.log(mid);\n                rl.close();\n                return;\n            } else if (nums[mid] < target) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n        console.log(left);\n        rl.close();\n    }\n});',NULL,1),
(7,'PYTHON','n, target = map(int, input().split())\nnums = list(map(int, input().split()))\n\nleft, right = 0, n - 1\nwhile left <= right:\n    mid = left + (right - left) // 2\n    if nums[mid] == target:\n        print(mid)\n        break\n    elif nums[mid] < target:\n        left = mid + 1\n    else:\n        right = mid - 1\nelse:\n    print(left)',NULL,1),
(8,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint findFirst(int nums[], int n, int target) {\n    int left = 0, right = n - 1;\n    int ans = -1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] >= target) {\n            if (nums[mid] == target) ans = mid;\n            right = mid - 1;\n        } else {\n            left = mid + 1;\n        }\n    }\n    return ans;\n}\n\nint findLast(int nums[], int n, int target) {\n    int left = 0, right = n - 1;\n    int ans = -1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] <= target) {\n            if (nums[mid] == target) ans = mid;\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    return ans;\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int *nums = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    int target;\n    scanf(\"%d\", &target);\n\n    int left = findFirst(nums, n, target);\n    int right = findLast(nums, n, target);\n\n    printf(\"[%d,%d]\\n\", left, right);\n\n    free(nums);\n    return 0;\n}',NULL,1),
(8,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint findFirst(const vector<int>& nums, int target) {\n    int left = 0, right = nums.size() - 1;\n    int ans = -1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] >= target) {\n            if (nums[mid] == target) ans = mid;\n            right = mid - 1;\n        } else {\n            left = mid + 1;\n        }\n    }\n    return ans;\n}\n\nint findLast(const vector<int>& nums, int target) {\n    int left = 0, right = nums.size() - 1;\n    int ans = -1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] <= target) {\n            if (nums[mid] == target) ans = mid;\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    return ans;\n}\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    int target;\n    cin >> target;\n\n    int left = findFirst(nums, target);\n    int right = findLast(nums, target);\n\n    cout << \"[\" << left << \",\" << right << \"]\" << endl;\n    return 0;\n}',NULL,1),
(8,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        int target = sc.nextInt();\n\n        int left = findFirst(nums, target);\n        int right = findLast(nums, target);\n\n        System.out.println(\"[\" + left + \",\" + right + \"]\");\n    }\n\n    private static int findFirst(int[] nums, int target) {\n        int left = 0, right = nums.length - 1;\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n            if (nums[mid] >= target) {\n                right = mid - 1;\n            } else {\n                left = mid + 1;\n            }\n        }\n        if (left < nums.length && nums[left] == target) {\n            return left;\n        }\n        return -1;\n    }\n\n    private static int findLast(int[] nums, int target) {\n        int left = 0, right = nums.length - 1;\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n            if (nums[mid] <= target) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n        if (right >= 0 && nums[right] == target) {\n            return right;\n        }\n        return -1;\n    }\n}',NULL,1),
(8,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    const target = parseInt(lines[2]);\n\n    const left = findFirst(nums, target);\n    const right = findLast(nums, target);\n\n    console.log(`[${left},${right}]`);\n});\n\nfunction findFirst(nums, target) {\n    let left = 0, right = nums.length - 1;\n    let ans = -1;\n    while (left <= right) {\n        const mid = left + Math.floor((right - left) / 2);\n        if (nums[mid] >= target) {\n            if (nums[mid] === target) ans = mid;\n            right = mid - 1;\n        } else {\n            left = mid + 1;\n        }\n    }\n    return ans;\n}\n\nfunction findLast(nums, target) {\n    let left = 0, right = nums.length - 1;\n    let ans = -1;\n    while (left <= right) {\n        const mid = left + Math.floor((right - left) / 2);\n        if (nums[mid] <= target) {\n            if (nums[mid] === target) ans = mid;\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    return ans;\n}',NULL,1),
(8,'PYTHON','import sys\n\ndef find_first(nums, target):\n    left, right = 0, len(nums) - 1\n    ans = -1\n    while left <= right:\n        mid = left + (right - left) // 2\n        if nums[mid] >= target:\n            if nums[mid] == target:\n                ans = mid\n            right = mid - 1\n        else:\n            left = mid + 1\n    return ans\n\ndef find_last(nums, target):\n    left, right = 0, len(nums) - 1\n    ans = -1\n    while left <= right:\n        mid = left + (right - left) // 2\n        if nums[mid] <= target:\n            if nums[mid] == target:\n                ans = mid\n            left = mid + 1\n        else:\n            right = mid - 1\n    return ans\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    nums = list(map(int, data[1:1 + n]))\n    target = int(data[1 + n])\n    left = find_first(nums, target)\n    right = find_last(nums, target)\n    print(f\"[{left},{right}]\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(9,'C','#include <stdio.h>\n\nint search(int nums[], int n, int target) {\n    int left = 0, right = n - 1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] == target) {\n            return mid;\n        }\n        if (nums[left] <= nums[mid]) {\n            if (target >= nums[left] && target < nums[mid]) {\n                right = mid - 1;\n            } else {\n                left = mid + 1;\n            }\n        } else {\n            if (target > nums[mid] && target <= nums[right]) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n    }\n    return -1;\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    int target;\n    scanf(\"%d\", &target);\n    printf(\"%d\\n\", search(nums, n, target));\n    return 0;\n}',NULL,1),
(9,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint search(vector<int>& nums, int target) {\n    int left = 0, right = nums.size() - 1;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] == target) {\n            return mid;\n        }\n        if (nums[left] <= nums[mid]) {\n            if (target >= nums[left] && target < nums[mid]) {\n                right = mid - 1;\n            } else {\n                left = mid + 1;\n            }\n        } else {\n            if (target > nums[mid] && target <= nums[right]) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n    }\n    return -1;\n}\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    int target;\n    cin >> target;\n    cout << search(nums, target) << endl;\n    return 0;\n}',NULL,1),
(9,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        int target = sc.nextInt();\n        System.out.println(search(nums, target));\n    }\n\n    public static int search(int[] nums, int target) {\n        int left = 0, right = nums.length - 1;\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n            if (nums[mid] == target) {\n                return mid;\n            }\n            if (nums[left] <= nums[mid]) {\n                if (target >= nums[left] && target < nums[mid]) {\n                    right = mid - 1;\n                } else {\n                    left = mid + 1;\n                }\n            } else {\n                if (target > nums[mid] && target <= nums[right]) {\n                    left = mid + 1;\n                } else {\n                    right = mid - 1;\n                }\n            }\n        }\n        return -1;\n    }\n}',NULL,1),
(9,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    const target = parseInt(lines[2]);\n    console.log(search(nums, target));\n});\n\nfunction search(nums, target) {\n    let left = 0, right = nums.length - 1;\n    while (left <= right) {\n        let mid = left + Math.floor((right - left) / 2);\n        if (nums[mid] === target) {\n            return mid;\n        }\n        if (nums[left] <= nums[mid]) {\n            if (target >= nums[left] && target < nums[mid]) {\n                right = mid - 1;\n            } else {\n                left = mid + 1;\n            }\n        } else {\n            if (target > nums[mid] && target <= nums[right]) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n    }\n    return -1;\n}',NULL,1),
(9,'PYTHON','import sys\n\ndef search(nums, target):\n    left, right = 0, len(nums) - 1\n    while left <= right:\n        mid = left + (right - left) // 2\n        if nums[mid] == target:\n            return mid\n        if nums[left] <= nums[mid]:\n            if nums[left] <= target < nums[mid]:\n                right = mid - 1\n            else:\n                left = mid + 1\n        else:\n            if nums[mid] < target <= nums[right]:\n                left = mid + 1\n            else:\n                right = mid - 1\n    return -1\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    nums = list(map(int, data[1:1 + n]))\n    target = int(data[1 + n])\n    print(search(nums, target))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(10,'C','#include <stdio.h>\n\nint mySqrt(int x) {\n    if (x == 0) return 0;\n    int left = 1, right = x;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (mid <= x / mid) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    return right;\n}\n\nint main() {\n    int x;\n    scanf(\"%d\", &x);\n    printf(\"%d\\n\", mySqrt(x));\n    return 0;\n}',NULL,1),
(10,'CPP','#include <iostream>\nusing namespace std;\n\nint mySqrt(int x) {\n    if (x == 0) return 0;\n    int left = 1, right = x;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        if (mid <= x / mid) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    return right;\n}\n\nint main() {\n    int x;\n    cin >> x;\n    cout << mySqrt(x) << endl;\n    return 0;\n}',NULL,1),
(10,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int x = sc.nextInt();\n        System.out.println(mySqrt(x));\n    }\n\n    public static int mySqrt(int x) {\n        if (x == 0) return 0;\n        int left = 1, right = x, ans = 0;\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n            if (mid <= x / mid) {\n                ans = mid;\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n        return ans;\n    }\n}',NULL,1),
(10,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const x = parseInt(line.trim(), 10);\n    console.log(mySqrt(x));\n    rl.close();\n});\n\nfunction mySqrt(x) {\n    if (x === 0) return 0;\n    let left = 1, right = x;\n    while (left <= right) {\n        let mid = left + Math.floor((right - left) / 2);\n        if (mid <= Math.floor(x / mid)) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    return right;\n}',NULL,1),
(10,'PYTHON','import sys\n\ndef mySqrt(x):\n    if x == 0:\n        return 0\n    left, right = 1, x\n    while left <= right:\n        mid = left + (right - left) // 2\n        if mid <= x // mid:\n            left = mid + 1\n        else:\n            right = mid - 1\n    return right\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    x = int(data[0])\n    print(mySqrt(x))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(11,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint cmp(const void *a, const void *b) {\n    return (*(int *)a - *(int *)b);\n}\n\nint main() {\n    int gn, sn;\n    scanf(\"%d %d\", &gn, &sn);\n    int *g = (int *)malloc(gn * sizeof(int));\n    int *s = (int *)malloc(sn * sizeof(int));\n    for (int i = 0; i < gn; i++) {\n        scanf(\"%d\", &g[i]);\n    }\n    for (int i = 0; i < sn; i++) {\n        scanf(\"%d\", &s[i]);\n    }\n    qsort(g, gn, sizeof(int), cmp);\n    qsort(s, sn, sizeof(int), cmp);\n    int i = 0, j = 0;\n    while (i < gn && j < sn) {\n        if (s[j] >= g[i]) {\n            i++;\n        }\n        j++;\n    }\n    printf(\"%d\\n\", i);\n    free(g);\n    free(s);\n    return 0;\n}',NULL,1),
(11,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int gn, sn;\n    cin >> gn >> sn;\n    vector<int> g(gn), s(sn);\n    for (int i = 0; i < gn; i++) {\n        cin >> g[i];\n    }\n    for (int i = 0; i < sn; i++) {\n        cin >> s[i];\n    }\n    sort(g.begin(), g.end());\n    sort(s.begin(), s.end());\n    int i = 0, j = 0;\n    while (i < gn && j < sn) {\n        if (s[j] >= g[i]) {\n            i++;\n        }\n        j++;\n    }\n    cout << i << endl;\n    return 0;\n}',NULL,1),
(11,'JAVA','import java.util.Arrays;\nimport java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextInt()) return;\n        int gn = sc.nextInt();\n        int sn = sc.nextInt();\n        int[] g = new int[gn];\n        int[] s = new int[sn];\n        for (int i = 0; i < gn; i++) g[i] = sc.nextInt();\n        for (int i = 0; i < sn; i++) s[i] = sc.nextInt();\n        Arrays.sort(g);\n        Arrays.sort(s);\n        int i = 0, j = 0, count = 0;\n        while (i < gn && j < sn) {\n            if (s[j] >= g[i]) {\n                count++;\n                i++;\n                j++;\n            } else {\n                j++;\n            }\n        }\n        System.out.println(count);\n    }\n}',NULL,1),
(11,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const first = lines[0].split(/\\s+/).map(Number);\n    const gn = first[0];\n    const sn = first[1];\n    const g = lines[1].split(/\\s+/).map(Number);\n    const s = lines[2].split(/\\s+/).map(Number);\n\n    g.sort((a, b) => a - b);\n    s.sort((a, b) => a - b);\n\n    let i = 0, j = 0;\n    while (i < gn && j < sn) {\n        if (s[j] >= g[i]) {\n            i++;\n        }\n        j++;\n    }\n    console.log(i);\n});',NULL,1),
(11,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().split()\n    if not data:\n        return\n    gn = int(data[0])\n    sn = int(data[1])\n    g = list(map(int, data[2:2 + gn]))\n    s = list(map(int, data[2 + gn:2 + gn + sn]))\n    g.sort()\n    s.sort()\n    i = j = 0\n    while i < gn and j < sn:\n        if s[j] >= g[i]:\n            i += 1\n        j += 1\n    print(i)\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(12,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    int maxReach = 0;\n    int canReach = 1;\n    for (int i = 0; i < n; i++) {\n        if (i > maxReach) {\n            canReach = 0;\n            break;\n        }\n        if (i + nums[i] > maxReach) {\n            maxReach = i + nums[i];\n        }\n        if (maxReach >= n - 1) {\n            break;\n        }\n    }\n    if (canReach) {\n        printf(\"true\\n\");\n    } else {\n        printf(\"false\\n\");\n    }\n    return 0;\n}',NULL,1),
(12,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    int maxReach = 0;\n    bool canReach = true;\n    for (int i = 0; i < n; i++) {\n        if (i > maxReach) {\n            canReach = false;\n            break;\n        }\n        maxReach = max(maxReach, i + nums[i]);\n        if (maxReach >= n - 1) {\n            break;\n        }\n    }\n    cout << (canReach ? \"true\" : \"false\") << endl;\n    return 0;\n}',NULL,1),
(12,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        int maxReach = 0;\n        boolean canReach = true;\n        for (int i = 0; i < n; i++) {\n            if (i > maxReach) {\n                canReach = false;\n                break;\n            }\n            maxReach = Math.max(maxReach, i + nums[i]);\n            if (maxReach >= n - 1) {\n                break;\n            }\n        }\n        System.out.println(canReach && maxReach >= n - 1);\n    }\n}',NULL,1),
(12,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    let maxReach = 0;\n    let canReach = true;\n    for (let i = 0; i < n; i++) {\n        if (i > maxReach) {\n            canReach = false;\n            break;\n        }\n        maxReach = Math.max(maxReach, i + nums[i]);\n        if (maxReach >= n - 1) {\n            break;\n        }\n    }\n    console.log(canReach);\n});',NULL,1),
(12,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\nmaxReach = 0\ncanReach = True\nfor i in range(n):\n    if i > maxReach:\n        canReach = False\n        break\n    maxReach = max(maxReach, i + nums[i])\n    if maxReach >= n - 1:\n        break\nprint(str(canReach).lower())',NULL,1),
(13,'C','#include <stdio.h>\n#include <stdbool.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int five = 0, ten = 0;\n    bool ok = true;\n    for (int i = 0; i < n; i++) {\n        int bill;\n        scanf(\"%d\", &bill);\n        if (bill == 5) {\n            five++;\n        } else if (bill == 10) {\n            if (five > 0) {\n                five--;\n                ten++;\n            } else {\n                ok = false;\n                break;\n            }\n        } else {\n            if (ten > 0 && five > 0) {\n                ten--;\n                five--;\n            } else if (five >= 3) {\n                five -= 3;\n            } else {\n                ok = false;\n                break;\n            }\n        }\n    }\n    printf(ok ? \"true\\n\" : \"false\\n\");\n    return 0;\n}',NULL,1),
(13,'CPP','#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int five = 0, ten = 0;\n    bool ok = true;\n    for (int i = 0; i < n; i++) {\n        int bill;\n        cin >> bill;\n        if (bill == 5) {\n            five++;\n        } else if (bill == 10) {\n            if (five > 0) {\n                five--;\n                ten++;\n            } else {\n                ok = false;\n                break;\n            }\n        } else {\n            if (ten > 0 && five > 0) {\n                ten--;\n                five--;\n            } else if (five >= 3) {\n                five -= 3;\n            } else {\n                ok = false;\n                break;\n            }\n        }\n    }\n    cout << (ok ? \"true\" : \"false\") << endl;\n    return 0;\n}',NULL,1),
(13,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int five = 0, ten = 0;\n        boolean ok = true;\n        for (int i = 0; i < n; i++) {\n            int bill = sc.nextInt();\n            if (bill == 5) {\n                five++;\n            } else if (bill == 10) {\n                if (five > 0) {\n                    five--;\n                    ten++;\n                } else {\n                    ok = false;\n                    break;\n                }\n            } else {\n                if (ten > 0 && five > 0) {\n                    ten--;\n                    five--;\n                } else if (five >= 3) {\n                    five -= 3;\n                } else {\n                    ok = false;\n                    break;\n                }\n            }\n        }\n        System.out.println(ok);\n    }\n}',NULL,1),
(13,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const bills = lines[1].split(/\\s+/).map(Number);\n    let five = 0, ten = 0;\n    let ok = true;\n    for (let i = 0; i < n; i++) {\n        const bill = bills[i];\n        if (bill === 5) {\n            five++;\n        } else if (bill === 10) {\n            if (five > 0) {\n                five--;\n                ten++;\n            } else {\n                ok = false;\n                break;\n            }\n        } else {\n            if (ten > 0 && five > 0) {\n                ten--;\n                five--;\n            } else if (five >= 3) {\n                five -= 3;\n            } else {\n                ok = false;\n                break;\n            }\n        }\n    }\n    console.log(ok);\n});',NULL,1),
(13,'PYTHON','n = int(input())\nbills = list(map(int, input().split()))\nfive = 0\nten = 0\nok = True\nfor bill in bills:\n    if bill == 5:\n        five += 1\n    elif bill == 10:\n        if five > 0:\n            five -= 1\n            ten += 1\n        else:\n            ok = False\n            break\n    else:\n        if ten > 0 and five > 0:\n            ten -= 1\n            five -= 1\n        elif five >= 3:\n            five -= 3\n        else:\n            ok = False\n            break\nprint(\"true\" if ok else \"false\")',NULL,1),
(14,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int prices[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &prices[i]);\n    }\n    int maxProfit = 0;\n    for (int i = 1; i < n; i++) {\n        if (prices[i] > prices[i - 1]) {\n            maxProfit += prices[i] - prices[i - 1];\n        }\n    }\n    printf(\"%d\\n\", maxProfit);\n    return 0;\n}',NULL,1),
(14,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> prices(n);\n    for (int i = 0; i < n; i++) {\n        cin >> prices[i];\n    }\n    int maxProfit = 0;\n    for (int i = 1; i < n; i++) {\n        if (prices[i] > prices[i - 1]) {\n            maxProfit += prices[i] - prices[i - 1];\n        }\n    }\n    cout << maxProfit << endl;\n    return 0;\n}',NULL,1),
(14,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] prices = new int[n];\n        for (int i = 0; i < n; i++) {\n            prices[i] = sc.nextInt();\n        }\n        int maxProfit = 0;\n        for (int i = 1; i < n; i++) {\n            if (prices[i] > prices[i - 1]) {\n                maxProfit += prices[i] - prices[i - 1];\n            }\n        }\n        System.out.println(maxProfit);\n    }\n}',NULL,1),
(14,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const prices = lines[1].split(\' \').map(Number);\n    let maxProfit = 0;\n    for (let i = 1; i < n; i++) {\n        if (prices[i] > prices[i - 1]) {\n            maxProfit += prices[i] - prices[i - 1];\n        }\n    }\n    console.log(maxProfit);\n});',NULL,1),
(14,'PYTHON','n = int(input())\nprices = list(map(int, input().split()))\nmax_profit = 0\nfor i in range(1, n):\n    if prices[i] > prices[i - 1]:\n        max_profit += prices[i] - prices[i - 1]\nprint(max_profit)',NULL,1),
(15,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int *ratings = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &ratings[i]);\n    }\n\n    int *candies = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        candies[i] = 1;\n    }\n\n    for (int i = 1; i < n; i++) {\n        if (ratings[i] > ratings[i - 1]) {\n            candies[i] = candies[i - 1] + 1;\n        }\n    }\n\n    for (int i = n - 2; i >= 0; i--) {\n        if (ratings[i] > ratings[i + 1]) {\n            int need = candies[i + 1] + 1;\n            if (need > candies[i]) {\n                candies[i] = need;\n            }\n        }\n    }\n\n    int total = 0;\n    for (int i = 0; i < n; i++) {\n        total += candies[i];\n    }\n\n    printf(\"%d\\n\", total);\n\n    free(ratings);\n    free(candies);\n    return 0;\n}',NULL,1),
(15,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> ratings(n);\n    for (int i = 0; i < n; i++) {\n        cin >> ratings[i];\n    }\n\n    vector<int> candies(n, 1);\n\n    for (int i = 1; i < n; i++) {\n        if (ratings[i] > ratings[i - 1]) {\n            candies[i] = candies[i - 1] + 1;\n        }\n    }\n\n    for (int i = n - 2; i >= 0; i--) {\n        if (ratings[i] > ratings[i + 1]) {\n            candies[i] = max(candies[i], candies[i + 1] + 1);\n        }\n    }\n\n    int total = 0;\n    for (int c : candies) {\n        total += c;\n    }\n\n    cout << total << endl;\n    return 0;\n}',NULL,1),
(15,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] ratings = new int[n];\n        for (int i = 0; i < n; i++) {\n            ratings[i] = sc.nextInt();\n        }\n        int[] candies = new int[n];\n        Arrays.fill(candies, 1);\n        for (int i = 1; i < n; i++) {\n            if (ratings[i] > ratings[i - 1]) {\n                candies[i] = candies[i - 1] + 1;\n            }\n        }\n        for (int i = n - 2; i >= 0; i--) {\n            if (ratings[i] > ratings[i + 1]) {\n                candies[i] = Math.max(candies[i], candies[i + 1] + 1);\n            }\n        }\n        int sum = 0;\n        for (int c : candies) {\n            sum += c;\n        }\n        System.out.println(sum);\n    }\n}',NULL,1),
(15,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const ratings = lines[1].split(\' \').map(Number);\n    \n    const candies = new Array(n).fill(1);\n    \n    for (let i = 1; i < n; i++) {\n        if (ratings[i] > ratings[i - 1]) {\n            candies[i] = candies[i - 1] + 1;\n        }\n    }\n    \n    for (let i = n - 2; i >= 0; i--) {\n        if (ratings[i] > ratings[i + 1]) {\n            candies[i] = Math.max(candies[i], candies[i + 1] + 1);\n        }\n    }\n    \n    let total = 0;\n    for (const c of candies) {\n        total += c;\n    }\n    \n    console.log(total);\n});',NULL,1),
(15,'PYTHON','n = int(input())\nratings = list(map(int, input().split()))\n\ncandies = [1] * n\n\nfor i in range(1, n):\n    if ratings[i] > ratings[i - 1]:\n        candies[i] = candies[i - 1] + 1\n\nfor i in range(n - 2, -1, -1):\n    if ratings[i] > ratings[i + 1]:\n        candies[i] = max(candies[i], candies[i + 1] + 1)\n\nprint(sum(candies))',NULL,1),
(16,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint n;\nint nums[100];\nint used[100];\nint path[100];\nint res[10000][100];\nint resCount = 0;\n\nvoid backtrack(int depth) {\n    if (depth == n) {\n        for (int i = 0; i < n; i++) {\n            res[resCount][i] = path[i];\n        }\n        resCount++;\n        return;\n    }\n    for (int i = 0; i < n; i++) {\n        if (used[i]) continue;\n        used[i] = 1;\n        path[depth] = nums[i];\n        backtrack(depth + 1);\n        used[i] = 0;\n    }\n}\n\nint main() {\n    scanf(\"%d\", &n);\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    backtrack(0);\n    printf(\"[\");\n    for (int i = 0; i < resCount; i++) {\n        printf(\"[\");\n        for (int j = 0; j < n; j++) {\n            printf(\"%d\", res[i][j]);\n            if (j != n - 1) printf(\",\");\n        }\n        printf(\"]\");\n        if (i != resCount - 1) printf(\",\");\n    }\n    printf(\"]\\n\");\n    return 0;\n}',NULL,1),
(16,'CPP','#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\n\nvoid backtrack(vector<int>& nums, vector<bool>& used, vector<int>& path, vector<vector<int>>& res) {\n    if (path.size() == nums.size()) {\n        res.push_back(path);\n        return;\n    }\n    for (int i = 0; i < (int)nums.size(); i++) {\n        if (used[i]) continue;\n        used[i] = true;\n        path.push_back(nums[i]);\n        backtrack(nums, used, path, res);\n        path.pop_back();\n        used[i] = false;\n    }\n}\n\nstring format(vector<vector<int>>& res) {\n    string sb;\n    sb += \"[\";\n    for (int i = 0; i < (int)res.size(); i++) {\n        sb += \"[\";\n        vector<int>& list = res[i];\n        for (int j = 0; j < (int)list.size(); j++) {\n            sb += to_string(list[j]);\n            if (j != (int)list.size() - 1) sb += \",\";\n        }\n        sb += \"]\";\n        if (i != (int)res.size() - 1) sb += \",\";\n    }\n    sb += \"]\";\n    return sb;\n}\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    vector<vector<int>> res;\n    vector<bool> used(n, false);\n    vector<int> path;\n    backtrack(nums, used, path, res);\n    cout << format(res) << endl;\n    return 0;\n}',NULL,1),
(16,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        List<List<Integer>> result = new ArrayList<>();\n        boolean[] used = new boolean[n];\n        backtrack(nums, used, new ArrayList<>(), result);\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < result.size(); i++) {\n            sb.append(\"[\");\n            List<Integer> perm = result.get(i);\n            for (int j = 0; j < perm.size(); j++) {\n                sb.append(perm.get(j));\n                if (j < perm.size() - 1) {\n                    sb.append(\",\");\n                }\n            }\n            sb.append(\"]\");\n            if (i < result.size() - 1) {\n                sb.append(\",\");\n            }\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n\n    private static void backtrack(int[] nums, boolean[] used, List<Integer> path, List<List<Integer>> result) {\n        if (path.size() == nums.length) {\n            result.add(new ArrayList<>(path));\n            return;\n        }\n        for (int i = 0; i < nums.length; i++) {\n            if (used[i]) continue;\n            used[i] = true;\n            path.add(nums[i]);\n            backtrack(nums, used, path, result);\n            path.remove(path.size() - 1);\n            used[i] = false;\n        }\n    }\n}',NULL,1),
(16,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    const res = [];\n    const used = new Array(n).fill(false);\n    backtrack(nums, used, [], res);\n    console.log(format(res));\n});\n\nfunction backtrack(nums, used, path, res) {\n    if (path.length === nums.length) {\n        res.push([...path]);\n        return;\n    }\n    for (let i = 0; i < nums.length; i++) {\n        if (used[i]) continue;\n        used[i] = true;\n        path.push(nums[i]);\n        backtrack(nums, used, path, res);\n        path.pop();\n        used[i] = false;\n    }\n}\n\nfunction format(res) {\n    let sb = \'\';\n    sb += \'[\';\n    for (let i = 0; i < res.length; i++) {\n        sb += \'[\';\n        const list = res[i];\n        for (let j = 0; j < list.length; j++) {\n            sb += list[j];\n            if (j !== list.length - 1) sb += \',\';\n        }\n        sb += \']\';\n        if (i !== res.length - 1) sb += \',\';\n    }\n    sb += \']\';\n    return sb;\n}',NULL,1),
(16,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    nums = list(map(int, data[1:1+n]))\n    res = []\n    used = [False] * n\n    path = []\n\n    def backtrack():\n        if len(path) == n:\n            res.append(path[:])\n            return\n        for i in range(n):\n            if used[i]:\n                continue\n            used[i] = True\n            path.append(nums[i])\n            backtrack()\n            path.pop()\n            used[i] = False\n\n    backtrack()\n\n    parts = []\n    for perm in res:\n        parts.append(\"[\" + \",\".join(map(str, perm)) + \"]\")\n    print(\"[\" + \",\".join(parts) + \"]\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(17,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[20];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    int total = 1 << n;\n    printf(\"[\");\n    for (int mask = 0; mask < total; mask++) {\n        if (mask > 0) printf(\",\");\n        printf(\"[\");\n        int first = 1;\n        for (int i = 0; i < n; i++) {\n            if (mask & (1 << i)) {\n                if (!first) printf(\",\");\n                printf(\"%d\", nums[i]);\n                first = 0;\n            }\n        }\n        printf(\"]\");\n    }\n    printf(\"]\\n\");\n    return 0;\n}',NULL,1),
(17,'CPP','#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n\n    vector<vector<int>> result;\n    int total = 1 << n;\n    for (int mask = 0; mask < total; mask++) {\n        vector<int> subset;\n        for (int i = 0; i < n; i++) {\n            if ((mask & (1 << i)) != 0) {\n                subset.push_back(nums[i]);\n            }\n        }\n        result.push_back(subset);\n    }\n\n    string sb;\n    sb += \"[\";\n    for (int i = 0; i < (int)result.size(); i++) {\n        if (i > 0) sb += \",\";\n        sb += \"[\";\n        const vector<int>& subset = result[i];\n        for (int j = 0; j < (int)subset.size(); j++) {\n            if (j > 0) sb += \",\";\n            sb += to_string(subset[j]);\n        }\n        sb += \"]\";\n    }\n    sb += \"]\";\n    cout << sb << endl;\n\n    return 0;\n}',NULL,1),
(17,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n\n        List<List<Integer>> result = new ArrayList<>();\n        int total = 1 << n;\n        for (int mask = 0; mask < total; mask++) {\n            List<Integer> subset = new ArrayList<>();\n            for (int i = 0; i < n; i++) {\n                if ((mask & (1 << i)) != 0) {\n                    subset.add(nums[i]);\n                }\n            }\n            result.add(subset);\n        }\n\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < result.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(\"[\");\n            List<Integer> subset = result.get(i);\n            for (int j = 0; j < subset.size(); j++) {\n                if (j > 0) sb.append(\",\");\n                sb.append(subset.get(j));\n            }\n            sb.append(\"]\");\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n}',NULL,1),
(17,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet input = [];\nrl.on(\'line\', (line) => {\n    input.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(input[0]);\n    const nums = input[1].split(\' \').map(Number);\n\n    const result = [];\n    const total = 1 << n;\n    for (let mask = 0; mask < total; mask++) {\n        const subset = [];\n        for (let i = 0; i < n; i++) {\n            if ((mask & (1 << i)) !== 0) {\n                subset.push(nums[i]);\n            }\n        }\n        result.push(subset);\n    }\n\n    let sb = \'\';\n    sb += \'[\';\n    for (let i = 0; i < result.length; i++) {\n        if (i > 0) sb += \',\';\n        sb += \'[\';\n        const subset = result[i];\n        for (let j = 0; j < subset.length; j++) {\n            if (j > 0) sb += \',\';\n            sb += subset[j];\n        }\n        sb += \']\';\n    }\n    sb += \']\';\n    console.log(sb);\n});',NULL,1),
(17,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\n\nresult = []\ntotal = 1 << n\nfor mask in range(total):\n    subset = []\n    for i in range(n):\n        if mask & (1 << i):\n            subset.append(nums[i])\n    result.append(subset)\n\nsb = []\nsb.append(\"[\")\nfor i in range(len(result)):\n    if i > 0:\n        sb.append(\",\")\n    sb.append(\"[\")\n    subset = result[i]\n    for j in range(len(subset)):\n        if j > 0:\n            sb.append(\",\")\n        sb.append(str(subset[j]))\n    sb.append(\"]\")\nsb.append(\"]\")\nprint(\"\".join(sb))',NULL,1),
(18,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint cmp(const void *a, const void *b) {\n    return (*(int *)a - *(int *)b);\n}\n\nvoid backtrack(int *candidates, int n, int target, int start, int *current, int curLen, int **result, int *resultSize, int **resultColSize) {\n    if (target == 0) {\n        result[*resultSize] = (int *)malloc(curLen * sizeof(int));\n        for (int i = 0; i < curLen; i++) {\n            result[*resultSize][i] = current[i];\n        }\n        (*resultColSize)[*resultSize] = curLen;\n        (*resultSize)++;\n        return;\n    }\n    for (int i = start; i < n; i++) {\n        if (candidates[i] > target) {\n            break;\n        }\n        current[curLen] = candidates[i];\n        backtrack(candidates, n, target - candidates[i], i, current, curLen + 1, result, resultSize, resultColSize);\n    }\n}\n\nint main() {\n    int n, target;\n    scanf(\"%d %d\", &n, &target);\n    int *candidates = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &candidates[i]);\n    }\n    qsort(candidates, n, sizeof(int), cmp);\n\n    int maxSize = 10000;\n    int **result = (int **)malloc(maxSize * sizeof(int *));\n    int *resultColSize = (int *)malloc(maxSize * sizeof(int));\n    int resultSize = 0;\n\n    int *current = (int *)malloc(1000 * sizeof(int));\n    backtrack(candidates, n, target, 0, current, 0, result, &resultSize, &resultColSize);\n\n    printf(\"[\");\n    for (int i = 0; i < resultSize; i++) {\n        printf(\"[\");\n        for (int j = 0; j < resultColSize[i]; j++) {\n            printf(\"%d\", result[i][j]);\n            if (j < resultColSize[i] - 1) {\n                printf(\",\");\n            }\n        }\n        printf(\"]\");\n        if (i < resultSize - 1) {\n            printf(\",\");\n        }\n    }\n    printf(\"]\\n\");\n\n    for (int i = 0; i < resultSize; i++) {\n        free(result[i]);\n    }\n    free(result);\n    free(resultColSize);\n    free(current);\n    free(candidates);\n\n    return 0;\n}',NULL,1),
(18,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nvoid backtrack(vector<int>& candidates, int target, int start, vector<int>& current, vector<vector<int>>& result) {\n    if (target == 0) {\n        result.push_back(current);\n        return;\n    }\n    for (int i = start; i < (int)candidates.size(); i++) {\n        if (candidates[i] > target) {\n            break;\n        }\n        current.push_back(candidates[i]);\n        backtrack(candidates, target - candidates[i], i, current, result);\n        current.pop_back();\n    }\n}\n\nstring format(vector<vector<int>>& result) {\n    string sb = \"[\";\n    for (int i = 0; i < (int)result.size(); i++) {\n        sb += \"[\";\n        vector<int>& list = result[i];\n        for (int j = 0; j < (int)list.size(); j++) {\n            sb += to_string(list[j]);\n            if (j < (int)list.size() - 1) {\n                sb += \",\";\n            }\n        }\n        sb += \"]\";\n        if (i < (int)result.size() - 1) {\n            sb += \",\";\n        }\n    }\n    sb += \"]\";\n    return sb;\n}\n\nint main() {\n    int n, target;\n    cin >> n >> target;\n    vector<int> candidates(n);\n    for (int i = 0; i < n; i++) {\n        cin >> candidates[i];\n    }\n    sort(candidates.begin(), candidates.end());\n    vector<vector<int>> result;\n    vector<int> current;\n    backtrack(candidates, target, 0, current, result);\n    cout << format(result) << endl;\n    return 0;\n}',NULL,1),
(18,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int target = sc.nextInt();\n        int[] candidates = new int[n];\n        for (int i = 0; i < n; i++) {\n            candidates[i] = sc.nextInt();\n        }\n        Arrays.sort(candidates);\n        List<List<Integer>> result = new ArrayList<>();\n        backtrack(candidates, target, 0, new ArrayList<>(), result);\n        System.out.println(format(result));\n    }\n\n    private static void backtrack(int[] candidates, int remain, int start, List<Integer> path, List<List<Integer>> result) {\n        if (remain == 0) {\n            result.add(new ArrayList<>(path));\n            return;\n        }\n        for (int i = start; i < candidates.length; i++) {\n            if (candidates[i] > remain) {\n                break;\n            }\n            path.add(candidates[i]);\n            backtrack(candidates, remain - candidates[i], i, path, result);\n            path.remove(path.size() - 1);\n        }\n    }\n\n    private static String format(List<List<Integer>> result) {\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < result.size(); i++) {\n            sb.append(\"[\");\n            List<Integer> list = result.get(i);\n            for (int j = 0; j < list.size(); j++) {\n                sb.append(list.get(j));\n                if (j < list.size() - 1) {\n                    sb.append(\",\");\n                }\n            }\n            sb.append(\"]\");\n            if (i < result.size() - 1) {\n                sb.append(\",\");\n            }\n        }\n        sb.append(\"]\");\n        return sb.toString();\n    }\n}',NULL,1),
(18,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const [n, target] = lines[0].split(\' \').map(Number);\n        const candidates = lines[1].split(\' \').map(Number);\n        candidates.sort((a, b) => a - b);\n        const result = [];\n        backtrack(candidates, target, 0, [], result);\n        console.log(format(result));\n        rl.close();\n    }\n});\n\nfunction backtrack(candidates, target, start, current, result) {\n    if (target === 0) {\n        result.push([...current]);\n        return;\n    }\n    for (let i = start; i < candidates.length; i++) {\n        if (candidates[i] > target) {\n            break;\n        }\n        current.push(candidates[i]);\n        backtrack(candidates, target - candidates[i], i, current, result);\n        current.pop();\n    }\n}\n\nfunction format(result) {\n    let sb = \'\';\n    sb += \'[\';\n    for (let i = 0; i < result.length; i++) {\n        sb += \'[\';\n        const list = result[i];\n        for (let j = 0; j < list.length; j++) {\n            sb += list[j];\n            if (j < list.length - 1) {\n                sb += \',\';\n            }\n        }\n        sb += \']\';\n        if (i < result.length - 1) {\n            sb += \',\';\n        }\n    }\n    sb += \']\';\n    return sb;\n}',NULL,1),
(18,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    target = int(data[1])\n    candidates = list(map(int, data[2:2 + n]))\n    candidates.sort()\n    result = []\n    \n    def backtrack(start, remaining, current):\n        if remaining == 0:\n            result.append(current[:])\n            return\n        for i in range(start, len(candidates)):\n            if candidates[i] > remaining:\n                break\n            current.append(candidates[i])\n            backtrack(i, remaining - candidates[i], current)\n            current.pop()\n    \n    backtrack(0, target, [])\n    \n    parts = []\n    for lst in result:\n        parts.append(\"[\" + \",\".join(map(str, lst)) + \"]\")\n    print(\"[\" + \",\".join(parts) + \"]\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(19,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nvoid backtrack(char ***res, int *returnSize, char *cur, int len, int open, int close, int n) {\n    if (len == n * 2) {\n        cur[len] = \'\\0\';\n        *res = (char **)realloc(*res, (*returnSize + 1) * sizeof(char *));\n        (*res)[*returnSize] = (char *)malloc((n * 2 + 1) * sizeof(char));\n        strcpy((*res)[*returnSize], cur);\n        (*returnSize)++;\n        return;\n    }\n    if (open < n) {\n        cur[len] = \'(\';\n        backtrack(res, returnSize, cur, len + 1, open + 1, close, n);\n    }\n    if (close < open) {\n        cur[len] = \')\';\n        backtrack(res, returnSize, cur, len + 1, open, close + 1, n);\n    }\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n\n    char **res = NULL;\n    int returnSize = 0;\n    char *cur = (char *)malloc((n * 2 + 1) * sizeof(char));\n\n    backtrack(&res, &returnSize, cur, 0, 0, 0, n);\n\n    printf(\"[\");\n    for (int i = 0; i < returnSize; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"\'%s\'\", res[i]);\n    }\n    printf(\"]\\n\");\n\n    for (int i = 0; i < returnSize; i++) {\n        free(res[i]);\n    }\n    free(res);\n    free(cur);\n\n    return 0;\n}',NULL,1),
(19,'CPP','#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\n\nvoid backtrack(vector<string>& res, string& cur, int open, int close, int n) {\n    if ((int)cur.length() == n * 2) {\n        res.push_back(cur);\n        return;\n    }\n    if (open < n) {\n        cur.push_back(\'(\');\n        backtrack(res, cur, open + 1, close, n);\n        cur.pop_back();\n    }\n    if (close < open) {\n        cur.push_back(\')\');\n        backtrack(res, cur, open, close + 1, n);\n        cur.pop_back();\n    }\n}\n\nint main() {\n    int n;\n    cin >> n;\n    vector<string> res;\n    string cur;\n    backtrack(res, cur, 0, 0, n);\n    cout << \"[\";\n    for (int i = 0; i < (int)res.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << \"\'\" << res[i] << \"\'\";\n    }\n    cout << \"]\" << endl;\n    return 0;\n}',NULL,1),
(19,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        List<String> res = new ArrayList<>();\n        backtrack(res, new StringBuilder(), 0, 0, n);\n        StringBuilder sb = new StringBuilder();\n        sb.append(\'[\');\n        for (int i = 0; i < res.size(); i++) {\n            if (i > 0) sb.append(\',\');\n            sb.append(\'\\\'\').append(res.get(i)).append(\'\\\'\');\n        }\n        sb.append(\']\');\n        System.out.println(sb.toString());\n    }\n\n    private static void backtrack(List<String> res, StringBuilder cur, int open, int close, int n) {\n        if (cur.length() == n * 2) {\n            res.add(cur.toString());\n            return;\n        }\n        if (open < n) {\n            cur.append(\'(\');\n            backtrack(res, cur, open + 1, close, n);\n            cur.deleteCharAt(cur.length() - 1);\n        }\n        if (close < open) {\n            cur.append(\')\');\n            backtrack(res, cur, open, close + 1, n);\n            cur.deleteCharAt(cur.length() - 1);\n        }\n    }\n}',NULL,1),
(19,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const n = parseInt(line.trim(), 10);\n    const res = [];\n    backtrack(res, \'\', 0, 0, n);\n    let output = \'[\';\n    for (let i = 0; i < res.length; i++) {\n        if (i > 0) output += \',\';\n        output += \"\'\" + res[i] + \"\'\";\n    }\n    output += \']\';\n    console.log(output);\n    rl.close();\n});\n\nfunction backtrack(res, cur, open, close, n) {\n    if (cur.length === n * 2) {\n        res.push(cur);\n        return;\n    }\n    if (open < n) {\n        backtrack(res, cur + \'(\', open + 1, close, n);\n    }\n    if (close < open) {\n        backtrack(res, cur + \')\', open, close + 1, n);\n    }\n}',NULL,1),
(19,'PYTHON','n = int(input())\nres = []\n\ndef backtrack(cur, open_count, close_count):\n    if len(cur) == n * 2:\n        res.append(cur)\n        return\n    if open_count < n:\n        backtrack(cur + \'(\', open_count + 1, close_count)\n    if close_count < open_count:\n        backtrack(cur + \')\', open_count, close_count + 1)\n\nbacktrack(\'\', 0, 0)\nprint(\'[\' + \',\'.join(\"\'\" + s + \"\'\" for s in res) + \']\')',NULL,1),
(20,'C','#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n\nint m, n;\nchar board[100][100];\nchar word[1000];\n\nbool dfs(int i, int j, int k) {\n    if (i < 0 || i >= m || j < 0 || j >= n || board[i][j] != word[k]) {\n        return false;\n    }\n    if (k == (int)strlen(word) - 1) {\n        return true;\n    }\n    char temp = board[i][j];\n    board[i][j] = \'#\';\n    bool found = dfs(i + 1, j, k + 1)\n            || dfs(i - 1, j, k + 1)\n            || dfs(i, j + 1, k + 1)\n            || dfs(i, j - 1, k + 1);\n    board[i][j] = temp;\n    return found;\n}\n\nint main() {\n    scanf(\"%d %d\", &m, &n);\n    for (int i = 0; i < m; i++) {\n        scanf(\"%s\", board[i]);\n    }\n    scanf(\"%s\", word);\n    bool result = false;\n    for (int i = 0; i < m && !result; i++) {\n        for (int j = 0; j < n && !result; j++) {\n            if (dfs(i, j, 0)) {\n                result = true;\n            }\n        }\n    }\n    if (result) {\n        printf(\"true\\n\");\n    } else {\n        printf(\"false\\n\");\n    }\n    return 0;\n}',NULL,1),
(20,'CPP','#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\n\nbool dfs(vector<vector<char>>& board, const string& word, int i, int j, int k) {\n    if (i < 0 || i >= (int)board.size() || j < 0 || j >= (int)board[0].size() || board[i][j] != word[k]) {\n        return false;\n    }\n    if (k == (int)word.length() - 1) {\n        return true;\n    }\n    char temp = board[i][j];\n    board[i][j] = \'#\';\n    bool found = dfs(board, word, i + 1, j, k + 1)\n            || dfs(board, word, i - 1, j, k + 1)\n            || dfs(board, word, i, j + 1, k + 1)\n            || dfs(board, word, i, j - 1, k + 1);\n    board[i][j] = temp;\n    return found;\n}\n\nint main() {\n    int m, n;\n    cin >> m >> n;\n    cin.ignore();\n    vector<vector<char>> board(m, vector<char>(n));\n    for (int i = 0; i < m; i++) {\n        string line;\n        getline(cin, line);\n        for (int j = 0; j < n; j++) {\n            board[i][j] = line[j];\n        }\n    }\n    string word;\n    getline(cin, word);\n    bool result = false;\n    for (int i = 0; i < m && !result; i++) {\n        for (int j = 0; j < n && !result; j++) {\n            if (dfs(board, word, i, j, 0)) {\n                result = true;\n            }\n        }\n    }\n    cout << (result ? \"true\" : \"false\") << endl;\n    return 0;\n}',NULL,1),
(20,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n        sc.nextLine();\n        char[][] board = new char[m][n];\n        for (int i = 0; i < m; i++) {\n            String line = sc.nextLine();\n            for (int j = 0; j < n; j++) {\n                board[i][j] = line.charAt(j);\n            }\n        }\n        String word = sc.nextLine();\n        boolean result = false;\n        for (int i = 0; i < m && !result; i++) {\n            for (int j = 0; j < n && !result; j++) {\n                if (dfs(board, word, i, j, 0)) {\n                    result = true;\n                }\n            }\n        }\n        System.out.println(result);\n    }\n\n    private static boolean dfs(char[][] board, String word, int i, int j, int k) {\n        if (i < 0 || i >= board.length || j < 0 || j >= board[0].length || board[i][j] != word.charAt(k)) {\n            return false;\n        }\n        if (k == word.length() - 1) {\n            return true;\n        }\n        char temp = board[i][j];\n        board[i][j] = \'#\';\n        boolean found = dfs(board, word, i + 1, j, k + 1)\n                || dfs(board, word, i - 1, j, k + 1)\n                || dfs(board, word, i, j + 1, k + 1)\n                || dfs(board, word, i, j - 1, k + 1);\n        board[i][j] = temp;\n        return found;\n    }\n}',NULL,1),
(20,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n});\n\nrl.on(\'close\', () => {\n    let idx = 0;\n    const [m, n] = lines[idx++].trim().split(/\\s+/).map(Number);\n    const board = [];\n    for (let i = 0; i < m; i++) {\n        board.push(lines[idx++].trim().split(\'\'));\n    }\n    const word = lines[idx++].trim();\n\n    function dfs(i, j, k) {\n        if (i < 0 || i >= board.length || j < 0 || j >= board[0].length || board[i][j] !== word[k]) {\n            return false;\n        }\n        if (k === word.length - 1) {\n            return true;\n        }\n        const temp = board[i][j];\n        board[i][j] = \'#\';\n        const found = dfs(i + 1, j, k + 1)\n            || dfs(i - 1, j, k + 1)\n            || dfs(i, j + 1, k + 1)\n            || dfs(i, j - 1, k + 1);\n        board[i][j] = temp;\n        return found;\n    }\n\n    let result = false;\n    for (let i = 0; i < m && !result; i++) {\n        for (let j = 0; j < n && !result; j++) {\n            if (dfs(i, j, 0)) {\n                result = true;\n            }\n        }\n    }\n    console.log(result);\n});',NULL,1),
(20,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().splitlines()\n    if not data:\n        return\n    first = data[0].split()\n    m, n = int(first[0]), int(first[1])\n    board = []\n    for i in range(1, 1 + m):\n        board.append(list(data[i]))\n    word = data[1 + m]\n\n    def dfs(i, j, k):\n        if i < 0 or i >= m or j < 0 or j >= n or board[i][j] != word[k]:\n            return False\n        if k == len(word) - 1:\n            return True\n        temp = board[i][j]\n        board[i][j] = \'#\'\n        found = (dfs(i + 1, j, k + 1) or\n                 dfs(i - 1, j, k + 1) or\n                 dfs(i, j + 1, k + 1) or\n                 dfs(i, j - 1, k + 1))\n        board[i][j] = temp\n        return found\n\n    result = False\n    for i in range(m):\n        for j in range(n):\n            if dfs(i, j, 0):\n                result = True\n                break\n        if result:\n            break\n\n    print(\"true\" if result else \"false\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(21,'C','#include <stdio.h>\n#include <stdlib.h>\n\nvoid swap(int *a, int *b) {\n    int tmp = *a;\n    *a = *b;\n    *b = tmp;\n}\n\nint partition(int arr[], int left, int right) {\n    int mid = left + (right - left) / 2;\n    int pivotValue = arr[mid];\n    swap(&arr[mid], &arr[right]);\n    int storeIndex = left;\n    for (int i = left; i < right; i++) {\n        if (arr[i] < pivotValue) {\n            swap(&arr[i], &arr[storeIndex]);\n            storeIndex++;\n        }\n    }\n    swap(&arr[storeIndex], &arr[right]);\n    return storeIndex;\n}\n\nvoid quickSort(int arr[], int left, int right) {\n    if (left >= right) return;\n    int pivot = partition(arr, left, right);\n    quickSort(arr, left, pivot - 1);\n    quickSort(arr, pivot + 1, right);\n}\n\nint main() {\n    int n;\n    if (scanf(\"%d\", &n) != 1) return 0;\n    int *arr = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &arr[i]);\n    }\n    quickSort(arr, 0, n - 1);\n    for (int i = 0; i < n; i++) {\n        if (i > 0) printf(\" \");\n        printf(\"%d\", arr[i]);\n    }\n    printf(\"\\n\");\n    free(arr);\n    return 0;\n}',NULL,1),
(21,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nvoid quickSort(vector<int>& arr, int left, int right);\nint partition(vector<int>& arr, int left, int right);\nvoid swap(int& a, int& b);\n\nint main() {\n    int n;\n    if (!(cin >> n)) return 0;\n    vector<int> arr(n);\n    for (int i = 0; i < n; i++) {\n        cin >> arr[i];\n    }\n    quickSort(arr, 0, n - 1);\n    for (int i = 0; i < n; i++) {\n        if (i > 0) cout << \' \';\n        cout << arr[i];\n    }\n    cout << endl;\n    return 0;\n}\n\nvoid quickSort(vector<int>& arr, int left, int right) {\n    if (left >= right) return;\n    int pivot = partition(arr, left, right);\n    quickSort(arr, left, pivot - 1);\n    quickSort(arr, pivot + 1, right);\n}\n\nint partition(vector<int>& arr, int left, int right) {\n    int mid = left + (right - left) / 2;\n    int pivotValue = arr[mid];\n    swap(arr[mid], arr[right]);\n    int storeIndex = left;\n    for (int i = left; i < right; i++) {\n        if (arr[i] < pivotValue) {\n            swap(arr[i], arr[storeIndex]);\n            storeIndex++;\n        }\n    }\n    swap(arr[storeIndex], arr[right]);\n    return storeIndex;\n}\n\nvoid swap(int& a, int& b) {\n    int tmp = a;\n    a = b;\n    b = tmp;\n}',NULL,1),
(21,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextInt()) return;\n        int n = sc.nextInt();\n        int[] arr = new int[n];\n        for (int i = 0; i < n; i++) {\n            arr[i] = sc.nextInt();\n        }\n        quickSort(arr, 0, n - 1);\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < n; i++) {\n            if (i > 0) sb.append(\' \');\n            sb.append(arr[i]);\n        }\n        System.out.println(sb.toString());\n    }\n\n    private static void quickSort(int[] arr, int left, int right) {\n        if (left >= right) return;\n        int pivot = arr[left + (right - left) / 2];\n        int i = left, j = right;\n        while (i <= j) {\n            while (arr[i] < pivot) i++;\n            while (arr[j] > pivot) j--;\n            if (i <= j) {\n                int temp = arr[i];\n                arr[i] = arr[j];\n                arr[j] = temp;\n                i++;\n                j--;\n            }\n        }\n        quickSort(arr, left, j);\n        quickSort(arr, i, right);\n    }\n}',NULL,1),
(21,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet input = [];\n\nrl.on(\'line\', (line) => {\n    input.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    if (input.length === 0) return;\n    const n = parseInt(input[0]);\n    if (isNaN(n)) return;\n    const arr = input[1].split(\' \').map(Number);\n    quickSort(arr, 0, n - 1);\n    console.log(arr.join(\' \'));\n});\n\nfunction quickSort(arr, left, right) {\n    if (left >= right) return;\n    const pivot = partition(arr, left, right);\n    quickSort(arr, left, pivot - 1);\n    quickSort(arr, pivot + 1, right);\n}\n\nfunction partition(arr, left, right) {\n    const mid = left + Math.floor((right - left) / 2);\n    const pivotValue = arr[mid];\n    swap(arr, mid, right);\n    let storeIndex = left;\n    for (let i = left; i < right; i++) {\n        if (arr[i] < pivotValue) {\n            swap(arr, i, storeIndex);\n            storeIndex++;\n        }\n    }\n    swap(arr, storeIndex, right);\n    return storeIndex;\n}\n\nfunction swap(arr, i, j) {\n    const tmp = arr[i];\n    arr[i] = arr[j];\n    arr[j] = tmp;\n}',NULL,1),
(21,'PYTHON','import sys\n\ndef quick_sort(arr, left, right):\n    if left >= right:\n        return\n    pivot = partition(arr, left, right)\n    quick_sort(arr, left, pivot - 1)\n    quick_sort(arr, pivot + 1, right)\n\ndef partition(arr, left, right):\n    mid = left + (right - left) // 2\n    pivot_value = arr[mid]\n    arr[mid], arr[right] = arr[right], arr[mid]\n    store_index = left\n    for i in range(left, right):\n        if arr[i] < pivot_value:\n            arr[i], arr[store_index] = arr[store_index], arr[i]\n            store_index += 1\n    arr[store_index], arr[right] = arr[right], arr[store_index]\n    return store_index\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    arr = list(map(int, data[1:1 + n]))\n    quick_sort(arr, 0, n - 1)\n    print(\' \'.join(map(str, arr)))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(22,'C','#include <stdio.h>\n#include <stdlib.h>\n\nvoid merge(int arr[], int left, int mid, int right) {\n    int n1 = mid - left + 1;\n    int n2 = right - mid;\n    int *L = (int *)malloc(n1 * sizeof(int));\n    int *R = (int *)malloc(n2 * sizeof(int));\n    for (int i = 0; i < n1; i++) L[i] = arr[left + i];\n    for (int j = 0; j < n2; j++) R[j] = arr[mid + 1 + j];\n    int i = 0, j = 0, k = left;\n    while (i < n1 && j < n2) {\n        if (L[i] <= R[j]) arr[k++] = L[i++];\n        else arr[k++] = R[j++];\n    }\n    while (i < n1) arr[k++] = L[i++];\n    while (j < n2) arr[k++] = R[j++];\n    free(L);\n    free(R);\n}\n\nvoid mergeSort(int arr[], int left, int right) {\n    if (left >= right) return;\n    int mid = left + (right - left) / 2;\n    mergeSort(arr, left, mid);\n    mergeSort(arr, mid + 1, right);\n    merge(arr, left, mid, right);\n}\n\nint main() {\n    int n;\n    if (scanf(\"%d\", &n) != 1) return 0;\n    int *arr = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &arr[i]);\n    }\n    mergeSort(arr, 0, n - 1);\n    for (int i = 0; i < n; i++) {\n        if (i > 0) printf(\" \");\n        printf(\"%d\", arr[i]);\n    }\n    printf(\"\\n\");\n    free(arr);\n    return 0;\n}',NULL,1),
(22,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nvoid merge(vector<int>& arr, int left, int mid, int right) {\n    vector<int> temp(right - left + 1);\n    int i = left, j = mid + 1, k = 0;\n    while (i <= mid && j <= right) {\n        if (arr[i] <= arr[j]) {\n            temp[k++] = arr[i++];\n        } else {\n            temp[k++] = arr[j++];\n        }\n    }\n    while (i <= mid) temp[k++] = arr[i++];\n    while (j <= right) temp[k++] = arr[j++];\n    for (int p = 0; p < temp.size(); p++) {\n        arr[left + p] = temp[p];\n    }\n}\n\nvoid mergeSort(vector<int>& arr, int left, int right) {\n    if (left >= right) return;\n    int mid = left + (right - left) / 2;\n    mergeSort(arr, left, mid);\n    mergeSort(arr, mid + 1, right);\n    merge(arr, left, mid, right);\n}\n\nint main() {\n    int n;\n    if (!(cin >> n)) return 0;\n    vector<int> arr(n);\n    for (int i = 0; i < n; i++) {\n        cin >> arr[i];\n    }\n    mergeSort(arr, 0, n - 1);\n    for (int i = 0; i < n; i++) {\n        if (i > 0) cout << \' \';\n        cout << arr[i];\n    }\n    cout << endl;\n    return 0;\n}',NULL,1),
(22,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextInt()) return;\n        int n = sc.nextInt();\n        int[] arr = new int[n];\n        for (int i = 0; i < n; i++) {\n            arr[i] = sc.nextInt();\n        }\n        mergeSort(arr, 0, n - 1);\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < n; i++) {\n            if (i > 0) sb.append(\' \');\n            sb.append(arr[i]);\n        }\n        System.out.println(sb.toString());\n    }\n\n    private static void mergeSort(int[] arr, int left, int right) {\n        if (left >= right) return;\n        int mid = left + (right - left) / 2;\n        mergeSort(arr, left, mid);\n        mergeSort(arr, mid + 1, right);\n        merge(arr, left, mid, right);\n    }\n\n    private static void merge(int[] arr, int left, int mid, int right) {\n        int[] temp = new int[right - left + 1];\n        int i = left, j = mid + 1, k = 0;\n        while (i <= mid && j <= right) {\n            if (arr[i] <= arr[j]) {\n                temp[k++] = arr[i++];\n            } else {\n                temp[k++] = arr[j++];\n            }\n        }\n        while (i <= mid) temp[k++] = arr[i++];\n        while (j <= right) temp[k++] = arr[j++];\n        System.arraycopy(temp, 0, arr, left, temp.length);\n    }\n}',NULL,1),
(22,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet input = [];\n\nrl.on(\'line\', (line) => {\n    input.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    if (input.length === 0) return;\n    const tokens = input.join(\' \').split(/\\s+/).filter(s => s.length > 0);\n    if (tokens.length === 0) return;\n    const n = parseInt(tokens[0], 10);\n    const arr = [];\n    for (let i = 0; i < n; i++) {\n        arr.push(parseInt(tokens[i + 1], 10));\n    }\n    mergeSort(arr, 0, n - 1);\n    console.log(arr.join(\' \'));\n});\n\nfunction mergeSort(arr, left, right) {\n    if (left >= right) return;\n    const mid = left + Math.floor((right - left) / 2);\n    mergeSort(arr, left, mid);\n    mergeSort(arr, mid + 1, right);\n    merge(arr, left, mid, right);\n}\n\nfunction merge(arr, left, mid, right) {\n    const temp = new Array(right - left + 1);\n    let i = left, j = mid + 1, k = 0;\n    while (i <= mid && j <= right) {\n        if (arr[i] <= arr[j]) {\n            temp[k++] = arr[i++];\n        } else {\n            temp[k++] = arr[j++];\n        }\n    }\n    while (i <= mid) temp[k++] = arr[i++];\n    while (j <= right) temp[k++] = arr[j++];\n    for (let t = 0; t < temp.length; t++) {\n        arr[left + t] = temp[t];\n    }\n}',NULL,1),
(22,'PYTHON','import sys\n\ndef merge_sort(arr, left, right):\n    if left >= right:\n        return\n    mid = left + (right - left) // 2\n    merge_sort(arr, left, mid)\n    merge_sort(arr, mid + 1, right)\n    merge(arr, left, mid, right)\n\ndef merge(arr, left, mid, right):\n    temp = []\n    i, j = left, mid + 1\n    while i <= mid and j <= right:\n        if arr[i] <= arr[j]:\n            temp.append(arr[i])\n            i += 1\n        else:\n            temp.append(arr[j])\n            j += 1\n    while i <= mid:\n        temp.append(arr[i])\n        i += 1\n    while j <= right:\n        temp.append(arr[j])\n        j += 1\n    arr[left:right + 1] = temp\n\ndef main():\n    data = sys.stdin.read().split()\n    if not data:\n        return\n    n = int(data[0])\n    arr = list(map(int, data[1:1 + n]))\n    merge_sort(arr, 0, n - 1)\n    print(\' \'.join(map(str, arr)))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(23,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int arr[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &arr[i]);\n    }\n    for (int i = 0; i < n - 1; i++) {\n        for (int j = 0; j < n - 1 - i; j++) {\n            if (arr[j] > arr[j + 1]) {\n                int temp = arr[j];\n                arr[j] = arr[j + 1];\n                arr[j + 1] = temp;\n            }\n        }\n    }\n    for (int i = 0; i < n; i++) {\n        if (i > 0) {\n            printf(\" \");\n        }\n        printf(\"%d\", arr[i]);\n    }\n    printf(\"\\n\");\n    return 0;\n}',NULL,1),
(23,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> arr(n);\n    for (int i = 0; i < n; i++) {\n        cin >> arr[i];\n    }\n    for (int i = 0; i < n - 1; i++) {\n        for (int j = 0; j < n - 1 - i; j++) {\n            if (arr[j] > arr[j + 1]) {\n                int temp = arr[j];\n                arr[j] = arr[j + 1];\n                arr[j + 1] = temp;\n            }\n        }\n    }\n    for (int i = 0; i < n; i++) {\n        if (i > 0) {\n            cout << \" \";\n        }\n        cout << arr[i];\n    }\n    cout << endl;\n    return 0;\n}',NULL,1),
(23,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextInt()) return;\n        int n = sc.nextInt();\n        int[] arr = new int[n];\n        for (int i = 0; i < n; i++) {\n            arr[i] = sc.nextInt();\n        }\n\n        for (int i = 0; i < n - 1; i++) {\n            for (int j = 0; j < n - 1 - i; j++) {\n                if (arr[j] > arr[j + 1]) {\n                    int temp = arr[j];\n                    arr[j] = arr[j + 1];\n                    arr[j + 1] = temp;\n                }\n            }\n        }\n\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < n; i++) {\n            if (i > 0) sb.append(\' \');\n            sb.append(arr[i]);\n        }\n        System.out.println(sb.toString());\n    }\n}',NULL,1),
(23,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n  input: process.stdin,\n  output: process.stdout\n});\n\nlet input = [];\nrl.on(\'line\', (line) => {\n  input.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n  const n = parseInt(input[0]);\n  const arr = input[1].split(\' \').map(Number);\n\n  for (let i = 0; i < n - 1; i++) {\n    for (let j = 0; j < n - 1 - i; j++) {\n      if (arr[j] > arr[j + 1]) {\n        const temp = arr[j];\n        arr[j] = arr[j + 1];\n        arr[j + 1] = temp;\n      }\n    }\n  }\n\n  let output = \'\';\n  for (let i = 0; i < n; i++) {\n    if (i > 0) {\n      output += \' \';\n    }\n    output += arr[i];\n  }\n  console.log(output);\n});',NULL,1),
(23,'PYTHON','n = int(input())\narr = list(map(int, input().split()))\nfor i in range(n - 1):\n    for j in range(n - 1 - i):\n        if arr[j] > arr[j + 1]:\n            arr[j], arr[j + 1] = arr[j + 1], arr[j]\nprint(\' \'.join(map(str, arr)))',NULL,1),
(24,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int arr[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &arr[i]);\n    }\n\n    for (int i = 0; i < n - 1; i++) {\n        int minIndex = i;\n        for (int j = i + 1; j < n; j++) {\n            if (arr[j] < arr[minIndex]) {\n                minIndex = j;\n            }\n        }\n        int temp = arr[i];\n        arr[i] = arr[minIndex];\n        arr[minIndex] = temp;\n    }\n\n    for (int i = 0; i < n; i++) {\n        if (i > 0) {\n            printf(\" \");\n        }\n        printf(\"%d\", arr[i]);\n    }\n    printf(\"\\n\");\n    return 0;\n}',NULL,1),
(24,'CPP','#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int arr[n];\n    for (int i = 0; i < n; i++) {\n        cin >> arr[i];\n    }\n\n    for (int i = 0; i < n - 1; i++) {\n        int minIndex = i;\n        for (int j = i + 1; j < n; j++) {\n            if (arr[j] < arr[minIndex]) {\n                minIndex = j;\n            }\n        }\n        int temp = arr[i];\n        arr[i] = arr[minIndex];\n        arr[minIndex] = temp;\n    }\n\n    for (int i = 0; i < n; i++) {\n        if (i > 0) {\n            cout << \" \";\n        }\n        cout << arr[i];\n    }\n    cout << endl;\n    return 0;\n}',NULL,1),
(24,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] arr = new int[n];\n        for (int i = 0; i < n; i++) {\n            arr[i] = sc.nextInt();\n        }\n\n        for (int i = 0; i < n - 1; i++) {\n            int minIndex = i;\n            for (int j = i + 1; j < n; j++) {\n                if (arr[j] < arr[minIndex]) {\n                    minIndex = j;\n                }\n            }\n            int temp = arr[i];\n            arr[i] = arr[minIndex];\n            arr[minIndex] = temp;\n        }\n\n        for (int i = 0; i < n; i++) {\n            if (i > 0) {\n                System.out.print(\" \");\n            }\n            System.out.print(arr[i]);\n        }\n        System.out.println();\n    }\n}',NULL,1),
(24,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet input = [];\nrl.on(\'line\', (line) => {\n    input.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(input[0]);\n    const arr = input[1].split(\' \').map(Number);\n\n    for (let i = 0; i < n - 1; i++) {\n        let minIndex = i;\n        for (let j = i + 1; j < n; j++) {\n            if (arr[j] < arr[minIndex]) {\n                minIndex = j;\n            }\n        }\n        let temp = arr[i];\n        arr[i] = arr[minIndex];\n        arr[minIndex] = temp;\n    }\n\n    let result = \'\';\n    for (let i = 0; i < n; i++) {\n        if (i > 0) {\n            result += \' \';\n        }\n        result += arr[i];\n    }\n    console.log(result);\n});',NULL,1),
(24,'PYTHON','n = int(input())\narr = list(map(int, input().split()))\n\nfor i in range(n - 1):\n    min_index = i\n    for j in range(i + 1, n):\n        if arr[j] < arr[min_index]:\n            min_index = j\n    arr[i], arr[min_index] = arr[min_index], arr[i]\n\nprint(\' \'.join(map(str, arr)))',NULL,1),
(25,'C','#include <stdio.h>\n\nvoid insertionSort(int arr[], int n) {\n    for (int i = 1; i < n; i++) {\n        int key = arr[i];\n        int j = i - 1;\n        while (j >= 0 && arr[j] > key) {\n            arr[j + 1] = arr[j];\n            j--;\n        }\n        arr[j + 1] = key;\n    }\n}\n\nint main() {\n    int n;\n    if (scanf(\"%d\", &n) != 1) return 0;\n    int arr[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &arr[i]);\n    }\n    insertionSort(arr, n);\n    for (int i = 0; i < n; i++) {\n        if (i > 0) printf(\" \");\n        printf(\"%d\", arr[i]);\n    }\n    printf(\"\\n\");\n    return 0;\n}',NULL,1),
(25,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nvoid insertionSort(vector<int>& arr) {\n    for (int i = 1; i < (int)arr.size(); i++) {\n        int key = arr[i];\n        int j = i - 1;\n        while (j >= 0 && arr[j] > key) {\n            arr[j + 1] = arr[j];\n            j--;\n        }\n        arr[j + 1] = key;\n    }\n}\n\nint main() {\n    int n;\n    if (!(cin >> n)) return 0;\n    vector<int> arr(n);\n    for (int i = 0; i < n; i++) {\n        cin >> arr[i];\n    }\n    insertionSort(arr);\n    for (int i = 0; i < n; i++) {\n        if (i > 0) cout << \' \';\n        cout << arr[i];\n    }\n    cout << endl;\n    return 0;\n}',NULL,1),
(25,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextInt()) return;\n        int n = sc.nextInt();\n        int[] arr = new int[n];\n        for (int i = 0; i < n; i++) {\n            arr[i] = sc.nextInt();\n        }\n        insertionSort(arr);\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < n; i++) {\n            if (i > 0) sb.append(\' \');\n            sb.append(arr[i]);\n        }\n        System.out.println(sb.toString());\n    }\n\n    private static void insertionSort(int[] arr) {\n        for (int i = 1; i < arr.length; i++) {\n            int key = arr[i];\n            int j = i - 1;\n            while (j >= 0 && arr[j] > key) {\n                arr[j + 1] = arr[j];\n                j--;\n            }\n            arr[j + 1] = key;\n        }\n    }\n}',NULL,1),
(25,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet input = [];\n\nrl.on(\'line\', (line) => {\n    input.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    if (input.length === 0) return;\n    const n = parseInt(input[0]);\n    if (isNaN(n)) return;\n    const arr = input[1].split(\' \').map(Number);\n    insertionSort(arr);\n    console.log(arr.join(\' \'));\n});\n\nfunction insertionSort(arr) {\n    for (let i = 1; i < arr.length; i++) {\n        let key = arr[i];\n        let j = i - 1;\n        while (j >= 0 && arr[j] > key) {\n            arr[j + 1] = arr[j];\n            j--;\n        }\n        arr[j + 1] = key;\n    }\n}',NULL,1),
(25,'PYTHON','import sys\n\ndef insertion_sort(arr):\n    for i in range(1, len(arr)):\n        key = arr[i]\n        j = i - 1\n        while j >= 0 and arr[j] > key:\n            arr[j + 1] = arr[j]\n            j -= 1\n        arr[j + 1] = key\n\ndef main():\n    data = sys.stdin.read().split()\n    if not data:\n        return\n    n = int(data[0])\n    arr = list(map(int, data[1:1 + n]))\n    insertion_sort(arr)\n    print(\' \'.join(map(str, arr)))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(26,'C','#include <stdio.h>\n\nint main() {\n    unsigned int n;\n    if (scanf(\"%u\", &n) == 1) {\n        int count = 0;\n        while (n != 0) {\n            n &= (n - 1);\n            count++;\n        }\n        printf(\"%d\\n\", count);\n    }\n    return 0;\n}',NULL,1),
(26,'CPP','#include <iostream>\n\nint main() {\n    unsigned int n;\n    if (std::cin >> n) {\n        int count = 0;\n        while (n != 0) {\n            n &= (n - 1);\n            count++;\n        }\n        std::cout << count << std::endl;\n    }\n    return 0;\n}',NULL,1),
(26,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        int n = scanner.nextInt();\n        int count = 0;\n        while (n != 0) {\n            n &= (n - 1);\n            count++;\n        }\n        System.out.println(count);\n    }\n}',NULL,1),
(26,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const n = parseInt(line.trim(), 10);\n    if (!isNaN(n)) {\n        let count = 0;\n        let num = n;\n        while (num !== 0) {\n            num &= (num - 1);\n            count++;\n        }\n        console.log(count);\n    }\n    rl.close();\n});',NULL,1),
