(27,'C','#include <stdio.h>\n\nint main() {\n    int x, y;\n    scanf(\"%d %d\", &x, &y);\n    unsigned int xor_val = (unsigned int)(x ^ y);\n    int distance = 0;\n    while (xor_val != 0) {\n        distance += xor_val & 1;\n        xor_val >>= 1;\n    }\n    printf(\"%d\\n\", distance);\n    return 0;\n}',NULL,1),
(27,'CPP','#include <iostream>\nusing namespace std;\n\nint main() {\n    int x, y;\n    cin >> x >> y;\n    int xorValue = x ^ y;\n    int distance = 0;\n    while (xorValue != 0) {\n        distance += xorValue & 1;\n        xorValue >>= 1;\n    }\n    cout << distance << endl;\n    return 0;\n}',NULL,1),
(27,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        int x = scanner.nextInt();\n        int y = scanner.nextInt();\n        int xor = x ^ y;\n        int distance = 0;\n        while (xor != 0) {\n            distance += xor & 1;\n            xor >>>= 1;\n        }\n        System.out.println(distance);\n    }\n}',NULL,1),
(27,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const [x, y] = line.trim().split(/\\s+/).map(Number);\n    let xor = x ^ y;\n    let distance = 0;\n    while (xor !== 0) {\n        distance += xor & 1;\n        xor >>>= 1;\n    }\n    console.log(distance);\n    rl.close();\n});',NULL,1),
(27,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().split()\n    if len(data) < 2:\n        return\n    x = int(data[0])\n    y = int(data[1])\n    xor = x ^ y\n    distance = 0\n    while xor != 0:\n        distance += xor & 1\n        xor >>= 1\n    print(distance)\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(28,'C','#include <stdio.h>\n#include <stdint.h>\n\nint main() {\n    uint32_t n;\n    scanf(\"%u\", &n);\n    uint32_t result = 0;\n    for (int i = 0; i < 32; i++) {\n        result <<= 1;\n        result |= (n & 1);\n        n >>= 1;\n    }\n    printf(\"%u\\n\", result);\n    return 0;\n}',NULL,1),
