(28,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        long n = scanner.nextLong();\n        int result = 0;\n        for (int i = 0; i < 32; i++) {\n            result = (result << 1) | ((int)(n >> i) & 1);\n        }\n        System.out.println(Integer.toUnsignedString(result));\n    }\n}',NULL,1),
(28,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    let n = BigInt(line.trim());\n    let result = 0;\n    for (let i = 0; i < 32; i++) {\n        result = (result << 1) >>> 0;\n        result = (result | Number(n & 1n)) >>> 0;\n        n >>= 1n;\n    }\n    console.log(result >>> 0);\n    rl.close();\n});',NULL,1),
