(29,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int ans = 0;\n        for (int i = 0; i < n; i++) {\n            ans ^= sc.nextInt();\n        }\n        System.out.println(ans);\n    }\n}',NULL,1),
(29,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const n = parseInt(lines[0]);\n        const nums = lines[1].split(/\\s+/).map(Number);\n        let ans = 0;\n        for (let i = 0; i < n; i++) {\n            ans ^= nums[i];\n        }\n        console.log(ans);\n        rl.close();\n    }\n});',NULL,1),
