(31,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const n = parseInt(line.trim());\n    let a = 0, b = 1;\n    for (let i = 1; i < n; i++) {\n        const c = a + b;\n        a = b;\n        b = c;\n    }\n    console.log(n === 0 ? 0 : b);\n    rl.close();\n});',NULL,1),
