(32,'C','#include <stdio.h>\n#include <string.h>\n\nint getValue(char c) {\n    switch (c) {\n        case \'I\': return 1;\n        case \'V\': return 5;\n        case \'X\': return 10;\n        case \'L\': return 50;\n        case \'C\': return 100;\n        case \'D\': return 500;\n        case \'M\': return 1000;\n        default: return 0;\n    }\n}\n\nint main() {\n    char s[1000];\n    if (fgets(s, sizeof(s), stdin) == NULL) return 0;\n    s[strcspn(s, \"\\n\")] = \'\\0\';\n    int result = 0;\n    int prev = 0;\n    int len = strlen(s);\n    for (int i = len - 1; i >= 0; i--) {\n        int value = getValue(s[i]);\n        if (value < prev) {\n            result -= value;\n        } else {\n            result += value;\n            prev = value;\n        }\n    }\n    printf(\"%d\\n\", result);\n    return 0;\n}',NULL,1),
(32,'CPP','#include <iostream>\n#include <string>\nusing namespace std;\n\nint getValue(char c) {\n    switch (c) {\n        case \'I\': return 1;\n        case \'V\': return 5;\n        case \'X\': return 10;\n        case \'L\': return 50;\n        case \'C\': return 100;\n        case \'D\': return 500;\n        case \'M\': return 1000;\n        default: return 0;\n    }\n}\n\nint main() {\n    string s;\n    getline(cin, s);\n    int result = 0;\n    int prev = 0;\n    for (int i = s.length() - 1; i >= 0; i--) {\n        int value = getValue(s[i]);\n        if (value < prev) {\n            result -= value;\n        } else {\n            result += value;\n            prev = value;\n        }\n    }\n    cout << result << endl;\n    return 0;\n}',NULL,1),
(32,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        String s = scanner.nextLine().trim();\n        int result = 0;\n        int prev = 0;\n        for (int i = s.length() - 1; i >= 0; i--) {\n            int curr = value(s.charAt(i));\n            if (curr < prev) {\n                result -= curr;\n            } else {\n                result += curr;\n            }\n            prev = curr;\n        }\n        System.out.println(result);\n    }\n\n    private static int value(char c) {\n        switch (c) {\n            case \'I\': return 1;\n            case \'V\': return 5;\n            case \'X\': return 10;\n            case \'L\': return 50;\n            case \'C\': return 100;\n            case \'D\': return 500;\n            case \'M\': return 1000;\n            default: return 0;\n        }\n    }\n}',NULL,1),
(32,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (input) => {\n    const s = input.trim();\n    let result = 0;\n    let prev = 0;\n    for (let i = s.length - 1; i >= 0; i--) {\n        const value = getValue(s[i]);\n        if (value < prev) {\n            result -= value;\n        } else {\n            result += value;\n            prev = value;\n        }\n    }\n    console.log(result);\n    rl.close();\n});\n\nfunction getValue(c) {\n    switch (c) {\n        case \'I\': return 1;\n        case \'V\': return 5;\n        case \'X\': return 10;\n        case \'L\': return 50;\n        case \'C\': return 100;\n        case \'D\': return 500;\n        case \'M\': return 1000;\n        default: return 0;\n    }\n}',NULL,1),
(32,'PYTHON','s = input().strip()\nresult = 0\nprev = 0\nvalues = {\'I\': 1, \'V\': 5, \'X\': 10, \'L\': 50, \'C\': 100, \'D\': 500, \'M\': 1000}\nfor c in reversed(s):\n    value = values.get(c, 0)\n    if value < prev:\n        result -= value\n    else:\n        result += value\n        prev = value\nprint(result)',NULL,1),
(33,'C','#include <stdio.h>\n#include <limits.h>\n\nint main() {\n    int x;\n    scanf(\"%d\", &x);\n    int rev = 0;\n    while (x != 0) {\n        int pop = x % 10;\n        x /= 10;\n        if (rev > INT_MAX / 10 || (rev == INT_MAX / 10 && pop > 7)) {\n            printf(\"0\\n\");\n            return 0;\n        }\n        if (rev < INT_MIN / 10 || (rev == INT_MIN / 10 && pop < -8)) {\n            printf(\"0\\n\");\n            return 0;\n        }\n        rev = rev * 10 + pop;\n    }\n    printf(\"%d\\n\", rev);\n    return 0;\n}',NULL,1),
(33,'CPP','#include <iostream>\n#include <climits>\n\nint main() {\n    int x;\n    std::cin >> x;\n    int rev = 0;\n    while (x != 0) {\n        int pop = x % 10;\n        x /= 10;\n        if (rev > INT_MAX / 10 || (rev == INT_MAX / 10 && pop > 7)) {\n            std::cout << 0 << std::endl;\n            return 0;\n        }\n        if (rev < INT_MIN / 10 || (rev == INT_MIN / 10 && pop < -8)) {\n            std::cout << 0 << std::endl;\n            return 0;\n        }\n        rev = rev * 10 + pop;\n    }\n    std::cout << rev << std::endl;\n    return 0;\n}',NULL,1),
(33,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int x = sc.nextInt();\n        int rev = 0;\n        while (x != 0) {\n            int pop = x % 10;\n            x /= 10;\n            if (rev > Integer.MAX_VALUE / 10 || (rev == Integer.MAX_VALUE / 10 && pop > 7)) {\n                System.out.println(0);\n                return;\n            }\n            if (rev < Integer.MIN_VALUE / 10 || (rev == Integer.MIN_VALUE / 10 && pop < -8)) {\n                System.out.println(0);\n                return;\n            }\n            rev = rev * 10 + pop;\n        }\n        System.out.println(rev);\n    }\n}',NULL,1),
(33,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    let x = parseInt(line.trim(), 10);\n    let rev = 0;\n    while (x !== 0) {\n        let pop = x % 10;\n        x = Math.trunc(x / 10);\n        if (rev > 214748364 || (rev === 214748364 && pop > 7)) {\n            console.log(0);\n            rl.close();\n            return;\n        }\n        if (rev < -214748364 || (rev === -214748364 && pop < -8)) {\n            console.log(0);\n            rl.close();\n            return;\n        }\n        rev = rev * 10 + pop;\n    }\n    console.log(rev);\n    rl.close();\n});',NULL,1),
(33,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    x = int(data[0])\n    rev = 0\n    INT_MAX = 2**31 - 1\n    INT_MIN = -2**31\n    while x != 0:\n        pop = x % 10\n        x = int(x / 10)\n        if rev > INT_MAX // 10 or (rev == INT_MAX // 10 and pop > 7):\n            print(0)\n            return\n        if rev < INT_MIN // 10 or (rev == INT_MIN // 10 and pop < -8):\n            print(0)\n            return\n        rev = rev * 10 + pop\n    print(rev)\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(34,'C','#include <stdio.h>\n#include <stdbool.h>\n\nbool isPalindrome(int x) {\n    if (x < 0 || (x % 10 == 0 && x != 0)) {\n        return false;\n    }\n    int reversed = 0;\n    while (x > reversed) {\n        reversed = reversed * 10 + x % 10;\n        x /= 10;\n    }\n    return x == reversed || x == reversed / 10;\n}\n\nint main() {\n    int x;\n    if (scanf(\"%d\", &x) == 1) {\n        if (isPalindrome(x)) {\n            printf(\"true\\n\");\n        } else {\n            printf(\"false\\n\");\n        }\n    }\n    return 0;\n}',NULL,1),
(34,'CPP','#include <iostream>\nusing namespace std;\n\nbool isPalindrome(int x) {\n    if (x < 0 || (x % 10 == 0 && x != 0)) {\n        return false;\n    }\n    int reversed = 0;\n    while (x > reversed) {\n        reversed = reversed * 10 + x % 10;\n        x /= 10;\n    }\n    return x == reversed || x == reversed / 10;\n}\n\nint main() {\n    int x;\n    if (cin >> x) {\n        cout << (isPalindrome(x) ? \"true\" : \"false\") << endl;\n    }\n    return 0;\n}',NULL,1),
(34,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        int x = scanner.nextInt();\n        System.out.println(isPalindrome(x));\n    }\n\n    private static boolean isPalindrome(int x) {\n        if (x < 0 || (x % 10 == 0 && x != 0)) {\n            return false;\n        }\n        int reversed = 0;\n        while (x > reversed) {\n            reversed = reversed * 10 + x % 10;\n            x /= 10;\n        }\n        return x == reversed || x == reversed / 10;\n    }\n}',NULL,1),
(34,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const x = parseInt(line.trim(), 10);\n    if (!isNaN(x)) {\n        console.log(isPalindrome(x));\n    }\n    rl.close();\n});\n\nfunction isPalindrome(x) {\n    if (x < 0 || (x % 10 === 0 && x !== 0)) {\n        return false;\n    }\n    let reversed = 0;\n    while (x > reversed) {\n        reversed = reversed * 10 + x % 10;\n        x = Math.floor(x / 10);\n    }\n    return x === reversed || x === Math.floor(reversed / 10);\n}',NULL,1),
(34,'PYTHON','import sys\n\ndef is_palindrome(x):\n    if x < 0 or (x % 10 == 0 and x != 0):\n        return False\n    reversed_num = 0\n    while x > reversed_num:\n        reversed_num = reversed_num * 10 + x % 10\n        x //= 10\n    return x == reversed_num or x == reversed_num // 10\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if data:\n        x = int(data[0])\n        print(\"true\" if is_palindrome(x) else \"false\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(35,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nchar* multiply(char* num1, char* num2) {\n    if (strcmp(num1, \"0\") == 0 || strcmp(num2, \"0\") == 0) {\n        char* zero = (char*)malloc(2);\n        zero[0] = \'0\';\n        zero[1] = \'\\0\';\n        return zero;\n    }\n    int m = strlen(num1);\n    int n = strlen(num2);\n    int* res = (int*)calloc(m + n, sizeof(int));\n    for (int i = m - 1; i >= 0; i--) {\n        for (int j = n - 1; j >= 0; j--) {\n            int mul = (num1[i] - \'0\') * (num2[j] - \'0\');\n            int p1 = i + j;\n            int p2 = i + j + 1;\n            int sum = mul + res[p2];\n            res[p2] = sum % 10;\n            res[p1] += sum / 10;\n        }\n    }\n    char* result = (char*)malloc(m + n + 1);\n    int idx = 0;\n    int i = 0;\n    while (i < m + n && res[i] == 0) i++;\n    while (i < m + n) {\n        result[idx++] = res[i] + \'0\';\n        i++;\n    }\n    result[idx] = \'\\0\';\n    free(res);\n    return result;\n}\n\nint main() {\n    char num1[1000], num2[1000];\n    scanf(\"%s %s\", num1, num2);\n    char* result = multiply(num1, num2);\n    printf(\"%s\\n\", result);\n    free(result);\n    return 0;\n}',NULL,1),
(35,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n\nusing namespace std;\n\nstring multiply(string num1, string num2) {\n    if (num1 == \"0\" || num2 == \"0\") {\n        return \"0\";\n    }\n    int m = num1.length();\n    int n = num2.length();\n    vector<int> res(m + n, 0);\n    for (int i = m - 1; i >= 0; i--) {\n        int x = num1[i] - \'0\';\n        for (int j = n - 1; j >= 0; j--) {\n            int y = num2[j] - \'0\';\n            int sum = res[i + j + 1] + x * y;\n            res[i + j + 1] = sum % 10;\n            res[i + j] += sum / 10;\n        }\n    }\n    string sb;\n    for (int i = 0; i < (int)res.size(); i++) {\n        if (sb.empty() && res[i] == 0) {\n            continue;\n        }\n        sb += to_string(res[i]);\n    }\n    return sb;\n}\n\nint main() {\n    string num1, num2;\n    cin >> num1 >> num2;\n    cout << multiply(num1, num2) << endl;\n    return 0;\n}',NULL,1),
(35,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String num1 = sc.next();\n        String num2 = sc.next();\n        System.out.println(multiply(num1, num2));\n    }\n\n    public static String multiply(String num1, String num2) {\n        if (\"0\".equals(num1) || \"0\".equals(num2)) {\n            return \"0\";\n        }\n        int m = num1.length();\n        int n = num2.length();\n        int[] res = new int[m + n];\n        for (int i = m - 1; i >= 0; i--) {\n            int x = num1.charAt(i) - \'0\';\n            for (int j = n - 1; j >= 0; j--) {\n                int y = num2.charAt(j) - \'0\';\n                int sum = res[i + j + 1] + x * y;\n                res[i + j + 1] = sum % 10;\n                res[i + j] += sum / 10;\n            }\n        }\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < res.length; i++) {\n            if (sb.length() == 0 && res[i] == 0) {\n                continue;\n            }\n            sb.append(res[i]);\n        }\n        return sb.toString();\n    }\n}',NULL,1),
(35,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet input = [];\nrl.on(\'line\', (line) => {\n    input.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const [num1, num2] = input[0].split(\' \');\n    console.log(multiply(num1, num2));\n});\n\nfunction multiply(num1, num2) {\n    if (num1 === \"0\" || num2 === \"0\") {\n        return \"0\";\n    }\n    const m = num1.length;\n    const n = num2.length;\n    const res = new Array(m + n).fill(0);\n    for (let i = m - 1; i >= 0; i--) {\n        const x = num1.charCodeAt(i) - \'0\'.charCodeAt(0);\n        for (let j = n - 1; j >= 0; j--) {\n            const y = num2.charCodeAt(j) - \'0\'.charCodeAt(0);\n            const sum = res[i + j + 1] + x * y;\n            res[i + j + 1] = sum % 10;\n            res[i + j] += Math.floor(sum / 10);\n        }\n    }\n    let sb = \"\";\n    for (let i = 0; i < res.length; i++) {\n        if (sb.length === 0 && res[i] === 0) {\n            continue;\n        }\n        sb += res[i];\n    }\n    return sb;\n}',NULL,1),
(35,'PYTHON','import sys\n\ndef multiply(num1, num2):\n    if num1 == \"0\" or num2 == \"0\":\n        return \"0\"\n    m, n = len(num1), len(num2)\n    res = [0] * (m + n)\n    for i in range(m - 1, -1, -1):\n        x = ord(num1[i]) - ord(\'0\')\n        for j in range(n - 1, -1, -1):\n            y = ord(num2[j]) - ord(\'0\')\n            total = res[i + j + 1] + x * y\n            res[i + j + 1] = total % 10\n            res[i + j] += total // 10\n    result = []\n    for num in res:\n        if not result and num == 0:\n            continue\n        result.append(str(num))\n    return \'\'.join(result)\n\ndef main():\n    data = sys.stdin.read().split()\n    num1, num2 = data[0], data[1]\n    print(multiply(num1, num2))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(36,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nstruct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n};\n\nstatic int maxDepth(struct TreeNode* root) {\n    if (root == NULL) return 0;\n    int left = maxDepth(root->left);\n    int right = maxDepth(root->right);\n    return 1 + (left > right ? left : right);\n}\n\nstatic struct TreeNode* newNode(int val) {\n    struct TreeNode* node = (struct TreeNode*)malloc(sizeof(struct TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nint main(void) {\n    char line[1000000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n\n    size_t len = strlen(line);\n    while (len > 0 && (line[len - 1] == \'\\n\' || line[len - 1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n\n    char *start = line;\n    while (*start == \' \' || *start == \'\\t\') start++;\n    char *end = start + strlen(start);\n    while (end > start && (end[-1] == \' \' || end[-1] == \'\\t\')) {\n        *--end = \'\\0\';\n    }\n\n    if (*start == \'[\') {\n        start++;\n        if (end > start && end[-1] == \']\') {\n            end[-1] = \'\\0\';\n        }\n    }\n\n    if (*start == \'\\0\') {\n        printf(\"0\\n\");\n        return 0;\n    }\n\n    int capacity = 1024;\n    int *nums = (int*)malloc(sizeof(int) * capacity);\n    int *isNull = (int*)malloc(sizeof(int) * capacity);\n    int count = 0;\n\n    char *token = strtok(start, \",\");\n    while (token != NULL) {\n        while (*token == \' \' || *token == \'\\t\') token++;\n        char *tend = token + strlen(token);\n        while (tend > token && (tend[-1] == \' \' || tend[-1] == \'\\t\')) {\n            *--tend = \'\\0\';\n        }\n\n        if (count >= capacity) {\n            capacity *= 2;\n            nums = (int*)realloc(nums, sizeof(int) * capacity);\n            isNull = (int*)realloc(isNull, sizeof(int) * capacity);\n        }\n\n        if (strcmp(token, \"null\") == 0) {\n            isNull[count] = 1;\n            nums[count] = 0;\n        } else {\n            isNull[count] = 0;\n            nums[count] = atoi(token);\n        }\n        count++;\n        token = strtok(NULL, \",\");\n    }\n\n    if (count == 0 || isNull[0]) {\n        printf(\"0\\n\");\n        free(nums);\n        free(isNull);\n        return 0;\n    }\n\n    struct TreeNode **queue = (struct TreeNode**)malloc(sizeof(struct TreeNode*) * (count + 1));\n    int head = 0, tail = 0;\n\n    struct TreeNode *root = newNode(nums[0]);\n    queue[tail++] = root;\n    int i = 1;\n\n    while (head < tail && i < count) {\n        struct TreeNode *node = queue[head++];\n\n        if (i < count && !isNull[i]) {\n            node->left = newNode(nums[i]);\n            queue[tail++] = node->left;\n        }\n        i++;\n\n        if (i < count && !isNull[i]) {\n            node->right = newNode(nums[i]);\n            queue[tail++] = node->right;\n        }\n        i++;\n    }\n\n    printf(\"%d\\n\", maxDepth(root));\n\n    free(queue);\n    free(nums);\n    free(isNull);\n    return 0;\n}',NULL,1),
(36,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <sstream>\n#include <algorithm>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode *left;\n    TreeNode *right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(vector<string>& nums) {\n    if (nums.empty() || nums[0] == \"null\") return nullptr;\n    TreeNode* root = new TreeNode(stoi(nums[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)nums.size()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (i < (int)nums.size() && nums[i] != \"null\") {\n            node->left = new TreeNode(stoi(nums[i]));\n            q.push(node->left);\n        }\n        i++;\n        if (i < (int)nums.size() && nums[i] != \"null\") {\n            node->right = new TreeNode(stoi(nums[i]));\n            q.push(node->right);\n        }\n        i++;\n    }\n    return root;\n}\n\nint maxDepth(TreeNode* root) {\n    if (root == nullptr) return 0;\n    return 1 + max(maxDepth(root->left), maxDepth(root->right));\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    while (!line.empty() && (line.front() == \' \' || line.front() == \'\\t\')) line.erase(line.begin());\n    while (!line.empty() && (line.back() == \' \' || line.back() == \'\\t\' || line.back() == \'\\r\')) line.pop_back();\n    if (!line.empty() && line.front() == \'[\') {\n        line = line.substr(1, line.size() - 2);\n    }\n    if (line.empty()) {\n        cout << 0 << endl;\n        return 0;\n    }\n    vector<string> parts;\n    stringstream ss(line);\n    string token;\n    while (getline(ss, token, \',\')) {\n        size_t start = token.find_first_not_of(\" \\t\");\n        size_t end = token.find_last_not_of(\" \\t\");\n        if (start == string::npos) {\n            parts.push_back(\"\");\n        } else {\n            parts.push_back(token.substr(start, end - start + 1));\n        }\n    }\n    TreeNode* root = buildTree(parts);\n    cout << maxDepth(root) << endl;\n    return 0;\n}',NULL,1),
(36,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.startsWith(\"[\")) {\n            line = line.substring(1, line.length() - 1);\n        }\n        if (line.isEmpty()) {\n            System.out.println(0);\n            return;\n        }\n        String[] parts = line.split(\",\");\n        Integer[] nums = new Integer[parts.length];\n        for (int i = 0; i < parts.length; i++) {\n            String s = parts[i].trim();\n            if (s.equals(\"null\")) {\n                nums[i] = null;\n            } else {\n                nums[i] = Integer.parseInt(s);\n            }\n        }\n        TreeNode root = buildTree(nums);\n        System.out.println(maxDepth(root));\n    }\n\n    private static TreeNode buildTree(Integer[] nums) {\n        if (nums == null || nums.length == 0 || nums[0] == null) {\n            return null;\n        }\n        TreeNode root = new TreeNode(nums[0]);\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < nums.length) {\n            TreeNode node = queue.poll();\n            if (i < nums.length && nums[i] != null) {\n                node.left = new TreeNode(nums[i]);\n                queue.offer(node.left);\n            }\n            i++;\n            if (i < nums.length && nums[i] != null) {\n                node.right = new TreeNode(nums[i]);\n                queue.offer(node.right);\n            }\n            i++;\n        }\n        return root;\n    }\n\n    private static int maxDepth(TreeNode root) {\n        if (root == null) {\n            return 0;\n        }\n        return 1 + Math.max(maxDepth(root.left), maxDepth(root.right));\n    }\n\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) {\n            this.val = val;\n        }\n    }\n}',NULL,1),
(36,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (input) => {\n    let line = input.trim();\n    if (line.startsWith(\'[\')) {\n        line = line.substring(1, line.length - 1);\n    }\n    if (line.length === 0) {\n        console.log(0);\n        rl.close();\n        return;\n    }\n    const parts = line.split(\',\');\n    const nums = parts.map(s => {\n        s = s.trim();\n        return s === \'null\' ? null : parseInt(s, 10);\n    });\n\n    const root = buildTree(nums);\n    console.log(maxDepth(root));\n    rl.close();\n});\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(nums) {\n    if (!nums || nums.length === 0 || nums[0] === null) return null;\n    const root = new TreeNode(nums[0]);\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < nums.length) {\n        const node = queue.shift();\n        if (i < nums.length && nums[i] !== null) {\n            node.left = new TreeNode(nums[i]);\n            queue.push(node.left);\n        }\n        i++;\n        if (i < nums.length && nums[i] !== null) {\n            node.right = new TreeNode(nums[i]);\n            queue.push(node.right);\n        }\n        i++;\n    }\n    return root;\n}\n\nfunction maxDepth(root) {\n    if (root === null) return 0;\n    return 1 + Math.max(maxDepth(root.left), maxDepth(root.right));\n}',NULL,1),
(36,'PYTHON','import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef build_tree(nums):\n    if not nums or nums[0] is None:\n        return None\n    root = TreeNode(nums[0])\n    queue = deque([root])\n    i = 1\n    while queue and i < len(nums):\n        node = queue.popleft()\n        if i < len(nums) and nums[i] is not None:\n            node.left = TreeNode(nums[i])\n            queue.append(node.left)\n        i += 1\n        if i < len(nums) and nums[i] is not None:\n            node.right = TreeNode(nums[i])\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef max_depth(root):\n    if root is None:\n        return 0\n    return 1 + max(max_depth(root.left), max_depth(root.right))\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line.startswith(\"[\"):\n        line = line[1:-1]\n    if not line:\n        print(0)\n        return\n    parts = line.split(\",\")\n    nums = []\n    for s in parts:\n        s = s.strip()\n        if s == \"null\":\n            nums.append(None)\n        else:\n            nums.append(int(s))\n    root = build_tree(nums)\n    print(max_depth(root))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(37,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <ctype.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\ntypedef struct {\n    TreeNode **data;\n    int front;\n    int rear;\n    int size;\n} Queue;\n\nvoid initQueue(Queue *q, int size) {\n    q->data = (TreeNode **)malloc(sizeof(TreeNode *) * size);\n    q->front = 0;\n    q->rear = 0;\n    q->size = size;\n}\n\nvoid enqueue(Queue *q, TreeNode *node) {\n    q->data[q->rear++] = node;\n}\n\nTreeNode *dequeue(Queue *q) {\n    return q->data[q->front++];\n}\n\nint isEmpty(Queue *q) {\n    return q->front == q->rear;\n}\n\nTreeNode *newNode(int val) {\n    TreeNode *node = (TreeNode *)malloc(sizeof(TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nTreeNode *buildTree(char *s) {\n    int len = strlen(s);\n    while (len > 0 && isspace(s[len - 1])) {\n        s[--len] = \'\\0\';\n    }\n    int start = 0;\n    while (start < len && isspace(s[start])) {\n        start++;\n    }\n    if (len - start <= 2) return NULL;\n    char *content = (char *)malloc(sizeof(char) * (len - start));\n    strncpy(content, s + start + 1, len - start - 2);\n    content[len - start - 2] = \'\\0\';\n\n    char *trimmed = content;\n    while (*trimmed && isspace(*trimmed)) trimmed++;\n    if (*trimmed == \'\\0\') {\n        free(content);\n        return NULL;\n    }\n\n    char *parts[10000];\n    int partCount = 0;\n    char *token = strtok(content, \",\");\n    while (token != NULL) {\n        parts[partCount++] = token;\n        token = strtok(NULL, \",\");\n    }\n\n    char *first = parts[0];\n    while (*first && isspace(*first)) first++;\n    if (strcmp(first, \"null\") == 0) {\n        free(content);\n        return NULL;\n    }\n\n    TreeNode *root = newNode(atoi(first));\n    Queue q;\n    initQueue(&q, partCount + 1);\n    enqueue(&q, root);\n    int i = 1;\n    while (!isEmpty(&q) && i < partCount) {\n        TreeNode *node = dequeue(&q);\n        if (i < partCount) {\n            char *leftVal = parts[i];\n            while (*leftVal && isspace(*leftVal)) leftVal++;\n            if (strcmp(leftVal, \"null\") != 0) {\n                node->left = newNode(atoi(leftVal));\n                enqueue(&q, node->left);\n            }\n            i++;\n        }\n        if (i < partCount) {\n            char *rightVal = parts[i];\n            while (*rightVal && isspace(*rightVal)) rightVal++;\n            if (strcmp(rightVal, \"null\") != 0) {\n                node->right = newNode(atoi(rightVal));\n                enqueue(&q, node->right);\n            }\n            i++;\n        }\n    }\n    free(q.data);\n    free(content);\n    return root;\n}\n\nint **levelOrder(TreeNode *root, int **columnSizes, int *returnSize) {\n    *returnSize = 0;\n    if (root == NULL) {\n        *columnSizes = NULL;\n        return NULL;\n    }\n\n    int capacity = 10000;\n    int **result = (int **)malloc(sizeof(int *) * capacity);\n    *columnSizes = (int *)malloc(sizeof(int) * capacity);\n\n    Queue q;\n    initQueue(&q, capacity);\n    enqueue(&q, root);\n\n    while (!isEmpty(&q)) {\n        int size = q.rear - q.front;\n        int *level = (int *)malloc(sizeof(int) * size);\n        for (int i = 0; i < size; i++) {\n            TreeNode *node = dequeue(&q);\n            level[i] = node->val;\n            if (node->left != NULL) enqueue(&q, node->left);\n            if (node->right != NULL) enqueue(&q, node->right);\n        }\n        result[*returnSize] = level;\n        (*columnSizes)[*returnSize] = size;\n        (*returnSize)++;\n    }\n\n    free(q.data);\n    return result;\n}\n\nvoid printResult(int **result, int *columnSizes, int returnSize) {\n    printf(\"[\");\n    for (int i = 0; i < returnSize; i++) {\n        printf(\"[\");\n        for (int j = 0; j < columnSizes[i]; j++) {\n            printf(\"%d\", result[i][j]);\n            if (j < columnSizes[i] - 1) printf(\",\");\n        }\n        printf(\"]\");\n        if (i < returnSize - 1) printf(\",\");\n    }\n    printf(\"]\\n\");\n}\n\nint main() {\n    char s[100000];\n    if (fgets(s, sizeof(s), stdin) == NULL) return 0;\n    int len = strlen(s);\n    while (len > 0 && (s[len - 1] == \'\\n\' || s[len - 1] == \'\\r\')) {\n        s[--len] = \'\\0\';\n    }\n\n    TreeNode *root = buildTree(s);\n    int *columnSizes;\n    int returnSize;\n    int **result = levelOrder(root, &columnSizes, &returnSize);\n    printResult(result, columnSizes, returnSize);\n\n    return 0;\n}',NULL,1),
(37,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <sstream>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode* left;\n    TreeNode* right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(const string& s) {\n    string str = s;\n    size_t start = str.find_first_not_of(\" \\t\\n\\r\");\n    size_t end = str.find_last_not_of(\" \\t\\n\\r\");\n    if (start == string::npos) return nullptr;\n    str = str.substr(start, end - start + 1);\n    if (str.length() <= 2) return nullptr;\n    string content = str.substr(1, str.length() - 2);\n    size_t cstart = content.find_first_not_of(\" \\t\\n\\r\");\n    size_t cend = content.find_last_not_of(\" \\t\\n\\r\");\n    if (cstart == string::npos) return nullptr;\n    content = content.substr(cstart, cend - cstart + 1);\n    if (content.empty()) return nullptr;\n\n    vector<string> parts;\n    stringstream ss(content);\n    string item;\n    while (getline(ss, item, \',\')) {\n        size_t istart = item.find_first_not_of(\" \\t\\n\\r\");\n        size_t iend = item.find_last_not_of(\" \\t\\n\\r\");\n        if (istart == string::npos) {\n            parts.push_back(\"\");\n        } else {\n            parts.push_back(item.substr(istart, iend - istart + 1));\n        }\n    }\n\n    if (parts.empty() || parts[0] == \"null\") return nullptr;\n\n    TreeNode* root = new TreeNode(stoi(parts[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)parts.size()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (i < (int)parts.size()) {\n            string leftVal = parts[i];\n            if (leftVal != \"null\") {\n                node->left = new TreeNode(stoi(leftVal));\n                q.push(node->left);\n            }\n            i++;\n        }\n        if (i < (int)parts.size()) {\n            string rightVal = parts[i];\n            if (rightVal != \"null\") {\n                node->right = new TreeNode(stoi(rightVal));\n                q.push(node->right);\n            }\n            i++;\n        }\n    }\n    return root;\n}\n\nvector<vector<int>> levelOrder(TreeNode* root) {\n    vector<vector<int>> result;\n    if (root == nullptr) return result;\n    queue<TreeNode*> q;\n    q.push(root);\n    while (!q.empty()) {\n        int size = q.size();\n        vector<int> level;\n        for (int i = 0; i < size; i++) {\n            TreeNode* node = q.front();\n            q.pop();\n            level.push_back(node->val);\n            if (node->left != nullptr) q.push(node->left);\n            if (node->right != nullptr) q.push(node->right);\n        }\n        result.push_back(level);\n    }\n    return result;\n}\n\nstring format(const vector<vector<int>>& result) {\n    string sb;\n    sb += \"[\";\n    for (int i = 0; i < (int)result.size(); i++) {\n        sb += \"[\";\n        const vector<int>& level = result[i];\n        for (int j = 0; j < (int)level.size(); j++) {\n            sb += to_string(level[j]);\n            if (j < (int)level.size() - 1) sb += \",\";\n        }\n        sb += \"]\";\n        if (i < (int)result.size() - 1) sb += \",\";\n    }\n    sb += \"]\";\n    return sb;\n}\n\nint main() {\n    string s;\n    getline(cin, s);\n    TreeNode* root = buildTree(s);\n    vector<vector<int>> result = levelOrder(root);\n    cout << format(result) << endl;\n    return 0;\n}',NULL,1),
(37,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.nextLine().trim();\n        if (s.startsWith(\"[\")) s = s.substring(1, s.length() - 1);\n        String[] parts = s.isEmpty() ? new String[0] : s.split(\",\");\n        TreeNode root = buildTree(parts);\n        List<List<Integer>> res = levelOrder(root);\n        System.out.println(format(res));\n    }\n\n    static TreeNode buildTree(String[] parts) {\n        if (parts.length == 0 || parts[0].trim().equals(\"null\")) return null;\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        Queue<TreeNode> q = new LinkedList<>();\n        q.offer(root);\n        int i = 1;\n        while (!q.isEmpty() && i < parts.length) {\n            TreeNode cur = q.poll();\n            if (i < parts.length) {\n                String left = parts[i++].trim();\n                if (!left.equals(\"null\")) {\n                    cur.left = new TreeNode(Integer.parseInt(left));\n                    q.offer(cur.left);\n                }\n            }\n            if (i < parts.length) {\n                String right = parts[i++].trim();\n                if (!right.equals(\"null\")) {\n                    cur.right = new TreeNode(Integer.parseInt(right));\n                    q.offer(cur.right);\n                }\n            }\n        }\n        return root;\n    }\n\n    static List<List<Integer>> levelOrder(TreeNode root) {\n        List<List<Integer>> res = new ArrayList<>();\n        if (root == null) return res;\n        Queue<TreeNode> q = new LinkedList<>();\n        q.offer(root);\n        while (!q.isEmpty()) {\n            int size = q.size();\n            List<Integer> level = new ArrayList<>();\n            for (int i = 0; i < size; i++) {\n                TreeNode node = q.poll();\n                level.add(node.val);\n                if (node.left != null) q.offer(node.left);\n                if (node.right != null) q.offer(node.right);\n            }\n            res.add(level);\n        }\n        return res;\n    }\n\n    static String format(List<List<Integer>> res) {\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < res.size(); i++) {\n            sb.append(\"[\");\n            List<Integer> level = res.get(i);\n            for (int j = 0; j < level.size(); j++) {\n                sb.append(level.get(j));\n                if (j < level.size() - 1) sb.append(\",\");\n            }\n            sb.append(\"]\");\n            if (i < res.size() - 1) sb.append(\",\");\n        }\n        sb.append(\"]\");\n        return sb.toString();\n    }\n\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) { this.val = val; }\n    }\n}',NULL,1),
(37,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(s) {\n    s = s.trim();\n    if (s.length <= 2) return null;\n    const content = s.substring(1, s.length - 1).trim();\n    if (content.length === 0) return null;\n    const parts = content.split(\',\');\n    if (parts.length === 0 || parts[0].trim() === \'null\') return null;\n    const root = new TreeNode(parseInt(parts[0].trim(), 10));\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < parts.length) {\n        const node = queue.shift();\n        if (i < parts.length) {\n            const leftVal = parts[i].trim();\n            if (leftVal !== \'null\') {\n                node.left = new TreeNode(parseInt(leftVal, 10));\n                queue.push(node.left);\n            }\n            i++;\n        }\n        if (i < parts.length) {\n            const rightVal = parts[i].trim();\n            if (rightVal !== \'null\') {\n                node.right = new TreeNode(parseInt(rightVal, 10));\n                queue.push(node.right);\n            }\n            i++;\n        }\n    }\n    return root;\n}\n\nfunction levelOrder(root) {\n    const result = [];\n    if (root === null) return result;\n    const queue = [root];\n    while (queue.length > 0) {\n        const size = queue.length;\n        const level = [];\n        for (let i = 0; i < size; i++) {\n            const node = queue.shift();\n            level.push(node.val);\n            if (node.left !== null) queue.push(node.left);\n            if (node.right !== null) queue.push(node.right);\n        }\n        result.push(level);\n    }\n    return result;\n}\n\nfunction format(result) {\n    let sb = \'\';\n    sb += \'[\';\n    for (let i = 0; i < result.length; i++) {\n        sb += \'[\';\n        const level = result[i];\n        for (let j = 0; j < level.length; j++) {\n            sb += level[j];\n            if (j < level.length - 1) sb += \',\';\n        }\n        sb += \']\';\n        if (i < result.length - 1) sb += \',\';\n    }\n    sb += \']\';\n    return sb;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const s = line.trim();\n    const root = buildTree(s);\n    const result = levelOrder(root);\n    console.log(format(result));\n    rl.close();\n});',NULL,1),
(37,'PYTHON','import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef build_tree(s):\n    s = s.strip()\n    if len(s) <= 2:\n        return None\n    content = s[1:-1].strip()\n    if not content:\n        return None\n    parts = content.split(\',\')\n    if not parts or parts[0].strip() == \'null\':\n        return None\n    root = TreeNode(int(parts[0].strip()))\n    queue = deque([root])\n    i = 1\n    while queue and i < len(parts):\n        node = queue.popleft()\n        if i < len(parts):\n            left_val = parts[i].strip()\n            if left_val != \'null\':\n                node.left = TreeNode(int(left_val))\n                queue.append(node.left)\n            i += 1\n        if i < len(parts):\n            right_val = parts[i].strip()\n            if right_val != \'null\':\n                node.right = TreeNode(int(right_val))\n                queue.append(node.right)\n            i += 1\n    return root\n\ndef level_order(root):\n    result = []\n    if root is None:\n        return result\n    queue = deque([root])\n    while queue:\n        size = len(queue)\n        level = []\n        for _ in range(size):\n            node = queue.popleft()\n            level.append(node.val)\n            if node.left:\n                queue.append(node.left)\n            if node.right:\n                queue.append(node.right)\n        result.append(level)\n    return result\n\ndef format_result(result):\n    sb = []\n    sb.append(\'[\')\n    for i, level in enumerate(result):\n        sb.append(\'[\')\n        for j, val in enumerate(level):\n            sb.append(str(val))\n            if j < len(level) - 1:\n                sb.append(\',\')\n        sb.append(\']\')\n        if i < len(result) - 1:\n            sb.append(\',\')\n    sb.append(\']\')\n    return \'\'.join(sb)\n\ndef main():\n    s = sys.stdin.readline().strip()\n    root = build_tree(s)\n    result = level_order(root)\n    print(format_result(result))\n\nif __name__ == \'__main__\':\n    main()',NULL,1),
(38,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\nTreeNode* createNode(int val) {\n    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nTreeNode* buildTree(char** parts, int partsSize) {\n    if (partsSize == 0 || strcmp(parts[0], \"null\") == 0) {\n        return NULL;\n    }\n    TreeNode* root = createNode(atoi(parts[0]));\n    TreeNode** queue = (TreeNode**)malloc(sizeof(TreeNode*) * partsSize);\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    int i = 1;\n    while (front < rear && i < partsSize) {\n        TreeNode* node = queue[front++];\n        if (i < partsSize && strcmp(parts[i], \"null\") != 0) {\n            node->left = createNode(atoi(parts[i]));\n            queue[rear++] = node->left;\n        }\n        i++;\n        if (i < partsSize && strcmp(parts[i], \"null\") != 0) {\n            node->right = createNode(atoi(parts[i]));\n            queue[rear++] = node->right;\n        }\n        i++;\n    }\n    free(queue);\n    return root;\n}\n\nint* preorderTraversal(TreeNode* root, int* returnSize) {\n    int* result = (int*)malloc(sizeof(int) * 10000);\n    *returnSize = 0;\n    if (root == NULL) {\n        return result;\n    }\n    TreeNode** stack = (TreeNode**)malloc(sizeof(TreeNode*) * 10000);\n    int top = 0;\n    stack[top++] = root;\n    while (top > 0) {\n        TreeNode* node = stack[--top];\n        result[(*returnSize)++] = node->val;\n        if (node->right != NULL) {\n            stack[top++] = node->right;\n        }\n        if (node->left != NULL) {\n            stack[top++] = node->left;\n        }\n    }\n    free(stack);\n    return result;\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) {\n        printf(\"[]\\n\");\n        return 0;\n    }\n    int len = strlen(line);\n    while (len > 0 && (line[len-1] == \'\\n\' || line[len-1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    if (len == 0) {\n        printf(\"[]\\n\");\n        return 0;\n    }\n    char* content = line;\n    if (line[0] == \'[\' && line[len-1] == \']\') {\n        line[len-1] = \'\\0\';\n        content = line + 1;\n    }\n    char* parts[10000];\n    int partsSize = 0;\n    char* token = strtok(content, \",\");\n    while (token != NULL) {\n        while (*token == \' \') token++;\n        int tlen = strlen(token);\n        while (tlen > 0 && token[tlen-1] == \' \') {\n            token[--tlen] = \'\\0\';\n        }\n        parts[partsSize++] = token;\n        token = strtok(NULL, \",\");\n    }\n    TreeNode* root = buildTree(parts, partsSize);\n    int returnSize = 0;\n    int* result = preorderTraversal(root, &returnSize);\n    printf(\"[\");\n    for (int i = 0; i < returnSize; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"%d\", result[i]);\n    }\n    printf(\"]\\n\");\n    free(result);\n    return 0;\n}',NULL,1),
(38,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <stack>\n#include <sstream>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode *left;\n    TreeNode *right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(const vector<string>& parts) {\n    if (parts.empty() || parts[0] == \"null\") {\n        return nullptr;\n    }\n    TreeNode* root = new TreeNode(stoi(parts[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)parts.size()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (i < (int)parts.size() && parts[i] != \"null\") {\n            node->left = new TreeNode(stoi(parts[i]));\n            q.push(node->left);\n        }\n        i++;\n        if (i < (int)parts.size() && parts[i] != \"null\") {\n            node->right = new TreeNode(stoi(parts[i]));\n            q.push(node->right);\n        }\n        i++;\n    }\n    return root;\n}\n\nvector<int> preorderTraversal(TreeNode* root) {\n    vector<int> result;\n    if (root == nullptr) {\n        return result;\n    }\n    stack<TreeNode*> st;\n    st.push(root);\n    while (!st.empty()) {\n        TreeNode* node = st.top();\n        st.pop();\n        result.push_back(node->val);\n        if (node->right != nullptr) {\n            st.push(node->right);\n        }\n        if (node->left != nullptr) {\n            st.push(node->left);\n        }\n    }\n    return result;\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\')) {\n        line.pop_back();\n    }\n    if (line.empty()) {\n        cout << \"[]\" << endl;\n        return 0;\n    }\n    line = line.substr(1, line.length() - 2);\n    vector<string> parts;\n    stringstream ss(line);\n    string item;\n    while (getline(ss, item, \',\')) {\n        size_t start = item.find_first_not_of(\" \\t\");\n        size_t end = item.find_last_not_of(\" \\t\");\n        if (start == string::npos) {\n            parts.push_back(\"\");\n        } else {\n            parts.push_back(item.substr(start, end - start + 1));\n        }\n    }\n    TreeNode* root = buildTree(parts);\n    vector<int> result = preorderTraversal(root);\n    cout << \"[\";\n    for (size_t i = 0; i < result.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << result[i];\n    }\n    cout << \"]\" << endl;\n    return 0;\n}',NULL,1),
(38,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.isEmpty()) {\n            System.out.println(\"[]\");\n            return;\n        }\n        line = line.substring(1, line.length() - 1).trim();\n        if (line.isEmpty()) {\n            System.out.println(\"[]\");\n            return;\n        }\n        String[] parts = line.split(\",\");\n        Integer[] nums = new Integer[parts.length];\n        for (int i = 0; i < parts.length; i++) {\n            String s = parts[i].trim();\n            if (s.equals(\"null\")) {\n                nums[i] = null;\n            } else {\n                nums[i] = Integer.parseInt(s);\n            }\n        }\n        TreeNode root = buildTree(nums);\n        List<Integer> res = new ArrayList<>();\n        preorder(root, res);\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < res.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(res.get(i));\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n\n    private static TreeNode buildTree(Integer[] nums) {\n        if (nums == null || nums.length == 0 || nums[0] == null) return null;\n        TreeNode root = new TreeNode(nums[0]);\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < nums.length) {\n            TreeNode node = queue.poll();\n            if (i < nums.length && nums[i] != null) {\n                node.left = new TreeNode(nums[i]);\n                queue.offer(node.left);\n            }\n            i++;\n            if (i < nums.length && nums[i] != null) {\n                node.right = new TreeNode(nums[i]);\n                queue.offer(node.right);\n            }\n            i++;\n        }\n        return root;\n    }\n\n    private static void preorder(TreeNode root, List<Integer> res) {\n        if (root == null) return;\n        res.add(root.val);\n        preorder(root.left, res);\n        preorder(root.right, res);\n    }\n\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) {\n            this.val = val;\n        }\n    }\n}',NULL,1),
(38,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line === \'\') {\n        console.log(\'[]\');\n        rl.close();\n        return;\n    }\n    line = line.substring(1, line.length - 1);\n    const parts = line.split(\',\');\n    const root = buildTree(parts);\n    const result = preorderTraversal(root);\n    console.log(\'[\' + result.join(\',\') + \']\');\n    rl.close();\n});\n\nfunction buildTree(parts) {\n    if (parts.length === 0 || parts[0].trim() === \'null\') {\n        return null;\n    }\n    const root = new TreeNode(parseInt(parts[0].trim()));\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < parts.length) {\n        const node = queue.shift();\n        if (i < parts.length && parts[i].trim() !== \'null\') {\n            node.left = new TreeNode(parseInt(parts[i].trim()));\n            queue.push(node.left);\n        }\n        i++;\n        if (i < parts.length && parts[i].trim() !== \'null\') {\n            node.right = new TreeNode(parseInt(parts[i].trim()));\n            queue.push(node.right);\n        }\n        i++;\n    }\n    return root;\n}\n\nfunction preorderTraversal(root) {\n    const result = [];\n    if (root === null) {\n        return result;\n    }\n    const stack = [root];\n    while (stack.length > 0) {\n        const node = stack.pop();\n        result.push(node.val);\n        if (node.right !== null) {\n            stack.push(node.right);\n        }\n        if (node.left !== null) {\n            stack.push(node.left);\n        }\n    }\n    return result;\n}\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}',NULL,1),
(38,'PYTHON','import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef build_tree(parts):\n    if not parts or parts[0] == \"null\":\n        return None\n    root = TreeNode(int(parts[0]))\n    queue = deque([root])\n    i = 1\n    while queue and i < len(parts):\n        node = queue.popleft()\n        if i < len(parts) and parts[i] != \"null\":\n            node.left = TreeNode(int(parts[i]))\n            queue.append(node.left)\n        i += 1\n        if i < len(parts) and parts[i] != \"null\":\n            node.right = TreeNode(int(parts[i]))\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef preorder_traversal(root):\n    result = []\n    if root is None:\n        return result\n    stack = [root]\n    while stack:\n        node = stack.pop()\n        result.append(node.val)\n        if node.right:\n            stack.append(node.right)\n        if node.left:\n            stack.append(node.left)\n    return result\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if not line:\n        print(\"[]\")\n        return\n    line = line[1:-1]\n    parts = [p.strip() for p in line.split(\",\")]\n    root = build_tree(parts)\n    result = preorder_traversal(root)\n    print(str(result).replace(\" \", \"\"))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(39,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\nTreeNode* createNode(int val) {\n    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nTreeNode* buildTree(int* nums, int* isNull, int len) {\n    if (len == 0 || isNull[0]) return NULL;\n    TreeNode* root = createNode(nums[0]);\n    TreeNode** queue = (TreeNode**)malloc(sizeof(TreeNode*) * len);\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    int i = 1;\n    while (front < rear && i < len) {\n        TreeNode* node = queue[front++];\n        if (i < len && !isNull[i]) {\n            node->left = createNode(nums[i]);\n            queue[rear++] = node->left;\n        }\n        i++;\n        if (i < len && !isNull[i]) {\n            node->right = createNode(nums[i]);\n            queue[rear++] = node->right;\n        }\n        i++;\n    }\n    free(queue);\n    return root;\n}\n\nint* inorderTraversal(TreeNode* root, int* returnSize) {\n    int* res = (int*)malloc(sizeof(int) * 10000);\n    TreeNode** stack = (TreeNode**)malloc(sizeof(TreeNode*) * 10000);\n    int top = 0;\n    int count = 0;\n    TreeNode* cur = root;\n    while (cur != NULL || top > 0) {\n        while (cur != NULL) {\n            stack[top++] = cur;\n            cur = cur->left;\n        }\n        cur = stack[--top];\n        res[count++] = cur->val;\n        cur = cur->right;\n    }\n    free(stack);\n    *returnSize = count;\n    return res;\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    int len = strlen(line);\n    while (len > 0 && (line[len-1] == \'\\n\' || line[len-1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    char* p = line;\n    while (*p == \' \' || *p == \'\\t\') p++;\n    if (*p == \'[\') {\n        p++;\n        char* end = strrchr(p, \']\');\n        if (end) *end = \'\\0\';\n    }\n    if (*p == \'\\0\') {\n        printf(\"[]\\n\");\n        return 0;\n    }\n    int nums[10000];\n    int isNull[10000];\n    int n = 0;\n    char* token = strtok(p, \",\");\n    while (token != NULL) {\n        while (*token == \' \' || *token == \'\\t\') token++;\n        char* e = token + strlen(token) - 1;\n        while (e > token && (*e == \' \' || *e == \'\\t\')) *e-- = \'\\0\';\n        if (strcmp(token, \"null\") == 0) {\n            isNull[n] = 1;\n            nums[n] = 0;\n        } else {\n            isNull[n] = 0;\n            nums[n] = atoi(token);\n        }\n        n++;\n        token = strtok(NULL, \",\");\n    }\n    TreeNode* root = buildTree(nums, isNull, n);\n    int returnSize = 0;\n    int* res = inorderTraversal(root, &returnSize);\n    printf(\"[\");\n    for (int i = 0; i < returnSize; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"%d\", res[i]);\n    }\n    printf(\"]\\n\");\n    free(res);\n    return 0;\n}',NULL,1),
(39,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <stack>\n#include <sstream>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode *left;\n    TreeNode *right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(const vector<string>& nums) {\n    if (nums.empty() || nums[0] == \"null\") return nullptr;\n    TreeNode* root = new TreeNode(stoi(nums[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)nums.size()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (i < (int)nums.size() && nums[i] != \"null\") {\n            node->left = new TreeNode(stoi(nums[i]));\n            q.push(node->left);\n        }\n        i++;\n        if (i < (int)nums.size() && nums[i] != \"null\") {\n            node->right = new TreeNode(stoi(nums[i]));\n            q.push(node->right);\n        }\n        i++;\n    }\n    return root;\n}\n\nvector<int> inorderTraversal(TreeNode* root) {\n    vector<int> res;\n    stack<TreeNode*> st;\n    TreeNode* cur = root;\n    while (cur != nullptr || !st.empty()) {\n        while (cur != nullptr) {\n            st.push(cur);\n            cur = cur->left;\n        }\n        cur = st.top();\n        st.pop();\n        res.push_back(cur->val);\n        cur = cur->right;\n    }\n    return res;\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\' || line.back() == \' \')) {\n        line.pop_back();\n    }\n    if (!line.empty() && line.front() == \'[\') {\n        line = line.substr(1, line.size() - 2);\n    }\n    if (line.empty()) {\n        cout << \"[]\" << endl;\n        return 0;\n    }\n    vector<string> parts;\n    stringstream ss(line);\n    string token;\n    while (getline(ss, token, \',\')) {\n        size_t start = token.find_first_not_of(\" \\t\");\n        size_t end = token.find_last_not_of(\" \\t\");\n        if (start == string::npos) {\n            parts.push_back(\"\");\n        } else {\n            parts.push_back(token.substr(start, end - start + 1));\n        }\n    }\n    TreeNode* root = buildTree(parts);\n    vector<int> res = inorderTraversal(root);\n    cout << \"[\";\n    for (size_t i = 0; i < res.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << res[i];\n    }\n    cout << \"]\" << endl;\n    return 0;\n}',NULL,1),
(39,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.startsWith(\"[\")) {\n            line = line.substring(1, line.length() - 1);\n        }\n        if (line.isEmpty()) {\n            System.out.println(\"[]\");\n            return;\n        }\n        String[] parts = line.split(\",\");\n        Integer[] nums = new Integer[parts.length];\n        for (int i = 0; i < parts.length; i++) {\n            String s = parts[i].trim();\n            if (s.equals(\"null\")) {\n                nums[i] = null;\n            } else {\n                nums[i] = Integer.parseInt(s);\n            }\n        }\n        TreeNode root = buildTree(nums);\n        List<Integer> res = inorderTraversal(root);\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < res.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(res.get(i));\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n\n    private static TreeNode buildTree(Integer[] nums) {\n        if (nums == null || nums.length == 0 || nums[0] == null) return null;\n        TreeNode root = new TreeNode(nums[0]);\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < nums.length) {\n            TreeNode node = queue.poll();\n            if (i < nums.length && nums[i] != null) {\n                node.left = new TreeNode(nums[i]);\n                queue.offer(node.left);\n            }\n            i++;\n            if (i < nums.length && nums[i] != null) {\n                node.right = new TreeNode(nums[i]);\n                queue.offer(node.right);\n            }\n            i++;\n        }\n        return root;\n    }\n\n    private static List<Integer> inorderTraversal(TreeNode root) {\n        List<Integer> res = new ArrayList<>();\n        Deque<TreeNode> stack = new ArrayDeque<>();\n        TreeNode cur = root;\n        while (cur != null || !stack.isEmpty()) {\n            while (cur != null) {\n                stack.push(cur);\n                cur = cur.left;\n            }\n            cur = stack.pop();\n            res.add(cur.val);\n            cur = cur.right;\n        }\n        return res;\n    }\n\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) {\n            this.val = val;\n        }\n    }\n}',NULL,1),
(39,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line.startsWith(\'[\')) {\n        line = line.substring(1, line.length - 1);\n    }\n    if (line.length === 0) {\n        console.log(\'[]\');\n        rl.close();\n        return;\n    }\n    const parts = line.split(\',\');\n    const nums = parts.map(s => {\n        s = s.trim();\n        return s === \'null\' ? null : parseInt(s, 10);\n    });\n    const root = buildTree(nums);\n    const res = inorderTraversal(root);\n    console.log(\'[\' + res.join(\',\') + \']\');\n    rl.close();\n});\n\nfunction buildTree(nums) {\n    if (!nums || nums.length === 0 || nums[0] === null) return null;\n    const root = new TreeNode(nums[0]);\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < nums.length) {\n        const node = queue.shift();\n        if (i < nums.length && nums[i] !== null) {\n            node.left = new TreeNode(nums[i]);\n            queue.push(node.left);\n        }\n        i++;\n        if (i < nums.length && nums[i] !== null) {\n            node.right = new TreeNode(nums[i]);\n            queue.push(node.right);\n        }\n        i++;\n    }\n    return root;\n}\n\nfunction inorderTraversal(root) {\n    const res = [];\n    const stack = [];\n    let cur = root;\n    while (cur !== null || stack.length > 0) {\n        while (cur !== null) {\n            stack.push(cur);\n            cur = cur.left;\n        }\n        cur = stack.pop();\n        res.push(cur.val);\n        cur = cur.right;\n    }\n    return res;\n}\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}',NULL,1),
(39,'PYTHON','import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef build_tree(nums):\n    if not nums or nums[0] is None:\n        return None\n    root = TreeNode(nums[0])\n    queue = deque([root])\n    i = 1\n    while queue and i < len(nums):\n        node = queue.popleft()\n        if i < len(nums) and nums[i] is not None:\n            node.left = TreeNode(nums[i])\n            queue.append(node.left)\n        i += 1\n        if i < len(nums) and nums[i] is not None:\n            node.right = TreeNode(nums[i])\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef inorder_traversal(root):\n    res = []\n    stack = []\n    cur = root\n    while cur or stack:\n        while cur:\n            stack.append(cur)\n            cur = cur.left\n        cur = stack.pop()\n        res.append(cur.val)\n        cur = cur.right\n    return res\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line.startswith(\"[\"):\n        line = line[1:-1]\n    if not line:\n        print(\"[]\")\n        return\n    parts = line.split(\",\")\n    nums = []\n    for s in parts:\n        s = s.strip()\n        if s == \"null\":\n            nums.append(None)\n        else:\n            nums.append(int(s))\n    root = build_tree(nums)\n    res = inorder_traversal(root)\n    print(\"[\" + \",\".join(str(x) for x in res) + \"]\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(40,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdbool.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\nstatic TreeNode* newTreeNode(int val) {\n    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nstatic TreeNode* buildTree(int* nums, int* isNull, int len) {\n    if (len == 0 || isNull[0]) return NULL;\n    TreeNode* root = newTreeNode(nums[0]);\n    TreeNode** queue = (TreeNode**)malloc(sizeof(TreeNode*) * len);\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    int i = 1;\n    while (front < rear && i < len) {\n        TreeNode* node = queue[front++];\n        if (i < len) {\n            if (!isNull[i]) {\n                node->left = newTreeNode(nums[i]);\n                queue[rear++] = node->left;\n            }\n            i++;\n        }\n        if (i < len) {\n            if (!isNull[i]) {\n                node->right = newTreeNode(nums[i]);\n                queue[rear++] = node->right;\n            }\n            i++;\n        }\n    }\n    free(queue);\n    return root;\n}\n\nstatic bool check(TreeNode* left, TreeNode* right) {\n    if (left == NULL && right == NULL) return true;\n    if (left == NULL || right == NULL) return false;\n    if (left->val != right->val) return false;\n    return check(left->left, right->right) && check(left->right, right->left);\n}\n\nstatic bool isSymmetric(TreeNode* root) {\n    if (root == NULL) return true;\n    return check(root->left, root->right);\n}\n\nint main(void) {\n    char line[1000005];\n    if (fgets(line, sizeof(line), stdin) == NULL) {\n        printf(\"true\\n\");\n        return 0;\n    }\n    size_t len = strlen(line);\n    while (len > 0 && (line[len - 1] == \'\\n\' || line[len - 1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    if (len == 0) {\n        printf(\"true\\n\");\n        return 0;\n    }\n    if (line[0] == \'[\' && len >= 2 && line[len - 1] == \']\') {\n        memmove(line, line + 1, len - 2);\n        line[len - 2] = \'\\0\';\n        len -= 2;\n    }\n    bool empty = true;\n    for (size_t i = 0; i < len; i++) {\n        if (line[i] != \' \' && line[i] != \'\\t\') {\n            empty = false;\n            break;\n        }\n    }\n    if (empty) {\n        printf(\"true\\n\");\n        return 0;\n    }\n\n    int capacity = 16;\n    int* nums = (int*)malloc(sizeof(int) * capacity);\n    int* isNull = (int*)malloc(sizeof(int) * capacity);\n    int count = 0;\n\n    char* p = line;\n    while (*p) {\n        while (*p == \' \' || *p == \'\\t\') p++;\n        if (*p == \'\\0\') break;\n        char* start = p;\n        while (*p && *p != \',\') p++;\n        char* end = p;\n        while (end > start && (end[-1] == \' \' || end[-1] == \'\\t\')) end--;\n        if (end > start) {\n            if (count >= capacity) {\n                capacity *= 2;\n                nums = (int*)realloc(nums, sizeof(int) * capacity);\n                isNull = (int*)realloc(isNull, sizeof(int) * capacity);\n            }\n            if ((end - start) == 4 && strncmp(start, \"null\", 4) == 0) {\n                nums[count] = 0;\n                isNull[count] = 1;\n            } else {\n                char tmp[64];\n                int l = (int)(end - start);\n                if (l > 63) l = 63;\n                memcpy(tmp, start, l);\n                tmp[l] = \'\\0\';\n                nums[count] = atoi(tmp);\n                isNull[count] = 0;\n            }\n            count++;\n        }\n        if (*p == \',\') p++;\n    }\n\n    TreeNode* root = buildTree(nums, isNull, count);\n    printf(\"%s\\n\", isSymmetric(root) ? \"true\" : \"false\");\n\n    free(nums);\n    free(isNull);\n    return 0;\n}',NULL,1),
(40,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <sstream>\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode* left;\n    TreeNode* right;\n    TreeNode(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(vector<string>& nums) {\n    if (nums.empty() || nums[0] == \"null\") return nullptr;\n    TreeNode* root = new TreeNode(stoi(nums[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)nums.size()) {\n        TreeNode* node = q.front(); q.pop();\n        if (i < (int)nums.size()) {\n            if (nums[i] != \"null\") {\n                node->left = new TreeNode(stoi(nums[i]));\n                q.push(node->left);\n            }\n            i++;\n        }\n        if (i < (int)nums.size()) {\n            if (nums[i] != \"null\") {\n                node->right = new TreeNode(stoi(nums[i]));\n                q.push(node->right);\n            }\n            i++;\n        }\n    }\n    return root;\n}\n\nbool check(TreeNode* left, TreeNode* right) {\n    if (!left && !right) return true;\n    if (!left || !right) return false;\n    if (left->val != right->val) return false;\n    return check(left->left, right->right) && check(left->right, right->left);\n}\n\nbool isSymmetric(TreeNode* root) {\n    if (!root) return true;\n    return check(root->left, root->right);\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\')) line.pop_back();\n    if (line.empty()) {\n        cout << \"true\" << endl;\n        return 0;\n    }\n    line = line.substr(1, line.size() - 2);\n    if (line.find_first_not_of(\" \\t\") == string::npos) {\n        cout << \"true\" << endl;\n        return 0;\n    }\n    vector<string> parts;\n    stringstream ss(line);\n    string token;\n    while (getline(ss, token, \',\')) {\n        size_t start = token.find_first_not_of(\" \\t\");\n        size_t end = token.find_last_not_of(\" \\t\");\n        if (start == string::npos) parts.push_back(\"\");\n        else parts.push_back(token.substr(start, end - start + 1));\n    }\n    TreeNode* root = buildTree(parts);\n    cout << (isSymmetric(root) ? \"true\" : \"false\") << endl;\n    return 0;\n}',NULL,1),
(40,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.isEmpty()) {\n            System.out.println(\"true\");\n            return;\n        }\n        line = line.substring(1, line.length() - 1).trim();\n        if (line.isEmpty()) {\n            System.out.println(\"true\");\n            return;\n        }\n        String[] parts = line.split(\",\");\n        Integer[] nums = new Integer[parts.length];\n        for (int i = 0; i < parts.length; i++) {\n            String s = parts[i].trim();\n            if (s.equals(\"null\")) {\n                nums[i] = null;\n            } else {\n                nums[i] = Integer.parseInt(s);\n            }\n        }\n        TreeNode root = buildTree(nums);\n        System.out.println(isSymmetric(root));\n    }\n\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) { this.val = val; }\n    }\n\n    static TreeNode buildTree(Integer[] nums) {\n        if (nums == null || nums.length == 0 || nums[0] == null) return null;\n        TreeNode root = new TreeNode(nums[0]);\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < nums.length) {\n            TreeNode node = queue.poll();\n            if (i < nums.length && nums[i] != null) {\n                node.left = new TreeNode(nums[i]);\n                queue.offer(node.left);\n            }\n            i++;\n            if (i < nums.length && nums[i] != null) {\n                node.right = new TreeNode(nums[i]);\n                queue.offer(node.right);\n            }\n            i++;\n        }\n        return root;\n    }\n\n    static boolean isSymmetric(TreeNode root) {\n        if (root == null) return true;\n        return check(root.left, root.right);\n    }\n\n    static boolean check(TreeNode left, TreeNode right) {\n        if (left == null && right == null) return true;\n        if (left == null || right == null) return false;\n        if (left.val != right.val) return false;\n        return check(left.left, right.right) && check(left.right, right.left);\n    }\n}',NULL,1),
(40,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line === \'\') {\n        console.log(\'true\');\n        rl.close();\n        return;\n    }\n    line = line.substring(1, line.length - 1);\n    if (line.trim() === \'\') {\n        console.log(\'true\');\n        rl.close();\n        return;\n    }\n    const parts = line.split(\',\');\n    const nums = parts.map(s => {\n        s = s.trim();\n        return s === \'null\' ? null : parseInt(s, 10);\n    });\n    const root = buildTree(nums);\n    console.log(isSymmetric(root));\n    rl.close();\n});\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(nums) {\n    if (!nums || nums.length === 0 || nums[0] === null) return null;\n    const root = new TreeNode(nums[0]);\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < nums.length) {\n        const node = queue.shift();\n        if (i < nums.length) {\n            if (nums[i] !== null) {\n                node.left = new TreeNode(nums[i]);\n                queue.push(node.left);\n            }\n            i++;\n        }\n        if (i < nums.length) {\n            if (nums[i] !== null) {\n                node.right = new TreeNode(nums[i]);\n                queue.push(node.right);\n            }\n            i++;\n        }\n    }\n    return root;\n}\n\nfunction isSymmetric(root) {\n    if (root === null) return true;\n    return check(root.left, root.right);\n}\n\nfunction check(left, right) {\n    if (left === null && right === null) return true;\n    if (left === null || right === null) return false;\n    if (left.val !== right.val) return false;\n    return check(left.left, right.right) && check(left.right, right.left);\n}',NULL,1),
(40,'PYTHON','import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef build_tree(nums):\n    if not nums or nums[0] is None:\n        return None\n    root = TreeNode(nums[0])\n    queue = deque([root])\n    i = 1\n    while queue and i < len(nums):\n        node = queue.popleft()\n        if i < len(nums):\n            if nums[i] is not None:\n                node.left = TreeNode(nums[i])\n                queue.append(node.left)\n            i += 1\n        if i < len(nums):\n            if nums[i] is not None:\n                node.right = TreeNode(nums[i])\n                queue.append(node.right)\n            i += 1\n    return root\n\ndef is_symmetric(root):\n    if root is None:\n        return True\n    return check(root.left, root.right)\n\ndef check(left, right):\n    if left is None and right is None:\n        return True\n    if left is None or right is None:\n        return False\n    if left.val != right.val:\n        return False\n    return check(left.left, right.right) and check(left.right, right.left)\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if not line:\n        print(\"true\")\n        return\n    line = line[1:-1]\n    if not line.strip():\n        print(\"true\")\n        return\n    parts = line.split(\",\")\n    nums = []\n    for s in parts:\n        s = s.strip()\n        if s == \"null\":\n            nums.append(None)\n        else:\n            nums.append(int(s))\n    root = build_tree(nums)\n    print(\"true\" if is_symmetric(root) else \"false\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(41,'C','#include <stdio.h>\n#include <stdlib.h>\n\nvoid dfs(char **grid, int i, int j, int m, int n) {\n    if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] != \'1\') {\n        return;\n    }\n    grid[i][j] = \'0\';\n    dfs(grid, i - 1, j, m, n);\n    dfs(grid, i + 1, j, m, n);\n    dfs(grid, i, j - 1, m, n);\n    dfs(grid, i, j + 1, m, n);\n}\n\nint main() {\n    int m, n;\n    scanf(\"%d %d\", &m, &n);\n\n    char **grid = (char **)malloc(m * sizeof(char *));\n    for (int i = 0; i < m; i++) {\n        grid[i] = (char *)malloc((n + 1) * sizeof(char));\n        scanf(\"%s\", grid[i]);\n    }\n\n    int count = 0;\n    for (int i = 0; i < m; i++) {\n        for (int j = 0; j < n; j++) {\n            if (grid[i][j] == \'1\') {\n                count++;\n                dfs(grid, i, j, m, n);\n            }\n        }\n    }\n\n    printf(\"%d\\n\", count);\n\n    for (int i = 0; i < m; i++) {\n        free(grid[i]);\n    }\n    free(grid);\n\n    return 0;\n}',NULL,1),
(41,'CPP','#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\n\nvoid dfs(vector<string>& grid, int i, int j, int m, int n) {\n    if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] != \'1\') {\n        return;\n    }\n    grid[i][j] = \'0\';\n    dfs(grid, i - 1, j, m, n);\n    dfs(grid, i + 1, j, m, n);\n    dfs(grid, i, j - 1, m, n);\n    dfs(grid, i, j + 1, m, n);\n}\n\nint main() {\n    int m, n;\n    cin >> m >> n;\n    cin.ignore();\n    vector<string> grid(m);\n    for (int i = 0; i < m; i++) {\n        getline(cin, grid[i]);\n    }\n    int count = 0;\n    for (int i = 0; i < m; i++) {\n        for (int j = 0; j < n; j++) {\n            if (grid[i][j] == \'1\') {\n                count++;\n                dfs(grid, i, j, m, n);\n            }\n        }\n    }\n    cout << count << endl;\n    return 0;\n}',NULL,1),
(41,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n        sc.nextLine();\n        char[][] grid = new char[m][n];\n        for (int i = 0; i < m; i++) {\n            String line = sc.nextLine();\n            grid[i] = line.toCharArray();\n        }\n        int count = 0;\n        for (int i = 0; i < m; i++) {\n            for (int j = 0; j < n; j++) {\n                if (grid[i][j] == \'1\') {\n                    count++;\n                    dfs(grid, i, j, m, n);\n                }\n            }\n        }\n        System.out.println(count);\n    }\n\n    private static void dfs(char[][] grid, int i, int j, int m, int n) {\n        if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] != \'1\') {\n            return;\n        }\n        grid[i][j] = \'0\';\n        dfs(grid, i + 1, j, m, n);\n        dfs(grid, i - 1, j, m, n);\n        dfs(grid, i, j + 1, m, n);\n        dfs(grid, i, j - 1, m, n);\n    }\n}',NULL,1),
(41,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n});\n\nrl.on(\'close\', () => {\n    const [m, n] = lines[0].trim().split(/\\s+/).map(Number);\n    const grid = [];\n    for (let i = 0; i < m; i++) {\n        grid.push(lines[i + 1].trim().split(\'\'));\n    }\n\n    let count = 0;\n\n    function dfs(i, j) {\n        if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] !== \'1\') {\n            return;\n        }\n        grid[i][j] = \'0\';\n        dfs(i - 1, j);\n        dfs(i + 1, j);\n        dfs(i, j - 1);\n        dfs(i, j + 1);\n    }\n\n    for (let i = 0; i < m; i++) {\n        for (let j = 0; j < n; j++) {\n            if (grid[i][j] === \'1\') {\n                count++;\n                dfs(i, j);\n            }\n        }\n    }\n\n    console.log(count);\n});',NULL,1),
(41,'PYTHON','import sys\n\ndef dfs(grid, i, j, m, n):\n    if i < 0 or i >= m or j < 0 or j >= n or grid[i][j] != \'1\':\n        return\n    grid[i][j] = \'0\'\n    dfs(grid, i - 1, j, m, n)\n    dfs(grid, i + 1, j, m, n)\n    dfs(grid, i, j - 1, m, n)\n    dfs(grid, i, j + 1, m, n)\n\ndef main():\n    data = sys.stdin.read().splitlines()\n    if not data:\n        return\n    m, n = map(int, data[0].split())\n    grid = []\n    for i in range(1, m + 1):\n        grid.append(list(data[i].strip()))\n    count = 0\n    for i in range(m):\n        for j in range(n):\n            if grid[i][j] == \'1\':\n                count += 1\n                dfs(grid, i, j, m, n)\n    print(count)\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(42,'C','#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct Node {\n    int val;\n    struct Node* next;\n} Node;\n\nint main() {\n    int numCourses, k;\n    scanf(\"%d %d\", &numCourses, &k);\n\n    Node** graph = (Node**)calloc(numCourses, sizeof(Node*));\n    int* indegree = (int*)calloc(numCourses, sizeof(int));\n\n    for (int i = 0; i < k; i++) {\n        int a, b;\n        scanf(\"%d %d\", &a, &b);\n        Node* node = (Node*)malloc(sizeof(Node));\n        node->val = a;\n        node->next = graph[b];\n        graph[b] = node;\n        indegree[a]++;\n    }\n\n    int* queue = (int*)malloc(numCourses * sizeof(int));\n    int front = 0, rear = 0;\n\n    for (int i = 0; i < numCourses; i++) {\n        if (indegree[i] == 0) {\n            queue[rear++] = i;\n        }\n    }\n\n    int count = 0;\n    while (front < rear) {\n        int cur = queue[front++];\n        count++;\n        Node* p = graph[cur];\n        while (p) {\n            int next = p->val;\n            indegree[next]--;\n            if (indegree[next] == 0) {\n                queue[rear++] = next;\n            }\n            p = p->next;\n        }\n    }\n\n    if (count == numCourses) {\n        printf(\"true\\n\");\n    } else {\n        printf(\"false\\n\");\n    }\n\n    for (int i = 0; i < numCourses; i++) {\n        Node* p = graph[i];\n        while (p) {\n            Node* tmp = p;\n            p = p->next;\n            free(tmp);\n        }\n    }\n    free(graph);\n    free(indegree);\n    free(queue);\n\n    return 0;\n}',NULL,1),
(42,'CPP','#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\n\nint main() {\n    int numCourses, k;\n    cin >> numCourses >> k;\n    vector<vector<int>> graph(numCourses);\n    vector<int> indegree(numCourses, 0);\n    for (int i = 0; i < k; i++) {\n        int a, b;\n        cin >> a >> b;\n        graph[b].push_back(a);\n        indegree[a]++;\n    }\n    queue<int> q;\n    for (int i = 0; i < numCourses; i++) {\n        if (indegree[i] == 0) {\n            q.push(i);\n        }\n    }\n    int count = 0;\n    while (!q.empty()) {\n        int cur = q.front();\n        q.pop();\n        count++;\n        for (int next : graph[cur]) {\n            indegree[next]--;\n            if (indegree[next] == 0) {\n                q.push(next);\n            }\n        }\n    }\n    cout << (count == numCourses ? \"true\" : \"false\") << endl;\n    return 0;\n}',NULL,1),
(42,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int numCourses = sc.nextInt();\n        int k = sc.nextInt();\n        List<List<Integer>> graph = new ArrayList<>();\n        for (int i = 0; i < numCourses; i++) {\n            graph.add(new ArrayList<>());\n        }\n        int[] indegree = new int[numCourses];\n        for (int i = 0; i < k; i++) {\n            int a = sc.nextInt();\n            int b = sc.nextInt();\n            graph.get(b).add(a);\n            indegree[a]++;\n        }\n        Queue<Integer> queue = new LinkedList<>();\n        for (int i = 0; i < numCourses; i++) {\n            if (indegree[i] == 0) {\n                queue.offer(i);\n            }\n        }\n        int count = 0;\n        while (!queue.isEmpty()) {\n            int cur = queue.poll();\n            count++;\n            for (int next : graph.get(cur)) {\n                indegree[next]--;\n                if (indegree[next] == 0) {\n                    queue.offer(next);\n                }\n            }\n        }\n        System.out.println(count == numCourses);\n    }\n}',NULL,1),
(42,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    if (lines.length === 0) return;\n    const first = lines[0].split(/\\s+/).map(Number);\n    const numCourses = first[0];\n    const k = first[1];\n\n    const graph = Array.from({ length: numCourses }, () => []);\n    const indegree = new Array(numCourses).fill(0);\n\n    for (let i = 1; i <= k; i++) {\n        const [a, b] = lines[i].split(/\\s+/).map(Number);\n        graph[b].push(a);\n        indegree[a]++;\n    }\n\n    const queue = [];\n    for (let i = 0; i < numCourses; i++) {\n        if (indegree[i] === 0) {\n            queue.push(i);\n        }\n    }\n\n    let count = 0;\n    let head = 0;\n    while (head < queue.length) {\n        const cur = queue[head++];\n        count++;\n        for (const next of graph[cur]) {\n            indegree[next]--;\n            if (indegree[next] === 0) {\n                queue.push(next);\n            }\n        }\n    }\n\n    console.log(count === numCourses);\n});',NULL,1),
(42,'PYTHON','import sys\nfrom collections import deque\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    numCourses = int(data[0])\n    k = int(data[1])\n    graph = [[] for _ in range(numCourses)]\n    indegree = [0] * numCourses\n    idx = 2\n    for _ in range(k):\n        a = int(data[idx])\n        b = int(data[idx + 1])\n        idx += 2\n        graph[b].append(a)\n        indegree[a] += 1\n    queue = deque([i for i in range(numCourses) if indegree[i] == 0])\n    count = 0\n    while queue:\n        cur = queue.popleft()\n        count += 1\n        for nxt in graph[cur]:\n            indegree[nxt] -= 1\n            if indegree[nxt] == 0:\n                queue.append(nxt)\n    print(\"true\" if count == numCourses else \"false\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(43,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct Node {\n    int val;\n    struct Node** neighbors;\n    int neighborCount;\n    int capacity;\n} Node;\n\nNode* createNode(int val) {\n    Node* node = (Node*)malloc(sizeof(Node));\n    node->val = val;\n    node->neighborCount = 0;\n    node->capacity = 4;\n    node->neighbors = (Node**)malloc(sizeof(Node*) * node->capacity);\n    return node;\n}\n\nvoid addNeighbor(Node* node, Node* neighbor) {\n    if (node->neighborCount >= node->capacity) {\n        node->capacity *= 2;\n        node->neighbors = (Node**)realloc(node->neighbors, sizeof(Node*) * node->capacity);\n    }\n    node->neighbors[node->neighborCount++] = neighbor;\n}\n\nNode* dfs(Node* node, Node** map, int n) {\n    if (node == NULL) return NULL;\n    if (map[node->val] != NULL) return map[node->val];\n    Node* copy = createNode(node->val);\n    map[node->val] = copy;\n    for (int i = 0; i < node->neighborCount; i++) {\n        addNeighbor(copy, dfs(node->neighbors[i], map, n));\n    }\n    return copy;\n}\n\nNode* cloneGraph(Node* node, int n) {\n    if (node == NULL) return NULL;\n    Node** map = (Node**)calloc(n + 1, sizeof(Node*));\n    Node* result = dfs(node, map, n);\n    free(map);\n    return result;\n}\n\nint main() {\n    int n;\n    if (scanf(\"%d\", &n) != 1) return 0;\n    int c;\n    while ((c = getchar()) != \'\\n\' && c != EOF);\n\n    Node** nodes = (Node**)malloc(sizeof(Node*) * (n + 1));\n    for (int i = 1; i <= n; i++) {\n        nodes[i] = createNode(i);\n    }\n\n    char line[100000];\n    for (int i = 1; i <= n; i++) {\n        if (fgets(line, sizeof(line), stdin) == NULL) break;\n        char* p = line;\n        while (*p) {\n            while (*p == \' \' || *p == \'\\t\' || *p == \'\\n\' || *p == \'\\r\') p++;\n            if (*p == \'\\0\') break;\n            int v = 0;\n            while (*p >= \'0\' && *p <= \'9\') {\n                v = v * 10 + (*p - \'0\');\n                p++;\n            }\n            if (v >= 1 && v <= n) {\n                addNeighbor(nodes[i], nodes[v]);\n            }\n        }\n    }\n\n    Node* cloned = cloneGraph(nodes[1], n);\n\n    printf(\"[\");\n    for (int i = 1; i <= n; i++) {\n        printf(\"[\");\n        for (int j = 0; j < nodes[i]->neighborCount; j++) {\n            printf(\"%d\", nodes[i]->neighbors[j]->val);\n            if (j < nodes[i]->neighborCount - 1) printf(\",\");\n        }\n        printf(\"]\");\n        if (i < n) printf(\",\");\n    }\n    printf(\"]\\n\");\n\n    return 0;\n}',NULL,1),
(43,'CPP','#include <iostream>\n#include <vector>\n#include <string>\n#include <sstream>\n#include <unordered_map>\n\nusing namespace std;\n\nstruct Node {\n    int val;\n    vector<Node*> neighbors;\n    Node() : val(0) {}\n    Node(int _val) : val(_val) {}\n    Node(int _val, vector<Node*> _neighbors) : val(_val), neighbors(_neighbors) {}\n};\n\nNode* dfs(Node* node, unordered_map<Node*, Node*>& mp) {\n    if (mp.count(node)) return mp[node];\n    Node* copy = new Node(node->val);\n    mp[node] = copy;\n    for (Node* nei : node->neighbors) {\n        copy->neighbors.push_back(dfs(nei, mp));\n    }\n    return copy;\n}\n\nNode* cloneGraph(Node* node) {\n    if (!node) return nullptr;\n    unordered_map<Node*, Node*> mp;\n    return dfs(node, mp);\n}\n\nint main() {\n    int n;\n    if (!(cin >> n)) return 0;\n    cin.ignore();\n    vector<Node*> nodes;\n    for (int i = 0; i < n; i++) {\n        nodes.push_back(new Node(i + 1));\n    }\n    for (int i = 0; i < n; i++) {\n        string line;\n        getline(cin, line);\n        if (line.empty()) continue;\n        istringstream iss(line);\n        int v;\n        while (iss >> v) {\n            nodes[i]->neighbors.push_back(nodes[v - 1]);\n        }\n    }\n    Node* cloned = cloneGraph(nodes[0]);\n    (void)cloned;\n    stringstream sb;\n    sb << \"[\";\n    for (int i = 0; i < n; i++) {\n        sb << \"[\";\n        vector<Node*>& nei = nodes[i]->neighbors;\n        for (size_t j = 0; j < nei.size(); j++) {\n            sb << nei[j]->val;\n            if (j + 1 < nei.size()) sb << \",\";\n        }\n        sb << \"]\";\n        if (i < n - 1) sb << \",\";\n    }\n    sb << \"]\";\n    cout << sb.str() << endl;\n    return 0;\n}',NULL,1),
(43,'JAVA','import java.util.*;\n\npublic class Main {\n    static class Node {\n        public int val;\n        public List<Node> neighbors;\n        public Node() {\n            val = 0;\n            neighbors = new ArrayList<>();\n        }\n        public Node(int _val) {\n            val = _val;\n            neighbors = new ArrayList<>();\n        }\n        public Node(int _val, ArrayList<Node> _neighbors) {\n            val = _val;\n            neighbors = _neighbors;\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextInt()) return;\n        int n = sc.nextInt();\n        sc.nextLine();\n\n        Node[] nodes = new Node[n + 1];\n        for (int i = 1; i <= n; i++) {\n            nodes[i] = new Node(i);\n        }\n\n        for (int i = 1; i <= n; i++) {\n            String line = sc.nextLine().trim();\n            if (line.isEmpty()) continue;\n            String[] parts = line.split(\"\\\\s+\");\n            for (String p : parts) {\n                if (p.isEmpty()) continue;\n                int v = Integer.parseInt(p);\n                nodes[i].neighbors.add(nodes[v]);\n            }\n        }\n\n        Node cloned = cloneGraph(nodes[1]);\n\n        List<List<Integer>> result = new ArrayList<>();\n        for (int i = 1; i <= n; i++) {\n            List<Integer> list = new ArrayList<>();\n            for (Node nb : nodes[i].neighbors) {\n                list.add(nb.val);\n            }\n            result.add(list);\n        }\n\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < result.size(); i++) {\n            sb.append(\"[\");\n            List<Integer> list = result.get(i);\n            for (int j = 0; j < list.size(); j++) {\n                sb.append(list.get(j));\n                if (j < list.size() - 1) sb.append(\",\");\n            }\n            sb.append(\"]\");\n            if (i < result.size() - 1) sb.append(\",\");\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n\n    public static Node cloneGraph(Node node) {\n        if (node == null) return null;\n        Map<Node, Node> map = new HashMap<>();\n        return dfs(node, map);\n    }\n\n    private static Node dfs(Node node, Map<Node, Node> map) {\n        if (map.containsKey(node)) return map.get(node);\n        Node copy = new Node(node.val);\n        map.put(node, copy);\n        for (Node nb : node.neighbors) {\n            copy.neighbors.add(dfs(nb, map));\n        }\n        return copy;\n    }\n}',NULL,1),
(43,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass Node {\n    constructor(val = 0, neighbors = []) {\n        this.val = val;\n        this.neighbors = neighbors;\n    }\n}\n\nfunction cloneGraph(node) {\n    if (node === null) return null;\n    const map = new Map();\n    return dfs(node, map);\n}\n\nfunction dfs(node, map) {\n    if (map.has(node)) return map.get(node);\n    const copy = new Node(node.val);\n    map.set(node, copy);\n    for (const nb of node.neighbors) {\n        copy.neighbors.push(dfs(nb, map));\n    }\n    return copy;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n});\n\nrl.on(\'close\', () => {\n    if (lines.length === 0) return;\n    let idx = 0;\n    const n = parseInt(lines[idx++].trim());\n    const nodes = new Array(n + 1);\n    for (let i = 1; i <= n; i++) {\n        nodes[i] = new Node(i);\n    }\n    for (let i = 1; i <= n; i++) {\n        const line = (lines[idx++] || \'\').trim();\n        if (line === \'\') continue;\n        const parts = line.split(/\\s+/);\n        for (const p of parts) {\n            if (p === \'\') continue;\n            const v = parseInt(p);\n            nodes[i].neighbors.push(nodes[v]);\n        }\n    }\n\n    cloneGraph(nodes[1]);\n\n    const result = [];\n    for (let i = 1; i <= n; i++) {\n        const list = [];\n        for (const nb of nodes[i].neighbors) {\n            list.push(nb.val);\n        }\n        result.push(list);\n    }\n\n    let sb = \'[\';\n    for (let i = 0; i < result.length; i++) {\n        sb += \'[\';\n        const list = result[i];\n        for (let j = 0; j < list.length; j++) {\n            sb += list[j];\n            if (j < list.length - 1) sb += \',\';\n        }\n        sb += \']\';\n        if (i < result.length - 1) sb += \',\';\n    }\n    sb += \']\';\n    console.log(sb);\n});',NULL,1),
(43,'PYTHON','import sys\n\nclass Node:\n    def __init__(self, val=0, neighbors=None):\n        self.val = val\n        self.neighbors = neighbors if neighbors is not None else []\n\ndef clone_graph(node, visited):\n    if node is None:\n        return None\n    if node in visited:\n        return visited[node]\n    copy = Node(node.val)\n    visited[node] = copy\n    for nb in node.neighbors:\n        copy.neighbors.append(clone_graph(nb, visited))\n    return copy\n\ndef main():\n    data = sys.stdin.read().splitlines()\n    if not data:\n        return\n    n = int(data[0].strip())\n    nodes = [None] + [Node(i) for i in range(1, n + 1)]\n    for i in range(1, n + 1):\n        if i >= len(data):\n            break\n        line = data[i].strip()\n        if not line:\n            continue\n        for p in line.split():\n            v = int(p)\n            nodes[i].neighbors.append(nodes[v])\n    clone_graph(nodes[1], {})\n    result = []\n    for i in range(1, n + 1):\n        result.append([nb.val for nb in nodes[i].neighbors])\n    out = \"[\" + \",\".join(\"[\" + \",\".join(map(str, lst)) + \"]\" for lst in result) + \"]\"\n    print(out)\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(44,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdbool.h>\n\n#define MAX_WORDS 10000\n#define MAX_LEN 64\n\ntypedef struct {\n    char word[MAX_LEN];\n} Word;\n\nstatic Word dictWords[MAX_WORDS];\nstatic int dictSize = 0;\n\nstatic int findWord(const char *w) {\n    for (int i = 0; i < dictSize; i++) {\n        if (strcmp(dictWords[i].word, w) == 0) return i;\n    }\n    return -1;\n}\n\nint main(void) {\n    char beginWord[MAX_LEN], endWord[MAX_LEN];\n    char line[1000000];\n\n    if (scanf(\"%63s\", beginWord) != 1) return 0;\n    if (scanf(\"%63s\", endWord) != 1) return 0;\n    getchar();\n\n    if (!fgets(line, sizeof(line), stdin)) line[0] = \'\\0\';\n\n    char *p = strtok(line, \" \\t\\r\\n\");\n    while (p) {\n        if (dictSize < MAX_WORDS) {\n            strncpy(dictWords[dictSize].word, p, MAX_LEN - 1);\n            dictWords[dictSize].word[MAX_LEN - 1] = \'\\0\';\n            dictSize++;\n        }\n        p = strtok(NULL, \" \\t\\r\\n\");\n    }\n\n    int endIdx = findWord(endWord);\n    if (endIdx == -1) {\n        printf(\"0\\n\");\n        return 0;\n    }\n\n    int beginIdx = findWord(beginWord);\n    if (beginIdx == -1) {\n        if (dictSize < MAX_WORDS) {\n            strncpy(dictWords[dictSize].word, beginWord, MAX_LEN - 1);\n            dictWords[dictSize].word[MAX_LEN - 1] = \'\\0\';\n            beginIdx = dictSize;\n            dictSize++;\n        }\n    }\n\n    bool visited[MAX_WORDS] = {0};\n    int queue[MAX_WORDS];\n    int front = 0, rear = 0;\n\n    queue[rear++] = beginIdx;\n    visited[beginIdx] = true;\n    int level = 1;\n\n    while (front < rear) {\n        int size = rear - front;\n        for (int i = 0; i < size; i++) {\n            int cur = queue[front++];\n            if (cur == endIdx) {\n                printf(\"%d\\n\", level);\n                return 0;\n            }\n\n            char chars[MAX_LEN];\n            strcpy(chars, dictWords[cur].word);\n            int len = (int)strlen(chars);\n\n            for (int j = 0; j < len; j++) {\n                char old = chars[j];\n                for (char c = \'a\'; c <= \'z\'; c++) {\n                    if (c == old) continue;\n                    chars[j] = c;\n                    int nxt = findWord(chars);\n                    if (nxt != -1 && !visited[nxt]) {\n                        visited[nxt] = true;\n                        queue[rear++] = nxt;\n                    }\n                }\n                chars[j] = old;\n            }\n        }\n        level++;\n    }\n\n    printf(\"0\\n\");\n    return 0;\n}',NULL,1),
(44,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <unordered_set>\n#include <queue>\n#include <sstream>\n\nusing namespace std;\n\nint main() {\n    string beginWord, endWord, line;\n    getline(cin, beginWord);\n    getline(cin, endWord);\n    getline(cin, line);\n\n    auto trim = [](string &s) {\n        size_t start = s.find_first_not_of(\" \\t\\r\\n\");\n        size_t end = s.find_last_not_of(\" \\t\\r\\n\");\n        if (start == string::npos) s = \"\";\n        else s = s.substr(start, end - start + 1);\n    };\n\n    trim(beginWord);\n    trim(endWord);\n    trim(line);\n\n    vector<string> wordList;\n    if (!line.empty()) {\n        stringstream ss(line);\n        string word;\n        while (ss >> word) {\n            wordList.push_back(word);\n        }\n    }\n\n    unordered_set<string> dict(wordList.begin(), wordList.end());\n    if (dict.find(endWord) == dict.end()) {\n        cout << 0 << endl;\n        return 0;\n    }\n\n    queue<string> q;\n    q.push(beginWord);\n    unordered_set<string> visited;\n    visited.insert(beginWord);\n    int level = 1;\n\n    while (!q.empty()) {\n        int size = q.size();\n        for (int i = 0; i < size; i++) {\n            string word = q.front();\n            q.pop();\n\n            if (word == endWord) {\n                cout << level << endl;\n                return 0;\n            }\n\n            for (int j = 0; j < (int)word.size(); j++) {\n                char old = word[j];\n                for (char c = \'a\'; c <= \'z\'; c++) {\n                    if (c == old) continue;\n                    word[j] = c;\n                    if (dict.find(word) != dict.end() && visited.find(word) == visited.end()) {\n                        visited.insert(word);\n                        q.push(word);\n                    }\n                }\n                word[j] = old;\n            }\n        }\n        level++;\n    }\n\n    cout << 0 << endl;\n    return 0;\n}',NULL,1),
(44,'JAVA','import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        String beginWord = br.readLine().trim();\n        String endWord = br.readLine().trim();\n        String line = br.readLine();\n        if (line == null) line = \"\";\n        line = line.trim();\n        List<String> wordList = new ArrayList<>();\n        if (!line.isEmpty()) {\n            String[] parts = line.split(\"\\\\s+\");\n            for (String p : parts) {\n                if (!p.isEmpty()) wordList.add(p);\n            }\n        }\n\n        Set<String> dict = new HashSet<>(wordList);\n        if (!dict.contains(endWord)) {\n            System.out.println(0);\n            return;\n        }\n\n        Queue<String> queue = new LinkedList<>();\n        queue.offer(beginWord);\n        Set<String> visited = new HashSet<>();\n        visited.add(beginWord);\n        int level = 1;\n\n        while (!queue.isEmpty()) {\n            int size = queue.size();\n            for (int i = 0; i < size; i++) {\n                String word = queue.poll();\n                if (word.equals(endWord)) {\n                    System.out.println(level);\n                    return;\n                }\n                char[] chars = word.toCharArray();\n                for (int j = 0; j < chars.length; j++) {\n                    char old = chars[j];\n                    for (char c = \'a\'; c <= \'z\'; c++) {\n                        if (c == old) continue;\n                        chars[j] = c;\n                        String next = new String(chars);\n                        if (dict.contains(next) && !visited.contains(next)) {\n                            visited.add(next);\n                            queue.offer(next);\n                        }\n                    }\n                    chars[j] = old;\n                }\n            }\n            level++;\n        }\n\n        System.out.println(0);\n    }\n}',NULL,1),
(44,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nconst lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n});\n\nrl.on(\'close\', () => {\n    const beginWord = lines[0].trim();\n    const endWord = lines[1].trim();\n    let line = lines[2] || \'\';\n    line = line.trim();\n    const wordList = [];\n    if (line.length > 0) {\n        const parts = line.split(/\\s+/);\n        for (const p of parts) {\n            if (p.length > 0) wordList.push(p);\n        }\n    }\n\n    const dict = new Set(wordList);\n    if (!dict.has(endWord)) {\n        console.log(0);\n        return;\n    }\n\n    const queue = [beginWord];\n    const visited = new Set();\n    visited.add(beginWord);\n    let level = 1;\n\n    while (queue.length > 0) {\n        const size = queue.length;\n        for (let i = 0; i < size; i++) {\n            const word = queue.shift();\n            if (word === endWord) {\n                console.log(level);\n                return;\n            }\n            const chars = word.split(\'\');\n            for (let j = 0; j < chars.length; j++) {\n                const old = chars[j];\n                for (let c = 97; c <= 122; c++) {\n                    const ch = String.fromCharCode(c);\n                    if (ch === old) continue;\n                    chars[j] = ch;\n                    const next = chars.join(\'\');\n                    if (dict.has(next) && !visited.has(next)) {\n                        visited.add(next);\n                        queue.push(next);\n                    }\n                }\n                chars[j] = old;\n            }\n        }\n        level++;\n    }\n\n    console.log(0);\n});',NULL,1),
(44,'PYTHON','import sys\nfrom collections import deque\n\ndef main():\n    lines = sys.stdin.read().splitlines()\n    if len(lines) < 2:\n        return\n    beginWord = lines[0].strip()\n    endWord = lines[1].strip()\n    line = lines[2].strip() if len(lines) > 2 else \"\"\n    wordList = line.split() if line else []\n\n    dict_set = set(wordList)\n    if endWord not in dict_set:\n        print(0)\n        return\n\n    queue = deque([beginWord])\n    visited = {beginWord}\n    level = 1\n\n    while queue:\n        size = len(queue)\n        for _ in range(size):\n            word = queue.popleft()\n            if word == endWord:\n                print(level)\n                return\n            chars = list(word)\n            for j in range(len(chars)):\n                old = chars[j]\n                for c in range(ord(\'a\'), ord(\'z\') + 1):\n                    ch = chr(c)\n                    if ch == old:\n                        continue\n                    chars[j] = ch\n                    nxt = \'\'.join(chars)\n                    if nxt in dict_set and nxt not in visited:\n                        visited.add(nxt)\n                        queue.append(nxt)\n                chars[j] = old\n        level += 1\n\n    print(0)\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(45,'C','#include <stdio.h>\n#include <stdlib.h>\n\nvoid dfs(int **isConnected, int *visited, int n, int i) {\n    visited[i] = 1;\n    for (int j = 0; j < n; j++) {\n        if (isConnected[i][j] == 1 && !visited[j]) {\n            dfs(isConnected, visited, n, j);\n        }\n    }\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n\n    int **isConnected = (int **)malloc(n * sizeof(int *));\n    for (int i = 0; i < n; i++) {\n        isConnected[i] = (int *)malloc(n * sizeof(int));\n        for (int j = 0; j < n; j++) {\n            scanf(\"%d\", &isConnected[i][j]);\n        }\n    }\n\n    int *visited = (int *)calloc(n, sizeof(int));\n    int provinces = 0;\n\n    for (int i = 0; i < n; i++) {\n        if (!visited[i]) {\n            dfs(isConnected, visited, n, i);\n            provinces++;\n        }\n    }\n\n    printf(\"%d\\n\", provinces);\n\n    for (int i = 0; i < n; i++) {\n        free(isConnected[i]);\n    }\n    free(isConnected);\n    free(visited);\n\n    return 0;\n}',NULL,1),
(45,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nvoid dfs(const vector<vector<int>>& isConnected, vector<bool>& visited, int i) {\n    visited[i] = true;\n    for (int j = 0; j < (int)isConnected.size(); j++) {\n        if (isConnected[i][j] == 1 && !visited[j]) {\n            dfs(isConnected, visited, j);\n        }\n    }\n}\n\nint main() {\n    int n;\n    cin >> n;\n    vector<vector<int>> isConnected(n, vector<int>(n));\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < n; j++) {\n            cin >> isConnected[i][j];\n        }\n    }\n    vector<bool> visited(n, false);\n    int provinces = 0;\n    for (int i = 0; i < n; i++) {\n        if (!visited[i]) {\n            dfs(isConnected, visited, i);\n            provinces++;\n        }\n    }\n    cout << provinces << endl;\n    return 0;\n}',NULL,1),
(45,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[][] isConnected = new int[n][n];\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j < n; j++) {\n                isConnected[i][j] = sc.nextInt();\n            }\n        }\n        boolean[] visited = new boolean[n];\n        int provinces = 0;\n        for (int i = 0; i < n; i++) {\n            if (!visited[i]) {\n                dfs(isConnected, visited, i);\n                provinces++;\n            }\n        }\n        System.out.println(provinces);\n    }\n\n    private static void dfs(int[][] isConnected, boolean[] visited, int i) {\n        visited[i] = true;\n        for (int j = 0; j < isConnected.length; j++) {\n            if (isConnected[i][j] == 1 && !visited[j]) {\n                dfs(isConnected, visited, j);\n            }\n        }\n    }\n}',NULL,1),
(45,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    let idx = 0;\n    const n = parseInt(lines[idx++]);\n    const isConnected = [];\n    for (let i = 0; i < n; i++) {\n        isConnected.push(lines[idx++].split(/\\s+/).map(Number));\n    }\n    const visited = new Array(n).fill(false);\n    let provinces = 0;\n\n    function dfs(i) {\n        visited[i] = true;\n        for (let j = 0; j < n; j++) {\n            if (isConnected[i][j] === 1 && !visited[j]) {\n                dfs(j);\n            }\n        }\n    }\n\n    for (let i = 0; i < n; i++) {\n        if (!visited[i]) {\n            dfs(i);\n            provinces++;\n        }\n    }\n\n    console.log(provinces);\n});',NULL,1),
(45,'PYTHON','import sys\n\ndef dfs(isConnected, visited, i):\n    visited[i] = True\n    for j in range(len(isConnected)):\n        if isConnected[i][j] == 1 and not visited[j]:\n            dfs(isConnected, visited, j)\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    isConnected = []\n    idx = 1\n    for i in range(n):\n        row = []\n        for j in range(n):\n            row.append(int(data[idx]))\n            idx += 1\n        isConnected.append(row)\n    visited = [False] * n\n    provinces = 0\n    for i in range(n):\n        if not visited[i]:\n            dfs(isConnected, visited, i)\n            provinces += 1\n    print(provinces)\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(46,'SQL','SELECT email FROM Person GROUP BY email HAVING COUNT(*) > 1;',NULL,1),
(47,'SQL','SELECT (SELECT DISTINCT salary FROM Employee ORDER BY salary DESC LIMIT 1 OFFSET 1) AS SecondHighestSalary;',NULL,1),
(48,'SQL','DELETE p1 FROM Person p1\nJOIN Person p2 ON p1.email = p2.email AND p1.id > p2.id;',NULL,1),
(49,'SQL','SELECT w1.id\nFROM Weather w1\nJOIN Weather w2\n  ON DATEDIFF(w1.recordDate, w2.recordDate) = 1\nWHERE w1.temperature > w2.temperature;',NULL,1),
(50,'SQL','SELECT d.Name AS Department, e.Name AS Employee, e.Salary\nFROM Employee e\nJOIN Department d ON e.DepartmentId = d.Id\nWHERE (e.DepartmentId, e.Salary) IN (\n    SELECT DepartmentId, MAX(Salary)\n    FROM Employee\n    GROUP BY DepartmentId\n);',NULL,1),
(51,'TEXT','1. **连接**：TCP面向连接，需三次握手；UDP无连接，直接发送。\n2. **可靠性**：TCP可靠，有确认、重传、排序、去重；UDP不可靠，不保证送达和顺序。\n3. **传输方式**：TCP面向字节流；UDP面向数据报，保留报文边界。\n4. **速度与开销**：TCP头部20字节起，开销大、速度慢；UDP头部仅8字节，开销小、速度快。\n5. **拥塞与流量控制**：TCP有拥塞控制和流量控制；UDP无。\n6. **通信模式**：TCP仅一对一；UDP支持一对一、一对多、多对多（广播、组播）。\n7. **适用场景**：TCP用于文件传输、网页等要求可靠的场景；UDP用于直播、游戏、DNS等重实时低延迟场景。',NULL,1),
(52,'TEXT','1. **安全性**：HTTP明文传输，易被窃听篡改；HTTPS在HTTP下加入TLS/SSL加密，保证机密性、完整性。\n\n2. **端口**：HTTP默认80，HTTPS默认443。\n\n3. **证书**：HTTPS需CA颁发证书验证服务器身份，防中间人攻击；HTTP无身份验证。\n\n4. **性能**：HTTPS因加解密和握手，延迟略高、消耗更多CPU，但现代优化后差距很小。\n\n5. **URL**：HTTPS以https://开头，HTTP为http://。\n\n核心：HTTPS = HTTP + TLS，解决明文传输的安全问题。',NULL,1),
(53,'TEXT','HTTP 常见请求方法：\n\n- **GET**：获取资源，参数在 URL，幂等、可缓存，不改变服务端状态。\n- **POST**：提交数据、创建资源，参数在请求体，非幂等，不可缓存。\n- **PUT**：全量更新资源，幂等，客户端提供完整资源。\n- **PATCH**：局部更新资源，非幂等。\n- **DELETE**：删除资源，幂等。\n- **HEAD**：同 GET 但只返回响应头，用于探测。\n- **OPTIONS**：查询支持的方法，用于 CORS 预检。\n\n核心区分：**幂等性**（GET/PUT/DELETE 幂等，POST 非幂等）与**安全性**（GET/HEAD 安全，不修改资源）。',NULL,1),
(54,'TEXT','**核心区别：**\n\n1. **存储位置**：Cookie 存在客户端浏览器；Session 存在服务端（Session ID 通常借 Cookie 传给客户端）。\n2. **安全性**：Cookie 明文可见、可篡改，安全性低；Session 存服务端，相对安全。\n3. **容量**：Cookie 单个约 4KB 且数量受限；Session 受服务器内存限制，容量更大。\n4. **性能**：Cookie 随每次请求发送，增加带宽；Session 存服务端，但高并发下占内存、需考虑共享。\n5. **生命周期**：Cookie 可设过期时间长期保存；Session 随会话结束或超时失效。\n\n**使用场景**：Cookie 用于记住登录状态、偏好设置等非敏感轻量数据；Session 用于存用户身份、权限等敏感信息。',NULL,1),
(55,'TEXT','**跨域问题**：浏览器同源策略限制，协议、域名、端口任一不同即为跨域，导致 AJAX 请求被拦截（请求可能发出，但响应被阻止）。\n\n**常见解决方法**：\n1. **CORS**：服务端设置 `Access-Control-Allow-Origin` 等响应头，最主流。\n2. **Nginx 反向代理**：同源访问代理服务器，由服务器转发，规避浏览器限制。\n3. **JSONP**：利用 script 标签，仅支持 GET，已少用。\n4. **开发环境代理**：如 webpack/vite devServer proxy。\n5. **postMessage / document.domain**：用于窗口间通信或子域场景。\n\n**核心**：跨域是浏览器行为，服务端之间无跨域；CORS 需处理预检请求（OPTIONS）。',NULL,1),
(56,'TEXT','1. **定义**：进程是资源分配的基本单位；线程是CPU调度的基本单位。\n2. **资源**：进程有独立地址空间和资源；线程共享所属进程的资源（内存、文件等），仅独享栈和寄存器。\n3. **开销**：进程创建、切换、销毁开销大；线程轻量，切换开销小。\n4. **通信**：进程间通信需借助IPC（管道、共享内存等）；线程可直接读写共享内存，但需同步。\n5. **独立性**：进程相互隔离，一个崩溃不影响其他；线程共享进程，一个线程崩溃可能导致整个进程退出。\n6. **关系**：一个进程可含多个线程，线程依附于进程存在。',NULL,1),
(57,'TEXT','死锁产生的四个必要条件：\n\n1. **互斥**：资源一次只能被一个进程占用。\n2. **占有并等待**：进程已持有至少一个资源，同时又在等待其他被占用的资源。\n3. **不可剥夺**：资源只能由持有它的进程主动释放，不能被强行抢占。\n4. **循环等待**：存在一个进程与资源的环形等待链，每个进程都在等待下一个进程持有的资源。\n\n四个条件同时满足才可能死锁，破坏其中任一条件即可预防死锁。',NULL,1),
(58,'TEXT','常见进程调度算法：\n\n- **FCFS（先来先服务）**：按到达顺序执行，非抢占。实现简单，但长作业先到会导致短作业等待，平均等待时间长（护航效应）。\n- **SJF（短作业优先）**：选运行时间最短的进程，分抢占/非抢占。平均等待时间最优，但需预知运行时间，长作业可能饥饿。\n- **RR（时间片轮转）**：按到达顺序轮流执行固定时间片，抢占式。响应快、公平，适合分时系统；时间片过大退化为FCFS，过小则切换开销大。\n- **优先级调度**：按优先级选进程，分抢占/非抢占，低优先级可能饥饿，可用老化解决。\n- **多级反馈队列**：多队列不同优先级+时间片，兼顾响应与吞吐，综合性强。',NULL,1),
(59,'TEXT','常见页面置换算法：\n\n- **OPT（最佳置换）**：淘汰未来最长时间不被访问的页面。缺页率最低，但需预知未来，仅作理论基准。\n- **FIFO（先进先出）**：淘汰最早进入内存的页面。实现简单，但可能淘汰常用页，且存在 Belady 异常（增加物理块反而缺页增多）。\n- **LRU（最近最久未使用）**：淘汰最长时间未被访问的页面。基于局部性原理，性能接近 OPT，但需记录访问历史，开销较大。\n- **Clock（时钟）**：LRU 的近似，用循环队列加访问位，访问位置 1，淘汰时扫描置 0，兼顾性能与开销。\n\n考点：各算法淘汰依据、优缺点、Belady 异常及 LRU 与 OPT 的区别。',NULL,1),
(60,'TEXT','银行家算法是操作系统的**死锁避免**算法。\n\n- **原理**：进程运行前先声明最大资源需求。系统分配资源前，先试探性分配，再执行**安全性检查**：判断是否存在一个安全序列，使所有进程能依次获得所需资源并完成。若存在则真正分配，否则拒绝，让进程等待。\n- **核心数据结构**：可利用资源、最大需求、已分配、需求矩阵。\n- **作用**：在资源分配前预判是否会导致系统进入不安全状态，从而**避免死锁**，而非事后检测或解除。\n- **局限**：需预知最大需求、进程数固定、资源单一时效率低，实际中较少直接使用。',NULL,1),
(61,'TEXT','**概念**：保证一个类仅有一个实例，并提供全局访问点。\n\n**实现要点**：\n1. 私有构造器，禁止外部 new。\n2. 静态私有实例变量。\n3. 提供静态公有获取方法。\n\n**常见方式**：\n- 饿汉式：类加载即创建，线程安全但可能浪费。\n- 懒汉式：延迟创建，需加锁或用双重检查锁保证线程安全。\n- 静态内部类：延迟加载且线程安全，推荐。\n- 枚举：最简洁，天然防反射和反序列化破坏。\n\n**使用场景**：全局配置、连接池、线程池、日志对象、缓存等需唯一实例且频繁访问的资源。',NULL,1),
(62,'TEXT','工厂模式是创建型设计模式，用工厂封装对象创建过程，使调用方与具体类解耦。\n\n分类：\n1. 简单工厂：一个工厂类按参数创建不同产品，不属于GOF23，违反开闭原则。\n2. 工厂方法：定义创建接口，由子类决定实例化哪个类，符合开闭原则。\n3. 抽象工厂：创建一系列相关产品族，适合多产品线组合。\n\n使用场景：对象创建逻辑复杂或需隐藏具体实现；产品类型可能扩展；需统一管理一族产品。',NULL,1),
(63,'TEXT','**概念**：观察者模式定义一对多依赖关系，当被观察者（Subject）状态改变时，自动通知所有观察者（Observer）更新。\n\n**核心角色**：\n- Subject：维护观察者列表，提供注册/注销/通知接口。\n- Observer：定义更新接口，接收通知。\n\n**使用场景**：\n- 事件驱动系统：GUI 事件监听、按钮点击回调。\n- 消息订阅：发布-订阅、MQ、Redis 订阅。\n- 数据联动：MVC 中 Model 变化通知 View 刷新。\n- 跨模块解耦：状态变更需通知多个不相关模块。\n\n**优点**：解耦、支持广播、符合开闭原则。\n**缺点**：通知顺序不可控、观察者过多影响性能、可能循环依赖。',NULL,1),
(64,'TEXT','**概念**：策略模式定义一系列算法，将每个算法封装成独立类并可相互替换，使算法的变化独立于使用它的客户端。\n\n**核心角色**：抽象策略（接口）、具体策略（实现类）、上下文（持有策略并调用）。\n\n**使用场景**：\n1. 同一问题有多种算法，需运行时动态切换（如排序、支付方式、促销计算）。\n2. 用多分支 if-else/switch 判断不同行为，且分支会持续扩展。\n3. 需要隔离算法实现细节，避免客户端依赖具体算法。\n\n**优点**：符合开闭原则，消除条件分支，算法可复用、易扩展。\n**缺点**：策略类增多，客户端需了解各策略差异。',NULL,1),
(65,'TEXT','MVC是一种分层架构模式，将应用分为三层：\n\n- **Model（模型）**：封装数据和业务逻辑，负责数据的存取与状态管理，不依赖View和Controller。\n- **View（视图）**：负责数据展示和用户界面渲染，只呈现Model的数据，不处理业务逻辑。\n- **Controller（控制器）**：接收用户输入，调用Model处理业务，再选择合适的View返回结果，起协调调度作用。\n\n核心思想是**关注点分离**：三者职责单一、解耦，便于维护、复用和测试。',NULL,1),
(66,'TEXT','面向对象三大特性：\n\n1. **封装**：将数据和操作数据的方法绑定在一起，隐藏内部实现细节，仅对外暴露必要接口。目的是降低耦合、提高安全性和可维护性。\n\n2. **继承**：子类复用父类的属性和方法，并可扩展或重写。目的是代码复用、建立类之间的层次关系。分为单继承和多继承。\n\n3. **多态**：同一接口在不同对象上有不同表现。分为编译时多态（重载）和运行时多态（重写，依赖继承与父类引用指向子类对象）。目的是提高扩展性和灵活性。\n\n三者关系：封装是基础，继承是手段，多态是目的。',NULL,1),
(67,'TEXT','1. **定义**：抽象类用 abstract class 声明，可含抽象方法和具体方法；接口用 interface 声明，方法默认 public abstract（Java 8 后可有 default、static 方法）。\n\n2. **继承**：类只能单继承抽象类，但可实现多个接口。\n\n3. **成员变量**：抽象类可有普通变量、常量；接口变量默认 public static final 常量。\n\n4. **构造器**：抽象类有构造器；接口没有。\n\n5. **访问修饰符**：抽象类方法可用各种修饰符；接口方法默认 public。\n\n6. **设计语义**：抽象类表示“is-a”，用于代码复用；接口表示“can-do”，用于定义行为契约、解耦。\n\n7. **使用场景**：共性逻辑用抽象类，扩展能力用接口。',NULL,1),
(68,'TEXT','**重载（Overload）**：同一类中，方法名相同、参数列表不同（个数、类型、顺序），与返回值无关，编译期确定，是编译时多态。\n\n**重写（Override）**：子类重新实现父类方法，方法名、参数列表、返回值（协变除外）必须相同，访问权限不能更严，不能重写 private/static/final 方法，运行期确定，是运行时多态。\n\n**核心区别**：\n1. 范围：重载同类内，重写发生在父子类间。\n2. 签名：重载参数必须不同，重写参数必须相同。\n3. 时机：重载编译期绑定，重写运行期绑定。\n4. 目的：重载扩展同类方法形式，重写改变父类行为。',NULL,1),
(69,'TEXT','1. **指代对象**：this 指向当前对象自身；super 指向当前对象的父类部分（父类实例）。\n2. **访问成员**：this 访问本类成员（属性、方法），可区分同名参数与成员变量；super 访问父类成员，用于调用被子类重写的方法或父类属性。\n3. **调用构造器**：this() 调用本类其他构造器；super() 调用父类构造器。二者都必须放在构造器首行，且不能同时出现。\n4. **使用场景**：this 用于区分变量、链式调用、返回当前对象；super 用于子类访问父类被覆盖的成员、初始化父类。\n5. **本质**：this 是当前对象引用；super 不是引用，只是访问父类成员的语法关键字。',NULL,1),
(70,'TEXT','**概念**：继承是面向对象中让子类复用父类属性和方法的机制，表达“is-a”关系。\n\n**优点**：\n1. 代码复用，减少冗余。\n2. 提高可扩展性，子类可扩展父类功能。\n3. 多态基础，便于统一接口编程。\n\n**缺点**：\n1. 耦合度高，父类改动易影响子类（脆弱基类问题）。\n2. 破坏封装，子类依赖父类实现细节。\n3. 继承层次过深导致结构复杂、难维护。\n4. 灵活性差，运行期难以改变继承关系，常建议优先组合而非继承。',NULL,1),
(71,'TEXT','函数式编程核心概念：\n\n1. **纯函数**：相同输入必得相同输出，无副作用，不修改外部状态。\n2. **不可变性**：数据一旦创建不可更改，变更通过创建新数据实现。\n3. **一等函数**：函数可作为参数传递、作为返回值、赋值给变量。\n4. **高阶函数**：接收函数或返回函数的函数，如 map、filter、reduce。\n5. **函数组合**：将小函数组合成复杂函数，强调声明式而非命令式。\n6. **引用透明**：表达式可被其计算结果替换而不影响程序。\n\n特点：无副作用、易于测试与并发、代码简洁可推理；但可能带来性能开销与学习成本。',NULL,1),
(72,'TEXT','Lambda表达式是匿名函数，用于简化函数式接口（仅一个抽象方法的接口）的实例化。\n\n核心要点：\n1. 语法：(参数) -> 表达式或代码块，参数类型可省略，由编译器推断。\n2. 本质：编译后生成函数式接口的实现对象，可替代匿名内部类。\n3. 前提：目标类型必须是函数式接口，常用@FunctionalInterface标注。\n4. 变量捕获：只能引用final或事实上的final局部变量。\n5. 典型应用：集合遍历、排序、Stream流操作、线程创建。\n6. 与方法引用（::）配合，进一步简化代码。',NULL,1),
(73,'TEXT','Stream API用于对集合进行声明式、函数式处理，核心用法：\n\n1. **创建**：集合.stream()、Arrays.stream()、Stream.of()。\n2. **中间操作**（惰性，返回新流）：filter过滤、map映射、flatMap扁平化、distinct去重、sorted排序、limit/skip截取。\n3. **终端操作**（触发执行）：forEach遍历、collect收集、reduce归约、count、anyMatch/allMatch、findFirst。\n4. **特性**：惰性求值，需终端操作才执行；不修改原数据；支持串行与parallelStream并行。\n\n核心思想：链式调用，将数据处理流程化。',NULL,1),
(74,'TEXT','纯函数指满足以下两个条件的函数：\n\n1. **相同输入必返回相同输出**：结果只由入参决定，不依赖外部可变状态、时间、随机数等。\n2. **无副作用**：不修改外部状态，如不改全局变量、不修改入参、不做 I/O、不发请求、不打印日志。\n\n特点与意义：\n\n- **可预测**：调用结果稳定，便于推理和测试。\n- **易测试**：无需 mock 外部环境，给定输入即可断言输出。\n- **可缓存**：相同输入可复用结果（如 memoization）。\n- **利于并发**：不共享可变状态，天然线程安全。\n- **易组合**：可作为构建函数式编程的基础单元。\n\n核心一句话：**输出只依赖输入，且不产生任何可观察的副作用。**',NULL,1),
(75,'TEXT','**概念**：高阶函数是满足以下任一条件的函数：接收一个或多个函数作为参数；或返回一个函数作为结果。本质是把函数当作一等公民，可像普通值一样传递和返回。\n\n**使用场景**：\n1. **回调**：事件处理、异步回调，将行为参数化。\n2. **数组操作**：map、filter、reduce 等，用函数描述处理逻辑。\n3. **函数组合与柯里化**：compose、curry，复用和拼装逻辑。\n4. **装饰/增强**：在不改原函数前提下添加日志、缓存、权限等（如装饰器）。\n5. **抽象控制流**：把循环、条件等通用逻辑封装，只暴露变化部分。\n\n**核心价值**：提升抽象层次、代码复用性与可组合性。',NULL,1),
(76,'TEXT','**作用**：synchronized 用于实现线程同步，保证同一时刻只有一个线程执行临界区代码，具备原子性、可见性、有序性。\n\n**三种用法**：\n1. 修饰实例方法：锁为当前实例对象。\n2. 修饰静态方法：锁为当前类的 Class 对象。\n3. 修饰代码块：锁为括号内指定对象。\n\n**原理**：基于对象监视器（Monitor），通过 monitorenter/monitorexit 指令实现，锁信息存于对象头 Mark Word。\n\n**特性**：可重入、非公平（默认）、JDK1.6 后引入偏向锁、轻量级锁、自旋等优化，性能大幅提升。',NULL,1),
(77,'TEXT','**作用**：保证变量在多线程间的**可见性**和**有序性**，但不保证**原子性**。\n\n**原理**：\n1. **可见性**：写操作后立即刷回主内存，读操作直接从主内存读取，使其他线程能立即看到最新值。\n2. **有序性**：通过内存屏障禁止指令重排序，保证 volatile 读写前后的指令不被乱序执行。\n3. **不保证原子性**：如 `i++` 包含读、改、写三步，多线程下仍会出错，需配合锁或原子类。\n\n**典型场景**：状态标志位、双重检查锁定的单例（防止指令重排）。\n\n**与 synchronized 区别**：volatile 轻量，仅保证可见性和有序性；synchronized 还保证原子性和互斥。',NULL,1),
(78,'TEXT','**概念**：线程池是预先创建并复用线程的并发框架，任务提交到队列，由空闲线程取出执行，避免频繁创建销毁线程。\n\n**优点**：\n1. 降低资源消耗，复用线程；\n2. 提高响应速度，任务到达即执行；\n3. 统一管理，可控并发数，防止资源耗尽；\n4. 提供任务队列、拒绝策略等扩展能力。\n\n**常见实现**：\n- Java：`ThreadPoolExecutor`（核心参数：核心/最大线程数、队列、拒绝策略），及 `Executors` 工具类；\n- 其他：C++ 手写线程池、Go 的 goroutine 调度、Python `concurrent.futures`。\n\n**核心考点**：任务调度流程、参数配置、拒绝策略、线程复用原理。',NULL,1),
(79,'TEXT','CAS（Compare-And-Swap）是一种无锁原子操作，用于实现并发同步。\n\n**概念**：包含三个操作数——内存位置V、预期旧值A、新值B。仅当V的当前值等于A时，才将V更新为B，否则不做任何操作。整个比较与交换过程由硬件保证原子性。\n\n**原理**：\n1. CPU提供原子指令（如x86的cmpxchg）实现，无需加锁。\n2. 返回操作是否成功，失败通常配合自旋重试。\n3. 存在ABA问题：值从A改为B又改回A，CAS无法察觉，可用版本号（如AtomicStampedReference）解决。\n\n**应用**：Java的AtomicInteger、AQS、无锁队列等底层均基于CAS。',NULL,1),
(80,'TEXT','AQS（AbstractQueuedSynchronizer）是JUC中构建锁和同步器的核心框架，基于模板方法模式。\n\n核心要点：\n1. **核心结构**：一个volatile的state状态位 + 一个FIFO双向等待队列（CLH变体）。\n2. **state含义**：由子类定义，如ReentrantLock表示重入次数，Semaphore表示许可数。\n3. **获取/释放**：通过CAS修改state，失败则封装成Node入队并阻塞（LockSupport.park）。\n4. **两种模式**：独占（如ReentrantLock）和共享（如Semaphore、CountDownLatch）。\n5. **作用**：屏蔽排队、阻塞、唤醒等复杂细节，子类只需实现tryAcquire/tryRelease等方法即可自定义同步器。',NULL,1),
(81,'TEXT','CAP定理：分布式系统中，一致性（Consistency）、可用性（Availability）、分区容错性（Partition tolerance）三者不可同时满足，最多满足两个。\n\n- **一致性C**：所有节点同一时刻看到相同数据，读操作总能返回最新写入值。\n- **可用性A**：每个请求都能在有限时间内得到非错误响应，但不保证是最新数据。\n- **分区容错性P**：网络分区（节点间消息丢失或延迟）时系统仍能继续运行。\n\n由于网络分区在分布式系统中不可避免，P通常必须保留，因此实际是在C和A之间取舍：如CP（ZooKeeper）、AP（Cassandra）。',NULL,1),
(82,'TEXT','分布式事务指事务操作跨多个节点/数据源，需保证整体ACID。\n\n常见方案：\n1. **2PC/3PC**：协调者统一提交，强一致但阻塞、性能差。\n2. **TCC**：Try-Confirm-Cancel，业务层补偿，侵入性强。\n3. **本地消息表/事务消息**：借助MQ最终一致，实现简单。\n4. **Saga**：长事务拆分为子事务，失败逐级补偿。\n5. **Seata**：AT模式自动补偿，对业务侵入小。\n\n核心权衡：强一致（2PC）vs 最终一致（消息、Saga、TCC）。',NULL,1),
(83,'TEXT','**概念**：一致性哈希将哈希空间组织成环（0~2³²-1），节点和数据都映射到环上，数据顺时针归属最近的节点。增删节点时只影响相邻区间，而非全部重映射。\n\n**核心机制**：\n- 普通哈希取模，节点数变化会导致几乎所有 key 失效；一致性哈希只迁移约 1/N 的数据。\n- 用**虚拟节点**解决数据倾斜：每个物理节点映射多个虚拟节点，使分布更均匀。\n\n**应用场景**：\n- 分布式缓存（如 Redis 集群）的 key 路由。\n- 负载均衡、分布式存储的数据分片。\n- 需动态扩缩容且要求最小数据迁移的场景。',NULL,1),
(84,'TEXT','**概念**：将请求按策略分发到多台服务器，避免单点过载。\n\n**作用**：\n- 提升吞吐量与可用性\n- 避免单点故障，支持水平扩展\n- 便于维护与灰度发布\n\n**常见算法**：\n- 轮询 / 加权轮询：依次分发，按性能加权\n- 随机 / 加权随机\n- 最少连接：发给当前连接最少的节点\n- 一致性哈希：同key固定落到同节点，减少缓存失效\n- IP哈希：同IP固定节点，保持会话\n\n**层次**：四层（LVS，基于IP/端口）、七层（Nginx，基于URL/Header）。',NULL,1),
(85,'TEXT','**概念**：将单一应用按业务拆分为多个独立部署的小服务，服务间通过轻量级通信（如 HTTP/RPC）协作，每个服务可独立开发、部署、扩展。\n\n**优点**：\n- 服务解耦，边界清晰，便于团队并行开发\n- 独立部署与扩容，故障隔离，单点问题不影响全局\n- 技术栈灵活，可按服务选型\n\n**缺点**：\n- 分布式复杂度高：网络延迟、调用失败、数据一致性难保证\n- 运维成本大：需服务发现、配置中心、链路追踪、监控等配套\n- 调试与测试困难，跨服务事务处理复杂\n\n**核心考点**：拆分粒度、分布式带来的复杂度与治理成本，适用场景是业务复杂、团队规模大的系统。',NULL,1),
(86,'TEXT','学习编程的核心方法：\n\n1. **选对语言与方向**：根据目标（后端、前端、数据）选一门主流语言，避免频繁切换。\n2. **系统学习基础**：掌握语法、数据结构、算法、操作系统、网络等核心知识。\n3. **动手实践**：通过写小项目、刷题、复现轮子加深理解，拒绝只看不写。\n4. **阅读源码与文档**：学习优秀开源项目，理解工程化写法与设计思想。\n5. **调试与总结**：善用调试工具，记录踩坑与解决方案，形成知识体系。\n6. **持续迭代**：参与真实项目或开源，接受代码评审，保持输入与输出平衡。\n\n关键：**刻意练习 + 项目驱动 + 持续反馈**。',NULL,1),
(87,'TEXT','**核心考点：稳定性、上进心、岗位匹配度。**\n\n回答分三层：\n\n1. **短期（1年）**：快速熟悉业务与团队协作，独立承担岗位职责，达到考核要求。\n2. **中期（2-3年）**：深耕专业领域，提升核心技能，能主导项目或模块，成为团队骨干。\n3. **长期（3-5年）**：结合公司发展，向更高阶方向（技术专家或管理）成长，持续为团队创造价值。\n\n**要点**：规划须与应聘岗位、公司方向一致；体现踏实、稳定、有目标，避免空泛或显得随时跳槽。',NULL,1),
(88,'TEXT','核心考点：用 STAR 法则讲清项目，突出个人贡献与量化结果。\n\n- **背景**：一句话说明项目目标、规模、你的角色。\n- **挑战**：点明最难的技术或协作难点（如高并发、性能瓶颈、跨团队）。\n- **行动**：重点讲“我”做了什么，而非团队做了什么；说清技术选型与决策理由。\n- **结果**：用数据量化，如性能提升、成本下降、上线收益。\n- **反思**：一句总结收获或改进点。\n\n避免流水账，突出个人不可替代性，准备被追问细节。',NULL,1),
(89,'TEXT','**考点**：考察自我认知、岗位匹配度、改进意识。\n\n**优点**：选1-2个与岗位强相关的，用具体事例佐证。如\"执行力强，曾主导XX项目按期交付\"。\n\n**缺点**：说真实但非致命的，避免\"我太追求完美\"这类伪缺点。如\"公开表达经验不足\"。\n\n**改进**：给出可落地的行动，如\"主动争取汇报机会，已坚持每月做一次分享\"。\n\n**原则**：\n- 优点扣岗位需求，缺点不碰核心能力红线。\n- 缺点必须配改进措施，体现成长性。\n- 真诚具体，忌空泛套话。',NULL,1),
(90,'TEXT','核心考点：动机真实性、岗位匹配度、公司认同感。\n\n1. **认同公司**：点出公司业务、产品、行业地位或文化中你真正认可的一点，避免空泛吹捧。\n2. **匹配岗位**：说明你的技能、经验与岗位要求高度契合，能快速上手并创造价值。\n3. **结合规划**：表达公司平台符合你的职业发展方向，你想在此长期成长。\n4. **差异化**：可提一个具体细节（如某产品、某技术、某价值观），体现你做过功课。\n\n答题结构：认可公司 + 我能贡献什么 + 我想获得什么成长。忌只谈公司好或只谈自己需要。',NULL,1),
(91,'TEXT','1. 核心流程：长链→唯一短码→存储映射；访问短链→查映射→302重定向。\n2. 短码生成：可用自增ID转62进制，或哈希+冲突处理；需全局唯一、不可预测可选加随机盐。\n3. 存储：KV存储，短码为key，长链为value；量大时用Redis缓存热点，MySQL持久化。\n4. 高并发：读多写少，缓存+CDN+分库分表；写走发号器或分布式ID。\n5. 重定向：用302便于统计和后续修改；如需永久用301。\n6. 扩展：防刷、限流、过期清理、统计点击、自定义短码。',NULL,1),
(92,'TEXT','1. 需求：单聊/群聊、在线状态、消息可靠投递、离线消息、多端同步。\n\n2. 架构：客户端通过 WebSocket 长连接接入网关层；网关无状态，用一致性哈希路由到同一用户连接。\n\n3. 存储：消息存 MySQL/Cassandra，按会话+时间分片；最近消息用 Redis 缓存；未读数、在线状态用 Redis。\n\n4. 投递：发送方消息先落库再推送；接收方在线则网关直推，离线则存离线表，上线拉取。\n\n5. 群聊：写扩散（小群）或读扩散（大群），用消息队列削峰异步投递。\n\n6. 可靠性：ACK 确认+重传、消息去重（seq/msgId）、有序性靠会话内递增序列号。\n\n7. 扩展：网关水平扩容，心跳保活，断线重连补拉增量消息。',NULL,1),
(93,'TEXT','核心思路：层层过滤，把流量挡在数据库之前。\n\n1. **前端**：按钮置灰防重复提交；静态资源走 CDN。\n2. **网关/接入层**：限流（令牌桶）、黑名单、验证码削峰。\n3. **Redis 预扣库存**：用 Lua 脚本原子判断并扣减，库存不足直接返回，避免超卖。\n4. **异步下单**：扣减成功后发 MQ，异步落库创建订单，削峰填谷。\n5. **数据库**：库存字段加乐观锁/唯一索引兜底，防超卖。\n6. **兜底**：失败重试、幂等（订单号去重）、限购。\n\n要点：Redis 抗量、MQ 异步、DB 兜底，保证不超卖、高可用。',NULL,1),
(94,'TEXT','1. 架构：客户端→路由层（一致性哈希）→缓存节点，节点间无共享，支持水平扩展。\n2. 数据分布：一致性哈希+虚拟节点，减少扩缩容时的数据迁移。\n3. 缓存策略：LRU/LFU 淘汰，TTL 过期，读多写少场景用 Cache-Aside。\n4. 高可用：主从复制+哨兵/集群选主，故障自动切换；多副本防单点。\n5. 一致性：最终一致，写时更新 DB 后删缓存（延迟双删），读时回填。\n6. 穿透/击穿/雪崩：布隆过滤器、互斥锁重建、过期时间加随机。\n7. 监控：命中率、延迟、内存、热点 key，支撑扩容与调优。',NULL,1),
(95,'TEXT','1. 采集：Agent（Filebeat/Fluentd）收集日志，异步发送，本地磁盘缓冲防丢。\n2. 传输：Kafka 削峰解耦，按主题分区，保证高吞吐与顺序性。\n3. 存储：分冷热。热数据存 ES 供实时检索；冷数据压缩后入对象存储（S3/HDFS）降成本。\n4. 分析：实时用 Flink/Spark Streaming 做告警与聚合；离线跑批做统计。\n5. 查询：Kibana/Grafana 可视化，按时间+索引分片。\n6. 保障：限流、背压、副本容错、TTL 清理。',NULL,1),
(96,'C','#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct {\n    int key;\n    int value;\n} Entry;\n\nint main() {\n    int n, target;\n    scanf(\"%d %d\", &n, &target);\n    int *nums = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    Entry *map = (Entry *)malloc(n * sizeof(Entry));\n    int size = 0;\n\n    for (int i = 0; i < n; i++) {\n        int complement = target - nums[i];\n        for (int j = 0; j < size; j++) {\n            if (map[j].key == complement) {\n                printf(\"[%d,%d]\\n\", map[j].value, i);\n                free(nums);\n                free(map);\n                return 0;\n            }\n        }\n        map[size].key = nums[i];\n        map[size].value = i;\n        size++;\n    }\n\n    free(nums);\n    free(map);\n    return 0;\n}',NULL,1),
(96,'CPP','#include <iostream>\n#include <vector>\n#include <unordered_map>\nusing namespace std;\n\nint main() {\n    int n, target;\n    cin >> n >> target;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    unordered_map<int, int> map;\n    for (int i = 0; i < n; i++) {\n        int complement = target - nums[i];\n        if (map.find(complement) != map.end()) {\n            cout << \"[\" << map[complement] << \",\" << i << \"]\" << endl;\n            return 0;\n        }\n        map[nums[i]] = i;\n    }\n    return 0;\n}',NULL,1),
(96,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int target = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        Map<Integer, Integer> map = new HashMap<>();\n        for (int i = 0; i < n; i++) {\n            int complement = target - nums[i];\n            if (map.containsKey(complement)) {\n                System.out.println(\"[\" + map.get(complement) + \",\" + i + \"]\");\n                return;\n            }\n            map.put(nums[i], i);\n        }\n    }\n}',NULL,1),
(96,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n  input: process.stdin,\n  output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n  lines.push(line.trim());\n  if (lines.length === 2) {\n    const [n, target] = lines[0].split(\' \').map(Number);\n    const nums = lines[1].split(\' \').map(Number);\n    const map = new Map();\n    for (let i = 0; i < n; i++) {\n      const complement = target - nums[i];\n      if (map.has(complement)) {\n        console.log(`[${map.get(complement)},${i}]`);\n        rl.close();\n        return;\n      }\n      map.set(nums[i], i);\n    }\n    rl.close();\n  }\n});',NULL,1),
(96,'PYTHON','n, target = map(int, input().split())\nnums = list(map(int, input().split()))\nseen = {}\nfor i, num in enumerate(nums):\n    complement = target - num\n    if complement in seen:\n        print(f\"[{seen[complement]},{i}]\")\n        break\n    seen[num] = i',NULL,1),
(97,'C','#include <stdio.h>\n#include <string.h>\n\nint lengthOfLongestSubstring(char *s) {\n    int last[128];\n    for (int i = 0; i < 128; i++) {\n        last[i] = -1;\n    }\n    int maxLen = 0;\n    int left = 0;\n    int len = strlen(s);\n    for (int right = 0; right < len; right++) {\n        unsigned char c = (unsigned char)s[right];\n        if (last[c] >= left) {\n            left = last[c] + 1;\n        }\n        last[c] = right;\n        int curLen = right - left + 1;\n        if (curLen > maxLen) {\n            maxLen = curLen;\n        }\n    }\n    return maxLen;\n}\n\nint main() {\n    char s[1000000];\n    if (fgets(s, sizeof(s), stdin) != NULL) {\n        size_t len = strlen(s);\n        if (len > 0 && s[len - 1] == \'\\n\') {\n            s[len - 1] = \'\\0\';\n        }\n        printf(\"%d\\n\", lengthOfLongestSubstring(s));\n    }\n    return 0;\n}',NULL,1),
(97,'CPP','#include <iostream>\n#include <string>\n#include <algorithm>\nusing namespace std;\n\nint lengthOfLongestSubstring(const string& s) {\n    int last[128];\n    for (int i = 0; i < 128; i++) {\n        last[i] = -1;\n    }\n    int maxLen = 0;\n    int left = 0;\n    for (int right = 0; right < (int)s.length(); right++) {\n        char c = s[right];\n        if (last[(int)c] >= left) {\n            left = last[(int)c] + 1;\n        }\n        last[(int)c] = right;\n        maxLen = max(maxLen, right - left + 1);\n    }\n    return maxLen;\n}\n\nint main() {\n    string s;\n    if (getline(cin, s)) {\n        cout << lengthOfLongestSubstring(s) << endl;\n    }\n    return 0;\n}',NULL,1),
(97,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        if (scanner.hasNextLine()) {\n            String s = scanner.nextLine();\n            System.out.println(lengthOfLongestSubstring(s));\n        }\n    }\n\n    public static int lengthOfLongestSubstring(String s) {\n        int[] last = new int[128];\n        for (int i = 0; i < 128; i++) {\n            last[i] = -1;\n        }\n        int maxLen = 0;\n        int left = 0;\n        for (int right = 0; right < s.length(); right++) {\n            char c = s.charAt(right);\n            if (last[c] >= left) {\n                left = last[c] + 1;\n            }\n            last[c] = right;\n            maxLen = Math.max(maxLen, right - left + 1);\n        }\n        return maxLen;\n    }\n}',NULL,1),
(97,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (s) => {\n    console.log(lengthOfLongestSubstring(s));\n    rl.close();\n});\n\nfunction lengthOfLongestSubstring(s) {\n    const last = new Array(128).fill(-1);\n    let maxLen = 0;\n    let left = 0;\n    for (let right = 0; right < s.length; right++) {\n        const c = s.charCodeAt(right);\n        if (last[c] >= left) {\n            left = last[c] + 1;\n        }\n        last[c] = right;\n        maxLen = Math.max(maxLen, right - left + 1);\n    }\n    return maxLen;\n}',NULL,1),
(97,'PYTHON','import sys\n\ndef lengthOfLongestSubstring(s):\n    last = [-1] * 128\n    maxLen = 0\n    left = 0\n    for right, c in enumerate(s):\n        code = ord(c)\n        if last[code] >= left:\n            left = last[code] + 1\n        last[code] = right\n        maxLen = max(maxLen, right - left + 1)\n    return maxLen\n\nif __name__ == \"__main__\":\n    s = sys.stdin.readline().rstrip(\'\\n\')\n    print(lengthOfLongestSubstring(s))',NULL,1),
(98,'C','#include <stdio.h>\n#include <string.h>\n\nint expand(char *s, int left, int right, int n) {\n    while (left >= 0 && right < n && s[left] == s[right]) {\n        left--;\n        right++;\n    }\n    return right - left - 1;\n}\n\nint main() {\n    char s[100000];\n    if (!fgets(s, sizeof(s), stdin)) return 0;\n    int n = strlen(s);\n    if (n > 0 && s[n - 1] == \'\\n\') {\n        s[n - 1] = \'\\0\';\n        n--;\n    }\n    if (n == 0) {\n        printf(\"\\n\");\n        return 0;\n    }\n    int start = 0, end = 0;\n    for (int i = 0; i < n; i++) {\n        int len1 = expand(s, i, i, n);\n        int len2 = expand(s, i, i + 1, n);\n        int len = len1 > len2 ? len1 : len2;\n        if (len > end - start + 1) {\n            start = i - (len - 1) / 2;\n            end = i + len / 2;\n        }\n    }\n    for (int i = start; i <= end; i++) {\n        putchar(s[i]);\n    }\n    putchar(\'\\n\');\n    return 0;\n}',NULL,1),
(98,'CPP','#include <iostream>\n#include <string>\nusing namespace std;\n\nint expand(const string& s, int left, int right) {\n    while (left >= 0 && right < (int)s.length() && s[left] == s[right]) {\n        left--;\n        right++;\n    }\n    return right - left - 1;\n}\n\nint main() {\n    string s;\n    if (!getline(cin, s)) return 0;\n    if (s.empty()) {\n        cout << \"\" << endl;\n        return 0;\n    }\n    int start = 0, end = 0;\n    for (int i = 0; i < (int)s.length(); i++) {\n        int len1 = expand(s, i, i);\n        int len2 = expand(s, i, i + 1);\n        int len = max(len1, len2);\n        if (len > end - start + 1) {\n            start = i - (len - 1) / 2;\n            end = i + len / 2;\n        }\n    }\n    cout << s.substr(start, end - start + 1) << endl;\n    return 0;\n}',NULL,1),
(98,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextLine()) return;\n        String s = sc.nextLine();\n        if (s == null || s.length() == 0) {\n            System.out.println(\"\");\n            return;\n        }\n        int start = 0, end = 0;\n        for (int i = 0; i < s.length(); i++) {\n            int len1 = expand(s, i, i);\n            int len2 = expand(s, i, i + 1);\n            int len = Math.max(len1, len2);\n            if (len > end - start + 1) {\n                start = i - (len - 1) / 2;\n                end = i + len / 2;\n            }\n        }\n        System.out.println(s.substring(start, end + 1));\n    }\n\n    private static int expand(String s, int left, int right) {\n        while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) {\n            left--;\n            right++;\n        }\n        return right - left - 1;\n    }\n}',NULL,1),
(98,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (s) => {\n    if (s === null || s.length === 0) {\n        console.log(\"\");\n        rl.close();\n        return;\n    }\n    let start = 0, end = 0;\n    for (let i = 0; i < s.length; i++) {\n        let len1 = expand(s, i, i);\n        let len2 = expand(s, i, i + 1);\n        let len = Math.max(len1, len2);\n        if (len > end - start + 1) {\n            start = i - Math.floor((len - 1) / 2);\n            end = i + Math.floor(len / 2);\n        }\n    }\n    console.log(s.substring(start, end + 1));\n    rl.close();\n});\n\nfunction expand(s, left, right) {\n    while (left >= 0 && right < s.length && s[left] === s[right]) {\n        left--;\n        right++;\n    }\n    return right - left - 1;\n}',NULL,1),
(98,'PYTHON','import sys\n\ndef expand(s, left, right):\n    while left >= 0 and right < len(s) and s[left] == s[right]:\n        left -= 1\n        right += 1\n    return right - left - 1\n\ndef main():\n    s = sys.stdin.readline().rstrip(\'\\n\')\n    if not s:\n        print(\"\")\n        return\n    start, end = 0, 0\n    for i in range(len(s)):\n        len1 = expand(s, i, i)\n        len2 = expand(s, i, i + 1)\n        length = max(len1, len2)\n        if length > end - start + 1:\n            start = i - (length - 1) // 2\n            end = i + length // 2\n    print(s[start:end + 1])\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(99,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nstruct ListNode {\n    int val;\n    struct ListNode *next;\n};\n\nstruct ListNode* reverseList(struct ListNode* head) {\n    struct ListNode* prev = NULL;\n    struct ListNode* curr = head;\n    while (curr != NULL) {\n        struct ListNode* nextTemp = curr->next;\n        curr->next = prev;\n        prev = curr;\n        curr = nextTemp;\n    }\n    return prev;\n}\n\nint main() {\n    char input[100000];\n    if (fgets(input, sizeof(input), stdin) == NULL) {\n        return 0;\n    }\n\n    size_t len = strlen(input);\n    while (len > 0 && (input[len - 1] == \'\\n\' || input[len - 1] == \'\\r\')) {\n        input[--len] = \'\\0\';\n    }\n\n    struct ListNode dummy;\n    dummy.val = 0;\n    dummy.next = NULL;\n    struct ListNode* tail = &dummy;\n\n    char* token = strtok(input, \"->\");\n    while (token != NULL) {\n        if (strcmp(token, \"NULL\") == 0) {\n            break;\n        }\n        int val = atoi(token);\n        struct ListNode* node = (struct ListNode*)malloc(sizeof(struct ListNode));\n        node->val = val;\n        node->next = NULL;\n        tail->next = node;\n        tail = node;\n        token = strtok(NULL, \"->\");\n    }\n\n    struct ListNode* reversed = reverseList(dummy.next);\n\n    struct ListNode* curr = reversed;\n    while (curr != NULL) {\n        printf(\"%d->\", curr->val);\n        curr = curr->next;\n    }\n    printf(\"NULL\\n\");\n\n    return 0;\n}',NULL,1),
(99,'CPP','#include <iostream>\n#include <string>\n#include <sstream>\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int x) : val(x), next(nullptr) {}\n};\n\nListNode* reverseList(ListNode* head) {\n    ListNode* prev = nullptr;\n    ListNode* curr = head;\n    while (curr != nullptr) {\n        ListNode* nextTemp = curr->next;\n        curr->next = prev;\n        prev = curr;\n        curr = nextTemp;\n    }\n    return prev;\n}\n\nint main() {\n    std::ios::sync_with_stdio(false);\n    std::cin.tie(nullptr);\n\n    std::string input;\n    std::getline(std::cin, input);\n\n    ListNode dummy(0);\n    ListNode* tail = &dummy;\n\n    size_t pos = 0;\n    while (pos < input.size()) {\n        size_t nextPos = input.find(\"->\", pos);\n        std::string part;\n        if (nextPos == std::string::npos) {\n            part = input.substr(pos);\n            pos = input.size();\n        } else {\n            part = input.substr(pos, nextPos - pos);\n            pos = nextPos + 2;\n        }\n\n        if (part == \"NULL\") {\n            break;\n        }\n\n        int val = std::stoi(part);\n        tail->next = new ListNode(val);\n        tail = tail->next;\n    }\n\n    ListNode* reversed = reverseList(dummy.next);\n\n    std::ostringstream oss;\n    ListNode* curr = reversed;\n    while (curr != nullptr) {\n        oss << curr->val << \"->\";\n        curr = curr->next;\n    }\n    oss << \"NULL\";\n    std::cout << oss.str() << \"\\n\";\n\n    return 0;\n}',NULL,1),
(99,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) {\n            this.val = val;\n        }\n    }\n\n    public static ListNode reverseList(ListNode head) {\n        ListNode prev = null;\n        ListNode curr = head;\n        while (curr != null) {\n            ListNode nextTemp = curr.next;\n            curr.next = prev;\n            prev = curr;\n            curr = nextTemp;\n        }\n        return prev;\n    }\n\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        String input = scanner.nextLine().trim();\n        String[] parts = input.split(\"->\");\n        ListNode dummy = new ListNode(0);\n        ListNode tail = dummy;\n        for (String part : parts) {\n            if (part.equals(\"NULL\")) {\n                break;\n            }\n            int val = Integer.parseInt(part);\n            tail.next = new ListNode(val);\n            tail = tail.next;\n        }\n\n        ListNode reversed = reverseList(dummy.next);\n\n        StringBuilder sb = new StringBuilder();\n        ListNode curr = reversed;\n        while (curr != null) {\n            sb.append(curr.val).append(\"->\");\n            curr = curr.next;\n        }\n        sb.append(\"NULL\");\n        System.out.println(sb.toString());\n    }\n}',NULL,1),
(99,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass ListNode {\n    constructor(val) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction reverseList(head) {\n    let prev = null;\n    let curr = head;\n    while (curr !== null) {\n        let nextTemp = curr.next;\n        curr.next = prev;\n        prev = curr;\n        curr = nextTemp;\n    }\n    return prev;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const input = line.trim();\n    const parts = input.split(\'->\');\n    const dummy = new ListNode(0);\n    let tail = dummy;\n    for (const part of parts) {\n        if (part === \'NULL\') {\n            break;\n        }\n        const val = parseInt(part, 10);\n        tail.next = new ListNode(val);\n        tail = tail.next;\n    }\n\n    const reversed = reverseList(dummy.next);\n\n    let sb = \'\';\n    let curr = reversed;\n    while (curr !== null) {\n        sb += curr.val + \'->\';\n        curr = curr.next;\n    }\n    sb += \'NULL\';\n    console.log(sb);\n    rl.close();\n});',NULL,1),
(99,'PYTHON','import sys\n\nclass ListNode:\n    def __init__(self, val):\n        self.val = val\n        self.next = None\n\ndef reverseList(head):\n    prev = None\n    curr = head\n    while curr is not None:\n        nextTemp = curr.next\n        curr.next = prev\n        prev = curr\n        curr = nextTemp\n    return prev\n\ndef main():\n    input_str = sys.stdin.readline().strip()\n    parts = input_str.split(\"->\")\n    dummy = ListNode(0)\n    tail = dummy\n    for part in parts:\n        if part == \"NULL\":\n            break\n        val = int(part)\n        tail.next = ListNode(val)\n        tail = tail.next\n\n    reversed_head = reverseList(dummy.next)\n\n    sb = []\n    curr = reversed_head\n    while curr is not None:\n        sb.append(str(curr.val))\n        sb.append(\"->\")\n        curr = curr.next\n    sb.append(\"NULL\")\n    print(\"\".join(sb))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(100,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nstruct ListNode {\n    int val;\n    struct ListNode *next;\n};\n\nstruct ListNode* parseList(char *line) {\n    if (line == NULL) return NULL;\n    while (*line == \' \' || *line == \'\\t\' || *line == \'\\n\' || *line == \'\\r\') line++;\n    if (*line == \'\\0\' || strcmp(line, \"NULL\") == 0) return NULL;\n\n    struct ListNode dummy;\n    dummy.val = 0;\n    dummy.next = NULL;\n    struct ListNode *cur = &dummy;\n\n    char *token = strtok(line, \"->\");\n    while (token != NULL) {\n        while (*token == \' \' || *token == \'\\t\') token++;\n        if (strcmp(token, \"NULL\") == 0) break;\n        struct ListNode *node = (struct ListNode*)malloc(sizeof(struct ListNode));\n        node->val = atoi(token);\n        node->next = NULL;\n        cur->next = node;\n        cur = cur->next;\n        token = strtok(NULL, \"->\");\n    }\n    return dummy.next;\n}\n\nstruct ListNode* mergeTwoLists(struct ListNode* l1, struct ListNode* l2) {\n    struct ListNode dummy;\n    dummy.val = 0;\n    dummy.next = NULL;\n    struct ListNode *cur = &dummy;\n\n    while (l1 != NULL && l2 != NULL) {\n        if (l1->val <= l2->val) {\n            cur->next = l1;\n            l1 = l1->next;\n        } else {\n            cur->next = l2;\n            l2 = l2->next;\n        }\n        cur = cur->next;\n    }\n    if (l1 != NULL) cur->next = l1;\n    if (l2 != NULL) cur->next = l2;\n    return dummy.next;\n}\n\nint main() {\n    char line1[10000];\n    char line2[10000];\n\n    if (fgets(line1, sizeof(line1), stdin) == NULL) return 0;\n    if (fgets(line2, sizeof(line2), stdin) == NULL) return 0;\n\n    line1[strcspn(line1, \"\\n\")] = \'\\0\';\n    line2[strcspn(line2, \"\\n\")] = \'\\0\';\n\n    struct ListNode *l1 = parseList(line1);\n    struct ListNode *l2 = parseList(line2);\n\n    struct ListNode *merged = mergeTwoLists(l1, l2);\n\n    struct ListNode *cur = merged;\n    while (cur != NULL) {\n        printf(\"%d\", cur->val);\n        if (cur->next != NULL) {\n            printf(\"->\");\n        }\n        cur = cur->next;\n    }\n    printf(\"\\n\");\n\n    return 0;\n}',NULL,1),
(100,'CPP','#include <iostream>\n#include <string>\n#include <sstream>\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int val) : val(val), next(nullptr) {}\n};\n\nListNode* parseList(const std::string& line) {\n    if (line.empty()) {\n        return nullptr;\n    }\n    std::string s = line;\n    // trim\n    size_t start = s.find_first_not_of(\" \\t\\r\\n\");\n    if (start == std::string::npos) return nullptr;\n    size_t end = s.find_last_not_of(\" \\t\\r\\n\");\n    s = s.substr(start, end - start + 1);\n\n    if (s.empty() || s == \"NULL\") {\n        return nullptr;\n    }\n    if (s.size() >= 6 && s.substr(s.size() - 6) == \"->NULL\") {\n        s = s.substr(0, s.size() - 6);\n    } else if (s.size() >= 4 && s.substr(s.size() - 4) == \"NULL\") {\n        s = s.substr(0, s.size() - 4);\n        if (s.size() >= 2 && s.substr(s.size() - 2) == \"->\") {\n            s = s.substr(0, s.size() - 2);\n        }\n    }\n    if (s.empty()) {\n        return nullptr;\n    }\n\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    std::stringstream ss(s);\n    std::string part;\n    while (std::getline(ss, part, \'-\')) {\n        // getline with \'-\' delimiter will split \"1->2\" into \"1\" and \">2\"\n        // Better to manually parse\n    }\n\n    // Manual parse by \"->\"\n    size_t pos = 0;\n    while (pos < s.size()) {\n        size_t nextPos = s.find(\"->\", pos);\n        std::string token;\n        if (nextPos == std::string::npos) {\n            token = s.substr(pos);\n            pos = s.size();\n        } else {\n            token = s.substr(pos, nextPos - pos);\n            pos = nextPos + 2;\n        }\n        // trim token\n        size_t ts = token.find_first_not_of(\" \\t\\r\\n\");\n        if (ts == std::string::npos) continue;\n        size_t te = token.find_last_not_of(\" \\t\\r\\n\");\n        token = token.substr(ts, te - ts + 1);\n        if (token.empty()) continue;\n        cur->next = new ListNode(std::stoi(token));\n        cur = cur->next;\n    }\n    return dummy.next;\n}\n\nListNode* mergeTwoLists(ListNode* l1, ListNode* l2) {\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    while (l1 != nullptr && l2 != nullptr) {\n        if (l1->val <= l2->val) {\n            cur->next = l1;\n            l1 = l1->next;\n        } else {\n            cur->next = l2;\n            l2 = l2->next;\n        }\n        cur = cur->next;\n    }\n    if (l1 != nullptr) {\n        cur->next = l1;\n    } else {\n        cur->next = l2;\n    }\n    return dummy.next;\n}\n\nint main() {\n    std::string line1, line2;\n    std::getline(std::cin, line1);\n    std::getline(std::cin, line2);\n\n    ListNode* l1 = parseList(line1);\n    ListNode* l2 = parseList(line2);\n\n    ListNode* merged = mergeTwoLists(l1, l2);\n\n    std::string result;\n    ListNode* cur = merged;\n    while (cur != nullptr) {\n        result += std::to_string(cur->val);\n        if (cur->next != nullptr) {\n            result += \"->\";\n        }\n        cur = cur->next;\n    }\n    std::cout << result;\n    return 0;\n}',NULL,1),
(100,'JAVA','import java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) {\n            this.val = val;\n        }\n    }\n\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        String line1 = br.readLine();\n        String line2 = br.readLine();\n\n        ListNode l1 = parseList(line1);\n        ListNode l2 = parseList(line2);\n\n        ListNode merged = mergeTwoLists(l1, l2);\n\n        StringBuilder sb = new StringBuilder();\n        ListNode cur = merged;\n        while (cur != null) {\n            sb.append(cur.val);\n            if (cur.next != null) {\n                sb.append(\"->\");\n            }\n            cur = cur.next;\n        }\n        System.out.println(sb.toString());\n    }\n\n    private static ListNode parseList(String line) {\n        if (line == null) return null;\n        line = line.trim();\n        if (line.isEmpty() || line.equals(\"NULL\")) return null;\n\n        String[] parts = line.split(\"->\");\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        for (String part : parts) {\n            part = part.trim();\n            if (part.equals(\"NULL\")) break;\n            cur.next = new ListNode(Integer.parseInt(part));\n            cur = cur.next;\n        }\n        return dummy.next;\n    }\n\n    private static ListNode mergeTwoLists(ListNode l1, ListNode l2) {\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        while (l1 != null && l2 != null) {\n            if (l1.val <= l2.val) {\n                cur.next = l1;\n                l1 = l1.next;\n            } else {\n                cur.next = l2;\n                l2 = l2.next;\n            }\n            cur = cur.next;\n        }\n        if (l1 != null) cur.next = l1;\n        if (l2 != null) cur.next = l2;\n        return dummy.next;\n    }\n}',NULL,1),
(100,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass ListNode {\n    constructor(val) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction parseList(line) {\n    if (line === null || line === undefined) {\n        return null;\n    }\n    line = line.trim();\n    if (line === \'\' || line === \'NULL\') {\n        return null;\n    }\n    if (line.endsWith(\'->NULL\')) {\n        line = line.substring(0, line.length - 6);\n    } else if (line.endsWith(\'NULL\')) {\n        line = line.substring(0, line.length - 4);\n        if (line.endsWith(\'->\')) {\n            line = line.substring(0, line.length - 2);\n        }\n    }\n    if (line === \'\') {\n        return null;\n    }\n    const parts = line.split(\'->\');\n    const dummy = new ListNode(0);\n    let cur = dummy;\n    for (let part of parts) {\n        part = part.trim();\n        if (part === \'\') {\n            continue;\n        }\n        cur.next = new ListNode(parseInt(part, 10));\n        cur = cur.next;\n    }\n    return dummy.next;\n}\n\nfunction mergeTwoLists(l1, l2) {\n    const dummy = new ListNode(0);\n    let cur = dummy;\n    while (l1 !== null && l2 !== null) {\n        if (l1.val <= l2.val) {\n            cur.next = l1;\n            l1 = l1.next;\n        } else {\n            cur.next = l2;\n            l2 = l2.next;\n        }\n        cur = cur.next;\n    }\n    if (l1 !== null) {\n        cur.next = l1;\n    } else {\n        cur.next = l2;\n    }\n    return dummy.next;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nconst lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n    if (lines.length === 2) {\n        rl.close();\n    }\n});\n\nrl.on(\'close\', () => {\n    const l1 = parseList(lines[0]);\n    const l2 = parseList(lines[1]);\n    const merged = mergeTwoLists(l1, l2);\n    let sb = \'\';\n    let cur = merged;\n    while (cur !== null) {\n        sb += cur.val;\n        if (cur.next !== null) {\n            sb += \'->\';\n        }\n        cur = cur.next;\n    }\n    process.stdout.write(sb);\n});',NULL,1),
(100,'PYTHON','import sys\n\nclass ListNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.next = None\n\ndef parse_list(line):\n    if line is None:\n        return None\n    line = line.strip()\n    if not line or line == \"NULL\":\n        return None\n    if line.endswith(\"->NULL\"):\n        line = line[:-6]\n    elif line.endswith(\"NULL\"):\n        line = line[:-4]\n        if line.endswith(\"->\"):\n            line = line[:-2]\n    if not line:\n        return None\n    parts = line.split(\"->\")\n    dummy = ListNode(0)\n    cur = dummy\n    for part in parts:\n        part = part.strip()\n        if not part:\n            continue\n        cur.next = ListNode(int(part))\n        cur = cur.next\n    return dummy.next\n\ndef merge_two_lists(l1, l2):\n    dummy = ListNode(0)\n    cur = dummy\n    while l1 is not None and l2 is not None:\n        if l1.val <= l2.val:\n            cur.next = l1\n            l1 = l1.next\n        else:\n            cur.next = l2\n            l2 = l2.next\n        cur = cur.next\n    if l1 is not None:\n        cur.next = l1\n    else:\n        cur.next = l2\n    return dummy.next\n\ndef main():\n    lines = sys.stdin.read().splitlines()\n    line1 = lines[0] if len(lines) > 0 else None\n    line2 = lines[1] if len(lines) > 1 else None\n\n    l1 = parse_list(line1)\n    l2 = parse_list(line2)\n\n    merged = merge_two_lists(l1, l2)\n\n    result = []\n    cur = merged\n    while cur is not None:\n        result.append(str(cur.val))\n        cur = cur.next\n    sys.stdout.write(\"->\".join(result))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(101,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct Node {\n    int key, value;\n    struct Node *prev, *next;\n} Node;\n\ntypedef struct {\n    int capacity;\n    int size;\n    Node **map;\n    int mapSize;\n    Node *head, *tail;\n} LRUCache;\n\nstatic unsigned int hash(int key, int mod) {\n    unsigned int x = (unsigned int)key;\n    x = ((x >> 16) ^ x) * 0x45d9f3b;\n    x = ((x >> 16) ^ x) * 0x45d9f3b;\n    x = (x >> 16) ^ x;\n    return x % (unsigned int)mod;\n}\n\nstatic Node* mapGet(LRUCache *cache, int key) {\n    unsigned int idx = hash(key, cache->mapSize);\n    Node *cur = cache->map[idx];\n    while (cur) {\n        if (cur->key == key) return cur;\n        cur = cur->next;\n    }\n    return NULL;\n}\n\nstatic void mapPut(LRUCache *cache, int key, Node *node) {\n    unsigned int idx = hash(key, cache->mapSize);\n    node->next = cache->map[idx];\n    cache->map[idx] = node;\n}\n\nstatic void mapRemove(LRUCache *cache, int key) {\n    unsigned int idx = hash(key, cache->mapSize);\n    Node *cur = cache->map[idx];\n    Node *prev = NULL;\n    while (cur) {\n        if (cur->key == key) {\n            if (prev) prev->next = cur->next;\n            else cache->map[idx] = cur->next;\n            return;\n        }\n        prev = cur;\n        cur = cur->next;\n    }\n}\n\nstatic void addToHead(LRUCache *cache, Node *node) {\n    node->prev = cache->head;\n    node->next = cache->head->next;\n    cache->head->next->prev = node;\n    cache->head->next = node;\n}\n\nstatic void removeNode(LRUCache *cache, Node *node) {\n    (void)cache;\n    node->prev->next = node->next;\n    node->next->prev = node->prev;\n}\n\nstatic void moveToHead(LRUCache *cache, Node *node) {\n    removeNode(cache, node);\n    addToHead(cache, node);\n}\n\nstatic Node* removeTail(LRUCache *cache) {\n    Node *node = cache->tail->prev;\n    removeNode(cache, node);\n    return node;\n}\n\nstatic LRUCache* LRUCacheCreate(int capacity) {\n    LRUCache *cache = (LRUCache*)malloc(sizeof(LRUCache));\n    cache->capacity = capacity;\n    cache->size = 0;\n    cache->mapSize = capacity * 4 + 17;\n    cache->map = (Node**)calloc(cache->mapSize, sizeof(Node*));\n    cache->head = (Node*)malloc(sizeof(Node));\n    cache->tail = (Node*)malloc(sizeof(Node));\n    cache->head->key = -1;\n    cache->head->value = -1;\n    cache->tail->key = -1;\n    cache->tail->value = -1;\n    cache->head->prev = NULL;\n    cache->head->next = cache->tail;\n    cache->tail->prev = cache->head;\n    cache->tail->next = NULL;\n    return cache;\n}\n\nstatic int LRUCacheGet(LRUCache *cache, int key) {\n    Node *node = mapGet(cache, key);\n    if (!node) return -1;\n    moveToHead(cache, node);\n    return node->value;\n}\n\nstatic void LRUCachePut(LRUCache *cache, int key, int value) {\n    Node *node = mapGet(cache, key);\n    if (node) {\n        node->value = value;\n        moveToHead(cache, node);\n    } else {\n        if (cache->size == cache->capacity) {\n            Node *removed = removeTail(cache);\n            mapRemove(cache, removed->key);\n            free(removed);\n            cache->size--;\n        }\n        Node *newNode = (Node*)malloc(sizeof(Node));\n        newNode->key = key;\n        newNode->value = value;\n        newNode->prev = NULL;\n        newNode->next = NULL;\n        mapPut(cache, key, newNode);\n        addToHead(cache, newNode);\n        cache->size++;\n    }\n}\n\nint main(void) {\n    int capacity, m;\n    if (scanf(\"%d\", &capacity) != 1) return 0;\n    if (scanf(\"%d\", &m) != 1) return 0;\n\n    LRUCache *cache = LRUCacheCreate(capacity);\n\n    char op[16];\n    for (int i = 0; i < m; i++) {\n        if (scanf(\"%15s\", op) != 1) break;\n        if (strcmp(op, \"put\") == 0) {\n            int key, value;\n            scanf(\"%d %d\", &key, &value);\n            LRUCachePut(cache, key, value);\n        } else if (strcmp(op, \"get\") == 0) {\n            int key;\n            scanf(\"%d\", &key);\n            printf(\"%d\\n\", LRUCacheGet(cache, key));\n        }\n    }\n\n    return 0;\n}',NULL,1),
(101,'CPP','#include <bits/stdc++.h>\nusing namespace std;\n\nclass LRUCache {\nprivate:\n    struct Node {\n        int key, value;\n        Node *prev, *next;\n        Node(int k, int v) : key(k), value(v), prev(nullptr), next(nullptr) {}\n    };\n\n    int capacity;\n    unordered_map<int, Node*> mp;\n    Node *head, *tail;\n\n    void addToHead(Node* node) {\n        node->prev = head;\n        node->next = head->next;\n        head->next->prev = node;\n        head->next = node;\n    }\n\n    void removeNode(Node* node) {\n        node->prev->next = node->next;\n        node->next->prev = node->prev;\n    }\n\n    void moveToHead(Node* node) {\n        removeNode(node);\n        addToHead(node);\n    }\n\n    Node* removeTail() {\n        Node* node = tail->prev;\n        removeNode(node);\n        return node;\n    }\n\npublic:\n    LRUCache(int capacity) : capacity(capacity) {\n        head = new Node(-1, -1);\n        tail = new Node(-1, -1);\n        head->next = tail;\n        tail->prev = head;\n    }\n\n    int get(int key) {\n        auto it = mp.find(key);\n        if (it == mp.end()) return -1;\n        Node* node = it->second;\n        moveToHead(node);\n        return node->value;\n    }\n\n    void put(int key, int value) {\n        auto it = mp.find(key);\n        if (it != mp.end()) {\n            Node* node = it->second;\n            node->value = value;\n            moveToHead(node);\n        } else {\n            if ((int)mp.size() == capacity) {\n                Node* removed = removeTail();\n                mp.erase(removed->key);\n                delete removed;\n            }\n            Node* newNode = new Node(key, value);\n            mp[key] = newNode;\n            addToHead(newNode);\n        }\n    }\n};\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int capacity;\n    cin >> capacity;\n    int m;\n    cin >> m;\n\n    LRUCache cache(capacity);\n    string op;\n    while (m--) {\n        cin >> op;\n        if (op == \"put\") {\n            int key, value;\n            cin >> key >> value;\n            cache.put(key, value);\n        } else if (op == \"get\") {\n            int key;\n            cin >> key;\n            cout << cache.get(key) << \'\\n\';\n        }\n    }\n\n    return 0;\n}',NULL,1),
(101,'JAVA','import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    static class LRUCache {\n        class Node {\n            int key, value;\n            Node prev, next;\n            Node(int k, int v) {\n                key = k;\n                value = v;\n            }\n        }\n\n        private int capacity;\n        private Map<Integer, Node> map;\n        private Node head, tail;\n\n        public LRUCache(int capacity) {\n            this.capacity = capacity;\n            this.map = new HashMap<>();\n            head = new Node(-1, -1);\n            tail = new Node(-1, -1);\n            head.next = tail;\n            tail.prev = head;\n        }\n\n        public int get(int key) {\n            Node node = map.get(key);\n            if (node == null) return -1;\n            moveToHead(node);\n            return node.value;\n        }\n\n        public void put(int key, int value) {\n            Node node = map.get(key);\n            if (node != null) {\n                node.value = value;\n                moveToHead(node);\n            } else {\n                if (map.size() == capacity) {\n                    Node removed = removeTail();\n                    map.remove(removed.key);\n                }\n                Node newNode = new Node(key, value);\n                map.put(key, newNode);\n                addToHead(newNode);\n            }\n        }\n\n        private void addToHead(Node node) {\n            node.prev = head;\n            node.next = head.next;\n            head.next.prev = node;\n            head.next = node;\n        }\n\n        private void removeNode(Node node) {\n            node.prev.next = node.next;\n            node.next.prev = node.prev;\n        }\n\n        private void moveToHead(Node node) {\n            removeNode(node);\n            addToHead(node);\n        }\n\n        private Node removeTail() {\n            Node node = tail.prev;\n            removeNode(node);\n            return node;\n        }\n    }\n\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        int capacity = Integer.parseInt(br.readLine().trim());\n        int m = Integer.parseInt(br.readLine().trim());\n        LRUCache cache = new LRUCache(capacity);\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < m; i++) {\n            String line = br.readLine().trim();\n            if (line.isEmpty()) continue;\n            String[] parts = line.split(\"\\\\s+\");\n            if (parts[0].equals(\"put\")) {\n                int key = Integer.parseInt(parts[1]);\n                int value = Integer.parseInt(parts[2]);\n                cache.put(key, value);\n            } else if (parts[0].equals(\"get\")) {\n                int key = Integer.parseInt(parts[1]);\n                sb.append(cache.get(key)).append(\'\\n\');\n            }\n        }\n        System.out.print(sb);\n    }\n}',NULL,1),
(101,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass Node {\n    constructor(key, value) {\n        this.key = key;\n        this.value = value;\n        this.prev = null;\n        this.next = null;\n    }\n}\n\nclass LRUCache {\n    constructor(capacity) {\n        this.capacity = capacity;\n        this.map = new Map();\n        this.head = new Node(-1, -1);\n        this.tail = new Node(-1, -1);\n        this.head.next = this.tail;\n        this.tail.prev = this.head;\n    }\n\n    get(key) {\n        const node = this.map.get(key);\n        if (node === undefined) return -1;\n        this.moveToHead(node);\n        return node.value;\n    }\n\n    put(key, value) {\n        const node = this.map.get(key);\n        if (node !== undefined) {\n            node.value = value;\n            this.moveToHead(node);\n        } else {\n            if (this.map.size === this.capacity) {\n                const removed = this.removeTail();\n                this.map.delete(removed.key);\n            }\n            const newNode = new Node(key, value);\n            this.map.set(key, newNode);\n            this.addToHead(newNode);\n        }\n    }\n\n    addToHead(node) {\n        node.prev = this.head;\n        node.next = this.head.next;\n        this.head.next.prev = node;\n        this.head.next = node;\n    }\n\n    removeNode(node) {\n        node.prev.next = node.next;\n        node.next.prev = node.prev;\n    }\n\n    moveToHead(node) {\n        this.removeNode(node);\n        this.addToHead(node);\n    }\n\n    removeTail() {\n        const node = this.tail.prev;\n        this.removeNode(node);\n        return node;\n    }\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout,\n    terminal: false\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    let idx = 0;\n    const capacity = parseInt(lines[idx++]);\n    const m = parseInt(lines[idx++]);\n    const cache = new LRUCache(capacity);\n    const output = [];\n    for (let i = 0; i < m; i++) {\n        const line = lines[idx++];\n        if (!line) continue;\n        const parts = line.split(/\\s+/);\n        if (parts[0] === \'put\') {\n            const key = parseInt(parts[1]);\n            const value = parseInt(parts[2]);\n            cache.put(key, value);\n        } else if (parts[0] === \'get\') {\n            const key = parseInt(parts[1]);\n            output.push(cache.get(key));\n        }\n    }\n    process.stdout.write(output.join(\'\\n\') + (output.length ? \'\\n\' : \'\'));\n});',NULL,1),
(101,'PYTHON','import sys\n\nclass Node:\n    __slots__ = (\'key\', \'value\', \'prev\', \'next\')\n    def __init__(self, k, v):\n        self.key = k\n        self.value = v\n        self.prev = None\n        self.next = None\n\nclass LRUCache:\n    def __init__(self, capacity):\n        self.capacity = capacity\n        self.map = {}\n        self.head = Node(-1, -1)\n        self.tail = Node(-1, -1)\n        self.head.next = self.tail\n        self.tail.prev = self.head\n\n    def get(self, key):\n        node = self.map.get(key)\n        if node is None:\n            return -1\n        self.moveToHead(node)\n        return node.value\n\n    def put(self, key, value):\n        node = self.map.get(key)\n        if node is not None:\n            node.value = value\n            self.moveToHead(node)\n        else:\n            if len(self.map) == self.capacity:\n                removed = self.removeTail()\n                del self.map[removed.key]\n            newNode = Node(key, value)\n            self.map[key] = newNode\n            self.addToHead(newNode)\n\n    def addToHead(self, node):\n        node.prev = self.head\n        node.next = self.head.next\n        self.head.next.prev = node\n        self.head.next = node\n\n    def removeNode(self, node):\n        node.prev.next = node.next\n        node.next.prev = node.prev\n\n    def moveToHead(self, node):\n        self.removeNode(node)\n        self.addToHead(node)\n\n    def removeTail(self):\n        node = self.tail.prev\n        self.removeNode(node)\n        return node\n\ndef main():\n    data = sys.stdin.read().split()\n    if not data:\n        return\n    idx = 0\n    capacity = int(data[idx]); idx += 1\n    m = int(data[idx]); idx += 1\n    cache = LRUCache(capacity)\n    out = []\n    for _ in range(m):\n        op = data[idx]; idx += 1\n        if op == \'put\':\n            key = int(data[idx]); idx += 1\n            value = int(data[idx]); idx += 1\n            cache.put(key, value)\n        elif op == \'get\':\n            key = int(data[idx]); idx += 1\n            out.append(str(cache.get(key)))\n    sys.stdout.write(\'\\n\'.join(out) + (\'\\n\' if out else \'\'))\n\nif __name__ == \'__main__\':\n    main()',NULL,1),
(102,'C','#include <stdio.h>\n#include <string.h>\n#include <stdbool.h>\n\nbool isValid(const char *s) {\n    char stack[10000];\n    int top = -1;\n    for (int i = 0; s[i] != \'\\0\'; i++) {\n        char c = s[i];\n        if (c == \'(\' || c == \'{\' || c == \'[\') {\n            stack[++top] = c;\n        } else {\n            if (top == -1) {\n                return false;\n            }\n            char t = stack[top--];\n            if ((c == \')\' && t != \'(\') ||\n                (c == \'}\' && t != \'{\') ||\n                (c == \']\' && t != \'[\')) {\n                return false;\n            }\n        }\n    }\n    return top == -1;\n}\n\nint main(void) {\n    char s[10000];\n    if (fgets(s, sizeof(s), stdin) == NULL) {\n        return 0;\n    }\n    size_t len = strlen(s);\n    if (len > 0 && s[len - 1] == \'\\n\') {\n        s[len - 1] = \'\\0\';\n    }\n    if (isValid(s)) {\n        printf(\"true\\n\");\n    } else {\n        printf(\"false\\n\");\n    }\n    return 0;\n}',NULL,1),
(102,'CPP','#include <iostream>\n#include <string>\n#include <stack>\nusing namespace std;\n\nbool isValid(const string& s) {\n    stack<char> st;\n    for (char c : s) {\n        if (c == \'(\' || c == \'{\' || c == \'[\') {\n            st.push(c);\n        } else {\n            if (st.empty()) {\n                return false;\n            }\n            char top = st.top();\n            st.pop();\n            if ((c == \')\' && top != \'(\') ||\n                (c == \'}\' && top != \'{\') ||\n                (c == \']\' && top != \'[\')) {\n                return false;\n            }\n        }\n    }\n    return st.empty();\n}\n\nint main() {\n    string s;\n    if (!getline(cin, s)) {\n        return 0;\n    }\n    cout << (isValid(s) ? \"true\" : \"false\") << endl;\n    return 0;\n}',NULL,1),
(102,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextLine()) {\n            return;\n        }\n        String s = sc.nextLine();\n        System.out.println(isValid(s));\n    }\n\n    public static boolean isValid(String s) {\n        Deque<Character> stack = new ArrayDeque<>();\n        for (char c : s.toCharArray()) {\n            if (c == \'(\' || c == \'{\' || c == \'[\') {\n                stack.push(c);\n            } else {\n                if (stack.isEmpty()) {\n                    return false;\n                }\n                char top = stack.pop();\n                if ((c == \')\' && top != \'(\') ||\n                    (c == \'}\' && top != \'{\') ||\n                    (c == \']\' && top != \'[\')) {\n                    return false;\n                }\n            }\n        }\n        return stack.isEmpty();\n    }\n}',NULL,1),
(102,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (s) => {\n    console.log(isValid(s));\n    rl.close();\n});\n\nfunction isValid(s) {\n    const stack = [];\n    for (const c of s) {\n        if (c === \'(\' || c === \'{\' || c === \'[\') {\n            stack.push(c);\n        } else {\n            if (stack.length === 0) {\n                return false;\n            }\n            const top = stack.pop();\n            if ((c === \')\' && top !== \'(\') ||\n                (c === \'}\' && top !== \'{\') ||\n                (c === \']\' && top !== \'[\')) {\n                return false;\n            }\n        }\n    }\n    return stack.length === 0;\n}',NULL,1),
(102,'PYTHON','import sys\n\ndef isValid(s: str) -> bool:\n    stack = []\n    for c in s:\n        if c in \'({[\':\n            stack.append(c)\n        else:\n            if not stack:\n                return False\n            top = stack.pop()\n            if (c == \')\' and top != \'(\') or \\\n               (c == \'}\' and top != \'{\') or \\\n               (c == \']\' and top != \'[\'):\n                return False\n    return not stack\n\ndef main():\n    s = sys.stdin.readline().rstrip(\'\\n\')\n    print(\"true\" if isValid(s) else \"false\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(103,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint cmp(const void *a, const void *b) {\n    return (*(int *)a - *(int *)b);\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int *nums = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    qsort(nums, n, sizeof(int), cmp);\n\n    int **res = (int **)malloc(n * n * sizeof(int *));\n    int resSize = 0;\n\n    for (int i = 0; i < n - 2; i++) {\n        if (i > 0 && nums[i] == nums[i - 1]) continue;\n        int left = i + 1, right = n - 1;\n        while (left < right) {\n            int sum = nums[i] + nums[left] + nums[right];\n            if (sum == 0) {\n                res[resSize] = (int *)malloc(3 * sizeof(int));\n                res[resSize][0] = nums[i];\n                res[resSize][1] = nums[left];\n                res[resSize][2] = nums[right];\n                resSize++;\n                while (left < right && nums[left] == nums[left + 1]) left++;\n                while (left < right && nums[right] == nums[right - 1]) right--;\n                left++;\n                right--;\n            } else if (sum < 0) {\n                left++;\n            } else {\n                right--;\n            }\n        }\n    }\n\n    printf(\"[\");\n    for (int i = 0; i < resSize; i++) {\n        printf(\"[%d,%d,%d]\", res[i][0], res[i][1], res[i][2]);\n        if (i != resSize - 1) printf(\",\");\n    }\n    printf(\"]\\n\");\n\n    for (int i = 0; i < resSize; i++) {\n        free(res[i]);\n    }\n    free(res);\n    free(nums);\n    return 0;\n}',NULL,1),
(103,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    sort(nums.begin(), nums.end());\n    vector<vector<int>> res;\n    for (int i = 0; i < n - 2; i++) {\n        if (i > 0 && nums[i] == nums[i - 1]) continue;\n        int left = i + 1, right = n - 1;\n        while (left < right) {\n            int sum = nums[i] + nums[left] + nums[right];\n            if (sum == 0) {\n                res.push_back({nums[i], nums[left], nums[right]});\n                while (left < right && nums[left] == nums[left + 1]) left++;\n                while (left < right && nums[right] == nums[right - 1]) right--;\n                left++;\n                right--;\n            } else if (sum < 0) {\n                left++;\n            } else {\n                right--;\n            }\n        }\n    }\n    cout << \"[\";\n    for (int i = 0; i < (int)res.size(); i++) {\n        cout << \"[\" << res[i][0] << \",\" << res[i][1] << \",\" << res[i][2] << \"]\";\n        if (i != (int)res.size() - 1) cout << \",\";\n    }\n    cout << \"]\" << endl;\n    return 0;\n}',NULL,1),
(103,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        Arrays.sort(nums);\n        List<List<Integer>> res = new ArrayList<>();\n        for (int i = 0; i < n - 2; i++) {\n            if (i > 0 && nums[i] == nums[i - 1]) continue;\n            int left = i + 1, right = n - 1;\n            while (left < right) {\n                int sum = nums[i] + nums[left] + nums[right];\n                if (sum == 0) {\n                    res.add(Arrays.asList(nums[i], nums[left], nums[right]));\n                    while (left < right && nums[left] == nums[left + 1]) left++;\n                    while (left < right && nums[right] == nums[right - 1]) right--;\n                    left++;\n                    right--;\n                } else if (sum < 0) {\n                    left++;\n                } else {\n                    right--;\n                }\n            }\n        }\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < res.size(); i++) {\n            sb.append(\"[\");\n            sb.append(res.get(i).get(0)).append(\",\");\n            sb.append(res.get(i).get(1)).append(\",\");\n            sb.append(res.get(i).get(2));\n            sb.append(\"]\");\n            if (i != res.size() - 1) sb.append(\",\");\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n}',NULL,1),
(103,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    nums.sort((a, b) => a - b);\n    const res = [];\n    for (let i = 0; i < n - 2; i++) {\n        if (i > 0 && nums[i] === nums[i - 1]) continue;\n        let left = i + 1, right = n - 1;\n        while (left < right) {\n            const sum = nums[i] + nums[left] + nums[right];\n            if (sum === 0) {\n                res.push([nums[i], nums[left], nums[right]]);\n                while (left < right && nums[left] === nums[left + 1]) left++;\n                while (left < right && nums[right] === nums[right - 1]) right--;\n                left++;\n                right--;\n            } else if (sum < 0) {\n                left++;\n            } else {\n                right--;\n            }\n        }\n    }\n    let sb = \'[\';\n    for (let i = 0; i < res.length; i++) {\n        sb += \'[\';\n        sb += res[i][0] + \',\';\n        sb += res[i][1] + \',\';\n        sb += res[i][2];\n        sb += \']\';\n        if (i !== res.length - 1) sb += \',\';\n    }\n    sb += \']\';\n    console.log(sb);\n});',NULL,1),
(103,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\nnums.sort()\nres = []\nfor i in range(n - 2):\n    if i > 0 and nums[i] == nums[i - 1]:\n        continue\n    left, right = i + 1, n - 1\n    while left < right:\n        s = nums[i] + nums[left] + nums[right]\n        if s == 0:\n            res.append([nums[i], nums[left], nums[right]])\n            while left < right and nums[left] == nums[left + 1]:\n                left += 1\n            while left < right and nums[right] == nums[right - 1]:\n                right -= 1\n            left += 1\n            right -= 1\n        elif s < 0:\n            left += 1\n        else:\n            right -= 1\nsb = \"[\"\nfor i in range(len(res)):\n    sb += \"[\" + \",\".join(map(str, res[i])) + \"]\"\n    if i != len(res) - 1:\n        sb += \",\"\nsb += \"]\"\nprint(sb)',NULL,1),
(104,'C','#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct ListNode {\n    int val;\n    struct ListNode *next;\n} ListNode;\n\nint main() {\n    int n;\n    if (scanf(\"%d\", &n) != 1) return 0;\n\n    int *vals = (int *)malloc(sizeof(int) * (n > 0 ? n : 1));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &vals[i]);\n    }\n\n    int pos;\n    scanf(\"%d\", &pos);\n\n    if (n == 0) {\n        printf(\"false\\n\");\n        free(vals);\n        return 0;\n    }\n\n    ListNode **nodes = (ListNode **)malloc(sizeof(ListNode *) * n);\n    for (int i = 0; i < n; i++) {\n        nodes[i] = (ListNode *)malloc(sizeof(ListNode));\n        nodes[i]->val = vals[i];\n        nodes[i]->next = NULL;\n    }\n\n    for (int i = 0; i < n - 1; i++) {\n        nodes[i]->next = nodes[i + 1];\n    }\n\n    if (pos != -1) {\n        nodes[n - 1]->next = nodes[pos];\n    }\n\n    ListNode *slow = nodes[0];\n    ListNode *fast = nodes[0];\n    int hasCycle = 0;\n\n    while (fast != NULL && fast->next != NULL) {\n        slow = slow->next;\n        fast = fast->next->next;\n        if (slow == fast) {\n            hasCycle = 1;\n            break;\n        }\n    }\n\n    printf(\"%s\\n\", hasCycle ? \"true\" : \"false\");\n\n    for (int i = 0; i < n; i++) {\n        free(nodes[i]);\n    }\n    free(nodes);\n    free(vals);\n\n    return 0;\n}',NULL,1),
(104,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int x) : val(x), next(nullptr) {}\n};\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> vals(n);\n    for (int i = 0; i < n; i++) {\n        cin >> vals[i];\n    }\n    int pos;\n    cin >> pos;\n\n    if (n == 0) {\n        cout << \"false\" << endl;\n        return 0;\n    }\n\n    vector<ListNode*> nodes(n);\n    for (int i = 0; i < n; i++) {\n        nodes[i] = new ListNode(vals[i]);\n    }\n    for (int i = 0; i < n - 1; i++) {\n        nodes[i]->next = nodes[i + 1];\n    }\n    if (pos != -1) {\n        nodes[n - 1]->next = nodes[pos];\n    }\n\n    ListNode* slow = nodes[0];\n    ListNode* fast = nodes[0];\n    bool hasCycle = false;\n    while (fast != nullptr && fast->next != nullptr) {\n        slow = slow->next;\n        fast = fast->next->next;\n        if (slow == fast) {\n            hasCycle = true;\n            break;\n        }\n    }\n\n    cout << (hasCycle ? \"true\" : \"false\") << endl;\n\n    return 0;\n}',NULL,1),
(104,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int x) { val = x; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] vals = new int[n];\n        for (int i = 0; i < n; i++) {\n            vals[i] = sc.nextInt();\n        }\n        int pos = sc.nextInt();\n\n        if (n == 0) {\n            System.out.println(\"false\");\n            return;\n        }\n\n        ListNode[] nodes = new ListNode[n];\n        for (int i = 0; i < n; i++) {\n            nodes[i] = new ListNode(vals[i]);\n        }\n        for (int i = 0; i < n - 1; i++) {\n            nodes[i].next = nodes[i + 1];\n        }\n        if (pos != -1) {\n            nodes[n - 1].next = nodes[pos];\n        }\n\n        ListNode slow = nodes[0];\n        ListNode fast = nodes[0];\n        boolean hasCycle = false;\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n            if (slow == fast) {\n                hasCycle = true;\n                break;\n            }\n        }\n\n        System.out.println(hasCycle ? \"true\" : \"false\");\n    }\n}',NULL,1),
(104,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const vals = lines[1] ? lines[1].split(\' \').map(Number) : [];\n    const pos = parseInt(lines[2]);\n\n    if (n === 0) {\n        console.log(\"false\");\n        return;\n    }\n\n    class ListNode {\n        constructor(x) {\n            this.val = x;\n            this.next = null;\n        }\n    }\n\n    const nodes = [];\n    for (let i = 0; i < n; i++) {\n        nodes.push(new ListNode(vals[i]));\n    }\n    for (let i = 0; i < n - 1; i++) {\n        nodes[i].next = nodes[i + 1];\n    }\n    if (pos !== -1) {\n        nodes[n - 1].next = nodes[pos];\n    }\n\n    let slow = nodes[0];\n    let fast = nodes[0];\n    let hasCycle = false;\n    while (fast !== null && fast.next !== null) {\n        slow = slow.next;\n        fast = fast.next.next;\n        if (slow === fast) {\n            hasCycle = true;\n            break;\n        }\n    }\n\n    console.log(hasCycle ? \"true\" : \"false\");\n});',NULL,1),
(104,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    vals = list(map(int, data[1:1+n]))\n    pos = int(data[1+n])\n\n    if n == 0:\n        print(\"false\")\n        return\n\n    class ListNode:\n        __slots__ = (\'val\', \'next\')\n        def __init__(self, x):\n            self.val = x\n            self.next = None\n\n    nodes = [ListNode(v) for v in vals]\n    for i in range(n - 1):\n        nodes[i].next = nodes[i + 1]\n    if pos != -1:\n        nodes[n - 1].next = nodes[pos]\n\n    slow = nodes[0]\n    fast = nodes[0]\n    has_cycle = False\n    while fast is not None and fast.next is not None:\n        slow = slow.next\n        fast = fast.next.next\n        if slow is fast:\n            has_cycle = True\n            break\n\n    print(\"true\" if has_cycle else \"false\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(105,'C','#include <stdio.h>\n#include <stdlib.h>\n\nvoid swap(int *a, int *b) {\n    int t = *a;\n    *a = *b;\n    *b = t;\n}\n\nvoid heapify(int *heap, int size, int i) {\n    int smallest = i;\n    int left = 2 * i + 1;\n    int right = 2 * i + 2;\n\n    if (left < size && heap[left] < heap[smallest]) {\n        smallest = left;\n    }\n    if (right < size && heap[right] < heap[smallest]) {\n        smallest = right;\n    }\n    if (smallest != i) {\n        swap(&heap[i], &heap[smallest]);\n        heapify(heap, size, smallest);\n    }\n}\n\nvoid push(int *heap, int *size, int value) {\n    heap[*size] = value;\n    (*size)++;\n    int i = *size - 1;\n    while (i > 0) {\n        int parent = (i - 1) / 2;\n        if (heap[parent] <= heap[i]) {\n            break;\n        }\n        swap(&heap[parent], &heap[i]);\n        i = parent;\n    }\n}\n\nvoid pop(int *heap, int *size) {\n    heap[0] = heap[*size - 1];\n    (*size)--;\n    heapify(heap, *size, 0);\n}\n\nint main(void) {\n    int n, k;\n    scanf(\"%d %d\", &n, &k);\n\n    int *heap = (int *)malloc(sizeof(int) * (k + 1));\n    int size = 0;\n\n    for (int i = 0; i < n; i++) {\n        int x;\n        scanf(\"%d\", &x);\n        push(heap, &size, x);\n        if (size > k) {\n            pop(heap, &size);\n        }\n    }\n\n    printf(\"%d\\n\", heap[0]);\n\n    free(heap);\n    return 0;\n}',NULL,1),
(105,'CPP','#include <iostream>\n#include <queue>\n#include <vector>\n\nusing namespace std;\n\nint main() {\n    int n, k;\n    cin >> n >> k;\n    priority_queue<int, vector<int>, greater<int>> pq;\n    for (int i = 0; i < n; i++) {\n        int x;\n        cin >> x;\n        pq.push(x);\n        if ((int)pq.size() > k) {\n            pq.pop();\n        }\n    }\n    cout << pq.top() << endl;\n    return 0;\n}',NULL,1),
(105,'JAVA','import java.util.PriorityQueue;\nimport java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int k = sc.nextInt();\n        PriorityQueue<Integer> pq = new PriorityQueue<>();\n        for (int i = 0; i < n; i++) {\n            int x = sc.nextInt();\n            pq.offer(x);\n            if (pq.size() > k) {\n                pq.poll();\n            }\n        }\n        System.out.println(pq.peek());\n    }\n}',NULL,1),
(105,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const [n, k] = lines[0].split(\' \').map(Number);\n        const nums = lines[1].split(\' \').map(Number);\n        const pq = [];\n        const push = (x) => {\n            pq.push(x);\n            let i = pq.length - 1;\n            while (i > 0) {\n                const p = (i - 1) >> 1;\n                if (pq[p] <= pq[i]) break;\n                [pq[p], pq[i]] = [pq[i], pq[p]];\n                i = p;\n            }\n        };\n        const pop = () => {\n            const top = pq[0];\n            const last = pq.pop();\n            if (pq.length > 0) {\n                pq[0] = last;\n                let i = 0;\n                while (true) {\n                    let l = i * 2 + 1, r = i * 2 + 2, m = i;\n                    if (l < pq.length && pq[l] < pq[m]) m = l;\n                    if (r < pq.length && pq[r] < pq[m]) m = r;\n                    if (m === i) break;\n                    [pq[i], pq[m]] = [pq[m], pq[i]];\n                    i = m;\n                }\n            }\n            return top;\n        };\n        for (let i = 0; i < n; i++) {\n            push(nums[i]);\n            if (pq.length > k) pop();\n        }\n        console.log(pq[0]);\n        rl.close();\n    }\n});',NULL,1),
(105,'PYTHON','import sys\nimport heapq\n\ndef main():\n    data = sys.stdin.read().split()\n    if not data:\n        return\n    n = int(data[0])\n    k = int(data[1])\n    nums = list(map(int, data[2:2+n]))\n    heap = []\n    for x in nums:\n        heapq.heappush(heap, x)\n        if len(heap) > k:\n            heapq.heappop(heap)\n    print(heap[0])\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(106,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    int left = 0, right = n - 1;\n    while (left < right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] > nums[mid + 1]) {\n            right = mid;\n        } else {\n            left = mid + 1;\n        }\n    }\n    printf(\"%d\\n\", left);\n    return 0;\n}',NULL,1),
(106,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    int left = 0, right = n - 1;\n    while (left < right) {\n        int mid = left + (right - left) / 2;\n        if (nums[mid] > nums[mid + 1]) {\n            right = mid;\n        } else {\n            left = mid + 1;\n        }\n    }\n    cout << left << endl;\n    return 0;\n}',NULL,1),
(106,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        int left = 0, right = n - 1;\n        while (left < right) {\n            int mid = left + (right - left) / 2;\n            if (nums[mid] > nums[mid + 1]) {\n                right = mid;\n            } else {\n                left = mid + 1;\n            }\n        }\n        System.out.println(left);\n    }\n}',NULL,1),
(106,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    let left = 0, right = n - 1;\n    while (left < right) {\n        const mid = left + Math.floor((right - left) / 2);\n        if (nums[mid] > nums[mid + 1]) {\n            right = mid;\n        } else {\n            left = mid + 1;\n        }\n    }\n    console.log(left);\n});',NULL,1),
(106,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\nleft, right = 0, n - 1\nwhile left < right:\n    mid = left + (right - left) // 2\n    if nums[mid] > nums[mid + 1]:\n        right = mid\n    else:\n        left = mid + 1\nprint(left)',NULL,1),
(107,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    int maxSum = nums[0];\n    int currentSum = nums[0];\n    for (int i = 1; i < n; i++) {\n        currentSum = (nums[i] > currentSum + nums[i]) ? nums[i] : currentSum + nums[i];\n        maxSum = (maxSum > currentSum) ? maxSum : currentSum;\n    }\n    printf(\"%d\\n\", maxSum);\n    return 0;\n}',NULL,1),
(107,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    int maxSum = nums[0];\n    int currentSum = nums[0];\n    for (int i = 1; i < n; i++) {\n        currentSum = max(nums[i], currentSum + nums[i]);\n        maxSum = max(maxSum, currentSum);\n    }\n    cout << maxSum << endl;\n    return 0;\n}',NULL,1),
(107,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        int maxSum = nums[0];\n        int currentSum = nums[0];\n        for (int i = 1; i < n; i++) {\n            currentSum = Math.max(nums[i], currentSum + nums[i]);\n            maxSum = Math.max(maxSum, currentSum);\n        }\n        System.out.println(maxSum);\n    }\n}',NULL,1),
(107,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(/\\s+/).map(Number);\n    let maxSum = nums[0];\n    let currentSum = nums[0];\n    for (let i = 1; i < n; i++) {\n        currentSum = Math.max(nums[i], currentSum + nums[i]);\n        maxSum = Math.max(maxSum, currentSum);\n    }\n    console.log(maxSum);\n});',NULL,1),
(107,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\nmax_sum = nums[0]\ncurrent_sum = nums[0]\nfor i in range(1, n):\n    current_sum = max(nums[i], current_sum + nums[i])\n    max_sum = max(max_sum, current_sum)\nprint(max_sum)',NULL,1),
(108,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int height[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &height[i]);\n    }\n    int left = 0, right = n - 1;\n    int maxWater = 0;\n    while (left < right) {\n        int h = height[left] < height[right] ? height[left] : height[right];\n        int w = right - left;\n        int water = h * w;\n        if (water > maxWater) {\n            maxWater = water;\n        }\n        if (height[left] < height[right]) {\n            left++;\n        } else {\n            right--;\n        }\n    }\n    printf(\"%d\\n\", maxWater);\n    return 0;\n}',NULL,1),
(108,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> height(n);\n    for (int i = 0; i < n; i++) {\n        cin >> height[i];\n    }\n    int left = 0, right = n - 1;\n    int maxWater = 0;\n    while (left < right) {\n        int h = min(height[left], height[right]);\n        int w = right - left;\n        maxWater = max(maxWater, h * w);\n        if (height[left] < height[right]) {\n            left++;\n        } else {\n            right--;\n        }\n    }\n    cout << maxWater << endl;\n    return 0;\n}',NULL,1),
(108,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] height = new int[n];\n        for (int i = 0; i < n; i++) {\n            height[i] = sc.nextInt();\n        }\n        int left = 0, right = n - 1;\n        int maxWater = 0;\n        while (left < right) {\n            int h = Math.min(height[left], height[right]);\n            int w = right - left;\n            maxWater = Math.max(maxWater, h * w);\n            if (height[left] < height[right]) {\n                left++;\n            } else {\n                right--;\n            }\n        }\n        System.out.println(maxWater);\n    }\n}',NULL,1),
(108,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const height = lines[1].split(\' \').map(Number);\n    let left = 0, right = n - 1;\n    let maxWater = 0;\n    while (left < right) {\n        const h = Math.min(height[left], height[right]);\n        const w = right - left;\n        maxWater = Math.max(maxWater, h * w);\n        if (height[left] < height[right]) {\n            left++;\n        } else {\n            right--;\n        }\n    }\n    console.log(maxWater);\n});',NULL,1),
(108,'PYTHON','n = int(input())\nheight = list(map(int, input().split()))\nleft, right = 0, n - 1\nmax_water = 0\nwhile left < right:\n    h = min(height[left], height[right])\n    w = right - left\n    max_water = max(max_water, h * w)\n    if height[left] < height[right]:\n        left += 1\n    else:\n        right -= 1\nprint(max_water)',NULL,1),
(109,'C','#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct {\n    int start;\n    int end;\n} Interval;\n\nint cmp(const void *a, const void *b) {\n    Interval *ia = (Interval *)a;\n    Interval *ib = (Interval *)b;\n    if (ia->start < ib->start) return -1;\n    if (ia->start > ib->start) return 1;\n    return 0;\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n\n    Interval *intervals = (Interval *)malloc(n * sizeof(Interval));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d %d\", &intervals[i].start, &intervals[i].end);\n    }\n\n    qsort(intervals, n, sizeof(Interval), cmp);\n\n    Interval *merged = (Interval *)malloc(n * sizeof(Interval));\n    int m = 0;\n\n    for (int i = 0; i < n; i++) {\n        if (m == 0 || merged[m - 1].end < intervals[i].start) {\n            merged[m++] = intervals[i];\n        } else {\n            if (intervals[i].end > merged[m - 1].end) {\n                merged[m - 1].end = intervals[i].end;\n            }\n        }\n    }\n\n    printf(\"[\");\n    for (int i = 0; i < m; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"[%d,%d]\", merged[i].start, merged[i].end);\n    }\n    printf(\"]\\n\");\n\n    free(intervals);\n    free(merged);\n    return 0;\n}',NULL,1),
(109,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<vector<int>> intervals(n, vector<int>(2));\n    for (int i = 0; i < n; i++) {\n        cin >> intervals[i][0] >> intervals[i][1];\n    }\n    sort(intervals.begin(), intervals.end(), [](const vector<int>& a, const vector<int>& b) {\n        return a[0] < b[0];\n    });\n    vector<vector<int>> merged;\n    for (const auto& interval : intervals) {\n        if (merged.empty() || merged.back()[1] < interval[0]) {\n            merged.push_back({interval[0], interval[1]});\n        } else {\n            merged.back()[1] = max(merged.back()[1], interval[1]);\n        }\n    }\n    cout << \"[\";\n    for (size_t i = 0; i < merged.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << \"[\" << merged[i][0] << \",\" << merged[i][1] << \"]\";\n    }\n    cout << \"]\" << endl;\n    return 0;\n}',NULL,1),
(109,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[][] intervals = new int[n][2];\n        for (int i = 0; i < n; i++) {\n            intervals[i][0] = sc.nextInt();\n            intervals[i][1] = sc.nextInt();\n        }\n        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));\n        List<int[]> merged = new ArrayList<>();\n        for (int[] interval : intervals) {\n            if (merged.isEmpty() || merged.get(merged.size() - 1)[1] < interval[0]) {\n                merged.add(new int[]{interval[0], interval[1]});\n            } else {\n                merged.get(merged.size() - 1)[1] = Math.max(merged.get(merged.size() - 1)[1], interval[1]);\n            }\n        }\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < merged.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(\"[\").append(merged.get(i)[0]).append(\",\").append(merged.get(i)[1]).append(\"]\");\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n}',NULL,1),
(109,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const intervals = [];\n    for (let i = 1; i <= n; i++) {\n        const [a, b] = lines[i].split(\' \').map(Number);\n        intervals.push([a, b]);\n    }\n    intervals.sort((a, b) => a[0] - b[0]);\n    const merged = [];\n    for (const interval of intervals) {\n        if (merged.length === 0 || merged[merged.length - 1][1] < interval[0]) {\n            merged.push([interval[0], interval[1]]);\n        } else {\n            merged[merged.length - 1][1] = Math.max(merged[merged.length - 1][1], interval[1]);\n        }\n    }\n    let result = \'[\';\n    for (let i = 0; i < merged.length; i++) {\n        if (i > 0) result += \',\';\n        result += \'[\' + merged[i][0] + \',\' + merged[i][1] + \']\';\n    }\n    result += \']\';\n    console.log(result);\n});',NULL,1),
(109,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    intervals = []\n    idx = 1\n    for _ in range(n):\n        intervals.append([int(data[idx]), int(data[idx + 1])])\n        idx += 2\n\n    intervals.sort(key=lambda x: x[0])\n\n    merged = []\n    for interval in intervals:\n        if not merged or merged[-1][1] < interval[0]:\n            merged.append([interval[0], interval[1]])\n        else:\n            merged[-1][1] = max(merged[-1][1], interval[1])\n\n    result = \"[\" + \",\".join(f\"[{a},{b}]\" for a, b in merged) + \"]\"\n    print(result)\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(110,'C','#include <stdio.h>\n#include <string.h>\n#include <stdlib.h>\n\nint main(void) {\n    char word1[10005], word2[10005];\n    if (fgets(word1, sizeof(word1), stdin) == NULL) return 0;\n    if (fgets(word2, sizeof(word2), stdin) == NULL) return 0;\n\n    size_t n = strlen(word1);\n    size_t m = strlen(word2);\n    if (n > 0 && word1[n - 1] == \'\\n\') word1[--n] = \'\\0\';\n    if (m > 0 && word2[m - 1] == \'\\n\') word2[--m] = \'\\0\';\n\n    int *prev = (int *)malloc((m + 1) * sizeof(int));\n    int *cur = (int *)malloc((m + 1) * sizeof(int));\n    if (!prev || !cur) return 0;\n\n    for (size_t j = 0; j <= m; ++j) prev[j] = (int)j;\n\n    for (size_t i = 1; i <= n; ++i) {\n        cur[0] = (int)i;\n        for (size_t j = 1; j <= m; ++j) {\n            if (word1[i - 1] == word2[j - 1]) {\n                cur[j] = prev[j - 1];\n            } else {\n                int a = prev[j];\n                int b = cur[j - 1];\n                int c = prev[j - 1];\n                int min = a < b ? a : b;\n                if (c < min) min = c;\n                cur[j] = min + 1;\n            }\n        }\n        int *tmp = prev;\n        prev = cur;\n        cur = tmp;\n    }\n\n    printf(\"%d\\n\", prev[m]);\n\n    free(prev);\n    free(cur);\n    return 0;\n}',NULL,1),
(110,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\n\nusing namespace std;\n\nint main() {\n    string word1, word2;\n    getline(cin, word1);\n    getline(cin, word2);\n    int n = word1.length();\n    int m = word2.length();\n    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));\n    for (int i = 0; i <= n; i++) {\n        dp[i][0] = i;\n    }\n    for (int j = 0; j <= m; j++) {\n        dp[0][j] = j;\n    }\n    for (int i = 1; i <= n; i++) {\n        for (int j = 1; j <= m; j++) {\n            if (word1[i - 1] == word2[j - 1]) {\n                dp[i][j] = dp[i - 1][j - 1];\n            } else {\n                dp[i][j] = min(min(dp[i - 1][j], dp[i][j - 1]), dp[i - 1][j - 1]) + 1;\n            }\n        }\n    }\n    cout << dp[n][m] << endl;\n    return 0;\n}',NULL,1),
(110,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String word1 = sc.nextLine();\n        String word2 = sc.nextLine();\n        int n = word1.length();\n        int m = word2.length();\n        int[][] dp = new int[n + 1][m + 1];\n        for (int i = 0; i <= n; i++) {\n            dp[i][0] = i;\n        }\n        for (int j = 0; j <= m; j++) {\n            dp[0][j] = j;\n        }\n        for (int i = 1; i <= n; i++) {\n            for (int j = 1; j <= m; j++) {\n                if (word1.charAt(i - 1) == word2.charAt(j - 1)) {\n                    dp[i][j] = dp[i - 1][j - 1];\n                } else {\n                    dp[i][j] = Math.min(Math.min(dp[i - 1][j], dp[i][j - 1]), dp[i - 1][j - 1]) + 1;\n                }\n            }\n        }\n        System.out.println(dp[n][m]);\n    }\n}',NULL,1),
(110,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n    if (lines.length === 2) {\n        const word1 = lines[0];\n        const word2 = lines[1];\n        const n = word1.length;\n        const m = word2.length;\n        const dp = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0));\n        for (let i = 0; i <= n; i++) {\n            dp[i][0] = i;\n        }\n        for (let j = 0; j <= m; j++) {\n            dp[0][j] = j;\n        }\n        for (let i = 1; i <= n; i++) {\n            for (let j = 1; j <= m; j++) {\n                if (word1[i - 1] === word2[j - 1]) {\n                    dp[i][j] = dp[i - 1][j - 1];\n                } else {\n                    dp[i][j] = Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1;\n                }\n            }\n        }\n        console.log(dp[n][m]);\n        rl.close();\n    }\n});',NULL,1),
(110,'PYTHON','word1 = input()\nword2 = input()\nn = len(word1)\nm = len(word2)\ndp = [[0] * (m + 1) for _ in range(n + 1)]\nfor i in range(n + 1):\n    dp[i][0] = i\nfor j in range(m + 1):\n    dp[0][j] = j\nfor i in range(1, n + 1):\n    for j in range(1, m + 1):\n        if word1[i - 1] == word2[j - 1]:\n            dp[i][j] = dp[i - 1][j - 1]\n        else:\n            dp[i][j] = min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1\nprint(dp[n][m])',NULL,1),
(111,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    if (n == 0) {\n        printf(\"0\\n\");\n        return 0;\n    }\n    if (n == 1) {\n        printf(\"%d\\n\", nums[0]);\n        return 0;\n    }\n\n    int prev2 = nums[0];\n    int prev1 = nums[0] > nums[1] ? nums[0] : nums[1];\n\n    for (int i = 2; i < n; i++) {\n        int current = prev1 > prev2 + nums[i] ? prev1 : prev2 + nums[i];\n        prev2 = prev1;\n        prev1 = current;\n    }\n\n    printf(\"%d\\n\", prev1);\n    return 0;\n}',NULL,1),
(111,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n\n    if (n == 0) {\n        cout << 0 << endl;\n        return 0;\n    }\n    if (n == 1) {\n        cout << nums[0] << endl;\n        return 0;\n    }\n\n    int prev2 = nums[0];\n    int prev1 = max(nums[0], nums[1]);\n\n    for (int i = 2; i < n; i++) {\n        int current = max(prev1, prev2 + nums[i]);\n        prev2 = prev1;\n        prev1 = current;\n    }\n\n    cout << prev1 << endl;\n    return 0;\n}',NULL,1),
(111,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        int n = scanner.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = scanner.nextInt();\n        }\n        \n        if (n == 0) {\n            System.out.println(0);\n            return;\n        }\n        if (n == 1) {\n            System.out.println(nums[0]);\n            return;\n        }\n        \n        int prev2 = nums[0];\n        int prev1 = Math.max(nums[0], nums[1]);\n        \n        for (int i = 2; i < n; i++) {\n            int current = Math.max(prev1, prev2 + nums[i]);\n            prev2 = prev1;\n            prev1 = current;\n        }\n        \n        System.out.println(prev1);\n    }\n}',NULL,1),
(111,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n\n    if (n === 0) {\n        console.log(0);\n        return;\n    }\n    if (n === 1) {\n        console.log(nums[0]);\n        return;\n    }\n\n    let prev2 = nums[0];\n    let prev1 = Math.max(nums[0], nums[1]);\n\n    for (let i = 2; i < n; i++) {\n        let current = Math.max(prev1, prev2 + nums[i]);\n        prev2 = prev1;\n        prev1 = current;\n    }\n\n    console.log(prev1);\n});',NULL,1),
(111,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\n\nif n == 0:\n    print(0)\nelif n == 1:\n    print(nums[0])\nelse:\n    prev2 = nums[0]\n    prev1 = max(nums[0], nums[1])\n    for i in range(2, n):\n        current = max(prev1, prev2 + nums[i])\n        prev2 = prev1\n        prev1 = current\n    print(prev1)',NULL,1),
(112,'C','#include <stdio.h>\n\nvoid swap(int *a, int *b) {\n    int tmp = *a;\n    *a = *b;\n    *b = tmp;\n}\n\nvoid reverse(int *nums, int left, int right) {\n    while (left < right) {\n        swap(&nums[left], &nums[right]);\n        left++;\n        right--;\n    }\n}\n\nvoid nextPermutation(int *nums, int n) {\n    int i = n - 2;\n    while (i >= 0 && nums[i] >= nums[i + 1]) {\n        i--;\n    }\n    if (i >= 0) {\n        int j = n - 1;\n        while (nums[j] <= nums[i]) {\n            j--;\n        }\n        swap(&nums[i], &nums[j]);\n    }\n    reverse(nums, i + 1, n - 1);\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    nextPermutation(nums, n);\n    for (int i = 0; i < n; i++) {\n        if (i > 0) printf(\" \");\n        printf(\"%d\", nums[i]);\n    }\n    printf(\"\\n\");\n    return 0;\n}',NULL,1),
(112,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nvoid nextPermutation(vector<int>& nums) {\n    int i = nums.size() - 2;\n    while (i >= 0 && nums[i] >= nums[i + 1]) {\n        i--;\n    }\n    if (i >= 0) {\n        int j = nums.size() - 1;\n        while (nums[j] <= nums[i]) {\n            j--;\n        }\n        swap(nums[i], nums[j]);\n    }\n    reverse(nums.begin() + i + 1, nums.end());\n}\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    nextPermutation(nums);\n    for (int i = 0; i < n; i++) {\n        if (i > 0) cout << \' \';\n        cout << nums[i];\n    }\n    cout << endl;\n    return 0;\n}',NULL,1),
(112,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        nextPermutation(nums);\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < n; i++) {\n            if (i > 0) sb.append(\' \');\n            sb.append(nums[i]);\n        }\n        System.out.println(sb.toString());\n    }\n\n    private static void nextPermutation(int[] nums) {\n        int i = nums.length - 2;\n        while (i >= 0 && nums[i] >= nums[i + 1]) {\n            i--;\n        }\n        if (i >= 0) {\n            int j = nums.length - 1;\n            while (nums[j] <= nums[i]) {\n                j--;\n            }\n            swap(nums, i, j);\n        }\n        reverse(nums, i + 1, nums.length - 1);\n    }\n\n    private static void swap(int[] nums, int i, int j) {\n        int tmp = nums[i];\n        nums[i] = nums[j];\n        nums[j] = tmp;\n    }\n\n    private static void reverse(int[] nums, int left, int right) {\n        while (left < right) {\n            swap(nums, left, right);\n            left++;\n            right--;\n        }\n    }\n}',NULL,1),
(112,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const n = parseInt(lines[0]);\n        const nums = lines[1].split(\' \').map(Number);\n        nextPermutation(nums);\n        console.log(nums.join(\' \'));\n        rl.close();\n    }\n});\n\nfunction nextPermutation(nums) {\n    let i = nums.length - 2;\n    while (i >= 0 && nums[i] >= nums[i + 1]) {\n        i--;\n    }\n    if (i >= 0) {\n        let j = nums.length - 1;\n        while (nums[j] <= nums[i]) {\n            j--;\n        }\n        swap(nums, i, j);\n    }\n    reverse(nums, i + 1, nums.length - 1);\n}\n\nfunction swap(nums, i, j) {\n    let tmp = nums[i];\n    nums[i] = nums[j];\n    nums[j] = tmp;\n}\n\nfunction reverse(nums, left, right) {\n    while (left < right) {\n        swap(nums, left, right);\n        left++;\n        right--;\n    }\n}',NULL,1),
(112,'PYTHON','import sys\n\ndef next_permutation(nums):\n    i = len(nums) - 2\n    while i >= 0 and nums[i] >= nums[i + 1]:\n        i -= 1\n    if i >= 0:\n        j = len(nums) - 1\n        while nums[j] <= nums[i]:\n            j -= 1\n        nums[i], nums[j] = nums[j], nums[i]\n    left, right = i + 1, len(nums) - 1\n    while left < right:\n        nums[left], nums[right] = nums[right], nums[left]\n        left += 1\n        right -= 1\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    nums = list(map(int, data[1:1 + n]))\n    next_permutation(nums)\n    print(\' \'.join(map(str, nums)))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(113,'C','#include <stdio.h>\n#include <string.h>\n\nint main(void) {\n    int n;\n    if (scanf(\"%d\", &n) != 1) {\n        return 0;\n    }\n    getchar();\n\n    char strs[1000][1000];\n    for (int i = 0; i < n; i++) {\n        if (fgets(strs[i], sizeof(strs[i]), stdin) == NULL) {\n            strs[i][0] = \'\\0\';\n            continue;\n        }\n        size_t len = strlen(strs[i]);\n        if (len > 0 && strs[i][len - 1] == \'\\n\') {\n            strs[i][len - 1] = \'\\0\';\n        }\n    }\n\n    if (n == 0) {\n        printf(\"\\n\");\n        return 0;\n    }\n\n    char prefix[1000];\n    strcpy(prefix, strs[0]);\n\n    for (int i = 1; i < n; i++) {\n        while (strncmp(strs[i], prefix, strlen(prefix)) != 0) {\n            size_t len = strlen(prefix);\n            if (len == 0) {\n                printf(\"\\n\");\n                return 0;\n            }\n            prefix[len - 1] = \'\\0\';\n        }\n    }\n\n    printf(\"%s\\n\", prefix);\n    return 0;\n}',NULL,1),
(113,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n\nusing namespace std;\n\nstring longestCommonPrefix(vector<string>& strs) {\n    if (strs.empty()) {\n        return \"\";\n    }\n    string prefix = strs[0];\n    for (size_t i = 1; i < strs.size(); i++) {\n        while (strs[i].find(prefix) != 0) {\n            prefix = prefix.substr(0, prefix.length() - 1);\n            if (prefix.empty()) {\n                return \"\";\n            }\n        }\n    }\n    return prefix;\n}\n\nint main() {\n    int n;\n    cin >> n;\n    cin.ignore();\n    vector<string> strs(n);\n    for (int i = 0; i < n; i++) {\n        getline(cin, strs[i]);\n    }\n    cout << longestCommonPrefix(strs) << endl;\n    return 0;\n}',NULL,1),
(113,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        int n = Integer.parseInt(scanner.nextLine().trim());\n        String[] strs = new String[n];\n        for (int i = 0; i < n; i++) {\n            strs[i] = scanner.nextLine();\n        }\n        System.out.println(longestCommonPrefix(strs));\n    }\n\n    public static String longestCommonPrefix(String[] strs) {\n        if (strs == null || strs.length == 0) {\n            return \"\";\n        }\n        String prefix = strs[0];\n        for (int i = 1; i < strs.length; i++) {\n            while (strs[i].indexOf(prefix) != 0) {\n                prefix = prefix.substring(0, prefix.length() - 1);\n                if (prefix.isEmpty()) {\n                    return \"\";\n                }\n            }\n        }\n        return prefix;\n    }\n}',NULL,1),
(113,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0].trim(), 10);\n    const strs = [];\n    for (let i = 0; i < n; i++) {\n        strs.push(lines[i + 1]);\n    }\n    console.log(longestCommonPrefix(strs));\n});\n\nfunction longestCommonPrefix(strs) {\n    if (strs == null || strs.length === 0) {\n        return \"\";\n    }\n    let prefix = strs[0];\n    for (let i = 1; i < strs.length; i++) {\n        while (strs[i].indexOf(prefix) !== 0) {\n            prefix = prefix.substring(0, prefix.length - 1);\n            if (prefix.length === 0) {\n                return \"\";\n            }\n        }\n    }\n    return prefix;\n}',NULL,1),
(113,'PYTHON','n = int(input().strip())\nstrs = []\nfor _ in range(n):\n    strs.append(input())\n\ndef longestCommonPrefix(strs):\n    if not strs:\n        return \"\"\n    prefix = strs[0]\n    for s in strs[1:]:\n        while not s.startswith(prefix):\n            prefix = prefix[:-1]\n            if not prefix:\n                return \"\"\n    return prefix\n\nprint(longestCommonPrefix(strs))',NULL,1),
(114,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\n#define MAXN 1000005\n\nint inStack[MAXN], outStack[MAXN];\nint inTop = 0, outTop = 0;\n\nvoid pushIn(int x) {\n    inStack[inTop++] = x;\n}\n\nint popIn() {\n    return inStack[--inTop];\n}\n\nint emptyIn() {\n    return inTop == 0;\n}\n\nvoid pushOut(int x) {\n    outStack[outTop++] = x;\n}\n\nint popOut() {\n    return outStack[--outTop];\n}\n\nint peekOut() {\n    return outStack[outTop - 1];\n}\n\nint emptyOut() {\n    return outTop == 0;\n}\n\nint main() {\n    int m;\n    scanf(\"%d\", &m);\n    getchar();\n\n    char line[100];\n    char output[1000000];\n    int outLen = 0;\n\n    for (int i = 0; i < m; i++) {\n        fgets(line, sizeof(line), stdin);\n        line[strcspn(line, \"\\n\")] = \'\\0\';\n\n        if (strncmp(line, \"push\", 4) == 0) {\n            int x = atoi(line + 5);\n            pushIn(x);\n        } else if (strcmp(line, \"pop\") == 0) {\n            if (emptyOut()) {\n                while (!emptyIn()) {\n                    pushOut(popIn());\n                }\n            }\n            outLen += sprintf(output + outLen, \"%d\\n\", popOut());\n        } else if (strcmp(line, \"peek\") == 0) {\n            if (emptyOut()) {\n                while (!emptyIn()) {\n                    pushOut(popIn());\n                }\n            }\n            outLen += sprintf(output + outLen, \"%d\\n\", peekOut());\n        } else if (strcmp(line, \"empty\") == 0) {\n            outLen += sprintf(output + outLen, \"%s\\n\", (emptyIn() && emptyOut()) ? \"true\" : \"false\");\n        }\n    }\n\n    printf(\"%s\", output);\n    return 0;\n}',NULL,1),
(114,'CPP','#include <iostream>\n#include <stack>\n#include <string>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int m;\n    cin >> m;\n    stack<int> inStack, outStack;\n    string op;\n\n    while (m--) {\n        cin >> op;\n        if (op == \"push\") {\n            int x;\n            cin >> x;\n            inStack.push(x);\n        } else if (op == \"pop\") {\n            if (outStack.empty()) {\n                while (!inStack.empty()) {\n                    outStack.push(inStack.top());\n                    inStack.pop();\n                }\n            }\n            cout << outStack.top() << \'\\n\';\n            outStack.pop();\n        } else if (op == \"peek\") {\n            if (outStack.empty()) {\n                while (!inStack.empty()) {\n                    outStack.push(inStack.top());\n                    inStack.pop();\n                }\n            }\n            cout << outStack.top() << \'\\n\';\n        } else if (op == \"empty\") {\n            cout << (inStack.empty() && outStack.empty() ? \"true\" : \"false\") << \'\\n\';\n        }\n    }\n\n    return 0;\n}',NULL,1),
(114,'JAVA','import java.util.*;\nimport java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        int m = Integer.parseInt(br.readLine().trim());\n        Deque<Integer> inStack = new ArrayDeque<>();\n        Deque<Integer> outStack = new ArrayDeque<>();\n        StringBuilder sb = new StringBuilder();\n\n        for (int i = 0; i < m; i++) {\n            String line = br.readLine().trim();\n            if (line.startsWith(\"push\")) {\n                int x = Integer.parseInt(line.substring(5).trim());\n                inStack.push(x);\n            } else if (line.equals(\"pop\")) {\n                if (outStack.isEmpty()) {\n                    while (!inStack.isEmpty()) {\n                        outStack.push(inStack.pop());\n                    }\n                }\n                sb.append(outStack.pop()).append(\'\\n\');\n            } else if (line.equals(\"peek\")) {\n                if (outStack.isEmpty()) {\n                    while (!inStack.isEmpty()) {\n                        outStack.push(inStack.pop());\n                    }\n                }\n                sb.append(outStack.peek()).append(\'\\n\');\n            } else if (line.equals(\"empty\")) {\n                sb.append(inStack.isEmpty() && outStack.isEmpty() ? \"true\" : \"false\").append(\'\\n\');\n            }\n        }\n\n        System.out.print(sb);\n    }\n}',NULL,1),
(114,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const m = parseInt(lines[0]);\n    const inStack = [];\n    const outStack = [];\n    let output = [];\n\n    for (let i = 1; i <= m; i++) {\n        const line = lines[i];\n        if (line.startsWith(\'push\')) {\n            const x = parseInt(line.substring(5).trim());\n            inStack.push(x);\n        } else if (line === \'pop\') {\n            if (outStack.length === 0) {\n                while (inStack.length > 0) {\n                    outStack.push(inStack.pop());\n                }\n            }\n            output.push(outStack.pop());\n        } else if (line === \'peek\') {\n            if (outStack.length === 0) {\n                while (inStack.length > 0) {\n                    outStack.push(inStack.pop());\n                }\n            }\n            output.push(outStack[outStack.length - 1]);\n        } else if (line === \'empty\') {\n            output.push(inStack.length === 0 && outStack.length === 0 ? \'true\' : \'false\');\n        }\n    }\n\n    process.stdout.write(output.join(\'\\n\') + (output.length > 0 ? \'\\n\' : \'\'));\n});',NULL,1),
(114,'PYTHON','import sys\n\ndef main():\n    input_data = sys.stdin.read().splitlines()\n    m = int(input_data[0].strip())\n    in_stack = []\n    out_stack = []\n    output = []\n\n    for i in range(1, m + 1):\n        line = input_data[i].strip()\n        if line.startswith(\"push\"):\n            x = int(line[5:].strip())\n            in_stack.append(x)\n        elif line == \"pop\":\n            if not out_stack:\n                while in_stack:\n                    out_stack.append(in_stack.pop())\n            output.append(str(out_stack.pop()))\n        elif line == \"peek\":\n            if not out_stack:\n                while in_stack:\n                    out_stack.append(in_stack.pop())\n            output.append(str(out_stack[-1]))\n        elif line == \"empty\":\n            output.append(\"true\" if not in_stack and not out_stack else \"false\")\n\n    sys.stdout.write(\"\\n\".join(output) + (\"\\n\" if output else \"\"))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(115,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct {\n    int *data;\n    int *minData;\n    int top;\n    int minTop;\n    int capacity;\n} MinStack;\n\nMinStack* minStackCreate(int capacity) {\n    MinStack *obj = (MinStack*)malloc(sizeof(MinStack));\n    obj->data = (int*)malloc(sizeof(int) * capacity);\n    obj->minData = (int*)malloc(sizeof(int) * capacity);\n    obj->top = -1;\n    obj->minTop = -1;\n    obj->capacity = capacity;\n    return obj;\n}\n\nvoid minStackPush(MinStack *obj, int val) {\n    obj->data[++obj->top] = val;\n    if (obj->minTop == -1 || val <= obj->minData[obj->minTop]) {\n        obj->minData[++obj->minTop] = val;\n    }\n}\n\nvoid minStackPop(MinStack *obj) {\n    int val = obj->data[obj->top--];\n    if (val == obj->minData[obj->minTop]) {\n        obj->minTop--;\n    }\n}\n\nint minStackTop(MinStack *obj) {\n    return obj->data[obj->top];\n}\n\nint minStackGetMin(MinStack *obj) {\n    return obj->minData[obj->minTop];\n}\n\nvoid minStackFree(MinStack *obj) {\n    free(obj->data);\n    free(obj->minData);\n    free(obj);\n}\n\nint main() {\n    int m;\n    if (scanf(\"%d\", &m) != 1) return 0;\n\n    MinStack *stack = minStackCreate(m + 5);\n\n    char op[20];\n    int val;\n    char output[1000000];\n    int outPos = 0;\n\n    for (int i = 0; i < m; i++) {\n        scanf(\"%s\", op);\n        if (strcmp(op, \"push\") == 0) {\n            scanf(\"%d\", &val);\n            minStackPush(stack, val);\n        } else if (strcmp(op, \"pop\") == 0) {\n            minStackPop(stack);\n        } else if (strcmp(op, \"top\") == 0) {\n            outPos += sprintf(output + outPos, \"%d\\n\", minStackTop(stack));\n        } else if (strcmp(op, \"getMin\") == 0) {\n            outPos += sprintf(output + outPos, \"%d\\n\", minStackGetMin(stack));\n        }\n    }\n\n    fwrite(output, 1, outPos, stdout);\n\n    minStackFree(stack);\n    return 0;\n}',NULL,1),
(115,'CPP','#include <iostream>\n#include <string>\n#include <stack>\nusing namespace std;\n\nclass MinStack {\nprivate:\n    stack<int> st;\n    stack<int> minSt;\npublic:\n    void push(int val) {\n        st.push(val);\n        if (minSt.empty() || val <= minSt.top()) {\n            minSt.push(val);\n        }\n    }\n    void pop() {\n        int val = st.top();\n        st.pop();\n        if (val == minSt.top()) {\n            minSt.pop();\n        }\n    }\n    int top() {\n        return st.top();\n    }\n    int getMin() {\n        return minSt.top();\n    }\n};\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int m;\n    cin >> m;\n    MinStack stack;\n    string op;\n    for (int i = 0; i < m; ++i) {\n        cin >> op;\n        if (op == \"push\") {\n            int val;\n            cin >> val;\n            stack.push(val);\n        } else if (op == \"pop\") {\n            stack.pop();\n        } else if (op == \"top\") {\n            cout << stack.top() << \'\\n\';\n        } else if (op == \"getMin\") {\n            cout << stack.getMin() << \'\\n\';\n        }\n    }\n    return 0;\n}',NULL,1),
(115,'JAVA','import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        int m = Integer.parseInt(br.readLine().trim());\n        MinStack stack = new MinStack();\n        StringBuilder sb = new StringBuilder();\n\n        for (int i = 0; i < m; i++) {\n            String line = br.readLine().trim();\n            if (line.startsWith(\"push\")) {\n                int val = Integer.parseInt(line.substring(5).trim());\n                stack.push(val);\n            } else if (line.equals(\"pop\")) {\n                stack.pop();\n            } else if (line.equals(\"top\")) {\n                sb.append(stack.top()).append(\'\\n\');\n            } else if (line.equals(\"getMin\")) {\n                sb.append(stack.getMin()).append(\'\\n\');\n            }\n        }\n\n        System.out.print(sb.toString());\n    }\n\n    static class MinStack {\n        private Deque<Integer> stack;\n        private Deque<Integer> minStack;\n\n        public MinStack() {\n            stack = new ArrayDeque<>();\n            minStack = new ArrayDeque<>();\n        }\n\n        public void push(int val) {\n            stack.push(val);\n            if (minStack.isEmpty() || val <= minStack.peek()) {\n                minStack.push(val);\n            }\n        }\n\n        public void pop() {\n            int val = stack.pop();\n            if (val == minStack.peek()) {\n                minStack.pop();\n            }\n        }\n\n        public int top() {\n            return stack.peek();\n        }\n\n        public int getMin() {\n            return minStack.peek();\n        }\n    }\n}',NULL,1),
(115,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nclass MinStack {\n    constructor() {\n        this.stack = [];\n        this.minStack = [];\n    }\n\n    push(val) {\n        this.stack.push(val);\n        if (this.minStack.length === 0 || val <= this.minStack[this.minStack.length - 1]) {\n            this.minStack.push(val);\n        }\n    }\n\n    pop() {\n        const val = this.stack.pop();\n        if (val === this.minStack[this.minStack.length - 1]) {\n            this.minStack.pop();\n        }\n    }\n\n    top() {\n        return this.stack[this.stack.length - 1];\n    }\n\n    getMin() {\n        return this.minStack[this.minStack.length - 1];\n    }\n}\n\nlet m = null;\nlet count = 0;\nconst stack = new MinStack();\nconst output = [];\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (m === null) {\n        m = parseInt(line);\n        return;\n    }\n\n    if (count >= m) return;\n    count++;\n\n    if (line.startsWith(\'push\')) {\n        const val = parseInt(line.substring(5).trim());\n        stack.push(val);\n    } else if (line === \'pop\') {\n        stack.pop();\n    } else if (line === \'top\') {\n        output.push(stack.top());\n    } else if (line === \'getMin\') {\n        output.push(stack.getMin());\n    }\n\n    if (count === m) {\n        console.log(output.join(\'\\n\'));\n        rl.close();\n    }\n});',NULL,1),
(115,'PYTHON','import sys\n\nclass MinStack:\n    def __init__(self):\n        self.stack = []\n        self.min_stack = []\n\n    def push(self, val):\n        self.stack.append(val)\n        if not self.min_stack or val <= self.min_stack[-1]:\n            self.min_stack.append(val)\n\n    def pop(self):\n        val = self.stack.pop()\n        if val == self.min_stack[-1]:\n            self.min_stack.pop()\n\n    def top(self):\n        return self.stack[-1]\n\n    def getMin(self):\n        return self.min_stack[-1]\n\ndef main():\n    data = sys.stdin.read().strip().split(\'\\n\')\n    if not data:\n        return\n    m = int(data[0].strip())\n    stack = MinStack()\n    out = []\n    for i in range(1, m + 1):\n        line = data[i].strip()\n        if line.startswith(\"push\"):\n            val = int(line[5:].strip())\n            stack.push(val)\n        elif line == \"pop\":\n            stack.pop()\n        elif line == \"top\":\n            out.append(str(stack.top()))\n        elif line == \"getMin\":\n            out.append(str(stack.getMin()))\n    sys.stdout.write(\'\\n\'.join(out))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(116,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\nTreeNode* createNode(int val) {\n    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nTreeNode* buildTree(char* line) {\n    char* s = line;\n    while (*s == \' \' || *s == \'\\t\') s++;\n    if (*s == \'[\') s++;\n    int len = strlen(s);\n    while (len > 0 && (s[len-1] == \']\' || s[len-1] == \'\\n\' || s[len-1] == \'\\r\' || s[len-1] == \' \' || s[len-1] == \'\\t\')) {\n        s[--len] = \'\\0\';\n    }\n    if (len == 0) return NULL;\n\n    char* parts[10000];\n    int count = 0;\n    char* token = strtok(s, \",\");\n    while (token != NULL) {\n        while (*token == \' \') token++;\n        parts[count++] = token;\n        token = strtok(NULL, \",\");\n    }\n    if (count == 0 || strcmp(parts[0], \"null\") == 0) return NULL;\n\n    TreeNode* root = createNode(atoi(parts[0]));\n    TreeNode* queue[10000];\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    int i = 1;\n    while (front < rear && i < count) {\n        TreeNode* cur = queue[front++];\n        if (i < count) {\n            char* leftVal = parts[i++];\n            if (strcmp(leftVal, \"null\") != 0) {\n                cur->left = createNode(atoi(leftVal));\n                queue[rear++] = cur->left;\n            }\n        }\n        if (i < count) {\n            char* rightVal = parts[i++];\n            if (strcmp(rightVal, \"null\") != 0) {\n                cur->right = createNode(atoi(rightVal));\n                queue[rear++] = cur->right;\n            }\n        }\n    }\n    return root;\n}\n\nTreeNode* findNode(TreeNode* root, int val) {\n    if (root == NULL) return NULL;\n    if (root->val == val) return root;\n    TreeNode* left = findNode(root->left, val);\n    if (left != NULL) return left;\n    return findNode(root->right, val);\n}\n\nTreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {\n    if (root == NULL || root == p || root == q) return root;\n    TreeNode* left = lowestCommonAncestor(root->left, p, q);\n    TreeNode* right = lowestCommonAncestor(root->right, p, q);\n    if (left != NULL && right != NULL) return root;\n    return left != NULL ? left : right;\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    int pVal, qVal;\n    scanf(\"%d\", &pVal);\n    scanf(\"%d\", &qVal);\n\n    TreeNode* root = buildTree(line);\n    TreeNode* p = findNode(root, pVal);\n    TreeNode* q = findNode(root, qVal);\n    TreeNode* lca = lowestCommonAncestor(root, p, q);\n    printf(\"%d\\n\", lca->val);\n    return 0;\n}',NULL,1),
(116,'CPP','#include <bits/stdc++.h>\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode *left;\n    TreeNode *right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(const string& line) {\n    string s = line;\n    size_t start = s.find_first_not_of(\" \\t\\r\\n\");\n    size_t end = s.find_last_not_of(\" \\t\\r\\n\");\n    if (start == string::npos) return nullptr;\n    s = s.substr(start, end - start + 1);\n\n    if (!s.empty() && s.front() == \'[\') s.erase(s.begin());\n    if (!s.empty() && s.back() == \']\') s.pop_back();\n\n    if (s.empty()) return nullptr;\n\n    vector<string> parts;\n    stringstream ss(s);\n    string item;\n    while (getline(ss, item, \',\')) {\n        size_t l = item.find_first_not_of(\" \\t\\r\\n\");\n        size_t r = item.find_last_not_of(\" \\t\\r\\n\");\n        if (l == string::npos) parts.push_back(\"\");\n        else parts.push_back(item.substr(l, r - l + 1));\n    }\n\n    if (parts.empty() || parts[0] == \"null\") return nullptr;\n\n    TreeNode* root = new TreeNode(stoi(parts[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n\n    while (!q.empty() && i < (int)parts.size()) {\n        TreeNode* cur = q.front();\n        q.pop();\n\n        if (i < (int)parts.size()) {\n            string leftVal = parts[i++];\n            if (leftVal != \"null\") {\n                cur->left = new TreeNode(stoi(leftVal));\n                q.push(cur->left);\n            }\n        }\n\n        if (i < (int)parts.size()) {\n            string rightVal = parts[i++];\n            if (rightVal != \"null\") {\n                cur->right = new TreeNode(stoi(rightVal));\n                q.push(cur->right);\n            }\n        }\n    }\n\n    return root;\n}\n\nTreeNode* findNode(TreeNode* root, int val) {\n    if (!root) return nullptr;\n    if (root->val == val) return root;\n    TreeNode* left = findNode(root->left, val);\n    if (left) return left;\n    return findNode(root->right, val);\n}\n\nTreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {\n    if (!root || root == p || root == q) return root;\n    TreeNode* left = lowestCommonAncestor(root->left, p, q);\n    TreeNode* right = lowestCommonAncestor(root->right, p, q);\n    if (left && right) return root;\n    return left ? left : right;\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    string line;\n    getline(cin, line);\n\n    string pLine, qLine;\n    getline(cin, pLine);\n    getline(cin, qLine);\n\n    int pVal = stoi(pLine);\n    int qVal = stoi(qLine);\n\n    TreeNode* root = buildTree(line);\n    TreeNode* p = findNode(root, pVal);\n    TreeNode* q = findNode(root, qVal);\n    TreeNode* lca = lowestCommonAncestor(root, p, q);\n\n    cout << lca->val << \'\\n\';\n    return 0;\n}',NULL,1),
(116,'JAVA','import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int x) { val = x; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        int pVal = Integer.parseInt(sc.nextLine().trim());\n        int qVal = Integer.parseInt(sc.nextLine().trim());\n\n        TreeNode root = buildTree(line);\n        TreeNode p = findNode(root, pVal);\n        TreeNode q = findNode(root, qVal);\n        TreeNode lca = lowestCommonAncestor(root, p, q);\n        System.out.println(lca.val);\n    }\n\n    private static TreeNode buildTree(String line) {\n        String s = line.trim();\n        if (s.startsWith(\"[\")) s = s.substring(1);\n        if (s.endsWith(\"]\")) s = s.substring(0, s.length() - 1);\n        if (s.isEmpty()) return null;\n\n        String[] parts = s.split(\",\");\n        if (parts.length == 0 || parts[0].trim().equals(\"null\")) return null;\n\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < parts.length) {\n            TreeNode cur = queue.poll();\n            if (i < parts.length) {\n                String leftVal = parts[i++].trim();\n                if (!leftVal.equals(\"null\")) {\n                    cur.left = new TreeNode(Integer.parseInt(leftVal));\n                    queue.offer(cur.left);\n                }\n            }\n            if (i < parts.length) {\n                String rightVal = parts[i++].trim();\n                if (!rightVal.equals(\"null\")) {\n                    cur.right = new TreeNode(Integer.parseInt(rightVal));\n                    queue.offer(cur.right);\n                }\n            }\n        }\n        return root;\n    }\n\n    private static TreeNode findNode(TreeNode root, int val) {\n        if (root == null) return null;\n        if (root.val == val) return root;\n        TreeNode left = findNode(root.left, val);\n        if (left != null) return left;\n        return findNode(root.right, val);\n    }\n\n    private static TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {\n        if (root == null || root == p || root == q) return root;\n        TreeNode left = lowestCommonAncestor(root.left, p, q);\n        TreeNode right = lowestCommonAncestor(root.right, p, q);\n        if (left != null && right != null) return root;\n        return left != null ? left : right;\n    }\n}',NULL,1),
(116,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(line) {\n    let s = line.trim();\n    if (s.startsWith(\'[\')) s = s.substring(1);\n    if (s.endsWith(\']\')) s = s.substring(0, s.length - 1);\n    if (s.length === 0) return null;\n\n    const parts = s.split(\',\');\n    if (parts.length === 0 || parts[0].trim() === \'null\') return null;\n\n    const root = new TreeNode(parseInt(parts[0].trim(), 10));\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < parts.length) {\n        const cur = queue.shift();\n        if (i < parts.length) {\n            const leftVal = parts[i++].trim();\n            if (leftVal !== \'null\') {\n                cur.left = new TreeNode(parseInt(leftVal, 10));\n                queue.push(cur.left);\n            }\n        }\n        if (i < parts.length) {\n            const rightVal = parts[i++].trim();\n            if (rightVal !== \'null\') {\n                cur.right = new TreeNode(parseInt(rightVal, 10));\n                queue.push(cur.right);\n            }\n        }\n    }\n    return root;\n}\n\nfunction findNode(root, val) {\n    if (root === null) return null;\n    if (root.val === val) return root;\n    const left = findNode(root.left, val);\n    if (left !== null) return left;\n    return findNode(root.right, val);\n}\n\nfunction lowestCommonAncestor(root, p, q) {\n    if (root === null || root === p || root === q) return root;\n    const left = lowestCommonAncestor(root.left, p, q);\n    const right = lowestCommonAncestor(root.right, p, q);\n    if (left !== null && right !== null) return root;\n    return left !== null ? left : right;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nconst lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n    if (lines.length === 3) {\n        rl.close();\n        const treeLine = lines[0].trim();\n        const pVal = parseInt(lines[1].trim(), 10);\n        const qVal = parseInt(lines[2].trim(), 10);\n\n        const root = buildTree(treeLine);\n        const p = findNode(root, pVal);\n        const q = findNode(root, qVal);\n        const lca = lowestCommonAncestor(root, p, q);\n        console.log(lca.val);\n    }\n});',NULL,1),
(116,'PYTHON','import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, x):\n        self.val = x\n        self.left = None\n        self.right = None\n\ndef build_tree(line):\n    s = line.strip()\n    if s.startswith(\"[\"):\n        s = s[1:]\n    if s.endswith(\"]\"):\n        s = s[:-1]\n    if not s:\n        return None\n    parts = [x.strip() for x in s.split(\",\")]\n    if not parts or parts[0] == \"null\":\n        return None\n    root = TreeNode(int(parts[0]))\n    queue = deque([root])\n    i = 1\n    while queue and i < len(parts):\n        cur = queue.popleft()\n        if i < len(parts):\n            left_val = parts[i]\n            i += 1\n            if left_val != \"null\":\n                cur.left = TreeNode(int(left_val))\n                queue.append(cur.left)\n        if i < len(parts):\n            right_val = parts[i]\n            i += 1\n            if right_val != \"null\":\n                cur.right = TreeNode(int(right_val))\n                queue.append(cur.right)\n    return root\n\ndef find_node(root, val):\n    if root is None:\n        return None\n    if root.val == val:\n        return root\n    left = find_node(root.left, val)\n    if left is not None:\n        return left\n    return find_node(root.right, val)\n\ndef lowest_common_ancestor(root, p, q):\n    if root is None or root is p or root is q:\n        return root\n    left = lowest_common_ancestor(root.left, p, q)\n    right = lowest_common_ancestor(root.right, p, q)\n    if left is not None and right is not None:\n        return root\n    return left if left is not None else right\n\ndef main():\n    line = sys.stdin.readline().strip()\n    p_val = int(sys.stdin.readline().strip())\n    q_val = int(sys.stdin.readline().strip())\n    root = build_tree(line)\n    p = find_node(root, p_val)\n    q = find_node(root, q_val)\n    lca = lowest_common_ancestor(root, p, q)\n    print(lca.val)\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(117,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdbool.h>\n#include <limits.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\nstatic TreeNode* newTreeNode(int val) {\n    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nstatic TreeNode* buildTree(int* nums, int* isNull, int n) {\n    if (n == 0 || isNull[0]) return NULL;\n    TreeNode* root = newTreeNode(nums[0]);\n    TreeNode** queue = (TreeNode**)malloc(sizeof(TreeNode*) * n);\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    int i = 1;\n    while (front < rear && i < n) {\n        TreeNode* node = queue[front++];\n        if (i < n && !isNull[i]) {\n            node->left = newTreeNode(nums[i]);\n            queue[rear++] = node->left;\n        }\n        i++;\n        if (i < n && !isNull[i]) {\n            node->right = newTreeNode(nums[i]);\n            queue[rear++] = node->right;\n        }\n        i++;\n    }\n    free(queue);\n    return root;\n}\n\nstatic bool validate(TreeNode* node, long long min, long long max) {\n    if (node == NULL) return true;\n    if (node->val <= min) return false;\n    if (node->val >= max) return false;\n    return validate(node->left, min, node->val) && validate(node->right, node->val, max);\n}\n\nstatic bool isValidBST(TreeNode* root) {\n    return validate(root, LLONG_MIN, LLONG_MAX);\n}\n\nint main(void) {\n    char line[1000005];\n    if (!fgets(line, sizeof(line), stdin)) return 0;\n    size_t len = strlen(line);\n    while (len > 0 && (line[len - 1] == \'\\n\' || line[len - 1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    char* s = line;\n    while (*s == \' \' || *s == \'\\t\') s++;\n    if (*s == \'[\') s++;\n    len = strlen(s);\n    while (len > 0 && (s[len - 1] == \' \' || s[len - 1] == \'\\t\')) {\n        s[--len] = \'\\0\';\n    }\n    if (len > 0 && s[len - 1] == \']\') s[--len] = \'\\0\';\n    if (len == 0) {\n        printf(\"true\\n\");\n        return 0;\n    }\n\n    int capacity = 16;\n    int* nums = (int*)malloc(sizeof(int) * capacity);\n    int* isNull = (int*)malloc(sizeof(int) * capacity);\n    int n = 0;\n\n    char* token = strtok(s, \",\");\n    while (token != NULL) {\n        while (*token == \' \' || *token == \'\\t\') token++;\n        size_t tlen = strlen(token);\n        while (tlen > 0 && (token[tlen - 1] == \' \' || token[tlen - 1] == \'\\t\')) {\n            token[--tlen] = \'\\0\';\n        }\n        if (n >= capacity) {\n            capacity *= 2;\n            nums = (int*)realloc(nums, sizeof(int) * capacity);\n            isNull = (int*)realloc(isNull, sizeof(int) * capacity);\n        }\n        if (strcmp(token, \"null\") == 0) {\n            nums[n] = 0;\n            isNull[n] = 1;\n        } else {\n            nums[n] = atoi(token);\n            isNull[n] = 0;\n        }\n        n++;\n        token = strtok(NULL, \",\");\n    }\n\n    TreeNode* root = buildTree(nums, isNull, n);\n    printf(\"%s\\n\", isValidBST(root) ? \"true\" : \"false\");\n\n    free(nums);\n    free(isNull);\n    return 0;\n}',NULL,1),
(117,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <sstream>\n#include <climits>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode *left, *right;\n    TreeNode(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(vector<string>& nums) {\n    if (nums.empty() || nums[0] == \"null\") return nullptr;\n    TreeNode* root = new TreeNode(stoi(nums[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)nums.size()) {\n        TreeNode* node = q.front(); q.pop();\n        if (i < (int)nums.size() && nums[i] != \"null\") {\n            node->left = new TreeNode(stoi(nums[i]));\n            q.push(node->left);\n        }\n        i++;\n        if (i < (int)nums.size() && nums[i] != \"null\") {\n            node->right = new TreeNode(stoi(nums[i]));\n            q.push(node->right);\n        }\n        i++;\n    }\n    return root;\n}\n\nbool validate(TreeNode* node, long long minVal, long long maxVal) {\n    if (!node) return true;\n    if (node->val <= minVal || node->val >= maxVal) return false;\n    return validate(node->left, minVal, node->val) && validate(node->right, node->val, maxVal);\n}\n\nbool isValidBST(TreeNode* root) {\n    return validate(root, LLONG_MIN, LLONG_MAX);\n}\n\nint main() {\n    string line;\n    if (!getline(cin, line)) return 0;\n    while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\')) line.pop_back();\n    if (!line.empty() && line.front() == \'[\') line = line.substr(1);\n    if (!line.empty() && line.back() == \']\') line.pop_back();\n    if (line.empty()) {\n        cout << \"true\" << endl;\n        return 0;\n    }\n    vector<string> parts;\n    stringstream ss(line);\n    string token;\n    while (getline(ss, token, \',\')) {\n        size_t start = token.find_first_not_of(\" \\t\");\n        size_t end = token.find_last_not_of(\" \\t\");\n        if (start == string::npos) parts.push_back(\"\");\n        else parts.push_back(token.substr(start, end - start + 1));\n    }\n    TreeNode* root = buildTree(parts);\n    cout << (isValidBST(root) ? \"true\" : \"false\") << endl;\n    return 0;\n}',NULL,1),
(117,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (!sc.hasNextLine()) return;\n        String line = sc.nextLine().trim();\n        if (line.startsWith(\"[\")) line = line.substring(1);\n        if (line.endsWith(\"]\")) line = line.substring(0, line.length() - 1);\n        if (line.isEmpty()) {\n            System.out.println(\"true\");\n            return;\n        }\n        String[] parts = line.split(\",\");\n        Integer[] nums = new Integer[parts.length];\n        for (int i = 0; i < parts.length; i++) {\n            String s = parts[i].trim();\n            if (s.equals(\"null\")) nums[i] = null;\n            else nums[i] = Integer.parseInt(s);\n        }\n        TreeNode root = buildTree(nums);\n        System.out.println(isValidBST(root));\n    }\n\n    static class TreeNode {\n        int val;\n        TreeNode left, right;\n        TreeNode(int val) { this.val = val; }\n    }\n\n    static TreeNode buildTree(Integer[] nums) {\n        if (nums.length == 0 || nums[0] == null) return null;\n        TreeNode root = new TreeNode(nums[0]);\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < nums.length) {\n            TreeNode node = queue.poll();\n            if (i < nums.length && nums[i] != null) {\n                node.left = new TreeNode(nums[i]);\n                queue.offer(node.left);\n            }\n            i++;\n            if (i < nums.length && nums[i] != null) {\n                node.right = new TreeNode(nums[i]);\n                queue.offer(node.right);\n            }\n            i++;\n        }\n        return root;\n    }\n\n    static boolean isValidBST(TreeNode root) {\n        return validate(root, null, null);\n    }\n\n    static boolean validate(TreeNode node, Integer min, Integer max) {\n        if (node == null) return true;\n        if (min != null && node.val <= min) return false;\n        if (max != null && node.val >= max) return false;\n        return validate(node.left, min, node.val) && validate(node.right, node.val, max);\n    }\n}',NULL,1),
(117,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (input) => {\n    let line = input.trim();\n    if (line.startsWith(\'[\')) line = line.substring(1);\n    if (line.endsWith(\']\')) line = line.substring(0, line.length - 1);\n    if (line.length === 0) {\n        console.log(\'true\');\n        rl.close();\n        return;\n    }\n    const parts = line.split(\',\');\n    const nums = parts.map(s => {\n        s = s.trim();\n        return s === \'null\' ? null : parseInt(s, 10);\n    });\n    const root = buildTree(nums);\n    console.log(isValidBST(root));\n    rl.close();\n});\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(nums) {\n    if (nums.length === 0 || nums[0] === null) return null;\n    const root = new TreeNode(nums[0]);\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < nums.length) {\n        const node = queue.shift();\n        if (i < nums.length && nums[i] !== null) {\n            node.left = new TreeNode(nums[i]);\n            queue.push(node.left);\n        }\n        i++;\n        if (i < nums.length && nums[i] !== null) {\n            node.right = new TreeNode(nums[i]);\n            queue.push(node.right);\n        }\n        i++;\n    }\n    return root;\n}\n\nfunction isValidBST(root) {\n    return validate(root, null, null);\n}\n\nfunction validate(node, min, max) {\n    if (node === null) return true;\n    if (min !== null && node.val <= min) return false;\n    if (max !== null && node.val >= max) return false;\n    return validate(node.left, min, node.val) && validate(node.right, node.val, max);\n}',NULL,1),
(117,'PYTHON','import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(nums):\n    if not nums or nums[0] is None:\n        return None\n    root = TreeNode(nums[0])\n    queue = deque([root])\n    i = 1\n    while queue and i < len(nums):\n        node = queue.popleft()\n        if i < len(nums) and nums[i] is not None:\n            node.left = TreeNode(nums[i])\n            queue.append(node.left)\n        i += 1\n        if i < len(nums) and nums[i] is not None:\n            node.right = TreeNode(nums[i])\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef validate(node, min_val, max_val):\n    if node is None:\n        return True\n    if min_val is not None and node.val <= min_val:\n        return False\n    if max_val is not None and node.val >= max_val:\n        return False\n    return validate(node.left, min_val, node.val) and validate(node.right, node.val, max_val)\n\ndef main():\n    line = sys.stdin.readline()\n    if not line:\n        return\n    line = line.strip()\n    if line.startswith(\"[\"):\n        line = line[1:]\n    if line.endswith(\"]\"):\n        line = line[:-1]\n    if line == \"\":\n        print(\"true\")\n        return\n    parts = line.split(\",\")\n    nums = []\n    for s in parts:\n        s = s.strip()\n        if s == \"null\":\n            nums.append(None)\n        else:\n            nums.append(int(s))\n    root = build_tree(nums)\n    print(\"true\" if validate(root, None, None) else \"false\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(118,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\nTreeNode* createNode(int val) {\n    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nTreeNode* buildTree(char** parts, int partsSize) {\n    if (partsSize == 0 || strcmp(parts[0], \"null\") == 0) return NULL;\n    TreeNode* root = createNode(atoi(parts[0]));\n    TreeNode** queue = (TreeNode**)malloc(sizeof(TreeNode*) * (partsSize + 1));\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    int i = 1;\n    while (front < rear && i < partsSize) {\n        TreeNode* node = queue[front++];\n        if (i < partsSize) {\n            char* leftVal = parts[i++];\n            if (strcmp(leftVal, \"null\") != 0) {\n                node->left = createNode(atoi(leftVal));\n                queue[rear++] = node->left;\n            }\n        }\n        if (i < partsSize) {\n            char* rightVal = parts[i++];\n            if (strcmp(rightVal, \"null\") != 0) {\n                node->right = createNode(atoi(rightVal));\n                queue[rear++] = node->right;\n            }\n        }\n    }\n    free(queue);\n    return root;\n}\n\nTreeNode* invertTree(TreeNode* root) {\n    if (root == NULL) return NULL;\n    TreeNode* temp = root->left;\n    root->left = invertTree(root->right);\n    root->right = invertTree(temp);\n    return root;\n}\n\nchar* serialize(TreeNode* root) {\n    if (root == NULL) {\n        char* res = (char*)malloc(3);\n        strcpy(res, \"[]\");\n        return res;\n    }\n    int capacity = 1024;\n    char** res = (char**)malloc(sizeof(char*) * capacity);\n    int count = 0;\n    TreeNode** queue = (TreeNode**)malloc(sizeof(TreeNode*) * capacity);\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    while (front < rear) {\n        TreeNode* node = queue[front++];\n        if (count >= capacity) {\n            capacity *= 2;\n            res = (char**)realloc(res, sizeof(char*) * capacity);\n            queue = (TreeNode**)realloc(queue, sizeof(TreeNode*) * capacity);\n        }\n        if (node == NULL) {\n            res[count] = (char*)malloc(5);\n            strcpy(res[count], \"null\");\n            count++;\n        } else {\n            char* buf = (char*)malloc(16);\n            sprintf(buf, \"%d\", node->val);\n            res[count] = buf;\n            count++;\n            queue[rear++] = node->left;\n            queue[rear++] = node->right;\n        }\n    }\n    while (count > 0 && strcmp(res[count - 1], \"null\") == 0) {\n        count--;\n    }\n    int totalLen = 3;\n    for (int i = 0; i < count; i++) {\n        totalLen += strlen(res[i]) + 1;\n    }\n    char* result = (char*)malloc(totalLen);\n    result[0] = \'\\0\';\n    strcat(result, \"[\");\n    for (int i = 0; i < count; i++) {\n        if (i > 0) strcat(result, \",\");\n        strcat(result, res[i]);\n    }\n    strcat(result, \"]\");\n    for (int i = 0; i < count; i++) free(res[i]);\n    free(res);\n    free(queue);\n    return result;\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    int len = strlen(line);\n    while (len > 0 && (line[len-1] == \'\\n\' || line[len-1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    char* start = line;\n    while (*start == \' \' || *start == \'\\t\') start++;\n    int slen = strlen(start);\n    while (slen > 0 && (start[slen-1] == \' \' || start[slen-1] == \'\\t\')) {\n        start[--slen] = \'\\0\';\n    }\n    if (slen >= 2 && start[0] == \'[\') {\n        start[slen-1] = \'\\0\';\n        start++;\n    }\n    char** parts = (char**)malloc(sizeof(char*) * 100000);\n    int partsSize = 0;\n    if (strlen(start) > 0) {\n        char* token = strtok(start, \",\");\n        while (token != NULL) {\n            while (*token == \' \') token++;\n            int tlen = strlen(token);\n            while (tlen > 0 && token[tlen-1] == \' \') token[--tlen] = \'\\0\';\n            parts[partsSize++] = token;\n            token = strtok(NULL, \",\");\n        }\n    }\n    TreeNode* root = buildTree(parts, partsSize);\n    root = invertTree(root);\n    char* output = serialize(root);\n    printf(\"%s\\n\", output);\n    free(output);\n    free(parts);\n    return 0;\n}',NULL,1),
(118,'CPP','#include <bits/stdc++.h>\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode *left;\n    TreeNode *right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(const vector<string>& parts) {\n    if (parts.empty() || parts[0] == \"null\") return nullptr;\n    TreeNode* root = new TreeNode(stoi(parts[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)parts.size()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (i < (int)parts.size()) {\n            string leftVal = parts[i++];\n            if (leftVal != \"null\") {\n                node->left = new TreeNode(stoi(leftVal));\n                q.push(node->left);\n            }\n        }\n        if (i < (int)parts.size()) {\n            string rightVal = parts[i++];\n            if (rightVal != \"null\") {\n                node->right = new TreeNode(stoi(rightVal));\n                q.push(node->right);\n            }\n        }\n    }\n    return root;\n}\n\nTreeNode* invertTree(TreeNode* root) {\n    if (!root) return nullptr;\n    TreeNode* temp = root->left;\n    root->left = invertTree(root->right);\n    root->right = invertTree(temp);\n    return root;\n}\n\nstring serialize(TreeNode* root) {\n    if (!root) return \"[]\";\n    vector<string> res;\n    queue<TreeNode*> q;\n    q.push(root);\n    while (!q.empty()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (!node) {\n            res.push_back(\"null\");\n        } else {\n            res.push_back(to_string(node->val));\n            q.push(node->left);\n            q.push(node->right);\n        }\n    }\n    while (!res.empty() && res.back() == \"null\") {\n        res.pop_back();\n    }\n    string ans = \"[\";\n    for (int i = 0; i < (int)res.size(); i++) {\n        if (i) ans += \",\";\n        ans += res[i];\n    }\n    ans += \"]\";\n    return ans;\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\')) line.pop_back();\n    if (!line.empty() && line.front() == \'[\') line = line.substr(1, line.size() - 2);\n    vector<string> parts;\n    if (!line.empty()) {\n        stringstream ss(line);\n        string item;\n        while (getline(ss, item, \',\')) {\n            while (!item.empty() && item.front() == \' \') item.erase(item.begin());\n            while (!item.empty() && item.back() == \' \') item.pop_back();\n            parts.push_back(item);\n        }\n    }\n    TreeNode* root = buildTree(parts);\n    root = invertTree(root);\n    cout << serialize(root) << endl;\n    return 0;\n}',NULL,1),
(118,'JAVA','import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) { this.val = val; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.startsWith(\"[\")) line = line.substring(1, line.length() - 1);\n        String[] parts = line.isEmpty() ? new String[0] : line.split(\",\");\n        TreeNode root = buildTree(parts);\n        root = invertTree(root);\n        System.out.println(serialize(root));\n    }\n\n    private static TreeNode buildTree(String[] parts) {\n        if (parts.length == 0 || parts[0].trim().equals(\"null\")) return null;\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < parts.length) {\n            TreeNode node = queue.poll();\n            if (i < parts.length) {\n                String leftVal = parts[i++].trim();\n                if (!leftVal.equals(\"null\")) {\n                    node.left = new TreeNode(Integer.parseInt(leftVal));\n                    queue.offer(node.left);\n                }\n            }\n            if (i < parts.length) {\n                String rightVal = parts[i++].trim();\n                if (!rightVal.equals(\"null\")) {\n                    node.right = new TreeNode(Integer.parseInt(rightVal));\n                    queue.offer(node.right);\n                }\n            }\n        }\n        return root;\n    }\n\n    private static TreeNode invertTree(TreeNode root) {\n        if (root == null) return null;\n        TreeNode temp = root.left;\n        root.left = invertTree(root.right);\n        root.right = invertTree(temp);\n        return root;\n    }\n\n    private static String serialize(TreeNode root) {\n        if (root == null) return \"[]\";\n        List<String> res = new ArrayList<>();\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        while (!queue.isEmpty()) {\n            TreeNode node = queue.poll();\n            if (node == null) {\n                res.add(\"null\");\n            } else {\n                res.add(String.valueOf(node.val));\n                queue.offer(node.left);\n                queue.offer(node.right);\n            }\n        }\n        while (!res.isEmpty() && res.get(res.size() - 1).equals(\"null\")) {\n            res.remove(res.size() - 1);\n        }\n        return \"[\" + String.join(\",\", res) + \"]\";\n    }\n}',NULL,1),
(118,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(parts) {\n    if (parts.length === 0 || parts[0].trim() === \'null\') return null;\n    const root = new TreeNode(parseInt(parts[0].trim(), 10));\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < parts.length) {\n        const node = queue.shift();\n        if (i < parts.length) {\n            const leftVal = parts[i++].trim();\n            if (leftVal !== \'null\') {\n                node.left = new TreeNode(parseInt(leftVal, 10));\n                queue.push(node.left);\n            }\n        }\n        if (i < parts.length) {\n            const rightVal = parts[i++].trim();\n            if (rightVal !== \'null\') {\n                node.right = new TreeNode(parseInt(rightVal, 10));\n                queue.push(node.right);\n            }\n        }\n    }\n    return root;\n}\n\nfunction invertTree(root) {\n    if (root === null) return null;\n    const temp = root.left;\n    root.left = invertTree(root.right);\n    root.right = invertTree(temp);\n    return root;\n}\n\nfunction serialize(root) {\n    if (root === null) return \'[]\';\n    const res = [];\n    const queue = [root];\n    while (queue.length > 0) {\n        const node = queue.shift();\n        if (node === null) {\n            res.push(\'null\');\n        } else {\n            res.push(String(node.val));\n            queue.push(node.left);\n            queue.push(node.right);\n        }\n    }\n    while (res.length > 0 && res[res.length - 1] === \'null\') {\n        res.pop();\n    }\n    return \'[\' + res.join(\',\') + \']\';\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line.startsWith(\'[\')) line = line.substring(1, line.length - 1);\n    const parts = line.length === 0 ? [] : line.split(\',\');\n    let root = buildTree(parts);\n    root = invertTree(root);\n    console.log(serialize(root));\n    rl.close();\n});',NULL,1),
(118,'PYTHON','import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val=0, left=None, right=None):\n        self.val = val\n        self.left = left\n        self.right = right\n\ndef build_tree(parts):\n    if not parts or parts[0].strip() == \"null\":\n        return None\n    root = TreeNode(int(parts[0].strip()))\n    queue = deque([root])\n    i = 1\n    while queue and i < len(parts):\n        node = queue.popleft()\n        if i < len(parts):\n            left_val = parts[i].strip()\n            i += 1\n            if left_val != \"null\":\n                node.left = TreeNode(int(left_val))\n                queue.append(node.left)\n        if i < len(parts):\n            right_val = parts[i].strip()\n            i += 1\n            if right_val != \"null\":\n                node.right = TreeNode(int(right_val))\n                queue.append(node.right)\n    return root\n\ndef invert_tree(root):\n    if root is None:\n        return None\n    root.left, root.right = invert_tree(root.right), invert_tree(root.left)\n    return root\n\ndef serialize(root):\n    if root is None:\n        return \"[]\"\n    res = []\n    queue = deque([root])\n    while queue:\n        node = queue.popleft()\n        if node is None:\n            res.append(\"null\")\n        else:\n            res.append(str(node.val))\n            queue.append(node.left)\n            queue.append(node.right)\n    while res and res[-1] == \"null\":\n        res.pop()\n    return \"[\" + \",\".join(res) + \"]\"\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line.startswith(\"[\"):\n        line = line[1:-1]\n    parts = [] if line == \"\" else line.split(\",\")\n    root = build_tree(parts)\n    root = invert_tree(root)\n    print(serialize(root))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(119,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\ntypedef struct {\n    TreeNode **data;\n    int front;\n    int rear;\n    int size;\n    int capacity;\n} Queue;\n\nQueue* createQueue(int capacity) {\n    Queue *q = (Queue*)malloc(sizeof(Queue));\n    q->data = (TreeNode**)malloc(sizeof(TreeNode*) * capacity);\n    q->front = 0;\n    q->rear = 0;\n    q->size = 0;\n    q->capacity = capacity;\n    return q;\n}\n\nvoid enqueue(Queue *q, TreeNode *node) {\n    if (q->size == q->capacity) {\n        q->capacity *= 2;\n        q->data = (TreeNode**)realloc(q->data, sizeof(TreeNode*) * q->capacity);\n    }\n    q->data[q->rear] = node;\n    q->rear = (q->rear + 1) % q->capacity;\n    q->size++;\n}\n\nTreeNode* dequeue(Queue *q) {\n    if (q->size == 0) return NULL;\n    TreeNode *node = q->data[q->front];\n    q->front = (q->front + 1) % q->capacity;\n    q->size--;\n    return node;\n}\n\nint isEmpty(Queue *q) {\n    return q->size == 0;\n}\n\nvoid freeQueue(Queue *q) {\n    free(q->data);\n    free(q);\n}\n\nTreeNode* buildTree(char **parts, int partsSize) {\n    if (partsSize == 0 || strcmp(parts[0], \"null\") == 0) return NULL;\n    TreeNode *root = (TreeNode*)malloc(sizeof(TreeNode));\n    root->val = atoi(parts[0]);\n    root->left = NULL;\n    root->right = NULL;\n    \n    Queue *queue = createQueue(partsSize);\n    enqueue(queue, root);\n    int i = 1;\n    while (!isEmpty(queue) && i < partsSize) {\n        TreeNode *node = dequeue(queue);\n        if (i < partsSize) {\n            char *leftVal = parts[i++];\n            if (strcmp(leftVal, \"null\") != 0) {\n                node->left = (TreeNode*)malloc(sizeof(TreeNode));\n                node->left->val = atoi(leftVal);\n                node->left->left = NULL;\n                node->left->right = NULL;\n                enqueue(queue, node->left);\n            }\n        }\n        if (i < partsSize) {\n            char *rightVal = parts[i++];\n            if (strcmp(rightVal, \"null\") != 0) {\n                node->right = (TreeNode*)malloc(sizeof(TreeNode));\n                node->right->val = atoi(rightVal);\n                node->right->left = NULL;\n                node->right->right = NULL;\n                enqueue(queue, node->right);\n            }\n        }\n    }\n    freeQueue(queue);\n    return root;\n}\n\nint* rightSideView(TreeNode *root, int *returnSize) {\n    *returnSize = 0;\n    if (root == NULL) return NULL;\n    \n    int *res = (int*)malloc(sizeof(int) * 1000);\n    Queue *queue = createQueue(1000);\n    enqueue(queue, root);\n    \n    while (!isEmpty(queue)) {\n        int size = queue->size;\n        for (int i = 0; i < size; i++) {\n            TreeNode *node = dequeue(queue);\n            if (i == size - 1) {\n                res[(*returnSize)++] = node->val;\n            }\n            if (node->left != NULL) enqueue(queue, node->left);\n            if (node->right != NULL) enqueue(queue, node->right);\n        }\n    }\n    freeQueue(queue);\n    return res;\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    \n    int len = strlen(line);\n    while (len > 0 && (line[len-1] == \'\\n\' || line[len-1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    \n    if (len > 0 && line[0] == \'[\') {\n        memmove(line, line + 1, len - 1);\n        len--;\n        line[len] = \'\\0\';\n    }\n    if (len > 0 && line[len-1] == \']\') {\n        line[--len] = \'\\0\';\n    }\n    \n    if (len == 0) {\n        printf(\"[]\\n\");\n        return 0;\n    }\n    \n    char *parts[10000];\n    int partsSize = 0;\n    char *token = strtok(line, \",\");\n    while (token != NULL) {\n        while (*token == \' \') token++;\n        char *end = token + strlen(token) - 1;\n        while (end > token && *end == \' \') *end-- = \'\\0\';\n        parts[partsSize++] = token;\n        token = strtok(NULL, \",\");\n    }\n    \n    TreeNode *root = buildTree(parts, partsSize);\n    int returnSize = 0;\n    int *res = rightSideView(root, &returnSize);\n    \n    printf(\"[\");\n    for (int i = 0; i < returnSize; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"%d\", res[i]);\n    }\n    printf(\"]\\n\");\n    \n    free(res);\n    return 0;\n}',NULL,1),
(119,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <sstream>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode* left;\n    TreeNode* right;\n    TreeNode(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(const vector<string>& parts) {\n    if (parts.empty() || parts[0] == \"null\") return nullptr;\n    TreeNode* root = new TreeNode(stoi(parts[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)parts.size()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (i < (int)parts.size()) {\n            string leftVal = parts[i++];\n            if (leftVal != \"null\") {\n                node->left = new TreeNode(stoi(leftVal));\n                q.push(node->left);\n            }\n        }\n        if (i < (int)parts.size()) {\n            string rightVal = parts[i++];\n            if (rightVal != \"null\") {\n                node->right = new TreeNode(stoi(rightVal));\n                q.push(node->right);\n            }\n        }\n    }\n    return root;\n}\n\nvector<int> rightSideView(TreeNode* root) {\n    vector<int> res;\n    if (!root) return res;\n    queue<TreeNode*> q;\n    q.push(root);\n    while (!q.empty()) {\n        int size = q.size();\n        for (int i = 0; i < size; i++) {\n            TreeNode* node = q.front();\n            q.pop();\n            if (i == size - 1) res.push_back(node->val);\n            if (node->left) q.push(node->left);\n            if (node->right) q.push(node->right);\n        }\n    }\n    return res;\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\')) line.pop_back();\n    if (!line.empty() && line.front() == \'[\') line = line.substr(1, line.size() - 2);\n    if (line.empty()) {\n        cout << \"[]\" << endl;\n        return 0;\n    }\n    vector<string> parts;\n    stringstream ss(line);\n    string token;\n    while (getline(ss, token, \',\')) {\n        size_t start = token.find_first_not_of(\" \\t\");\n        size_t end = token.find_last_not_of(\" \\t\");\n        if (start == string::npos) parts.push_back(\"\");\n        else parts.push_back(token.substr(start, end - start + 1));\n    }\n    TreeNode* root = buildTree(parts);\n    vector<int> res = rightSideView(root);\n    cout << \"[\";\n    for (int i = 0; i < (int)res.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << res[i];\n    }\n    cout << \"]\" << endl;\n    return 0;\n}',NULL,1),
(119,'JAVA','import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) { this.val = val; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.startsWith(\"[\")) line = line.substring(1, line.length() - 1);\n        if (line.isEmpty()) {\n            System.out.println(\"[]\");\n            return;\n        }\n        String[] parts = line.split(\",\");\n        TreeNode root = buildTree(parts);\n        List<Integer> res = rightSideView(root);\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < res.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(res.get(i));\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n\n    static TreeNode buildTree(String[] parts) {\n        if (parts.length == 0 || parts[0].trim().equals(\"null\")) return null;\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < parts.length) {\n            TreeNode node = queue.poll();\n            if (i < parts.length) {\n                String leftVal = parts[i++].trim();\n                if (!leftVal.equals(\"null\")) {\n                    node.left = new TreeNode(Integer.parseInt(leftVal));\n                    queue.offer(node.left);\n                }\n            }\n            if (i < parts.length) {\n                String rightVal = parts[i++].trim();\n                if (!rightVal.equals(\"null\")) {\n                    node.right = new TreeNode(Integer.parseInt(rightVal));\n                    queue.offer(node.right);\n                }\n            }\n        }\n        return root;\n    }\n\n    static List<Integer> rightSideView(TreeNode root) {\n        List<Integer> res = new ArrayList<>();\n        if (root == null) return res;\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        while (!queue.isEmpty()) {\n            int size = queue.size();\n            for (int i = 0; i < size; i++) {\n                TreeNode node = queue.poll();\n                if (i == size - 1) res.add(node.val);\n                if (node.left != null) queue.offer(node.left);\n                if (node.right != null) queue.offer(node.right);\n            }\n        }\n        return res;\n    }\n}',NULL,1),
(119,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(parts) {\n    if (parts.length === 0 || parts[0].trim() === \'null\') return null;\n    const root = new TreeNode(parseInt(parts[0].trim()));\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < parts.length) {\n        const node = queue.shift();\n        if (i < parts.length) {\n            const leftVal = parts[i++].trim();\n            if (leftVal !== \'null\') {\n                node.left = new TreeNode(parseInt(leftVal));\n                queue.push(node.left);\n            }\n        }\n        if (i < parts.length) {\n            const rightVal = parts[i++].trim();\n            if (rightVal !== \'null\') {\n                node.right = new TreeNode(parseInt(rightVal));\n                queue.push(node.right);\n            }\n        }\n    }\n    return root;\n}\n\nfunction rightSideView(root) {\n    const res = [];\n    if (root === null) return res;\n    const queue = [root];\n    while (queue.length > 0) {\n        const size = queue.length;\n        for (let i = 0; i < size; i++) {\n            const node = queue.shift();\n            if (i === size - 1) res.push(node.val);\n            if (node.left !== null) queue.push(node.left);\n            if (node.right !== null) queue.push(node.right);\n        }\n    }\n    return res;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line.startsWith(\'[\')) line = line.substring(1, line.length - 1);\n    if (line.length === 0) {\n        console.log(\'[]\');\n        rl.close();\n        return;\n    }\n    const parts = line.split(\',\');\n    const root = buildTree(parts);\n    const res = rightSideView(root);\n    console.log(\'[\' + res.join(\',\') + \']\');\n    rl.close();\n});',NULL,1),
(119,'PYTHON','import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(parts):\n    if not parts or parts[0].strip() == \"null\":\n        return None\n    root = TreeNode(int(parts[0].strip()))\n    queue = deque([root])\n    i = 1\n    while queue and i < len(parts):\n        node = queue.popleft()\n        if i < len(parts):\n            left_val = parts[i].strip()\n            i += 1\n            if left_val != \"null\":\n                node.left = TreeNode(int(left_val))\n                queue.append(node.left)\n        if i < len(parts):\n            right_val = parts[i].strip()\n            i += 1\n            if right_val != \"null\":\n                node.right = TreeNode(int(right_val))\n                queue.append(node.right)\n    return root\n\ndef right_side_view(root):\n    res = []\n    if root is None:\n        return res\n    queue = deque([root])\n    while queue:\n        size = len(queue)\n        for i in range(size):\n            node = queue.popleft()\n            if i == size - 1:\n                res.append(node.val)\n            if node.left:\n                queue.append(node.left)\n            if node.right:\n                queue.append(node.right)\n    return res\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line.startswith(\"[\"):\n        line = line[1:-1]\n    if not line:\n        print(\"[]\")\n        return\n    parts = line.split(\",\")\n    root = build_tree(parts)\n    res = right_side_view(root)\n    print(\"[\" + \",\".join(map(str, res)) + \"]\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(120,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int candidate = 0;\n    int count = 0;\n    for (int i = 0; i < n; i++) {\n        int num;\n        scanf(\"%d\", &num);\n        if (count == 0) {\n            candidate = num;\n            count = 1;\n        } else if (num == candidate) {\n            count++;\n        } else {\n            count--;\n        }\n    }\n    printf(\"%d\\n\", candidate);\n    return 0;\n}',NULL,1),
(120,'CPP','#include <iostream>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    int candidate = 0;\n    int count = 0;\n    for (int i = 0; i < n; i++) {\n        int num;\n        cin >> num;\n        if (count == 0) {\n            candidate = num;\n            count = 1;\n        } else if (num == candidate) {\n            count++;\n        } else {\n            count--;\n        }\n    }\n    cout << candidate << endl;\n    return 0;\n}',NULL,1),
(120,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int candidate = 0;\n        int count = 0;\n        for (int i = 0; i < n; i++) {\n            int num = sc.nextInt();\n            if (count == 0) {\n                candidate = num;\n                count = 1;\n            } else if (num == candidate) {\n                count++;\n            } else {\n                count--;\n            }\n        }\n        System.out.println(candidate);\n    }\n}',NULL,1),
(120,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(/\\s+/).map(Number);\n    let candidate = 0;\n    let count = 0;\n    for (let i = 0; i < n; i++) {\n        const num = nums[i];\n        if (count === 0) {\n            candidate = num;\n            count = 1;\n        } else if (num === candidate) {\n            count++;\n        } else {\n            count--;\n        }\n    }\n    console.log(candidate);\n});',NULL,1),
(120,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\ncandidate = 0\ncount = 0\nfor num in nums:\n    if count == 0:\n        candidate = num\n        count = 1\n    elif num == candidate:\n        count += 1\n    else:\n        count -= 1\nprint(candidate)',NULL,1),
(121,'C','#include <stdio.h>\n#include <string.h>\n\nint main(void) {\n    char num1[100005], num2[100005];\n    char result[100010];\n    if (scanf(\"%s\", num1) != 1) return 0;\n    if (scanf(\"%s\", num2) != 1) return 0;\n\n    int i = (int)strlen(num1) - 1;\n    int j = (int)strlen(num2) - 1;\n    int carry = 0;\n    int k = 0;\n\n    while (i >= 0 || j >= 0 || carry != 0) {\n        int x = i >= 0 ? num1[i] - \'0\' : 0;\n        int y = j >= 0 ? num2[j] - \'0\' : 0;\n        int sum = x + y + carry;\n        result[k++] = (char)(\'0\' + sum % 10);\n        carry = sum / 10;\n        i--;\n        j--;\n    }\n\n    for (int left = 0, right = k - 1; left < right; left++, right--) {\n        char tmp = result[left];\n        result[left] = result[right];\n        result[right] = tmp;\n    }\n    result[k] = \'\\0\';\n\n    printf(\"%s\\n\", result);\n    return 0;\n}',NULL,1),
(121,'CPP','#include <iostream>\n#include <string>\n#include <algorithm>\n\nusing namespace std;\n\nstring addStrings(string num1, string num2) {\n    string result;\n    int i = num1.length() - 1;\n    int j = num2.length() - 1;\n    int carry = 0;\n\n    while (i >= 0 || j >= 0 || carry != 0) {\n        int x = i >= 0 ? num1[i] - \'0\' : 0;\n        int y = j >= 0 ? num2[j] - \'0\' : 0;\n        int sum = x + y + carry;\n        result.push_back(\'0\' + sum % 10);\n        carry = sum / 10;\n        i--;\n        j--;\n    }\n\n    reverse(result.begin(), result.end());\n    return result;\n}\n\nint main() {\n    string num1, num2;\n    getline(cin, num1);\n    getline(cin, num2);\n\n    while (!num1.empty() && (num1.back() == \'\\r\' || num1.back() == \'\\n\' || num1.back() == \' \')) {\n        num1.pop_back();\n    }\n    while (!num2.empty() && (num2.back() == \'\\r\' || num2.back() == \'\\n\' || num2.back() == \' \')) {\n        num2.pop_back();\n    }\n\n    cout << addStrings(num1, num2) << endl;\n    return 0;\n}',NULL,1),
(121,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String num1 = sc.nextLine().trim();\n        String num2 = sc.nextLine().trim();\n        System.out.println(addStrings(num1, num2));\n    }\n\n    public static String addStrings(String num1, String num2) {\n        StringBuilder sb = new StringBuilder();\n        int i = num1.length() - 1;\n        int j = num2.length() - 1;\n        int carry = 0;\n\n        while (i >= 0 || j >= 0 || carry != 0) {\n            int x = i >= 0 ? num1.charAt(i) - \'0\' : 0;\n            int y = j >= 0 ? num2.charAt(j) - \'0\' : 0;\n            int sum = x + y + carry;\n            sb.append(sum % 10);\n            carry = sum / 10;\n            i--;\n            j--;\n        }\n\n        return sb.reverse().toString();\n    }\n}',NULL,1),
(121,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\n\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        console.log(addStrings(lines[0], lines[1]));\n        rl.close();\n    }\n});\n\nfunction addStrings(num1, num2) {\n    let sb = [];\n    let i = num1.length - 1;\n    let j = num2.length - 1;\n    let carry = 0;\n\n    while (i >= 0 || j >= 0 || carry !== 0) {\n        let x = i >= 0 ? num1.charCodeAt(i) - \'0\'.charCodeAt(0) : 0;\n        let y = j >= 0 ? num2.charCodeAt(j) - \'0\'.charCodeAt(0) : 0;\n        let sum = x + y + carry;\n        sb.push(sum % 10);\n        carry = Math.floor(sum / 10);\n        i--;\n        j--;\n    }\n\n    return sb.reverse().join(\'\');\n}',NULL,1),
(121,'PYTHON','import sys\n\ndef addStrings(num1, num2):\n    i, j = len(num1) - 1, len(num2) - 1\n    carry = 0\n    res = []\n    while i >= 0 or j >= 0 or carry:\n        x = int(num1[i]) if i >= 0 else 0\n        y = int(num2[j]) if j >= 0 else 0\n        s = x + y + carry\n        res.append(str(s % 10))\n        carry = s // 10\n        i -= 1\n        j -= 1\n    return \'\'.join(reversed(res))\n\ndef main():\n    num1 = sys.stdin.readline().strip()\n    num2 = sys.stdin.readline().strip()\n    print(addStrings(num1, num2))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(122,'C','#include <stdio.h>\n#include <limits.h>\n\nint myAtoi(const char *s) {\n    int i = 0;\n    while (s[i] == \' \') {\n        i++;\n    }\n\n    int sign = 1;\n    if (s[i] == \'+\' || s[i] == \'-\') {\n        sign = (s[i] == \'-\') ? -1 : 1;\n        i++;\n    }\n\n    int result = 0;\n    while (s[i] >= \'0\' && s[i] <= \'9\') {\n        int digit = s[i] - \'0\';\n        if (result > (INT_MAX - digit) / 10) {\n            return sign == 1 ? INT_MAX : INT_MIN;\n        }\n        result = result * 10 + digit;\n        i++;\n    }\n\n    return sign * result;\n}\n\nint main(void) {\n    char s[100000];\n    if (fgets(s, sizeof(s), stdin)) {\n        int i = 0;\n        while (s[i] != \'\\0\' && s[i] != \'\\n\') {\n            i++;\n        }\n        s[i] = \'\\0\';\n        printf(\"%d\\n\", myAtoi(s));\n    }\n    return 0;\n}',NULL,1),
(122,'CPP','#include <iostream>\n#include <string>\n#include <climits>\n\nint myAtoi(const std::string& s) {\n    int i = 0, n = s.length();\n    while (i < n && s[i] == \' \') {\n        i++;\n    }\n    int sign = 1;\n    if (i < n && (s[i] == \'+\' || s[i] == \'-\')) {\n        sign = (s[i] == \'-\') ? -1 : 1;\n        i++;\n    }\n    int result = 0;\n    while (i < n && s[i] >= \'0\' && s[i] <= \'9\') {\n        int digit = s[i] - \'0\';\n        if (result > (INT_MAX - digit) / 10) {\n            return sign == 1 ? INT_MAX : INT_MIN;\n        }\n        result = result * 10 + digit;\n        i++;\n    }\n    return sign * result;\n}\n\nint main() {\n    std::string s;\n    if (std::getline(std::cin, s)) {\n        std::cout << myAtoi(s) << std::endl;\n    }\n    return 0;\n}',NULL,1),
(122,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (sc.hasNextLine()) {\n            String s = sc.nextLine();\n            System.out.println(myAtoi(s));\n        }\n    }\n\n    public static int myAtoi(String s) {\n        int i = 0, n = s.length();\n        while (i < n && s.charAt(i) == \' \') {\n            i++;\n        }\n        int sign = 1;\n        if (i < n && (s.charAt(i) == \'+\' || s.charAt(i) == \'-\')) {\n            sign = s.charAt(i) == \'-\' ? -1 : 1;\n            i++;\n        }\n        int result = 0;\n        while (i < n && Character.isDigit(s.charAt(i))) {\n            int digit = s.charAt(i) - \'0\';\n            if (result > (Integer.MAX_VALUE - digit) / 10) {\n                return sign == 1 ? Integer.MAX_VALUE : Integer.MIN_VALUE;\n            }\n            result = result * 10 + digit;\n            i++;\n        }\n        return sign * result;\n    }\n}',NULL,1),
(122,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (s) => {\n    console.log(myAtoi(s));\n    rl.close();\n});\n\nfunction myAtoi(s) {\n    let i = 0, n = s.length;\n    while (i < n && s[i] === \' \') {\n        i++;\n    }\n    let sign = 1;\n    if (i < n && (s[i] === \'+\' || s[i] === \'-\')) {\n        sign = s[i] === \'-\' ? -1 : 1;\n        i++;\n    }\n    let result = 0;\n    while (i < n && s[i] >= \'0\' && s[i] <= \'9\') {\n        let digit = s.charCodeAt(i) - \'0\'.charCodeAt(0);\n        if (result > (2147483647 - digit) / 10) {\n            return sign === 1 ? 2147483647 : -2147483648;\n        }\n        result = result * 10 + digit;\n        i++;\n    }\n    return sign * result;\n}',NULL,1),
(122,'PYTHON','import sys\n\ndef myAtoi(s: str) -> int:\n    i, n = 0, len(s)\n    while i < n and s[i] == \' \':\n        i += 1\n    sign = 1\n    if i < n and (s[i] == \'+\' or s[i] == \'-\'):\n        sign = -1 if s[i] == \'-\' else 1\n        i += 1\n    result = 0\n    while i < n and s[i].isdigit():\n        digit = ord(s[i]) - ord(\'0\')\n        if result > (2**31 - 1 - digit) // 10:\n            return 2**31 - 1 if sign == 1 else -2**31\n        result = result * 10 + digit\n        i += 1\n    return sign * result\n\nif __name__ == \"__main__\":\n    line = sys.stdin.readline()\n    if line:\n        s = line.rstrip(\'\\n\')\n        print(myAtoi(s))',NULL,1),
(123,'C','#include <stdio.h>\n#include <ctype.h>\n#include <string.h>\n\nint main() {\n    char s[100005];\n    if (fgets(s, sizeof(s), stdin) == NULL) {\n        return 0;\n    }\n    size_t len = strlen(s);\n    if (len > 0 && s[len - 1] == \'\\n\') {\n        s[len - 1] = \'\\0\';\n        len--;\n    }\n\n    int left = 0, right = (int)len - 1;\n    while (left < right) {\n        while (left < right && !isalnum((unsigned char)s[left])) {\n            left++;\n        }\n        while (left < right && !isalnum((unsigned char)s[right])) {\n            right--;\n        }\n        if (tolower((unsigned char)s[left]) != tolower((unsigned char)s[right])) {\n            printf(\"false\\n\");\n            return 0;\n        }\n        left++;\n        right--;\n    }\n    printf(\"true\\n\");\n    return 0;\n}',NULL,1),
(123,'CPP','#include <iostream>\n#include <string>\n#include <cctype>\nusing namespace std;\n\nint main() {\n    string s;\n    getline(cin, s);\n    int left = 0, right = (int)s.length() - 1;\n    while (left < right) {\n        while (left < right && !isalnum((unsigned char)s[left])) {\n            left++;\n        }\n        while (left < right && !isalnum((unsigned char)s[right])) {\n            right--;\n        }\n        if (tolower((unsigned char)s[left]) != tolower((unsigned char)s[right])) {\n            cout << \"false\" << endl;\n            return 0;\n        }\n        left++;\n        right--;\n    }\n    cout << \"true\" << endl;\n    return 0;\n}',NULL,1),
(123,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        String s = scanner.nextLine();\n        int left = 0, right = s.length() - 1;\n        while (left < right) {\n            while (left < right && !Character.isLetterOrDigit(s.charAt(left))) {\n                left++;\n            }\n            while (left < right && !Character.isLetterOrDigit(s.charAt(right))) {\n                right--;\n            }\n            if (Character.toLowerCase(s.charAt(left)) != Character.toLowerCase(s.charAt(right))) {\n                System.out.println(\"false\");\n                return;\n            }\n            left++;\n            right--;\n        }\n        System.out.println(\"true\");\n    }\n}',NULL,1),
(123,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (s) => {\n    let left = 0, right = s.length - 1;\n    while (left < right) {\n        while (left < right && !/[a-zA-Z0-9]/.test(s[left])) {\n            left++;\n        }\n        while (left < right && !/[a-zA-Z0-9]/.test(s[right])) {\n            right--;\n        }\n        if (s[left].toLowerCase() !== s[right].toLowerCase()) {\n            console.log(\"false\");\n            rl.close();\n            return;\n        }\n        left++;\n        right--;\n    }\n    console.log(\"true\");\n    rl.close();\n});',NULL,1),
(123,'PYTHON','s = input()\nleft, right = 0, len(s) - 1\nwhile left < right:\n    while left < right and not s[left].isalnum():\n        left += 1\n    while left < right and not s[right].isalnum():\n        right -= 1\n    if s[left].lower() != s[right].lower():\n        print(\"false\")\n        break\n    left += 1\n    right -= 1\nelse:\n    print(\"true\")',NULL,1),
(124,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n\n    int **matrix = (int **)malloc(n * sizeof(int *));\n    for (int i = 0; i < n; i++) {\n        matrix[i] = (int *)malloc(n * sizeof(int));\n        for (int j = 0; j < n; j++) {\n            scanf(\"%d\", &matrix[i][j]);\n        }\n    }\n\n    for (int i = 0; i < n / 2; i++) {\n        for (int j = i; j < n - 1 - i; j++) {\n            int temp = matrix[i][j];\n            matrix[i][j] = matrix[n - 1 - j][i];\n            matrix[n - 1 - j][i] = matrix[n - 1 - i][n - 1 - j];\n            matrix[n - 1 - i][n - 1 - j] = matrix[j][n - 1 - i];\n            matrix[j][n - 1 - i] = temp;\n        }\n    }\n\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < n; j++) {\n            printf(\"%d\", matrix[i][j]);\n            if (j < n - 1) {\n                printf(\" \");\n            }\n        }\n        printf(\"\\n\");\n    }\n\n    for (int i = 0; i < n; i++) {\n        free(matrix[i]);\n    }\n    free(matrix);\n\n    return 0;\n}',NULL,1),
(124,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<vector<int>> matrix(n, vector<int>(n));\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < n; j++) {\n            cin >> matrix[i][j];\n        }\n    }\n\n    for (int i = 0; i < n / 2; i++) {\n        for (int j = i; j < n - 1 - i; j++) {\n            int temp = matrix[i][j];\n            matrix[i][j] = matrix[n - 1 - j][i];\n            matrix[n - 1 - j][i] = matrix[n - 1 - i][n - 1 - j];\n            matrix[n - 1 - i][n - 1 - j] = matrix[j][n - 1 - i];\n            matrix[j][n - 1 - i] = temp;\n        }\n    }\n\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < n; j++) {\n            cout << matrix[i][j];\n            if (j < n - 1) {\n                cout << \' \';\n            }\n        }\n        cout << \'\\n\';\n    }\n    return 0;\n}',NULL,1),
(124,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[][] matrix = new int[n][n];\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j < n; j++) {\n                matrix[i][j] = sc.nextInt();\n            }\n        }\n\n        for (int i = 0; i < n / 2; i++) {\n            for (int j = i; j < n - 1 - i; j++) {\n                int temp = matrix[i][j];\n                matrix[i][j] = matrix[n - 1 - j][i];\n                matrix[n - 1 - j][i] = matrix[n - 1 - i][n - 1 - j];\n                matrix[n - 1 - i][n - 1 - j] = matrix[j][n - 1 - i];\n                matrix[j][n - 1 - i] = temp;\n            }\n        }\n\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j < n; j++) {\n                sb.append(matrix[i][j]);\n                if (j < n - 1) {\n                    sb.append(\' \');\n                }\n            }\n            sb.append(\'\\n\');\n        }\n        System.out.print(sb);\n    }\n}',NULL,1),
(124,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    let n = parseInt(lines[0]);\n    let matrix = [];\n    for (let i = 0; i < n; i++) {\n        matrix.push(lines[i + 1].split(\' \').map(Number));\n    }\n\n    for (let i = 0; i < Math.floor(n / 2); i++) {\n        for (let j = i; j < n - 1 - i; j++) {\n            let temp = matrix[i][j];\n            matrix[i][j] = matrix[n - 1 - j][i];\n            matrix[n - 1 - j][i] = matrix[n - 1 - i][n - 1 - j];\n            matrix[n - 1 - i][n - 1 - j] = matrix[j][n - 1 - i];\n            matrix[j][n - 1 - i] = temp;\n        }\n    }\n\n    let sb = \'\';\n    for (let i = 0; i < n; i++) {\n        for (let j = 0; j < n; j++) {\n            sb += matrix[i][j];\n            if (j < n - 1) {\n                sb += \' \';\n            }\n        }\n        sb += \'\\n\';\n    }\n    process.stdout.write(sb);\n});',NULL,1),
(124,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    matrix = []\n    idx = 1\n    for i in range(n):\n        row = []\n        for j in range(n):\n            row.append(int(data[idx]))\n            idx += 1\n        matrix.append(row)\n\n    for i in range(n // 2):\n        for j in range(i, n - 1 - i):\n            temp = matrix[i][j]\n            matrix[i][j] = matrix[n - 1 - j][i]\n            matrix[n - 1 - j][i] = matrix[n - 1 - i][n - 1 - j]\n            matrix[n - 1 - i][n - 1 - j] = matrix[j][n - 1 - i]\n            matrix[j][n - 1 - i] = temp\n\n    out = []\n    for i in range(n):\n        out.append(\' \'.join(map(str, matrix[i])))\n    sys.stdout.write(\'\\n\'.join(out) + \'\\n\')\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(125,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    for (int i = 0; i < n; i++) {\n        while (nums[i] > 0 && nums[i] <= n && nums[nums[i] - 1] != nums[i]) {\n            int temp = nums[nums[i] - 1];\n            nums[nums[i] - 1] = nums[i];\n            nums[i] = temp;\n        }\n    }\n    for (int i = 0; i < n; i++) {\n        if (nums[i] != i + 1) {\n            printf(\"%d\\n\", i + 1);\n            return 0;\n        }\n    }\n    printf(\"%d\\n\", n + 1);\n    return 0;\n}',NULL,1),
(125,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    for (int i = 0; i < n; i++) {\n        while (nums[i] > 0 && nums[i] <= n && nums[nums[i] - 1] != nums[i]) {\n            int temp = nums[nums[i] - 1];\n            nums[nums[i] - 1] = nums[i];\n            nums[i] = temp;\n        }\n    }\n    for (int i = 0; i < n; i++) {\n        if (nums[i] != i + 1) {\n            cout << i + 1 << endl;\n            return 0;\n        }\n    }\n    cout << n + 1 << endl;\n    return 0;\n}',NULL,1),
(125,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        for (int i = 0; i < n; i++) {\n            while (nums[i] > 0 && nums[i] <= n && nums[nums[i] - 1] != nums[i]) {\n                int temp = nums[nums[i] - 1];\n                nums[nums[i] - 1] = nums[i];\n                nums[i] = temp;\n            }\n        }\n        for (int i = 0; i < n; i++) {\n            if (nums[i] != i + 1) {\n                System.out.println(i + 1);\n                return;\n            }\n        }\n        System.out.println(n + 1);\n    }\n}',NULL,1),
(125,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const n = parseInt(lines[0]);\n        const nums = lines[1].split(\' \').map(Number);\n        \n        for (let i = 0; i < n; i++) {\n            while (nums[i] > 0 && nums[i] <= n && nums[nums[i] - 1] !== nums[i]) {\n                const temp = nums[nums[i] - 1];\n                nums[nums[i] - 1] = nums[i];\n                nums[i] = temp;\n            }\n        }\n        \n        for (let i = 0; i < n; i++) {\n            if (nums[i] !== i + 1) {\n                console.log(i + 1);\n                rl.close();\n                return;\n            }\n        }\n        \n        console.log(n + 1);\n        rl.close();\n    }\n});',NULL,1),
(125,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\n\nfor i in range(n):\n    while 0 < nums[i] <= n and nums[nums[i] - 1] != nums[i]:\n        nums[nums[i] - 1], nums[i] = nums[i], nums[nums[i] - 1]\n\nfor i in range(n):\n    if nums[i] != i + 1:\n        print(i + 1)\n        break\nelse:\n    print(n + 1)',NULL,1),
(126,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    int maxProd = nums[0];\n    int minProd = nums[0];\n    int result = nums[0];\n\n    for (int i = 1; i < n; i++) {\n        int cur = nums[i];\n        int a = maxProd * cur;\n        int b = minProd * cur;\n        int tempMax = cur;\n        if (a > tempMax) tempMax = a;\n        if (b > tempMax) tempMax = b;\n        int tempMin = cur;\n        if (a < tempMin) tempMin = a;\n        if (b < tempMin) tempMin = b;\n        maxProd = tempMax;\n        minProd = tempMin;\n        if (maxProd > result) result = maxProd;\n    }\n\n    printf(\"%d\\n\", result);\n    return 0;\n}',NULL,1),
(126,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n\n    int maxProd = nums[0];\n    int minProd = nums[0];\n    int result = nums[0];\n\n    for (int i = 1; i < n; i++) {\n        int cur = nums[i];\n        int tempMax = max(cur, max(maxProd * cur, minProd * cur));\n        int tempMin = min(cur, min(maxProd * cur, minProd * cur));\n        maxProd = tempMax;\n        minProd = tempMin;\n        result = max(result, maxProd);\n    }\n\n    cout << result << endl;\n    return 0;\n}',NULL,1),
(126,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n\n        int maxProd = nums[0];\n        int minProd = nums[0];\n        int result = nums[0];\n\n        for (int i = 1; i < n; i++) {\n            int cur = nums[i];\n            int tempMax = Math.max(cur, Math.max(maxProd * cur, minProd * cur));\n            int tempMin = Math.min(cur, Math.min(maxProd * cur, minProd * cur));\n            maxProd = tempMax;\n            minProd = tempMin;\n            result = Math.max(result, maxProd);\n        }\n\n        System.out.println(result);\n    }\n}',NULL,1),
(126,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(/\\s+/).map(Number);\n\n    let maxProd = nums[0];\n    let minProd = nums[0];\n    let result = nums[0];\n\n    for (let i = 1; i < n; i++) {\n        const cur = nums[i];\n        const tempMax = Math.max(cur, Math.max(maxProd * cur, minProd * cur));\n        const tempMin = Math.min(cur, Math.min(maxProd * cur, minProd * cur));\n        maxProd = tempMax;\n        minProd = tempMin;\n        result = Math.max(result, maxProd);\n    }\n\n    console.log(result);\n});',NULL,1),
(126,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\n\nmax_prod = nums[0]\nmin_prod = nums[0]\nresult = nums[0]\n\nfor i in range(1, n):\n    cur = nums[i]\n    temp_max = max(cur, max_prod * cur, min_prod * cur)\n    temp_min = min(cur, max_prod * cur, min_prod * cur)\n    max_prod = temp_max\n    min_prod = temp_min\n    result = max(result, max_prod)\n\nprint(result)',NULL,1),
(127,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nstruct ListNode {\n    int val;\n    struct ListNode *next;\n};\n\nstruct ListNode* swapPairs(struct ListNode* head) {\n    struct ListNode dummy;\n    dummy.next = head;\n    struct ListNode *prev = &dummy;\n\n    while (prev->next != NULL && prev->next->next != NULL) {\n        struct ListNode *first = prev->next;\n        struct ListNode *second = first->next;\n\n        first->next = second->next;\n        second->next = first;\n        prev->next = second;\n\n        prev = first;\n    }\n\n    return dummy.next;\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) {\n        return 0;\n    }\n\n    line[strcspn(line, \"\\r\\n\")] = \'\\0\';\n\n    if (strcmp(line, \"NULL\") == 0) {\n        printf(\"NULL\\n\");\n        return 0;\n    }\n\n    struct ListNode dummy;\n    dummy.next = NULL;\n    struct ListNode *cur = &dummy;\n\n    char *token = strtok(line, \"->\");\n    while (token != NULL) {\n        if (strcmp(token, \"NULL\") == 0) {\n            break;\n        }\n        struct ListNode *node = (struct ListNode *)malloc(sizeof(struct ListNode));\n        node->val = atoi(token);\n        node->next = NULL;\n        cur->next = node;\n        cur = cur->next;\n        token = strtok(NULL, \"->\");\n    }\n\n    struct ListNode *newHead = swapPairs(dummy.next);\n\n    struct ListNode *p = newHead;\n    while (p != NULL) {\n        printf(\"%d->\", p->val);\n        p = p->next;\n    }\n    printf(\"NULL\\n\");\n\n    return 0;\n}',NULL,1),
(127,'CPP','#include <iostream>\n#include <string>\n#include <sstream>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int v) : val(v), next(nullptr) {}\n};\n\nListNode* swapPairs(ListNode* head) {\n    ListNode dummy(0);\n    dummy.next = head;\n    ListNode* prev = &dummy;\n\n    while (prev->next != nullptr && prev->next->next != nullptr) {\n        ListNode* first = prev->next;\n        ListNode* second = first->next;\n\n        first->next = second->next;\n        second->next = first;\n        prev->next = second;\n\n        prev = first;\n    }\n\n    return dummy.next;\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    string line;\n    if (!getline(cin, line)) return 0;\n\n    if (line == \"NULL\") {\n        cout << \"NULL\\n\";\n        return 0;\n    }\n\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n\n    size_t pos = 0;\n    while (pos < line.size()) {\n        size_t nextPos = line.find(\"->\", pos);\n        string part;\n        if (nextPos == string::npos) {\n            part = line.substr(pos);\n            pos = line.size();\n        } else {\n            part = line.substr(pos, nextPos - pos);\n            pos = nextPos + 2;\n        }\n\n        if (part == \"NULL\" || part.empty()) break;\n\n        cur->next = new ListNode(stoi(part));\n        cur = cur->next;\n    }\n\n    ListNode* newHead = swapPairs(dummy.next);\n\n    string out;\n    ListNode* p = newHead;\n    while (p != nullptr) {\n        out += to_string(p->val);\n        out += \"->\";\n        p = p->next;\n    }\n    out += \"NULL\";\n\n    cout << out << \'\\n\';\n    return 0;\n}',NULL,1),
(127,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) {\n            this.val = val;\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.equals(\"NULL\")) {\n            System.out.println(\"NULL\");\n            return;\n        }\n\n        String[] parts = line.split(\"->\");\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        for (String part : parts) {\n            if (part.equals(\"NULL\")) {\n                break;\n            }\n            cur.next = new ListNode(Integer.parseInt(part));\n            cur = cur.next;\n        }\n\n        ListNode head = dummy.next;\n        ListNode newHead = swapPairs(head);\n\n        StringBuilder sb = new StringBuilder();\n        ListNode p = newHead;\n        while (p != null) {\n            sb.append(p.val).append(\"->\");\n            p = p.next;\n        }\n        sb.append(\"NULL\");\n        System.out.println(sb.toString());\n    }\n\n    private static ListNode swapPairs(ListNode head) {\n        ListNode dummy = new ListNode(0);\n        dummy.next = head;\n        ListNode prev = dummy;\n\n        while (prev.next != null && prev.next.next != null) {\n            ListNode first = prev.next;\n            ListNode second = first.next;\n\n            first.next = second.next;\n            second.next = first;\n            prev.next = second;\n\n            prev = first;\n        }\n\n        return dummy.next;\n    }\n}',NULL,1),
(127,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass ListNode {\n    constructor(val) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction swapPairs(head) {\n    const dummy = new ListNode(0);\n    dummy.next = head;\n    let prev = dummy;\n\n    while (prev.next !== null && prev.next.next !== null) {\n        const first = prev.next;\n        const second = first.next;\n\n        first.next = second.next;\n        second.next = first;\n        prev.next = second;\n\n        prev = first;\n    }\n\n    return dummy.next;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line === \'NULL\') {\n        console.log(\'NULL\');\n        rl.close();\n        return;\n    }\n\n    const parts = line.split(\'->\');\n    const dummy = new ListNode(0);\n    let cur = dummy;\n    for (const part of parts) {\n        if (part === \'NULL\') {\n            break;\n        }\n        cur.next = new ListNode(parseInt(part));\n        cur = cur.next;\n    }\n\n    const head = dummy.next;\n    const newHead = swapPairs(head);\n\n    let sb = \'\';\n    let p = newHead;\n    while (p !== null) {\n        sb += p.val + \'->\';\n        p = p.next;\n    }\n    sb += \'NULL\';\n    console.log(sb);\n    rl.close();\n});',NULL,1),
(127,'PYTHON','import sys\n\nclass ListNode:\n    def __init__(self, val):\n        self.val = val\n        self.next = None\n\ndef swapPairs(head):\n    dummy = ListNode(0)\n    dummy.next = head\n    prev = dummy\n\n    while prev.next is not None and prev.next.next is not None:\n        first = prev.next\n        second = first.next\n\n        first.next = second.next\n        second.next = first\n        prev.next = second\n\n        prev = first\n\n    return dummy.next\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line == \"NULL\":\n        print(\"NULL\")\n        return\n\n    parts = line.split(\"->\")\n    dummy = ListNode(0)\n    cur = dummy\n    for part in parts:\n        if part == \"NULL\":\n            break\n        cur.next = ListNode(int(part))\n        cur = cur.next\n\n    head = dummy.next\n    new_head = swapPairs(head)\n\n    sb = []\n    p = new_head\n    while p is not None:\n        sb.append(str(p.val))\n        sb.append(\"->\")\n        p = p.next\n    sb.append(\"NULL\")\n    print(\"\".join(sb))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(128,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct ListNode {\n    int val;\n    struct ListNode *next;\n} ListNode;\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n\n    line[strcspn(line, \"\\r\\n\")] = \'\\0\';\n\n    if (strcmp(line, \"NULL\") == 0) {\n        printf(\"NULL\\n\");\n        return 0;\n    }\n\n    ListNode dummy;\n    dummy.val = 0;\n    dummy.next = NULL;\n    ListNode *tail = &dummy;\n\n    char *token = strtok(line, \"->\");\n    while (token != NULL) {\n        if (strcmp(token, \"NULL\") == 0) {\n            break;\n        }\n        int val = atoi(token);\n        if (dummy.next == NULL || tail->val != val) {\n            ListNode *node = (ListNode *)malloc(sizeof(ListNode));\n            node->val = val;\n            node->next = NULL;\n            tail->next = node;\n            tail = node;\n        }\n        token = strtok(NULL, \"->\");\n    }\n\n    ListNode *cur = dummy.next;\n    while (cur != NULL) {\n        printf(\"%d->\", cur->val);\n        cur = cur->next;\n    }\n    printf(\"NULL\\n\");\n\n    cur = dummy.next;\n    while (cur != NULL) {\n        ListNode *tmp = cur;\n        cur = cur->next;\n        free(tmp);\n    }\n\n    return 0;\n}',NULL,1),
(128,'CPP','#include <iostream>\n#include <string>\n#include <sstream>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int v) : val(v), next(nullptr) {}\n};\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    string line;\n    if (!getline(cin, line)) return 0;\n\n    if (line == \"NULL\") {\n        cout << \"NULL\\n\";\n        return 0;\n    }\n\n    ListNode dummy(0);\n    ListNode* tail = &dummy;\n\n    size_t pos = 0;\n    while (pos < line.size()) {\n        size_t nextPos = line.find(\"->\", pos);\n        string part;\n        if (nextPos == string::npos) {\n            part = line.substr(pos);\n            pos = line.size();\n        } else {\n            part = line.substr(pos, nextPos - pos);\n            pos = nextPos + 2;\n        }\n\n        if (part == \"NULL\") break;\n\n        int val = 0;\n        for (char c : part) {\n            val = val * 10 + (c - \'0\');\n        }\n\n        if (dummy.next == nullptr || tail->val != val) {\n            tail->next = new ListNode(val);\n            tail = tail->next;\n        }\n    }\n\n    ListNode* cur = dummy.next;\n    bool first = true;\n    while (cur != nullptr) {\n        if (!first) cout << \"->\";\n        cout << cur->val;\n        first = false;\n        cur = cur->next;\n    }\n    if (!first) cout << \"->\";\n    cout << \"NULL\\n\";\n\n    return 0;\n}',NULL,1),
(128,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) {\n            this.val = val;\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.equals(\"NULL\")) {\n            System.out.println(\"NULL\");\n            return;\n        }\n\n        String[] parts = line.split(\"->\");\n        ListNode dummy = new ListNode(0);\n        ListNode tail = dummy;\n\n        for (String part : parts) {\n            if (part.equals(\"NULL\")) {\n                break;\n            }\n            int val = Integer.parseInt(part);\n            if (dummy.next == null || tail.val != val) {\n                tail.next = new ListNode(val);\n                tail = tail.next;\n            }\n        }\n\n        StringBuilder sb = new StringBuilder();\n        ListNode cur = dummy.next;\n        while (cur != null) {\n            sb.append(cur.val).append(\"->\");\n            cur = cur.next;\n        }\n        sb.append(\"NULL\");\n        System.out.println(sb.toString());\n    }\n}',NULL,1),
(128,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line === \'NULL\') {\n        console.log(\'NULL\');\n        rl.close();\n        return;\n    }\n\n    const parts = line.split(\'->\');\n    const dummy = { val: 0, next: null };\n    let tail = dummy;\n\n    for (const part of parts) {\n        if (part === \'NULL\') {\n            break;\n        }\n        const val = parseInt(part, 10);\n        if (dummy.next === null || tail.val !== val) {\n            tail.next = { val: val, next: null };\n            tail = tail.next;\n        }\n    }\n\n    let result = \'\';\n    let cur = dummy.next;\n    while (cur !== null) {\n        result += cur.val + \'->\';\n        cur = cur.next;\n    }\n    result += \'NULL\';\n    console.log(result);\n    rl.close();\n});',NULL,1),
(128,'PYTHON','import sys\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line == \"NULL\":\n        print(\"NULL\")\n        return\n\n    parts = line.split(\"->\")\n    dummy = type(\'ListNode\', (object,), {})()\n    dummy.val = 0\n    dummy.next = None\n    tail = dummy\n\n    for part in parts:\n        if part == \"NULL\":\n            break\n        val = int(part)\n        if dummy.next is None or tail.val != val:\n            node = type(\'ListNode\', (object,), {})()\n            node.val = val\n            node.next = None\n            tail.next = node\n            tail = node\n\n    sb = []\n    cur = dummy.next\n    while cur is not None:\n        sb.append(str(cur.val))\n        sb.append(\"->\")\n        cur = cur.next\n    sb.append(\"NULL\")\n    print(\"\".join(sb))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(129,'C','#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct ListNode {\n    int val;\n    struct ListNode *next;\n} ListNode;\n\nint main() {\n    int n;\n    if (scanf(\"%d\", &n) != 1) return 0;\n\n    int *vals = (int *)malloc(sizeof(int) * (n > 0 ? n : 1));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &vals[i]);\n    }\n\n    int pos;\n    scanf(\"%d\", &pos);\n\n    if (n == 0) {\n        printf(\"-1\\n\");\n        free(vals);\n        return 0;\n    }\n\n    ListNode **nodes = (ListNode **)malloc(sizeof(ListNode *) * n);\n    for (int i = 0; i < n; i++) {\n        nodes[i] = (ListNode *)malloc(sizeof(ListNode));\n        nodes[i]->val = vals[i];\n        nodes[i]->next = NULL;\n    }\n\n    for (int i = 0; i < n - 1; i++) {\n        nodes[i]->next = nodes[i + 1];\n    }\n\n    if (pos != -1) {\n        nodes[n - 1]->next = nodes[pos];\n    }\n\n    ListNode *head = nodes[0];\n    ListNode *slow = head;\n    ListNode *fast = head;\n    int hasCycle = 0;\n\n    while (fast != NULL && fast->next != NULL) {\n        slow = slow->next;\n        fast = fast->next->next;\n        if (slow == fast) {\n            hasCycle = 1;\n            break;\n        }\n    }\n\n    if (!hasCycle) {\n        printf(\"-1\\n\");\n    } else {\n        slow = head;\n        while (slow != fast) {\n            slow = slow->next;\n            fast = fast->next;\n        }\n\n        int index = 0;\n        ListNode *cur = head;\n        while (cur != slow) {\n            cur = cur->next;\n            index++;\n        }\n        printf(\"%d\\n\", index);\n    }\n\n    for (int i = 0; i < n; i++) {\n        free(nodes[i]);\n    }\n    free(nodes);\n    free(vals);\n\n    return 0;\n}',NULL,1),
(129,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int v) : val(v), next(nullptr) {}\n};\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> vals(n);\n    for (int i = 0; i < n; i++) {\n        cin >> vals[i];\n    }\n    int pos;\n    cin >> pos;\n\n    if (n == 0) {\n        cout << -1 << endl;\n        return 0;\n    }\n\n    vector<ListNode*> nodes(n);\n    for (int i = 0; i < n; i++) {\n        nodes[i] = new ListNode(vals[i]);\n    }\n    for (int i = 0; i < n - 1; i++) {\n        nodes[i]->next = nodes[i + 1];\n    }\n    if (pos != -1) {\n        nodes[n - 1]->next = nodes[pos];\n    }\n\n    ListNode* head = nodes[0];\n    ListNode* slow = head;\n    ListNode* fast = head;\n    bool hasCycle = false;\n\n    while (fast != nullptr && fast->next != nullptr) {\n        slow = slow->next;\n        fast = fast->next->next;\n        if (slow == fast) {\n            hasCycle = true;\n            break;\n        }\n    }\n\n    if (!hasCycle) {\n        cout << -1 << endl;\n        return 0;\n    }\n\n    slow = head;\n    while (slow != fast) {\n        slow = slow->next;\n        fast = fast->next;\n    }\n\n    int index = 0;\n    ListNode* cur = head;\n    while (cur != slow) {\n        cur = cur->next;\n        index++;\n    }\n    cout << index << endl;\n\n    return 0;\n}',NULL,1),
(129,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) {\n            this.val = val;\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] vals = new int[n];\n        for (int i = 0; i < n; i++) {\n            vals[i] = sc.nextInt();\n        }\n        int pos = sc.nextInt();\n\n        if (n == 0) {\n            System.out.println(-1);\n            return;\n        }\n\n        ListNode[] nodes = new ListNode[n];\n        for (int i = 0; i < n; i++) {\n            nodes[i] = new ListNode(vals[i]);\n        }\n        for (int i = 0; i < n - 1; i++) {\n            nodes[i].next = nodes[i + 1];\n        }\n        if (pos != -1) {\n            nodes[n - 1].next = nodes[pos];\n        }\n\n        ListNode head = nodes[0];\n        ListNode slow = head;\n        ListNode fast = head;\n        boolean hasCycle = false;\n\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n            if (slow == fast) {\n                hasCycle = true;\n                break;\n            }\n        }\n\n        if (!hasCycle) {\n            System.out.println(-1);\n            return;\n        }\n\n        slow = head;\n        while (slow != fast) {\n            slow = slow.next;\n            fast = fast.next;\n        }\n\n        int index = 0;\n        ListNode cur = head;\n        while (cur != slow) {\n            cur = cur.next;\n            index++;\n        }\n        System.out.println(index);\n    }\n}',NULL,1),
(129,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const vals = lines[1] ? lines[1].split(\' \').map(Number) : [];\n    const pos = parseInt(lines[2]);\n\n    if (n === 0) {\n        console.log(-1);\n        return;\n    }\n\n    class ListNode {\n        constructor(val) {\n            this.val = val;\n            this.next = null;\n        }\n    }\n\n    const nodes = [];\n    for (let i = 0; i < n; i++) {\n        nodes.push(new ListNode(vals[i]));\n    }\n    for (let i = 0; i < n - 1; i++) {\n        nodes[i].next = nodes[i + 1];\n    }\n    if (pos !== -1) {\n        nodes[n - 1].next = nodes[pos];\n    }\n\n    const head = nodes[0];\n    let slow = head;\n    let fast = head;\n    let hasCycle = false;\n\n    while (fast !== null && fast.next !== null) {\n        slow = slow.next;\n        fast = fast.next.next;\n        if (slow === fast) {\n            hasCycle = true;\n            break;\n        }\n    }\n\n    if (!hasCycle) {\n        console.log(-1);\n        return;\n    }\n\n    slow = head;\n    while (slow !== fast) {\n        slow = slow.next;\n        fast = fast.next;\n    }\n\n    let index = 0;\n    let cur = head;\n    while (cur !== slow) {\n        cur = cur.next;\n        index++;\n    }\n    console.log(index);\n});',NULL,1),
(129,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    vals = list(map(int, data[1:1+n]))\n    pos = int(data[1+n])\n\n    if n == 0:\n        print(-1)\n        return\n\n    class ListNode:\n        __slots__ = (\'val\', \'next\')\n        def __init__(self, val):\n            self.val = val\n            self.next = None\n\n    nodes = [ListNode(v) for v in vals]\n    for i in range(n - 1):\n        nodes[i].next = nodes[i + 1]\n    if pos != -1:\n        nodes[n - 1].next = nodes[pos]\n\n    head = nodes[0]\n    slow = head\n    fast = head\n    has_cycle = False\n\n    while fast is not None and fast.next is not None:\n        slow = slow.next\n        fast = fast.next.next\n        if slow is fast:\n            has_cycle = True\n            break\n\n    if not has_cycle:\n        print(-1)\n        return\n\n    slow = head\n    while slow is not fast:\n        slow = slow.next\n        fast = fast.next\n\n    index = 0\n    cur = head\n    while cur is not slow:\n        cur = cur.next\n        index += 1\n    print(index)\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(130,'C','#include <stdio.h>\n#include <stdlib.h>\n\nstruct ListNode {\n    int val;\n    struct ListNode *next;\n};\n\nint main() {\n    int len;\n    scanf(\"%d\", &len);\n\n    struct ListNode dummy;\n    dummy.val = 0;\n    dummy.next = NULL;\n    struct ListNode *tail = &dummy;\n\n    for (int i = 0; i < len; i++) {\n        int x;\n        scanf(\"%d\", &x);\n        struct ListNode *node = (struct ListNode *)malloc(sizeof(struct ListNode));\n        node->val = x;\n        node->next = NULL;\n        tail->next = node;\n        tail = node;\n    }\n\n    int n;\n    scanf(\"%d\", &n);\n\n    struct ListNode *fast = &dummy;\n    struct ListNode *slow = &dummy;\n\n    for (int i = 0; i <= n; i++) {\n        fast = fast->next;\n    }\n\n    while (fast != NULL) {\n        fast = fast->next;\n        slow = slow->next;\n    }\n\n    struct ListNode *toDelete = slow->next;\n    slow->next = slow->next->next;\n    free(toDelete);\n\n    struct ListNode *cur = dummy.next;\n    while (cur != NULL) {\n        printf(\"%d->\", cur->val);\n        cur = cur->next;\n    }\n    printf(\"NULL\\n\");\n\n    return 0;\n}',NULL,1),
(130,'CPP','#include <iostream>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int v) : val(v), next(nullptr) {}\n};\n\nint main() {\n    int len;\n    cin >> len;\n\n    ListNode* dummy = new ListNode(0);\n    ListNode* tail = dummy;\n    for (int i = 0; i < len; ++i) {\n        int x;\n        cin >> x;\n        tail->next = new ListNode(x);\n        tail = tail->next;\n    }\n\n    int n;\n    cin >> n;\n\n    ListNode* fast = dummy;\n    ListNode* slow = dummy;\n    for (int i = 0; i <= n; ++i) {\n        fast = fast->next;\n    }\n    while (fast != nullptr) {\n        fast = fast->next;\n        slow = slow->next;\n    }\n    slow->next = slow->next->next;\n\n    ListNode* cur = dummy->next;\n    while (cur != nullptr) {\n        cout << cur->val << \"->\";\n        cur = cur->next;\n    }\n    cout << \"NULL\" << endl;\n\n    return 0;\n}',NULL,1),
(130,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) {\n            this.val = val;\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int len = sc.nextInt();\n        ListNode dummy = new ListNode(0);\n        ListNode tail = dummy;\n        for (int i = 0; i < len; i++) {\n            tail.next = new ListNode(sc.nextInt());\n            tail = tail.next;\n        }\n        int n = sc.nextInt();\n\n        ListNode fast = dummy;\n        ListNode slow = dummy;\n        for (int i = 0; i <= n; i++) {\n            fast = fast.next;\n        }\n        while (fast != null) {\n            fast = fast.next;\n            slow = slow.next;\n        }\n        slow.next = slow.next.next;\n\n        StringBuilder sb = new StringBuilder();\n        ListNode cur = dummy.next;\n        while (cur != null) {\n            sb.append(cur.val).append(\"->\");\n            cur = cur.next;\n        }\n        sb.append(\"NULL\");\n        System.out.println(sb.toString());\n    }\n}',NULL,1),
(130,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const len = parseInt(lines[0]);\n    const values = lines[1].split(\' \').map(Number);\n    const n = parseInt(lines[2]);\n\n    class ListNode {\n        constructor(val) {\n            this.val = val;\n            this.next = null;\n        }\n    }\n\n    const dummy = new ListNode(0);\n    let tail = dummy;\n    for (let i = 0; i < len; i++) {\n        tail.next = new ListNode(values[i]);\n        tail = tail.next;\n    }\n\n    let fast = dummy;\n    let slow = dummy;\n    for (let i = 0; i <= n; i++) {\n        fast = fast.next;\n    }\n    while (fast !== null) {\n        fast = fast.next;\n        slow = slow.next;\n    }\n    slow.next = slow.next.next;\n\n    let result = \'\';\n    let cur = dummy.next;\n    while (cur !== null) {\n        result += cur.val + \'->\';\n        cur = cur.next;\n    }\n    result += \'NULL\';\n    console.log(result);\n});',NULL,1),
(130,'PYTHON','import sys\n\nclass ListNode:\n    def __init__(self, val):\n        self.val = val\n        self.next = None\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    length = int(data[0])\n    dummy = ListNode(0)\n    tail = dummy\n    idx = 1\n    for _ in range(length):\n        tail.next = ListNode(int(data[idx]))\n        tail = tail.next\n        idx += 1\n    n = int(data[idx])\n\n    fast = dummy\n    slow = dummy\n    for _ in range(n + 1):\n        fast = fast.next\n    while fast is not None:\n        fast = fast.next\n        slow = slow.next\n    slow.next = slow.next.next\n\n    res = []\n    cur = dummy.next\n    while cur is not None:\n        res.append(str(cur.val))\n        cur = cur.next\n    print(\"->\".join(res) + \"->NULL\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(131,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct ListNode {\n    int val;\n    struct ListNode *next;\n} ListNode;\n\nListNode* reverse(ListNode* head) {\n    ListNode* prev = NULL;\n    while (head != NULL) {\n        ListNode* next = head->next;\n        head->next = prev;\n        prev = head;\n        head = next;\n    }\n    return prev;\n}\n\nvoid reorderList(ListNode* head) {\n    if (head == NULL || head->next == NULL) return;\n    ListNode *slow = head, *fast = head;\n    while (fast->next != NULL && fast->next->next != NULL) {\n        slow = slow->next;\n        fast = fast->next->next;\n    }\n    ListNode* second = slow->next;\n    slow->next = NULL;\n    second = reverse(second);\n    ListNode* first = head;\n    while (second != NULL) {\n        ListNode* tmp1 = first->next;\n        ListNode* tmp2 = second->next;\n        first->next = second;\n        second->next = tmp1;\n        first = tmp1;\n        second = tmp2;\n    }\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    size_t len = strlen(line);\n    while (len > 0 && (line[len-1] == \'\\n\' || line[len-1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    if (len >= 6 && strcmp(line + len - 6, \"->NULL\") == 0) {\n        line[len - 6] = \'\\0\';\n    }\n    if (line[0] == \'\\0\') {\n        printf(\"NULL\\n\");\n        return 0;\n    }\n    ListNode dummy;\n    dummy.val = 0;\n    dummy.next = NULL;\n    ListNode* cur = &dummy;\n    char* token = strtok(line, \"->\");\n    while (token != NULL) {\n        cur->next = (ListNode*)malloc(sizeof(ListNode));\n        cur->next->val = atoi(token);\n        cur->next->next = NULL;\n        cur = cur->next;\n        token = strtok(NULL, \"->\");\n    }\n    ListNode* head = dummy.next;\n    reorderList(head);\n    cur = head;\n    while (cur != NULL) {\n        printf(\"%d->\", cur->val);\n        cur = cur->next;\n    }\n    printf(\"NULL\\n\");\n    return 0;\n}',NULL,1),
(131,'CPP','#include <iostream>\n#include <string>\n#include <sstream>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int v) : val(v), next(nullptr) {}\n};\n\nListNode* reverseList(ListNode* head) {\n    ListNode* prev = nullptr;\n    while (head != nullptr) {\n        ListNode* nxt = head->next;\n        head->next = prev;\n        prev = head;\n        head = nxt;\n    }\n    return prev;\n}\n\nvoid reorderList(ListNode* head) {\n    if (head == nullptr || head->next == nullptr) return;\n    ListNode* slow = head;\n    ListNode* fast = head;\n    while (fast->next != nullptr && fast->next->next != nullptr) {\n        slow = slow->next;\n        fast = fast->next->next;\n    }\n    ListNode* second = slow->next;\n    slow->next = nullptr;\n    second = reverseList(second);\n    ListNode* first = head;\n    while (second != nullptr) {\n        ListNode* tmp1 = first->next;\n        ListNode* tmp2 = second->next;\n        first->next = second;\n        second->next = tmp1;\n        first = tmp1;\n        second = tmp2;\n    }\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\' || line.back() == \' \')) {\n        line.pop_back();\n    }\n    if (line.size() >= 6 && line.substr(line.size() - 6) == \"->NULL\") {\n        line = line.substr(0, line.size() - 6);\n    }\n    if (line.empty()) {\n        cout << \"NULL\" << endl;\n        return 0;\n    }\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    stringstream ss(line);\n    string part;\n    while (getline(ss, part, \'-\')) {\n        if (part == \">\") continue;\n        if (!part.empty() && part[0] == \'>\') part = part.substr(1);\n        if (part.empty()) continue;\n        cur->next = new ListNode(stoi(part));\n        cur = cur->next;\n    }\n    ListNode* head = dummy.next;\n    reorderList(head);\n    ListNode* p = head;\n    while (p != nullptr) {\n        cout << p->val << \"->\";\n        p = p->next;\n    }\n    cout << \"NULL\" << endl;\n    return 0;\n}',NULL,1),
(131,'JAVA','import java.util.*;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) { this.val = val; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.endsWith(\"->NULL\")) {\n            line = line.substring(0, line.length() - 6);\n        }\n        if (line.isEmpty()) {\n            System.out.println(\"NULL\");\n            return;\n        }\n        String[] parts = line.split(\"->\");\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        for (String p : parts) {\n            cur.next = new ListNode(Integer.parseInt(p.trim()));\n            cur = cur.next;\n        }\n        ListNode head = dummy.next;\n        reorderList(head);\n        StringBuilder sb = new StringBuilder();\n        cur = head;\n        while (cur != null) {\n            sb.append(cur.val).append(\"->\");\n            cur = cur.next;\n        }\n        sb.append(\"NULL\");\n        System.out.println(sb.toString());\n    }\n\n    public static void reorderList(ListNode head) {\n        if (head == null || head.next == null) return;\n        ListNode slow = head, fast = head;\n        while (fast.next != null && fast.next.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n        }\n        ListNode second = slow.next;\n        slow.next = null;\n        second = reverse(second);\n        ListNode first = head;\n        while (second != null) {\n            ListNode tmp1 = first.next;\n            ListNode tmp2 = second.next;\n            first.next = second;\n            second.next = tmp1;\n            first = tmp1;\n            second = tmp2;\n        }\n    }\n\n    private static ListNode reverse(ListNode head) {\n        ListNode prev = null;\n        while (head != null) {\n            ListNode next = head.next;\n            head.next = prev;\n            prev = head;\n            head = next;\n        }\n        return prev;\n    }\n}',NULL,1),
(131,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass ListNode {\n    constructor(val) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction reorderList(head) {\n    if (head === null || head.next === null) return;\n    let slow = head, fast = head;\n    while (fast.next !== null && fast.next.next !== null) {\n        slow = slow.next;\n        fast = fast.next.next;\n    }\n    let second = slow.next;\n    slow.next = null;\n    second = reverse(second);\n    let first = head;\n    while (second !== null) {\n        let tmp1 = first.next;\n        let tmp2 = second.next;\n        first.next = second;\n        second.next = tmp1;\n        first = tmp1;\n        second = tmp2;\n    }\n}\n\nfunction reverse(head) {\n    let prev = null;\n    while (head !== null) {\n        let next = head.next;\n        head.next = prev;\n        prev = head;\n        head = next;\n    }\n    return prev;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line.endsWith(\'->NULL\')) {\n        line = line.substring(0, line.length - 6);\n    }\n    if (line === \'\') {\n        console.log(\'NULL\');\n        rl.close();\n        return;\n    }\n    const parts = line.split(\'->\');\n    const dummy = new ListNode(0);\n    let cur = dummy;\n    for (const p of parts) {\n        cur.next = new ListNode(parseInt(p.trim(), 10));\n        cur = cur.next;\n    }\n    const head = dummy.next;\n    reorderList(head);\n    let sb = \'\';\n    cur = head;\n    while (cur !== null) {\n        sb += cur.val + \'->\';\n        cur = cur.next;\n    }\n    sb += \'NULL\';\n    console.log(sb);\n    rl.close();\n});',NULL,1),
(131,'PYTHON','import sys\n\nclass ListNode:\n    def __init__(self, val=0, next=None):\n        self.val = val\n        self.next = next\n\ndef reorder_list(head):\n    if not head or not head.next:\n        return\n    slow = head\n    fast = head\n    while fast.next and fast.next.next:\n        slow = slow.next\n        fast = fast.next.next\n    second = slow.next\n    slow.next = None\n    second = reverse(second)\n    first = head\n    while second:\n        tmp1 = first.next\n        tmp2 = second.next\n        first.next = second\n        second.next = tmp1\n        first = tmp1\n        second = tmp2\n\ndef reverse(head):\n    prev = None\n    while head:\n        nxt = head.next\n        head.next = prev\n        prev = head\n        head = nxt\n    return prev\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line.endswith(\"->NULL\"):\n        line = line[:-6]\n    if not line:\n        print(\"NULL\")\n        return\n    parts = line.split(\"->\")\n    dummy = ListNode(0)\n    cur = dummy\n    for p in parts:\n        cur.next = ListNode(int(p.strip()))\n        cur = cur.next\n    head = dummy.next\n    reorder_list(head)\n    sb = []\n    cur = head\n    while cur:\n        sb.append(str(cur.val))\n        sb.append(\"->\")\n        cur = cur.next\n    sb.append(\"NULL\")\n    print(\"\".join(sb))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(132,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nstruct ListNode {\n    int val;\n    struct ListNode *next;\n};\n\nstruct ListNode* buildList(char *s) {\n    if (s == NULL || s[0] == \'\\0\' || strcmp(s, \"NULL\") == 0) {\n        return NULL;\n    }\n    struct ListNode dummy;\n    dummy.next = NULL;\n    struct ListNode *cur = &dummy;\n    char *token = strtok(s, \"->\");\n    while (token != NULL) {\n        if (strcmp(token, \"NULL\") == 0) {\n            break;\n        }\n        struct ListNode *node = (struct ListNode*)malloc(sizeof(struct ListNode));\n        node->val = atoi(token);\n        node->next = NULL;\n        cur->next = node;\n        cur = cur->next;\n        token = strtok(NULL, \"->\");\n    }\n    return dummy.next;\n}\n\nchar* printList(struct ListNode *head) {\n    char *buf = (char*)malloc(1000000);\n    buf[0] = \'\\0\';\n    struct ListNode *cur = head;\n    while (cur != NULL) {\n        char tmp[32];\n        sprintf(tmp, \"%d->\", cur->val);\n        strcat(buf, tmp);\n        cur = cur->next;\n    }\n    strcat(buf, \"NULL\");\n    return buf;\n}\n\nstruct ListNode* rotateRight(struct ListNode *head, int k) {\n    if (head == NULL || head->next == NULL || k == 0) {\n        return head;\n    }\n\n    int len = 1;\n    struct ListNode *tail = head;\n    while (tail->next != NULL) {\n        tail = tail->next;\n        len++;\n    }\n\n    k = k % len;\n    if (k == 0) {\n        return head;\n    }\n\n    tail->next = head;\n    struct ListNode *newTail = head;\n    for (int i = 0; i < len - k - 1; i++) {\n        newTail = newTail->next;\n    }\n\n    struct ListNode *newHead = newTail->next;\n    newTail->next = NULL;\n    return newHead;\n}\n\nint main() {\n    char line[1000000];\n    int k;\n\n    if (fgets(line, sizeof(line), stdin) == NULL) {\n        return 0;\n    }\n    line[strcspn(line, \"\\r\\n\")] = \'\\0\';\n\n    if (scanf(\"%d\", &k) != 1) {\n        return 0;\n    }\n\n    struct ListNode *head = buildList(line);\n    head = rotateRight(head, k);\n    char *result = printList(head);\n    printf(\"%s\\n\", result);\n\n    free(result);\n    return 0;\n}',NULL,1),
(132,'CPP','#include <iostream>\n#include <string>\n#include <sstream>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int v) : val(v), next(nullptr) {}\n};\n\nListNode* buildList(const string& s) {\n    if (s.empty() || s == \"NULL\") return nullptr;\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    size_t start = 0;\n    while (start < s.size()) {\n        size_t pos = s.find(\"->\", start);\n        string part;\n        if (pos == string::npos) {\n            part = s.substr(start);\n            start = s.size();\n        } else {\n            part = s.substr(start, pos - start);\n            start = pos + 2;\n        }\n        if (part == \"NULL\") break;\n        cur->next = new ListNode(stoi(part));\n        cur = cur->next;\n    }\n    return dummy.next;\n}\n\nstring printList(ListNode* head) {\n    string res;\n    ListNode* cur = head;\n    while (cur) {\n        res += to_string(cur->val);\n        res += \"->\";\n        cur = cur->next;\n    }\n    res += \"NULL\";\n    return res;\n}\n\nListNode* rotateRight(ListNode* head, int k) {\n    if (!head || !head->next || k == 0) return head;\n\n    int len = 1;\n    ListNode* tail = head;\n    while (tail->next) {\n        tail = tail->next;\n        len++;\n    }\n\n    k %= len;\n    if (k == 0) return head;\n\n    tail->next = head;\n    ListNode* newTail = head;\n    for (int i = 0; i < len - k - 1; i++) {\n        newTail = newTail->next;\n    }\n\n    ListNode* newHead = newTail->next;\n    newTail->next = nullptr;\n    return newHead;\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    string line;\n    getline(cin, line);\n    int k;\n    cin >> k;\n\n    ListNode* head = buildList(line);\n    head = rotateRight(head, k);\n    cout << printList(head) << \'\\n\';\n\n    return 0;\n}',NULL,1),
(132,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) {\n            this.val = val;\n        }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        int k = Integer.parseInt(sc.nextLine().trim());\n\n        ListNode head = buildList(line);\n        head = rotateRight(head, k);\n        System.out.println(printList(head));\n    }\n\n    private static ListNode buildList(String s) {\n        if (s == null || s.isEmpty() || s.equals(\"NULL\")) {\n            return null;\n        }\n        String[] parts = s.split(\"->\");\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        for (String part : parts) {\n            if (part.equals(\"NULL\")) {\n                break;\n            }\n            cur.next = new ListNode(Integer.parseInt(part));\n            cur = cur.next;\n        }\n        return dummy.next;\n    }\n\n    private static String printList(ListNode head) {\n        StringBuilder sb = new StringBuilder();\n        ListNode cur = head;\n        while (cur != null) {\n            sb.append(cur.val).append(\"->\");\n            cur = cur.next;\n        }\n        sb.append(\"NULL\");\n        return sb.toString();\n    }\n\n    private static ListNode rotateRight(ListNode head, int k) {\n        if (head == null || head.next == null || k == 0) {\n            return head;\n        }\n\n        int len = 1;\n        ListNode tail = head;\n        while (tail.next != null) {\n            tail = tail.next;\n            len++;\n        }\n\n        k = k % len;\n        if (k == 0) {\n            return head;\n        }\n\n        tail.next = head;\n        ListNode newTail = head;\n        for (int i = 0; i < len - k - 1; i++) {\n            newTail = newTail.next;\n        }\n\n        ListNode newHead = newTail.next;\n        newTail.next = null;\n        return newHead;\n    }\n}',NULL,1),
(132,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nclass ListNode {\n    constructor(val) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction buildList(s) {\n    if (s === null || s === \'\' || s === \'NULL\') {\n        return null;\n    }\n    const parts = s.split(\'->\');\n    const dummy = new ListNode(0);\n    let cur = dummy;\n    for (const part of parts) {\n        if (part === \'NULL\') {\n            break;\n        }\n        cur.next = new ListNode(parseInt(part));\n        cur = cur.next;\n    }\n    return dummy.next;\n}\n\nfunction printList(head) {\n    let sb = \'\';\n    let cur = head;\n    while (cur !== null) {\n        sb += cur.val + \'->\';\n        cur = cur.next;\n    }\n    sb += \'NULL\';\n    return sb;\n}\n\nfunction rotateRight(head, k) {\n    if (head === null || head.next === null || k === 0) {\n        return head;\n    }\n\n    let len = 1;\n    let tail = head;\n    while (tail.next !== null) {\n        tail = tail.next;\n        len++;\n    }\n\n    k = k % len;\n    if (k === 0) {\n        return head;\n    }\n\n    tail.next = head;\n    let newTail = head;\n    for (let i = 0; i < len - k - 1; i++) {\n        newTail = newTail.next;\n    }\n\n    const newHead = newTail.next;\n    newTail.next = null;\n    return newHead;\n}\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const listLine = lines[0];\n        const k = parseInt(lines[1]);\n\n        let head = buildList(listLine);\n        head = rotateRight(head, k);\n        console.log(printList(head));\n        rl.close();\n    }\n});',NULL,1),
(132,'PYTHON','import sys\n\nclass ListNode:\n    def __init__(self, val):\n        self.val = val\n        self.next = None\n\ndef build_list(s):\n    if s is None or s == \"\" or s == \"NULL\":\n        return None\n    parts = s.split(\"->\")\n    dummy = ListNode(0)\n    cur = dummy\n    for part in parts:\n        if part == \"NULL\":\n            break\n        cur.next = ListNode(int(part))\n        cur = cur.next\n    return dummy.next\n\ndef print_list(head):\n    sb = []\n    cur = head\n    while cur is not None:\n        sb.append(str(cur.val))\n        sb.append(\"->\")\n        cur = cur.next\n    sb.append(\"NULL\")\n    return \"\".join(sb)\n\ndef rotate_right(head, k):\n    if head is None or head.next is None or k == 0:\n        return head\n\n    length = 1\n    tail = head\n    while tail.next is not None:\n        tail = tail.next\n        length += 1\n\n    k = k % length\n    if k == 0:\n        return head\n\n    tail.next = head\n    new_tail = head\n    for _ in range(length - k - 1):\n        new_tail = new_tail.next\n\n    new_head = new_tail.next\n    new_tail.next = None\n    return new_head\n\ndef main():\n    lines = sys.stdin.read().splitlines()\n    if not lines:\n        return\n    line = lines[0].strip()\n    k = int(lines[1].strip())\n\n    head = build_list(line)\n    head = rotate_right(head, k)\n    print(print_list(head))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(133,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct ListNode {\n    int val;\n    struct ListNode *next;\n} ListNode;\n\ntypedef struct {\n    ListNode **data;\n    int size;\n    int capacity;\n} PriorityQueue;\n\nstatic void pq_init(PriorityQueue *pq, int capacity) {\n    pq->data = (ListNode **)malloc(sizeof(ListNode *) * capacity);\n    pq->size = 0;\n    pq->capacity = capacity;\n}\n\nstatic void pq_free(PriorityQueue *pq) {\n    free(pq->data);\n}\n\nstatic void pq_swap(ListNode **a, ListNode **b) {\n    ListNode *t = *a;\n    *a = *b;\n    *b = t;\n}\n\nstatic void pq_push(PriorityQueue *pq, ListNode *node) {\n    int i = pq->size++;\n    pq->data[i] = node;\n    while (i > 0) {\n        int p = (i - 1) / 2;\n        if (pq->data[p]->val <= pq->data[i]->val) break;\n        pq_swap(&pq->data[p], &pq->data[i]);\n        i = p;\n    }\n}\n\nstatic ListNode *pq_pop(PriorityQueue *pq) {\n    ListNode *res = pq->data[0];\n    pq->data[0] = pq->data[--pq->size];\n    int i = 0;\n    while (1) {\n        int l = i * 2 + 1;\n        int r = i * 2 + 2;\n        int smallest = i;\n        if (l < pq->size && pq->data[l]->val < pq->data[smallest]->val) smallest = l;\n        if (r < pq->size && pq->data[r]->val < pq->data[smallest]->val) smallest = r;\n        if (smallest == i) break;\n        pq_swap(&pq->data[i], &pq->data[smallest]);\n        i = smallest;\n    }\n    return res;\n}\n\nstatic ListNode *parseList(const char *s) {\n    if (s == NULL || s[0] == \'\\0\' || strcmp(s, \"NULL\") == 0) return NULL;\n    char *buf = (char *)malloc(strlen(s) + 1);\n    strcpy(buf, s);\n    ListNode dummy;\n    dummy.val = 0;\n    dummy.next = NULL;\n    ListNode *cur = &dummy;\n    char *token = strtok(buf, \"->\");\n    while (token != NULL) {\n        if (strcmp(token, \"NULL\") == 0) break;\n        ListNode *node = (ListNode *)malloc(sizeof(ListNode));\n        node->val = atoi(token);\n        node->next = NULL;\n        cur->next = node;\n        cur = node;\n        token = strtok(NULL, \"->\");\n    }\n    free(buf);\n    return dummy.next;\n}\n\nstatic char *formatList(ListNode *head) {\n    size_t cap = 1024;\n    size_t len = 0;\n    char *res = (char *)malloc(cap);\n    res[0] = \'\\0\';\n    ListNode *cur = head;\n    while (cur != NULL) {\n        char tmp[32];\n        int n = snprintf(tmp, sizeof(tmp), \"%d->\", cur->val);\n        if (len + (size_t)n + 6 > cap) {\n            cap *= 2;\n            res = (char *)realloc(res, cap);\n        }\n        strcpy(res + len, tmp);\n        len += (size_t)n;\n        cur = cur->next;\n    }\n    if (len + 5 > cap) {\n        cap = len + 5;\n        res = (char *)realloc(res, cap);\n    }\n    strcpy(res + len, \"NULL\");\n    return res;\n}\n\nstatic ListNode *mergeKLists(ListNode **lists, int k) {\n    PriorityQueue pq;\n    pq_init(&pq, k > 0 ? k : 1);\n    for (int i = 0; i < k; i++) {\n        if (lists[i] != NULL) pq_push(&pq, lists[i]);\n    }\n    ListNode dummy;\n    dummy.val = 0;\n    dummy.next = NULL;\n    ListNode *cur = &dummy;\n    while (pq.size > 0) {\n        ListNode *node = pq_pop(&pq);\n        cur->next = node;\n        cur = cur->next;\n        if (node->next != NULL) pq_push(&pq, node->next);\n    }\n    pq_free(&pq);\n    return dummy.next;\n}\n\nint main(void) {\n    int k;\n    if (scanf(\"%d\", &k) != 1) return 0;\n    int c;\n    while ((c = getchar()) != \'\\n\' && c != EOF) {}\n\n    ListNode **lists = (ListNode **)malloc(sizeof(ListNode *) * (k > 0 ? k : 1));\n    for (int i = 0; i < k; i++) {\n        size_t cap = 1024;\n        size_t len = 0;\n        char *line = (char *)malloc(cap);\n        line[0] = \'\\0\';\n        while ((c = getchar()) != \'\\n\' && c != EOF) {\n            if (len + 2 > cap) {\n                cap *= 2;\n                line = (char *)realloc(line, cap);\n            }\n            line[len++] = (char)c;\n            line[len] = \'\\0\';\n        }\n        lists[i] = parseList(line);\n        free(line);\n    }\n\n    ListNode *merged = mergeKLists(lists, k);\n    char *out = formatList(merged);\n    printf(\"%s\\n\", out);\n\n    free(out);\n    free(lists);\n    return 0;\n}',NULL,1),
(133,'CPP','#include <bits/stdc++.h>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode *next;\n    ListNode(int x) : val(x), next(nullptr) {}\n};\n\nListNode* parseList(const string& s) {\n    if (s.empty() || s == \"NULL\") return nullptr;\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    size_t start = 0;\n    while (start < s.size()) {\n        size_t pos = s.find(\"->\", start);\n        string part;\n        if (pos == string::npos) {\n            part = s.substr(start);\n            start = s.size();\n        } else {\n            part = s.substr(start, pos - start);\n            start = pos + 2;\n        }\n        if (part == \"NULL\") break;\n        cur->next = new ListNode(stoi(part));\n        cur = cur->next;\n    }\n    return dummy.next;\n}\n\nstring formatList(ListNode* head) {\n    string res;\n    ListNode* cur = head;\n    while (cur) {\n        res += to_string(cur->val);\n        res += \"->\";\n        cur = cur->next;\n    }\n    res += \"NULL\";\n    return res;\n}\n\nstruct Compare {\n    bool operator()(ListNode* a, ListNode* b) {\n        return a->val > b->val;\n    }\n};\n\nListNode* mergeKLists(vector<ListNode*>& lists) {\n    priority_queue<ListNode*, vector<ListNode*>, Compare> pq;\n    for (ListNode* node : lists) {\n        if (node) pq.push(node);\n    }\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    while (!pq.empty()) {\n        ListNode* node = pq.top();\n        pq.pop();\n        cur->next = node;\n        cur = cur->next;\n        if (node->next) pq.push(node->next);\n    }\n    return dummy.next;\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    int k;\n    cin >> k;\n    cin.ignore();\n\n    vector<ListNode*> lists;\n    lists.reserve(k);\n\n    for (int i = 0; i < k; ++i) {\n        string line;\n        getline(cin, line);\n        lists.push_back(parseList(line));\n    }\n\n    ListNode* merged = mergeKLists(lists);\n    cout << formatList(merged) << \'\\n\';\n\n    return 0;\n}',NULL,1),
(133,'JAVA','import java.util.*;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) { this.val = val; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int k = Integer.parseInt(sc.nextLine().trim());\n        List<ListNode> lists = new ArrayList<>();\n        for (int i = 0; i < k; i++) {\n            String line = sc.nextLine().trim();\n            lists.add(parseList(line));\n        }\n        ListNode merged = mergeKLists(lists);\n        System.out.println(formatList(merged));\n    }\n\n    private static ListNode parseList(String s) {\n        if (s == null || s.isEmpty() || s.equals(\"NULL\")) return null;\n        String[] parts = s.split(\"->\");\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        for (String p : parts) {\n            if (p.equals(\"NULL\")) break;\n            cur.next = new ListNode(Integer.parseInt(p.trim()));\n            cur = cur.next;\n        }\n        return dummy.next;\n    }\n\n    private static String formatList(ListNode head) {\n        StringBuilder sb = new StringBuilder();\n        ListNode cur = head;\n        while (cur != null) {\n            sb.append(cur.val).append(\"->\");\n            cur = cur.next;\n        }\n        sb.append(\"NULL\");\n        return sb.toString();\n    }\n\n    private static ListNode mergeKLists(List<ListNode> lists) {\n        PriorityQueue<ListNode> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a.val));\n        for (ListNode node : lists) {\n            if (node != null) pq.offer(node);\n        }\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        while (!pq.isEmpty()) {\n            ListNode node = pq.poll();\n            cur.next = node;\n            cur = cur.next;\n            if (node.next != null) pq.offer(node.next);\n        }\n        return dummy.next;\n    }\n}',NULL,1),
(133,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass ListNode {\n    constructor(val) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction parseList(s) {\n    if (!s || s === \'NULL\') return null;\n    const parts = s.split(\'->\');\n    const dummy = new ListNode(0);\n    let cur = dummy;\n    for (const p of parts) {\n        if (p === \'NULL\') break;\n        cur.next = new ListNode(parseInt(p.trim(), 10));\n        cur = cur.next;\n    }\n    return dummy.next;\n}\n\nfunction formatList(head) {\n    let sb = \'\';\n    let cur = head;\n    while (cur !== null) {\n        sb += cur.val + \'->\';\n        cur = cur.next;\n    }\n    sb += \'NULL\';\n    return sb;\n}\n\nfunction mergeKLists(lists) {\n    const pq = [];\n    const push = (node) => {\n        pq.push(node);\n        let i = pq.length - 1;\n        while (i > 0) {\n            const p = (i - 1) >> 1;\n            if (pq[p].val <= pq[i].val) break;\n            [pq[p], pq[i]] = [pq[i], pq[p]];\n            i = p;\n        }\n    };\n    const pop = () => {\n        const top = pq[0];\n        const last = pq.pop();\n        if (pq.length > 0) {\n            pq[0] = last;\n            let i = 0;\n            while (true) {\n                let l = i * 2 + 1;\n                let r = i * 2 + 2;\n                let smallest = i;\n                if (l < pq.length && pq[l].val < pq[smallest].val) smallest = l;\n                if (r < pq.length && pq[r].val < pq[smallest].val) smallest = r;\n                if (smallest === i) break;\n                [pq[i], pq[smallest]] = [pq[smallest], pq[i]];\n                i = smallest;\n            }\n        }\n        return top;\n    };\n\n    for (const node of lists) {\n        if (node !== null) push(node);\n    }\n\n    const dummy = new ListNode(0);\n    let cur = dummy;\n    while (pq.length > 0) {\n        const node = pop();\n        cur.next = node;\n        cur = cur.next;\n        if (node.next !== null) push(node.next);\n    }\n    return dummy.next;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n});\n\nrl.on(\'close\', () => {\n    const k = parseInt(lines[0].trim(), 10);\n    const lists = [];\n    for (let i = 0; i < k; i++) {\n        lists.push(parseList(lines[i + 1].trim()));\n    }\n    const merged = mergeKLists(lists);\n    console.log(formatList(merged));\n});',NULL,1),
(133,'PYTHON','import sys\nimport heapq\n\nclass ListNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.next = None\n\ndef parse_list(s):\n    if s is None or s == \"\" or s == \"NULL\":\n        return None\n    parts = s.split(\"->\")\n    dummy = ListNode(0)\n    cur = dummy\n    for p in parts:\n        if p == \"NULL\":\n            break\n        cur.next = ListNode(int(p.strip()))\n        cur = cur.next\n    return dummy.next\n\ndef format_list(head):\n    sb = []\n    cur = head\n    while cur is not None:\n        sb.append(str(cur.val))\n        sb.append(\"->\")\n        cur = cur.next\n    sb.append(\"NULL\")\n    return \"\".join(sb)\n\ndef merge_k_lists(lists):\n    heap = []\n    for node in lists:\n        if node is not None:\n            heapq.heappush(heap, (node.val, id(node), node))\n    dummy = ListNode(0)\n    cur = dummy\n    while heap:\n        val, _, node = heapq.heappop(heap)\n        cur.next = node\n        cur = cur.next\n        if node.next is not None:\n            heapq.heappush(heap, (node.next.val, id(node.next), node.next))\n    return dummy.next\n\ndef main():\n    data = sys.stdin.read().splitlines()\n    if not data:\n        return\n    k = int(data[0].strip())\n    lists = []\n    for i in range(1, k + 1):\n        line = data[i].strip() if i < len(data) else \"\"\n        lists.append(parse_list(line))\n    merged = merge_k_lists(lists)\n    print(format_list(merged))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(134,'C','#include <stdio.h>\n#include <stdlib.h>\n\nstruct ListNode {\n    int val;\n    struct ListNode *next;\n};\n\nstruct ListNode* merge(struct ListNode* l1, struct ListNode* l2) {\n    struct ListNode dummy;\n    struct ListNode* cur = &dummy;\n    dummy.next = NULL;\n    while (l1 != NULL && l2 != NULL) {\n        if (l1->val <= l2->val) {\n            cur->next = l1;\n            l1 = l1->next;\n        } else {\n            cur->next = l2;\n            l2 = l2->next;\n        }\n        cur = cur->next;\n    }\n    cur->next = (l1 != NULL) ? l1 : l2;\n    return dummy.next;\n}\n\nstruct ListNode* sortList(struct ListNode* head) {\n    if (head == NULL || head->next == NULL) return head;\n    struct ListNode *slow = head, *fast = head->next;\n    while (fast != NULL && fast->next != NULL) {\n        slow = slow->next;\n        fast = fast->next->next;\n    }\n    struct ListNode* mid = slow->next;\n    slow->next = NULL;\n    struct ListNode* left = sortList(head);\n    struct ListNode* right = sortList(mid);\n    return merge(left, right);\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    struct ListNode dummy;\n    dummy.next = NULL;\n    struct ListNode* cur = &dummy;\n    for (int i = 0; i < n; i++) {\n        int x;\n        scanf(\"%d\", &x);\n        struct ListNode* node = (struct ListNode*)malloc(sizeof(struct ListNode));\n        node->val = x;\n        node->next = NULL;\n        cur->next = node;\n        cur = cur->next;\n    }\n    struct ListNode* sorted = sortList(dummy.next);\n    while (sorted != NULL) {\n        printf(\"%d->\", sorted->val);\n        sorted = sorted->next;\n    }\n    printf(\"NULL\\n\");\n    return 0;\n}',NULL,1),
(134,'CPP','#include <iostream>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int v) : val(v), next(nullptr) {}\n};\n\nListNode* merge(ListNode* l1, ListNode* l2) {\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    while (l1 != nullptr && l2 != nullptr) {\n        if (l1->val <= l2->val) {\n            cur->next = l1;\n            l1 = l1->next;\n        } else {\n            cur->next = l2;\n            l2 = l2->next;\n        }\n        cur = cur->next;\n    }\n    cur->next = (l1 != nullptr) ? l1 : l2;\n    return dummy.next;\n}\n\nListNode* sortList(ListNode* head) {\n    if (head == nullptr || head->next == nullptr) return head;\n    ListNode* slow = head;\n    ListNode* fast = head->next;\n    while (fast != nullptr && fast->next != nullptr) {\n        slow = slow->next;\n        fast = fast->next->next;\n    }\n    ListNode* mid = slow->next;\n    slow->next = nullptr;\n    ListNode* left = sortList(head);\n    ListNode* right = sortList(mid);\n    return merge(left, right);\n}\n\nint main() {\n    int n;\n    cin >> n;\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    for (int i = 0; i < n; i++) {\n        int x;\n        cin >> x;\n        cur->next = new ListNode(x);\n        cur = cur->next;\n    }\n    ListNode* sorted = sortList(dummy.next);\n    while (sorted != nullptr) {\n        cout << sorted->val << \"->\";\n        sorted = sorted->next;\n    }\n    cout << \"NULL\" << endl;\n    return 0;\n}',NULL,1),
(134,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) { this.val = val; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        for (int i = 0; i < n; i++) {\n            cur.next = new ListNode(sc.nextInt());\n            cur = cur.next;\n        }\n        ListNode sorted = sortList(dummy.next);\n        StringBuilder sb = new StringBuilder();\n        while (sorted != null) {\n            sb.append(sorted.val).append(\"->\");\n            sorted = sorted.next;\n        }\n        sb.append(\"NULL\");\n        System.out.println(sb.toString());\n    }\n\n    public static ListNode sortList(ListNode head) {\n        if (head == null || head.next == null) return head;\n        ListNode slow = head, fast = head.next;\n        while (fast != null && fast.next != null) {\n            slow = slow.next;\n            fast = fast.next.next;\n        }\n        ListNode mid = slow.next;\n        slow.next = null;\n        ListNode left = sortList(head);\n        ListNode right = sortList(mid);\n        return merge(left, right);\n    }\n\n    private static ListNode merge(ListNode l1, ListNode l2) {\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        while (l1 != null && l2 != null) {\n            if (l1.val <= l2.val) {\n                cur.next = l1;\n                l1 = l1.next;\n            } else {\n                cur.next = l2;\n                l2 = l2.next;\n            }\n            cur = cur.next;\n        }\n        cur.next = (l1 != null) ? l1 : l2;\n        return dummy.next;\n    }\n}',NULL,1),
(134,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass ListNode {\n    constructor(val) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction sortList(head) {\n    if (head === null || head.next === null) return head;\n    let slow = head, fast = head.next;\n    while (fast !== null && fast.next !== null) {\n        slow = slow.next;\n        fast = fast.next.next;\n    }\n    let mid = slow.next;\n    slow.next = null;\n    let left = sortList(head);\n    let right = sortList(mid);\n    return merge(left, right);\n}\n\nfunction merge(l1, l2) {\n    let dummy = new ListNode(0);\n    let cur = dummy;\n    while (l1 !== null && l2 !== null) {\n        if (l1.val <= l2.val) {\n            cur.next = l1;\n            l1 = l1.next;\n        } else {\n            cur.next = l2;\n            l2 = l2.next;\n        }\n        cur = cur.next;\n    }\n    cur.next = (l1 !== null) ? l1 : l2;\n    return dummy.next;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        rl.close();\n        const n = parseInt(lines[0]);\n        const values = lines[1].split(\' \').map(Number);\n        let dummy = new ListNode(0);\n        let cur = dummy;\n        for (let i = 0; i < n; i++) {\n            cur.next = new ListNode(values[i]);\n            cur = cur.next;\n        }\n        let sorted = sortList(dummy.next);\n        let sb = \'\';\n        while (sorted !== null) {\n            sb += sorted.val + \'->\';\n            sorted = sorted.next;\n        }\n        sb += \'NULL\';\n        console.log(sb);\n    }\n});',NULL,1),
(134,'PYTHON','import sys\n\nclass ListNode:\n    __slots__ = (\'val\', \'next\')\n    def __init__(self, val):\n        self.val = val\n        self.next = None\n\ndef sortList(head):\n    if head is None or head.next is None:\n        return head\n    slow = head\n    fast = head.next\n    while fast is not None and fast.next is not None:\n        slow = slow.next\n        fast = fast.next.next\n    mid = slow.next\n    slow.next = None\n    left = sortList(head)\n    right = sortList(mid)\n    return merge(left, right)\n\ndef merge(l1, l2):\n    dummy = ListNode(0)\n    cur = dummy\n    while l1 is not None and l2 is not None:\n        if l1.val <= l2.val:\n            cur.next = l1\n            l1 = l1.next\n        else:\n            cur.next = l2\n            l2 = l2.next\n        cur = cur.next\n    cur.next = l1 if l1 is not None else l2\n    return dummy.next\n\ndef main():\n    data = sys.stdin.read().split()\n    if not data:\n        return\n    n = int(data[0])\n    dummy = ListNode(0)\n    cur = dummy\n    for i in range(n):\n        cur.next = ListNode(int(data[i + 1]))\n        cur = cur.next\n    sorted_head = sortList(dummy.next)\n    parts = []\n    while sorted_head is not None:\n        parts.append(str(sorted_head.val))\n        sorted_head = sorted_head.next\n    parts.append(\"NULL\")\n    sys.stdout.write(\"->\".join(parts))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(135,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <limits.h>\n\nstruct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n};\n\nstatic int maxSum;\n\nstruct TreeNode* newNode(int val) {\n    struct TreeNode* node = (struct TreeNode*)malloc(sizeof(struct TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nstruct TreeNode* buildTree(char** parts, int n) {\n    if (n == 0 || strcmp(parts[0], \"null\") == 0) return NULL;\n    struct TreeNode* root = newNode(atoi(parts[0]));\n    struct TreeNode** queue = (struct TreeNode**)malloc(sizeof(struct TreeNode*) * n);\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    int i = 1;\n    while (front < rear && i < n) {\n        struct TreeNode* node = queue[front++];\n        if (i < n && strcmp(parts[i], \"null\") != 0) {\n            node->left = newNode(atoi(parts[i]));\n            queue[rear++] = node->left;\n        }\n        i++;\n        if (i < n && strcmp(parts[i], \"null\") != 0) {\n            node->right = newNode(atoi(parts[i]));\n            queue[rear++] = node->right;\n        }\n        i++;\n    }\n    free(queue);\n    return root;\n}\n\nint dfs(struct TreeNode* node) {\n    if (node == NULL) return 0;\n    int left = dfs(node->left);\n    if (left < 0) left = 0;\n    int right = dfs(node->right);\n    if (right < 0) right = 0;\n    int cur = node->val + left + right;\n    if (cur > maxSum) maxSum = cur;\n    int ret = node->val + (left > right ? left : right);\n    return ret;\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    int len = strlen(line);\n    while (len > 0 && (line[len-1] == \'\\n\' || line[len-1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    char* s = line;\n    while (*s == \' \' || *s == \'\\t\') s++;\n    if (*s == \'[\') s++;\n    int end = strlen(s) - 1;\n    while (end >= 0 && (s[end] == \' \' || s[end] == \'\\t\')) end--;\n    if (end >= 0 && s[end] == \']\') s[end] = \'\\0\';\n\n    int isEmpty = 1;\n    for (int i = 0; s[i]; i++) {\n        if (s[i] != \' \' && s[i] != \'\\t\') { isEmpty = 0; break; }\n    }\n    if (isEmpty) {\n        printf(\"0\\n\");\n        return 0;\n    }\n\n    char* parts[100000];\n    int n = 0;\n    char* token = strtok(s, \",\");\n    while (token != NULL) {\n        while (*token == \' \' || *token == \'\\t\') token++;\n        int tl = strlen(token);\n        while (tl > 0 && (token[tl-1] == \' \' || token[tl-1] == \'\\t\')) token[--tl] = \'\\0\';\n        parts[n++] = token;\n        token = strtok(NULL, \",\");\n    }\n\n    struct TreeNode* root = buildTree(parts, n);\n    maxSum = INT_MIN;\n    dfs(root);\n    printf(\"%d\\n\", maxSum);\n    return 0;\n}',NULL,1),
(135,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <sstream>\n#include <climits>\n#include <algorithm>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode *left;\n    TreeNode *right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nint maxSum = INT_MIN;\n\nTreeNode* buildTree(const vector<string>& parts) {\n    if (parts.empty() || parts[0] == \"null\") return nullptr;\n    TreeNode* root = new TreeNode(stoi(parts[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)parts.size()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (i < (int)parts.size() && parts[i] != \"null\") {\n            node->left = new TreeNode(stoi(parts[i]));\n            q.push(node->left);\n        }\n        i++;\n        if (i < (int)parts.size() && parts[i] != \"null\") {\n            node->right = new TreeNode(stoi(parts[i]));\n            q.push(node->right);\n        }\n        i++;\n    }\n    return root;\n}\n\nint dfs(TreeNode* node) {\n    if (node == nullptr) return 0;\n    int left = max(0, dfs(node->left));\n    int right = max(0, dfs(node->right));\n    maxSum = max(maxSum, node->val + left + right);\n    return node->val + max(left, right);\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    if (!line.empty() && line.front() == \'[\') line.erase(0, 1);\n    if (!line.empty() && line.back() == \']\') line.pop_back();\n\n    if (line.find_first_not_of(\" \\t\\r\\n\") == string::npos) {\n        cout << 0 << endl;\n        return 0;\n    }\n\n    vector<string> parts;\n    stringstream ss(line);\n    string token;\n    while (getline(ss, token, \',\')) {\n        size_t start = token.find_first_not_of(\" \\t\\r\\n\");\n        size_t end = token.find_last_not_of(\" \\t\\r\\n\");\n        if (start == string::npos) {\n            parts.push_back(\"\");\n        } else {\n            parts.push_back(token.substr(start, end - start + 1));\n        }\n    }\n\n    TreeNode* root = buildTree(parts);\n    maxSum = INT_MIN;\n    dfs(root);\n    cout << maxSum << endl;\n\n    return 0;\n}',NULL,1),
(135,'JAVA','import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int x) { val = x; }\n    }\n\n    static int maxSum = Integer.MIN_VALUE;\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.startsWith(\"[\")) line = line.substring(1);\n        if (line.endsWith(\"]\")) line = line.substring(0, line.length() - 1);\n\n        if (line.trim().isEmpty()) {\n            System.out.println(0);\n            return;\n        }\n\n        String[] parts = line.split(\",\");\n        TreeNode root = buildTree(parts);\n        maxPathSum(root);\n        System.out.println(maxSum);\n    }\n\n    static TreeNode buildTree(String[] parts) {\n        if (parts.length == 0 || parts[0].trim().equals(\"null\")) return null;\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < parts.length) {\n            TreeNode node = queue.poll();\n            if (i < parts.length && !parts[i].trim().equals(\"null\")) {\n                node.left = new TreeNode(Integer.parseInt(parts[i].trim()));\n                queue.offer(node.left);\n            }\n            i++;\n            if (i < parts.length && !parts[i].trim().equals(\"null\")) {\n                node.right = new TreeNode(Integer.parseInt(parts[i].trim()));\n                queue.offer(node.right);\n            }\n            i++;\n        }\n        return root;\n    }\n\n    static int maxPathSum(TreeNode root) {\n        maxSum = Integer.MIN_VALUE;\n        dfs(root);\n        return maxSum;\n    }\n\n    static int dfs(TreeNode node) {\n        if (node == null) return 0;\n        int left = Math.max(0, dfs(node.left));\n        int right = Math.max(0, dfs(node.right));\n        maxSum = Math.max(maxSum, node.val + left + right);\n        return node.val + Math.max(left, right);\n    }\n}',NULL,1),
(135,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nlet maxSum = -Infinity;\n\nfunction buildTree(parts) {\n    if (parts.length === 0 || parts[0].trim() === \'null\') return null;\n    const root = new TreeNode(parseInt(parts[0].trim()));\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < parts.length) {\n        const node = queue.shift();\n        if (i < parts.length && parts[i].trim() !== \'null\') {\n            node.left = new TreeNode(parseInt(parts[i].trim()));\n            queue.push(node.left);\n        }\n        i++;\n        if (i < parts.length && parts[i].trim() !== \'null\') {\n            node.right = new TreeNode(parseInt(parts[i].trim()));\n            queue.push(node.right);\n        }\n        i++;\n    }\n    return root;\n}\n\nfunction dfs(node) {\n    if (node === null) return 0;\n    const left = Math.max(0, dfs(node.left));\n    const right = Math.max(0, dfs(node.right));\n    maxSum = Math.max(maxSum, node.val + left + right);\n    return node.val + Math.max(left, right);\n}\n\nfunction maxPathSum(root) {\n    maxSum = -Infinity;\n    dfs(root);\n    return maxSum;\n}\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line.startsWith(\'[\')) line = line.substring(1);\n    if (line.endsWith(\']\')) line = line.substring(0, line.length - 1);\n\n    if (line.trim() === \'\') {\n        console.log(0);\n        rl.close();\n        return;\n    }\n\n    const parts = line.split(\',\');\n    const root = buildTree(parts);\n    maxPathSum(root);\n    console.log(maxSum);\n    rl.close();\n});',NULL,1),
(135,'PYTHON','import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(parts):\n    if not parts or parts[0].strip() == \"null\":\n        return None\n    root = TreeNode(int(parts[0].strip()))\n    queue = deque([root])\n    i = 1\n    while queue and i < len(parts):\n        node = queue.popleft()\n        if i < len(parts) and parts[i].strip() != \"null\":\n            node.left = TreeNode(int(parts[i].strip()))\n            queue.append(node.left)\n        i += 1\n        if i < len(parts) and parts[i].strip() != \"null\":\n            node.right = TreeNode(int(parts[i].strip()))\n            queue.append(node.right)\n        i += 1\n    return root\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line.startswith(\"[\"):\n        line = line[1:]\n    if line.endswith(\"]\"):\n        line = line[:-1]\n    if line.strip() == \"\":\n        print(0)\n        return\n    parts = line.split(\",\")\n    root = build_tree(parts)\n    max_sum = float(\"-inf\")\n    def dfs(node):\n        nonlocal max_sum\n        if node is None:\n            return 0\n        left = max(0, dfs(node.left))\n        right = max(0, dfs(node.right))\n        max_sum = max(max_sum, node.val + left + right)\n        return node.val + max(left, right)\n    dfs(root)\n    print(max_sum)\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(136,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <ctype.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\ntypedef struct {\n    TreeNode **data;\n    int front;\n    int rear;\n    int size;\n    int capacity;\n} Queue;\n\nQueue* createQueue(int capacity) {\n    Queue *q = (Queue*)malloc(sizeof(Queue));\n    q->data = (TreeNode**)malloc(sizeof(TreeNode*) * capacity);\n    q->front = 0;\n    q->rear = 0;\n    q->size = 0;\n    q->capacity = capacity;\n    return q;\n}\n\nvoid enqueue(Queue *q, TreeNode *node) {\n    if (q->size == q->capacity) {\n        q->capacity *= 2;\n        q->data = (TreeNode**)realloc(q->data, sizeof(TreeNode*) * q->capacity);\n    }\n    q->data[q->rear] = node;\n    q->rear = (q->rear + 1) % q->capacity;\n    q->size++;\n}\n\nTreeNode* dequeue(Queue *q) {\n    if (q->size == 0) return NULL;\n    TreeNode *node = q->data[q->front];\n    q->front = (q->front + 1) % q->capacity;\n    q->size--;\n    return node;\n}\n\nint isEmpty(Queue *q) {\n    return q->size == 0;\n}\n\nvoid freeQueue(Queue *q) {\n    free(q->data);\n    free(q);\n}\n\nTreeNode* buildTree(char **parts, int partsSize) {\n    if (partsSize == 0 || strcmp(parts[0], \"null\") == 0) return NULL;\n    TreeNode *root = (TreeNode*)malloc(sizeof(TreeNode));\n    root->val = atoi(parts[0]);\n    root->left = NULL;\n    root->right = NULL;\n    \n    Queue *q = createQueue(partsSize);\n    enqueue(q, root);\n    int i = 1;\n    while (!isEmpty(q) && i < partsSize) {\n        TreeNode *node = dequeue(q);\n        if (i < partsSize) {\n            char *leftVal = parts[i++];\n            if (strcmp(leftVal, \"null\") != 0) {\n                node->left = (TreeNode*)malloc(sizeof(TreeNode));\n                node->left->val = atoi(leftVal);\n                node->left->left = NULL;\n                node->left->right = NULL;\n                enqueue(q, node->left);\n            }\n        }\n        if (i < partsSize) {\n            char *rightVal = parts[i++];\n            if (strcmp(rightVal, \"null\") != 0) {\n                node->right = (TreeNode*)malloc(sizeof(TreeNode));\n                node->right->val = atoi(rightVal);\n                node->right->left = NULL;\n                node->right->right = NULL;\n                enqueue(q, node->right);\n            }\n        }\n    }\n    freeQueue(q);\n    return root;\n}\n\nint** zigzagLevelOrder(TreeNode *root, int *returnSize, int **returnColumnSizes) {\n    if (root == NULL) {\n        *returnSize = 0;\n        return NULL;\n    }\n    \n    int capacity = 100;\n    int **result = (int**)malloc(sizeof(int*) * capacity);\n    *returnColumnSizes = (int*)malloc(sizeof(int) * capacity);\n    *returnSize = 0;\n    \n    Queue *q = createQueue(1000);\n    enqueue(q, root);\n    int leftToRight = 1;\n    \n    while (!isEmpty(q)) {\n        int size = q->size;\n        int *level = (int*)malloc(sizeof(int) * size);\n        int idx = 0;\n        \n        for (int i = 0; i < size; i++) {\n            TreeNode *node = dequeue(q);\n            if (leftToRight) {\n                level[idx++] = node->val;\n            } else {\n                level[size - 1 - idx++] = node->val;\n            }\n            if (node->left) enqueue(q, node->left);\n            if (node->right) enqueue(q, node->right);\n        }\n        \n        if (*returnSize >= capacity) {\n            capacity *= 2;\n            result = (int**)realloc(result, sizeof(int*) * capacity);\n            *returnColumnSizes = (int*)realloc(*returnColumnSizes, sizeof(int) * capacity);\n        }\n        result[*returnSize] = level;\n        (*returnColumnSizes)[*returnSize] = size;\n        (*returnSize)++;\n        leftToRight = !leftToRight;\n    }\n    \n    freeQueue(q);\n    return result;\n}\n\nvoid freeTree(TreeNode *root) {\n    if (root == NULL) return;\n    freeTree(root->left);\n    freeTree(root->right);\n    free(root);\n}\n\nint main() {\n    char line[100000];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    \n    int len = strlen(line);\n    while (len > 0 && (line[len-1] == \'\\n\' || line[len-1] == \'\\r\')) {\n        line[--len] = \'\\0\';\n    }\n    \n    char *start = line;\n    while (*start && isspace(*start)) start++;\n    char *end = start + strlen(start) - 1;\n    while (end > start && isspace(*end)) end--;\n    *(end + 1) = \'\\0\';\n    \n    if (*start == \'[\') start++;\n    end = start + strlen(start) - 1;\n    if (*end == \']\') *end = \'\\0\';\n    \n    if (strlen(start) == 0) {\n        printf(\"[]\\n\");\n        return 0;\n    }\n    \n    char *parts[10000];\n    int partsSize = 0;\n    char *token = strtok(start, \",\");\n    while (token != NULL) {\n        while (*token && isspace(*token)) token++;\n        char *tend = token + strlen(token) - 1;\n        while (tend > token && isspace(*tend)) *tend-- = \'\\0\';\n        parts[partsSize++] = token;\n        token = strtok(NULL, \",\");\n    }\n    \n    TreeNode *root = buildTree(parts, partsSize);\n    \n    int returnSize;\n    int *returnColumnSizes;\n    int **result = zigzagLevelOrder(root, &returnSize, &returnColumnSizes);\n    \n    printf(\"[\");\n    for (int i = 0; i < returnSize; i++) {\n        printf(\"[\");\n        for (int j = 0; j < returnColumnSizes[i]; j++) {\n            printf(\"%d\", result[i][j]);\n            if (j < returnColumnSizes[i] - 1) printf(\",\");\n        }\n        printf(\"]\");\n        if (i < returnSize - 1) printf(\",\");\n    }\n    printf(\"]\\n\");\n    \n    for (int i = 0; i < returnSize; i++) {\n        free(result[i]);\n    }\n    free(result);\n    free(returnColumnSizes);\n    freeTree(root);\n    \n    return 0;\n}',NULL,1),
(136,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <queue>\n#include <sstream>\n#include <algorithm>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode *left;\n    TreeNode *right;\n    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(const vector<string>& parts) {\n    if (parts.empty() || parts[0] == \"null\") return nullptr;\n    TreeNode* root = new TreeNode(stoi(parts[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n    while (!q.empty() && i < (int)parts.size()) {\n        TreeNode* node = q.front();\n        q.pop();\n        if (i < (int)parts.size()) {\n            string leftVal = parts[i++];\n            if (leftVal != \"null\") {\n                node->left = new TreeNode(stoi(leftVal));\n                q.push(node->left);\n            }\n        }\n        if (i < (int)parts.size()) {\n            string rightVal = parts[i++];\n            if (rightVal != \"null\") {\n                node->right = new TreeNode(stoi(rightVal));\n                q.push(node->right);\n            }\n        }\n    }\n    return root;\n}\n\nvector<vector<int>> zigzagLevelOrder(TreeNode* root) {\n    vector<vector<int>> result;\n    if (!root) return result;\n    queue<TreeNode*> q;\n    q.push(root);\n    bool leftToRight = true;\n    while (!q.empty()) {\n        int size = q.size();\n        vector<int> level(size);\n        for (int i = 0; i < size; i++) {\n            TreeNode* node = q.front();\n            q.pop();\n            int index = leftToRight ? i : (size - 1 - i);\n            level[index] = node->val;\n            if (node->left) q.push(node->left);\n            if (node->right) q.push(node->right);\n        }\n        result.push_back(level);\n        leftToRight = !leftToRight;\n    }\n    return result;\n}\n\nstring format(const vector<vector<int>>& result) {\n    string sb = \"[\";\n    for (int i = 0; i < (int)result.size(); i++) {\n        sb += \"[\";\n        const vector<int>& level = result[i];\n        for (int j = 0; j < (int)level.size(); j++) {\n            sb += to_string(level[j]);\n            if (j < (int)level.size() - 1) sb += \",\";\n        }\n        sb += \"]\";\n        if (i < (int)result.size() - 1) sb += \",\";\n    }\n    sb += \"]\";\n    return sb;\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\' || line.back() == \' \')) {\n        line.pop_back();\n    }\n    size_t start = line.find_first_not_of(\" \\t\");\n    if (start != string::npos) line = line.substr(start);\n    if (!line.empty() && line.front() == \'[\') line = line.substr(1);\n    if (!line.empty() && line.back() == \']\') line.pop_back();\n    if (line.empty()) {\n        cout << \"[]\" << endl;\n        return 0;\n    }\n    vector<string> parts;\n    stringstream ss(line);\n    string token;\n    while (getline(ss, token, \',\')) {\n        size_t s = token.find_first_not_of(\" \\t\");\n        size_t e = token.find_last_not_of(\" \\t\");\n        if (s == string::npos) {\n            parts.push_back(\"\");\n        } else {\n            parts.push_back(token.substr(s, e - s + 1));\n        }\n    }\n    TreeNode* root = buildTree(parts);\n    vector<vector<int>> result = zigzagLevelOrder(root);\n    cout << format(result) << endl;\n    return 0;\n}',NULL,1),
(136,'JAVA','import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int x) { val = x; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        if (line.startsWith(\"[\")) line = line.substring(1);\n        if (line.endsWith(\"]\")) line = line.substring(0, line.length() - 1);\n        if (line.isEmpty()) {\n            System.out.println(\"[]\");\n            return;\n        }\n        String[] parts = line.split(\",\");\n        TreeNode root = buildTree(parts);\n        List<List<Integer>> result = zigzagLevelOrder(root);\n        System.out.println(format(result));\n    }\n\n    private static TreeNode buildTree(String[] parts) {\n        if (parts.length == 0 || parts[0].trim().equals(\"null\")) return null;\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n        while (!queue.isEmpty() && i < parts.length) {\n            TreeNode node = queue.poll();\n            if (i < parts.length) {\n                String leftVal = parts[i++].trim();\n                if (!leftVal.equals(\"null\")) {\n                    node.left = new TreeNode(Integer.parseInt(leftVal));\n                    queue.offer(node.left);\n                }\n            }\n            if (i < parts.length) {\n                String rightVal = parts[i++].trim();\n                if (!rightVal.equals(\"null\")) {\n                    node.right = new TreeNode(Integer.parseInt(rightVal));\n                    queue.offer(node.right);\n                }\n            }\n        }\n        return root;\n    }\n\n    private static List<List<Integer>> zigzagLevelOrder(TreeNode root) {\n        List<List<Integer>> result = new ArrayList<>();\n        if (root == null) return result;\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        boolean leftToRight = true;\n        while (!queue.isEmpty()) {\n            int size = queue.size();\n            LinkedList<Integer> level = new LinkedList<>();\n            for (int i = 0; i < size; i++) {\n                TreeNode node = queue.poll();\n                if (leftToRight) {\n                    level.addLast(node.val);\n                } else {\n                    level.addFirst(node.val);\n                }\n                if (node.left != null) queue.offer(node.left);\n                if (node.right != null) queue.offer(node.right);\n            }\n            result.add(level);\n            leftToRight = !leftToRight;\n        }\n        return result;\n    }\n\n    private static String format(List<List<Integer>> result) {\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < result.size(); i++) {\n            sb.append(\"[\");\n            List<Integer> level = result.get(i);\n            for (int j = 0; j < level.size(); j++) {\n                sb.append(level.get(j));\n                if (j < level.size() - 1) sb.append(\",\");\n            }\n            sb.append(\"]\");\n            if (i < result.size() - 1) sb.append(\",\");\n        }\n        sb.append(\"]\");\n        return sb.toString();\n    }\n}',NULL,1),
(136,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(parts) {\n    if (parts.length === 0 || parts[0].trim() === \'null\') return null;\n    const root = new TreeNode(parseInt(parts[0].trim()));\n    const queue = [root];\n    let i = 1;\n    while (queue.length > 0 && i < parts.length) {\n        const node = queue.shift();\n        if (i < parts.length) {\n            const leftVal = parts[i++].trim();\n            if (leftVal !== \'null\') {\n                node.left = new TreeNode(parseInt(leftVal));\n                queue.push(node.left);\n            }\n        }\n        if (i < parts.length) {\n            const rightVal = parts[i++].trim();\n            if (rightVal !== \'null\') {\n                node.right = new TreeNode(parseInt(rightVal));\n                queue.push(node.right);\n            }\n        }\n    }\n    return root;\n}\n\nfunction zigzagLevelOrder(root) {\n    const result = [];\n    if (root === null) return result;\n    const queue = [root];\n    let leftToRight = true;\n    while (queue.length > 0) {\n        const size = queue.length;\n        const level = [];\n        for (let i = 0; i < size; i++) {\n            const node = queue.shift();\n            if (leftToRight) {\n                level.push(node.val);\n            } else {\n                level.unshift(node.val);\n            }\n            if (node.left !== null) queue.push(node.left);\n            if (node.right !== null) queue.push(node.right);\n        }\n        result.push(level);\n        leftToRight = !leftToRight;\n    }\n    return result;\n}\n\nfunction format(result) {\n    let sb = \'\';\n    sb += \'[\';\n    for (let i = 0; i < result.length; i++) {\n        sb += \'[\';\n        const level = result[i];\n        for (let j = 0; j < level.length; j++) {\n            sb += level[j];\n            if (j < level.length - 1) sb += \',\';\n        }\n        sb += \']\';\n        if (i < result.length - 1) sb += \',\';\n    }\n    sb += \']\';\n    return sb;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    line = line.trim();\n    if (line.startsWith(\'[\')) line = line.substring(1);\n    if (line.endsWith(\']\')) line = line.substring(0, line.length - 1);\n    if (line.length === 0) {\n        console.log(\'[]\');\n        rl.close();\n        return;\n    }\n    const parts = line.split(\',\');\n    const root = buildTree(parts);\n    const result = zigzagLevelOrder(root);\n    console.log(format(result));\n    rl.close();\n});',NULL,1),
(136,'PYTHON','import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, x):\n        self.val = x\n        self.left = None\n        self.right = None\n\ndef build_tree(parts):\n    if not parts or parts[0].strip() == \"null\":\n        return None\n    root = TreeNode(int(parts[0].strip()))\n    queue = deque([root])\n    i = 1\n    while queue and i < len(parts):\n        node = queue.popleft()\n        if i < len(parts):\n            left_val = parts[i].strip()\n            i += 1\n            if left_val != \"null\":\n                node.left = TreeNode(int(left_val))\n                queue.append(node.left)\n        if i < len(parts):\n            right_val = parts[i].strip()\n            i += 1\n            if right_val != \"null\":\n                node.right = TreeNode(int(right_val))\n                queue.append(node.right)\n    return root\n\ndef zigzag_level_order(root):\n    result = []\n    if root is None:\n        return result\n    queue = deque([root])\n    left_to_right = True\n    while queue:\n        size = len(queue)\n        level = deque()\n        for _ in range(size):\n            node = queue.popleft()\n            if left_to_right:\n                level.append(node.val)\n            else:\n                level.appendleft(node.val)\n            if node.left:\n                queue.append(node.left)\n            if node.right:\n                queue.append(node.right)\n        result.append(list(level))\n        left_to_right = not left_to_right\n    return result\n\ndef format_result(result):\n    sb = []\n    sb.append(\"[\")\n    for i, level in enumerate(result):\n        sb.append(\"[\")\n        for j, val in enumerate(level):\n            sb.append(str(val))\n            if j < len(level) - 1:\n                sb.append(\",\")\n        sb.append(\"]\")\n        if i < len(result) - 1:\n            sb.append(\",\")\n    sb.append(\"]\")\n    return \"\".join(sb)\n\ndef main():\n    line = sys.stdin.readline().strip()\n    if line.startswith(\"[\"):\n        line = line[1:]\n    if line.endswith(\"]\"):\n        line = line[:-1]\n    if not line:\n        print(\"[]\")\n        return\n    parts = line.split(\",\")\n    root = build_tree(parts)\n    result = zigzag_level_order(root)\n    print(format_result(result))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(137,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <ctype.h>\n\ntypedef struct TreeNode {\n    int val;\n    struct TreeNode *left;\n    struct TreeNode *right;\n} TreeNode;\n\nstatic TreeNode* newTreeNode(int val) {\n    TreeNode* node = (TreeNode*)malloc(sizeof(TreeNode));\n    node->val = val;\n    node->left = NULL;\n    node->right = NULL;\n    return node;\n}\n\nstatic char* trim(char* s) {\n    while (*s && isspace((unsigned char)*s)) s++;\n    if (*s == \'\\0\') return s;\n    char* end = s + strlen(s) - 1;\n    while (end > s && isspace((unsigned char)*end)) {\n        *end = \'\\0\';\n        end--;\n    }\n    return s;\n}\n\nstatic TreeNode* buildTree(char* line) {\n    if (line == NULL) return NULL;\n    line = trim(line);\n    if (*line == \'\\0\') return NULL;\n\n    if (line[0] == \'[\') line++;\n    size_t len = strlen(line);\n    if (len > 0 && line[len - 1] == \']\') line[len - 1] = \'\\0\';\n    line = trim(line);\n    if (*line == \'\\0\') return NULL;\n\n    char* parts[10000];\n    int count = 0;\n    char* token = strtok(line, \",\");\n    while (token != NULL && count < 10000) {\n        parts[count++] = trim(token);\n        token = strtok(NULL, \",\");\n    }\n\n    if (count == 0 || strcmp(parts[0], \"null\") == 0) return NULL;\n\n    TreeNode* root = newTreeNode(atoi(parts[0]));\n    TreeNode* queue[10000];\n    int front = 0, rear = 0;\n    queue[rear++] = root;\n    int i = 1;\n\n    while (front < rear && i < count) {\n        TreeNode* cur = queue[front++];\n\n        if (i < count) {\n            char* leftVal = parts[i++];\n            if (strcmp(leftVal, \"null\") != 0) {\n                cur->left = newTreeNode(atoi(leftVal));\n                queue[rear++] = cur->left;\n            }\n        }\n\n        if (i < count) {\n            char* rightVal = parts[i++];\n            if (strcmp(rightVal, \"null\") != 0) {\n                cur->right = newTreeNode(atoi(rightVal));\n                queue[rear++] = cur->right;\n            }\n        }\n    }\n\n    return root;\n}\n\nstatic int kthSmallest(TreeNode* root, int k) {\n    TreeNode* stack[10000];\n    int top = 0;\n    TreeNode* cur = root;\n\n    while (cur != NULL || top > 0) {\n        while (cur != NULL) {\n            stack[top++] = cur;\n            cur = cur->left;\n        }\n        cur = stack[--top];\n        k--;\n        if (k == 0) return cur->val;\n        cur = cur->right;\n    }\n\n    return -1;\n}\n\nint main(void) {\n    char line[100000];\n    int k;\n\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    line[strcspn(line, \"\\r\\n\")] = \'\\0\';\n\n    if (scanf(\"%d\", &k) != 1) return 0;\n\n    TreeNode* root = buildTree(line);\n    printf(\"%d\\n\", kthSmallest(root, k));\n\n    return 0;\n}',NULL,1),
(137,'CPP','#include <iostream>\n#include <string>\n#include <sstream>\n#include <vector>\n#include <queue>\n#include <stack>\n\nusing namespace std;\n\nstruct TreeNode {\n    int val;\n    TreeNode* left;\n    TreeNode* right;\n    TreeNode(int v) : val(v), left(nullptr), right(nullptr) {}\n};\n\nTreeNode* buildTree(const string& line) {\n    if (line.empty()) return nullptr;\n    string s = line;\n    size_t start = s.find_first_not_of(\" \\t\");\n    size_t end = s.find_last_not_of(\" \\t\");\n    if (start == string::npos) return nullptr;\n    s = s.substr(start, end - start + 1);\n    if (s.front() == \'[\') s = s.substr(1);\n    if (s.back() == \']\') s.pop_back();\n    if (s.empty()) return nullptr;\n\n    vector<string> parts;\n    stringstream ss(s);\n    string token;\n    while (getline(ss, token, \',\')) {\n        size_t l = token.find_first_not_of(\" \\t\");\n        size_t r = token.find_last_not_of(\" \\t\");\n        if (l == string::npos) parts.push_back(\"\");\n        else parts.push_back(token.substr(l, r - l + 1));\n    }\n\n    if (parts.empty() || parts[0] == \"null\") return nullptr;\n\n    TreeNode* root = new TreeNode(stoi(parts[0]));\n    queue<TreeNode*> q;\n    q.push(root);\n    int i = 1;\n\n    while (!q.empty() && i < (int)parts.size()) {\n        TreeNode* cur = q.front();\n        q.pop();\n\n        if (i < (int)parts.size()) {\n            string leftVal = parts[i++];\n            if (leftVal != \"null\") {\n                cur->left = new TreeNode(stoi(leftVal));\n                q.push(cur->left);\n            }\n        }\n\n        if (i < (int)parts.size()) {\n            string rightVal = parts[i++];\n            if (rightVal != \"null\") {\n                cur->right = new TreeNode(stoi(rightVal));\n                q.push(cur->right);\n            }\n        }\n    }\n\n    return root;\n}\n\nint kthSmallest(TreeNode* root, int k) {\n    stack<TreeNode*> st;\n    TreeNode* cur = root;\n\n    while (cur != nullptr || !st.empty()) {\n        while (cur != nullptr) {\n            st.push(cur);\n            cur = cur->left;\n        }\n        cur = st.top();\n        st.pop();\n        k--;\n        if (k == 0) return cur->val;\n        cur = cur->right;\n    }\n\n    return -1;\n}\n\nint main() {\n    string line;\n    getline(cin, line);\n    int k;\n    cin >> k;\n\n    TreeNode* root = buildTree(line);\n    cout << kthSmallest(root, k) << endl;\n\n    return 0;\n}',NULL,1),
(137,'JAVA','import java.util.*;\n\npublic class Main {\n    static class TreeNode {\n        int val;\n        TreeNode left;\n        TreeNode right;\n        TreeNode(int val) { this.val = val; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line = sc.nextLine().trim();\n        int k = Integer.parseInt(sc.nextLine().trim());\n\n        TreeNode root = buildTree(line);\n        System.out.println(kthSmallest(root, k));\n    }\n\n    private static TreeNode buildTree(String line) {\n        if (line == null || line.length() == 0) return null;\n        line = line.trim();\n        if (line.startsWith(\"[\")) line = line.substring(1);\n        if (line.endsWith(\"]\")) line = line.substring(0, line.length() - 1);\n        if (line.trim().isEmpty()) return null;\n\n        String[] parts = line.split(\",\");\n        if (parts.length == 0 || parts[0].trim().equals(\"null\")) return null;\n\n        TreeNode root = new TreeNode(Integer.parseInt(parts[0].trim()));\n        Queue<TreeNode> queue = new LinkedList<>();\n        queue.offer(root);\n        int i = 1;\n\n        while (!queue.isEmpty() && i < parts.length) {\n            TreeNode cur = queue.poll();\n\n            if (i < parts.length) {\n                String leftVal = parts[i].trim();\n                i++;\n                if (!leftVal.equals(\"null\")) {\n                    cur.left = new TreeNode(Integer.parseInt(leftVal));\n                    queue.offer(cur.left);\n                }\n            }\n\n            if (i < parts.length) {\n                String rightVal = parts[i].trim();\n                i++;\n                if (!rightVal.equals(\"null\")) {\n                    cur.right = new TreeNode(Integer.parseInt(rightVal));\n                    queue.offer(cur.right);\n                }\n            }\n        }\n\n        return root;\n    }\n\n    private static int kthSmallest(TreeNode root, int k) {\n        Deque<TreeNode> stack = new ArrayDeque<>();\n        TreeNode cur = root;\n\n        while (cur != null || !stack.isEmpty()) {\n            while (cur != null) {\n                stack.push(cur);\n                cur = cur.left;\n            }\n            cur = stack.pop();\n            k--;\n            if (k == 0) return cur.val;\n            cur = cur.right;\n        }\n\n        return -1;\n    }\n}',NULL,1),
(137,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass TreeNode {\n    constructor(val) {\n        this.val = val;\n        this.left = null;\n        this.right = null;\n    }\n}\n\nfunction buildTree(line) {\n    if (line === null || line.length === 0) return null;\n    line = line.trim();\n    if (line.startsWith(\'[\')) line = line.substring(1);\n    if (line.endsWith(\']\')) line = line.substring(0, line.length - 1);\n    if (line.trim().length === 0) return null;\n\n    const parts = line.split(\',\');\n    if (parts.length === 0 || parts[0].trim() === \'null\') return null;\n\n    const root = new TreeNode(parseInt(parts[0].trim()));\n    const queue = [root];\n    let i = 1;\n\n    while (queue.length > 0 && i < parts.length) {\n        const cur = queue.shift();\n\n        if (i < parts.length) {\n            const leftVal = parts[i].trim();\n            i++;\n            if (leftVal !== \'null\') {\n                cur.left = new TreeNode(parseInt(leftVal));\n                queue.push(cur.left);\n            }\n        }\n\n        if (i < parts.length) {\n            const rightVal = parts[i].trim();\n            i++;\n            if (rightVal !== \'null\') {\n                cur.right = new TreeNode(parseInt(rightVal));\n                queue.push(cur.right);\n            }\n        }\n    }\n\n    return root;\n}\n\nfunction kthSmallest(root, k) {\n    const stack = [];\n    let cur = root;\n\n    while (cur !== null || stack.length > 0) {\n        while (cur !== null) {\n            stack.push(cur);\n            cur = cur.left;\n        }\n        cur = stack.pop();\n        k--;\n        if (k === 0) return cur.val;\n        cur = cur.right;\n    }\n\n    return -1;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n    if (lines.length === 2) {\n        const treeLine = lines[0].trim();\n        const k = parseInt(lines[1].trim());\n        const root = buildTree(treeLine);\n        console.log(kthSmallest(root, k));\n        rl.close();\n    }\n});',NULL,1),
(137,'PYTHON','import sys\nfrom collections import deque\n\nclass TreeNode:\n    def __init__(self, val):\n        self.val = val\n        self.left = None\n        self.right = None\n\ndef build_tree(line):\n    if line is None or len(line) == 0:\n        return None\n    line = line.strip()\n    if line.startswith(\"[\"):\n        line = line[1:]\n    if line.endswith(\"]\"):\n        line = line[:-1]\n    if line.strip() == \"\":\n        return None\n\n    parts = line.split(\",\")\n    if len(parts) == 0 or parts[0].strip() == \"null\":\n        return None\n\n    root = TreeNode(int(parts[0].strip()))\n    queue = deque([root])\n    i = 1\n\n    while queue and i < len(parts):\n        cur = queue.popleft()\n\n        if i < len(parts):\n            left_val = parts[i].strip()\n            i += 1\n            if left_val != \"null\":\n                cur.left = TreeNode(int(left_val))\n                queue.append(cur.left)\n\n        if i < len(parts):\n            right_val = parts[i].strip()\n            i += 1\n            if right_val != \"null\":\n                cur.right = TreeNode(int(right_val))\n                queue.append(cur.right)\n\n    return root\n\ndef kth_smallest(root, k):\n    stack = []\n    cur = root\n\n    while cur is not None or stack:\n        while cur is not None:\n            stack.append(cur)\n            cur = cur.left\n        cur = stack.pop()\n        k -= 1\n        if k == 0:\n            return cur.val\n        cur = cur.right\n\n    return -1\n\ndef main():\n    line = sys.stdin.readline().strip()\n    k = int(sys.stdin.readline().strip())\n    root = build_tree(line)\n    print(kth_smallest(root, k))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(138,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    int n, k;\n    scanf(\"%d %d\", &n, &k);\n    int *nums = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    int *deque = (int *)malloc(n * sizeof(int));\n    int head = 0, tail = 0;\n    int *result = (int *)malloc((n - k + 1) * sizeof(int));\n    int idx = 0;\n\n    for (int i = 0; i < n; i++) {\n        while (head < tail && deque[head] < i - k + 1) {\n            head++;\n        }\n        while (head < tail && nums[deque[tail - 1]] < nums[i]) {\n            tail--;\n        }\n        deque[tail++] = i;\n        if (i >= k - 1) {\n            result[idx++] = nums[deque[head]];\n        }\n    }\n\n    printf(\"[\");\n    for (int i = 0; i < idx; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"%d\", result[i]);\n    }\n    printf(\"]\\n\");\n\n    free(nums);\n    free(deque);\n    free(result);\n    return 0;\n}',NULL,1),
(138,'CPP','#include <iostream>\n#include <vector>\n#include <deque>\nusing namespace std;\n\nint main() {\n    int n, k;\n    cin >> n >> k;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n\n    deque<int> dq;\n    vector<int> result(n - k + 1);\n    int idx = 0;\n\n    for (int i = 0; i < n; i++) {\n        while (!dq.empty() && dq.front() < i - k + 1) {\n            dq.pop_front();\n        }\n        while (!dq.empty() && nums[dq.back()] < nums[i]) {\n            dq.pop_back();\n        }\n        dq.push_back(i);\n        if (i >= k - 1) {\n            result[idx++] = nums[dq.front()];\n        }\n    }\n\n    cout << \"[\";\n    for (int i = 0; i < (int)result.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << result[i];\n    }\n    cout << \"]\" << endl;\n\n    return 0;\n}',NULL,1),
(138,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int k = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n\n        Deque<Integer> deque = new ArrayDeque<>();\n        int[] result = new int[n - k + 1];\n        int idx = 0;\n\n        for (int i = 0; i < n; i++) {\n            while (!deque.isEmpty() && deque.peekFirst() < i - k + 1) {\n                deque.pollFirst();\n            }\n            while (!deque.isEmpty() && nums[deque.peekLast()] < nums[i]) {\n                deque.pollLast();\n            }\n            deque.offerLast(i);\n            if (i >= k - 1) {\n                result[idx++] = nums[deque.peekFirst()];\n            }\n        }\n\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < result.length; i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(result[i]);\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n}',NULL,1),
(138,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const [n, k] = lines[0].split(\' \').map(Number);\n    const nums = lines[1].split(\' \').map(Number);\n\n    const deque = [];\n    const result = [];\n\n    for (let i = 0; i < n; i++) {\n        while (deque.length > 0 && deque[0] < i - k + 1) {\n            deque.shift();\n        }\n        while (deque.length > 0 && nums[deque[deque.length - 1]] < nums[i]) {\n            deque.pop();\n        }\n        deque.push(i);\n        if (i >= k - 1) {\n            result.push(nums[deque[0]]);\n        }\n    }\n\n    console.log(\'[\' + result.join(\',\') + \']\');\n});',NULL,1),
(138,'PYTHON','import sys\nfrom collections import deque\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    k = int(data[1])\n    nums = list(map(int, data[2:2 + n]))\n\n    dq = deque()\n    result = []\n\n    for i in range(n):\n        while dq and dq[0] < i - k + 1:\n            dq.popleft()\n        while dq and nums[dq[-1]] < nums[i]:\n            dq.pop()\n        dq.append(i)\n        if i >= k - 1:\n            result.append(nums[dq[0]])\n\n    print(\"[\" + \",\".join(map(str, result)) + \"]\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(139,'C','#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct {\n    int *data;\n    int size;\n    int capacity;\n} Heap;\n\nvoid heapInit(Heap *h, int capacity) {\n    h->data = (int *)malloc(sizeof(int) * capacity);\n    h->size = 0;\n    h->capacity = capacity;\n}\n\nvoid heapPush(Heap *h, int value) {\n    int i = h->size++;\n    h->data[i] = value;\n    while (i > 0) {\n        int parent = (i - 1) / 2;\n        if (h->data[parent] <= h->data[i]) break;\n        int tmp = h->data[parent];\n        h->data[parent] = h->data[i];\n        h->data[i] = tmp;\n        i = parent;\n    }\n}\n\nint heapPop(Heap *h) {\n    int result = h->data[0];\n    h->data[0] = h->data[--h->size];\n    int i = 0;\n    while (1) {\n        int left = i * 2 + 1;\n        int right = i * 2 + 2;\n        int smallest = i;\n        if (left < h->size && h->data[left] < h->data[smallest]) smallest = left;\n        if (right < h->size && h->data[right] < h->data[smallest]) smallest = right;\n        if (smallest == i) break;\n        int tmp = h->data[i];\n        h->data[i] = h->data[smallest];\n        h->data[smallest] = tmp;\n        i = smallest;\n    }\n    return result;\n}\n\nint main() {\n    int numCourses, m;\n    scanf(\"%d\", &numCourses);\n    scanf(\"%d\", &m);\n\n    int **graph = (int **)malloc(sizeof(int *) * numCourses);\n    int *graphSize = (int *)calloc(numCourses, sizeof(int));\n    int *graphCap = (int *)calloc(numCourses, sizeof(int));\n    for (int i = 0; i < numCourses; i++) {\n        graphCap[i] = 4;\n        graph[i] = (int *)malloc(sizeof(int) * graphCap[i]);\n    }\n\n    int *indegree = (int *)calloc(numCourses, sizeof(int));\n\n    for (int i = 0; i < m; i++) {\n        int ai, bi;\n        scanf(\"%d %d\", &ai, &bi);\n        if (graphSize[bi] == graphCap[bi]) {\n            graphCap[bi] *= 2;\n            graph[bi] = (int *)realloc(graph[bi], sizeof(int) * graphCap[bi]);\n        }\n        graph[bi][graphSize[bi]++] = ai;\n        indegree[ai]++;\n    }\n\n    Heap pq;\n    heapInit(&pq, numCourses);\n    for (int i = 0; i < numCourses; i++) {\n        if (indegree[i] == 0) {\n            heapPush(&pq, i);\n        }\n    }\n\n    int *order = (int *)malloc(sizeof(int) * numCourses);\n    int orderSize = 0;\n\n    while (pq.size > 0) {\n        int cur = heapPop(&pq);\n        order[orderSize++] = cur;\n        for (int i = 0; i < graphSize[cur]; i++) {\n            int next = graph[cur][i];\n            indegree[next]--;\n            if (indegree[next] == 0) {\n                heapPush(&pq, next);\n            }\n        }\n    }\n\n    if (orderSize != numCourses) {\n        printf(\"[]\\n\");\n    } else {\n        for (int i = 0; i < orderSize; i++) {\n            if (i > 0) printf(\" \");\n            printf(\"%d\", order[i]);\n        }\n        printf(\"\\n\");\n    }\n\n    for (int i = 0; i < numCourses; i++) {\n        free(graph[i]);\n    }\n    free(graph);\n    free(graphSize);\n    free(graphCap);\n    free(indegree);\n    free(order);\n    free(pq.data);\n\n    return 0;\n}',NULL,1),
(139,'CPP','#include <iostream>\n#include <vector>\n#include <queue>\nusing namespace std;\n\nint main() {\n    int numCourses, m;\n    cin >> numCourses >> m;\n\n    vector<vector<int>> graph(numCourses);\n    vector<int> indegree(numCourses, 0);\n\n    for (int i = 0; i < m; i++) {\n        int ai, bi;\n        cin >> ai >> bi;\n        graph[bi].push_back(ai);\n        indegree[ai]++;\n    }\n\n    priority_queue<int, vector<int>, greater<int>> pq;\n    for (int i = 0; i < numCourses; i++) {\n        if (indegree[i] == 0) {\n            pq.push(i);\n        }\n    }\n\n    vector<int> order;\n    while (!pq.empty()) {\n        int cur = pq.top();\n        pq.pop();\n        order.push_back(cur);\n        for (int next : graph[cur]) {\n            indegree[next]--;\n            if (indegree[next] == 0) {\n                pq.push(next);\n            }\n        }\n    }\n\n    if ((int)order.size() != numCourses) {\n        cout << \"[]\" << endl;\n    } else {\n        for (int i = 0; i < (int)order.size(); i++) {\n            if (i > 0) cout << \' \';\n            cout << order[i];\n        }\n        cout << endl;\n    }\n\n    return 0;\n}',NULL,1),
(139,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int numCourses = sc.nextInt();\n        int m = sc.nextInt();\n\n        List<List<Integer>> graph = new ArrayList<>();\n        for (int i = 0; i < numCourses; i++) {\n            graph.add(new ArrayList<>());\n        }\n\n        int[] indegree = new int[numCourses];\n\n        for (int i = 0; i < m; i++) {\n            int ai = sc.nextInt();\n            int bi = sc.nextInt();\n            graph.get(bi).add(ai);\n            indegree[ai]++;\n        }\n\n        PriorityQueue<Integer> pq = new PriorityQueue<>();\n        for (int i = 0; i < numCourses; i++) {\n            if (indegree[i] == 0) {\n                pq.offer(i);\n            }\n        }\n\n        List<Integer> order = new ArrayList<>();\n        while (!pq.isEmpty()) {\n            int cur = pq.poll();\n            order.add(cur);\n            for (int next : graph.get(cur)) {\n                indegree[next]--;\n                if (indegree[next] == 0) {\n                    pq.offer(next);\n                }\n            }\n        }\n\n        if (order.size() != numCourses) {\n            System.out.println(\"[]\");\n        } else {\n            StringBuilder sb = new StringBuilder();\n            for (int i = 0; i < order.size(); i++) {\n                if (i > 0) sb.append(\' \');\n                sb.append(order.get(i));\n            }\n            System.out.println(sb.toString());\n        }\n    }\n}',NULL,1),
(139,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    let idx = 0;\n    const numCourses = parseInt(lines[idx++]);\n    const m = parseInt(lines[idx++]);\n\n    const graph = Array.from({ length: numCourses }, () => []);\n    const indegree = new Array(numCourses).fill(0);\n\n    for (let i = 0; i < m; i++) {\n        const parts = lines[idx++].split(/\\s+/).map(Number);\n        const ai = parts[0];\n        const bi = parts[1];\n        graph[bi].push(ai);\n        indegree[ai]++;\n    }\n\n    const pq = [];\n    const push = (x) => {\n        pq.push(x);\n        let i = pq.length - 1;\n        while (i > 0) {\n            const p = (i - 1) >> 1;\n            if (pq[p] <= pq[i]) break;\n            [pq[p], pq[i]] = [pq[i], pq[p]];\n            i = p;\n        }\n    };\n    const pop = () => {\n        const top = pq[0];\n        const last = pq.pop();\n        if (pq.length > 0) {\n            pq[0] = last;\n            let i = 0;\n            const n = pq.length;\n            while (true) {\n                let smallest = i;\n                const l = 2 * i + 1;\n                const r = 2 * i + 2;\n                if (l < n && pq[l] < pq[smallest]) smallest = l;\n                if (r < n && pq[r] < pq[smallest]) smallest = r;\n                if (smallest === i) break;\n                [pq[i], pq[smallest]] = [pq[smallest], pq[i]];\n                i = smallest;\n            }\n        }\n        return top;\n    };\n\n    for (let i = 0; i < numCourses; i++) {\n        if (indegree[i] === 0) {\n            push(i);\n        }\n    }\n\n    const order = [];\n    while (pq.length > 0) {\n        const cur = pop();\n        order.push(cur);\n        for (const next of graph[cur]) {\n            indegree[next]--;\n            if (indegree[next] === 0) {\n                push(next);\n            }\n        }\n    }\n\n    if (order.length !== numCourses) {\n        console.log(\"[]\");\n    } else {\n        console.log(order.join(\' \'));\n    }\n});',NULL,1),
(139,'PYTHON','import sys\nimport heapq\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    it = iter(data)\n    numCourses = int(next(it))\n    m = int(next(it))\n\n    graph = [[] for _ in range(numCourses)]\n    indegree = [0] * numCourses\n\n    for _ in range(m):\n        ai = int(next(it))\n        bi = int(next(it))\n        graph[bi].append(ai)\n        indegree[ai] += 1\n\n    pq = []\n    for i in range(numCourses):\n        if indegree[i] == 0:\n            heapq.heappush(pq, i)\n\n    order = []\n    while pq:\n        cur = heapq.heappop(pq)\n        order.append(cur)\n        for nxt in graph[cur]:\n            indegree[nxt] -= 1\n            if indegree[nxt] == 0:\n                heapq.heappush(pq, nxt)\n\n    if len(order) != numCourses:\n        print(\"[]\")\n    else:\n        print(\" \".join(map(str, order)))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(140,'C','#include <stdio.h>\n#include <string.h>\n\nint main() {\n    char s[100005];\n    if (scanf(\"%s\", s) != 1) return 0;\n    int n = strlen(s);\n    int dp[100005] = {0};\n    int max = 0;\n    for (int i = 1; i < n; i++) {\n        if (s[i] == \')\') {\n            if (s[i - 1] == \'(\') {\n                dp[i] = (i >= 2 ? dp[i - 2] : 0) + 2;\n            } else if (i - dp[i - 1] > 0 && s[i - dp[i - 1] - 1] == \'(\') {\n                dp[i] = dp[i - 1] + ((i - dp[i - 1] >= 2) ? dp[i - dp[i - 1] - 2] : 0) + 2;\n            }\n            if (dp[i] > max) max = dp[i];\n        }\n    }\n    printf(\"%d\\n\", max);\n    return 0;\n}',NULL,1),
(140,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    string s;\n    getline(cin, s);\n    int n = s.length();\n    vector<int> dp(n, 0);\n    int maxLen = 0;\n    for (int i = 1; i < n; i++) {\n        if (s[i] == \')\') {\n            if (s[i - 1] == \'(\') {\n                dp[i] = (i >= 2 ? dp[i - 2] : 0) + 2;\n            } else if (i - dp[i - 1] > 0 && s[i - dp[i - 1] - 1] == \'(\') {\n                dp[i] = dp[i - 1] + ((i - dp[i - 1] >= 2) ? dp[i - dp[i - 1] - 2] : 0) + 2;\n            }\n            maxLen = max(maxLen, dp[i]);\n        }\n    }\n    cout << maxLen << endl;\n    return 0;\n}',NULL,1),
(140,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.nextLine();\n        int n = s.length();\n        int[] dp = new int[n];\n        int max = 0;\n        for (int i = 1; i < n; i++) {\n            if (s.charAt(i) == \')\') {\n                if (s.charAt(i - 1) == \'(\') {\n                    dp[i] = (i >= 2 ? dp[i - 2] : 0) + 2;\n                } else if (i - dp[i - 1] > 0 && s.charAt(i - dp[i - 1] - 1) == \'(\') {\n                    dp[i] = dp[i - 1] + ((i - dp[i - 1] >= 2) ? dp[i - dp[i - 1] - 2] : 0) + 2;\n                }\n                max = Math.max(max, dp[i]);\n            }\n        }\n        System.out.println(max);\n    }\n}',NULL,1),
(140,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (s) => {\n    const n = s.length;\n    const dp = new Array(n).fill(0);\n    let max = 0;\n    for (let i = 1; i < n; i++) {\n        if (s[i] === \')\') {\n            if (s[i - 1] === \'(\') {\n                dp[i] = (i >= 2 ? dp[i - 2] : 0) + 2;\n            } else if (i - dp[i - 1] > 0 && s[i - dp[i - 1] - 1] === \'(\') {\n                dp[i] = dp[i - 1] + ((i - dp[i - 1] >= 2) ? dp[i - dp[i - 1] - 2] : 0) + 2;\n            }\n            max = Math.max(max, dp[i]);\n        }\n    }\n    console.log(max);\n    rl.close();\n});',NULL,1),
(140,'PYTHON','s = input()\nn = len(s)\ndp = [0] * n\nmax_len = 0\nfor i in range(1, n):\n    if s[i] == \')\':\n        if s[i - 1] == \'(\':\n            dp[i] = (dp[i - 2] if i >= 2 else 0) + 2\n        elif i - dp[i - 1] > 0 and s[i - dp[i - 1] - 1] == \'(\':\n            dp[i] = dp[i - 1] + (dp[i - dp[i - 1] - 2] if i - dp[i - 1] >= 2 else 0) + 2\n        max_len = max(max_len, dp[i])\nprint(max_len)',NULL,1),
(141,'C','#include <stdio.h>\n#include <stdbool.h>\n\nint count = 0;\nint n;\n\nvoid dfs(int row, bool col[], bool diag1[], bool diag2[]) {\n    if (row == n) {\n        count++;\n        return;\n    }\n    for (int c = 0; c < n; c++) {\n        int d1 = row + c;\n        int d2 = row - c + n;\n        if (!col[c] && !diag1[d1] && !diag2[d2]) {\n            col[c] = true;\n            diag1[d1] = true;\n            diag2[d2] = true;\n            dfs(row + 1, col, diag1, diag2);\n            col[c] = false;\n            diag1[d1] = false;\n            diag2[d2] = false;\n        }\n    }\n}\n\nint main() {\n    scanf(\"%d\", &n);\n    bool col[n];\n    bool diag1[2 * n];\n    bool diag2[2 * n];\n    for (int i = 0; i < n; i++) col[i] = false;\n    for (int i = 0; i < 2 * n; i++) {\n        diag1[i] = false;\n        diag2[i] = false;\n    }\n    dfs(0, col, diag1, diag2);\n    printf(\"%d\\n\", count);\n    return 0;\n}',NULL,1),
(141,'CPP','#include <iostream>\nusing namespace std;\n\nint count = 0;\nint n;\nbool col[20];\nbool diag1[40];\nbool diag2[40];\n\nvoid dfs(int row) {\n    if (row == n) {\n        count++;\n        return;\n    }\n    for (int c = 0; c < n; c++) {\n        int d1 = row + c;\n        int d2 = row - c + n;\n        if (!col[c] && !diag1[d1] && !diag2[d2]) {\n            col[c] = true;\n            diag1[d1] = true;\n            diag2[d2] = true;\n            dfs(row + 1);\n            col[c] = false;\n            diag1[d1] = false;\n            diag2[d2] = false;\n        }\n    }\n}\n\nint main() {\n    cin >> n;\n    dfs(0);\n    cout << count << endl;\n    return 0;\n}',NULL,1),
(141,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    static int count = 0;\n    static int n;\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        n = sc.nextInt();\n        boolean[] col = new boolean[n];\n        boolean[] diag1 = new boolean[2 * n];\n        boolean[] diag2 = new boolean[2 * n];\n        dfs(0, col, diag1, diag2);\n        System.out.println(count);\n    }\n\n    static void dfs(int row, boolean[] col, boolean[] diag1, boolean[] diag2) {\n        if (row == n) {\n            count++;\n            return;\n        }\n        for (int c = 0; c < n; c++) {\n            int d1 = row + c;\n            int d2 = row - c + n;\n            if (!col[c] && !diag1[d1] && !diag2[d2]) {\n                col[c] = true;\n                diag1[d1] = true;\n                diag2[d2] = true;\n                dfs(row + 1, col, diag1, diag2);\n                col[c] = false;\n                diag1[d1] = false;\n                diag2[d2] = false;\n            }\n        }\n    }\n}',NULL,1),
(141,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet n;\nlet count = 0;\n\nrl.on(\'line\', (line) => {\n    n = parseInt(line.trim());\n    const col = new Array(n).fill(false);\n    const diag1 = new Array(2 * n).fill(false);\n    const diag2 = new Array(2 * n).fill(false);\n    dfs(0, col, diag1, diag2);\n    console.log(count);\n    rl.close();\n});\n\nfunction dfs(row, col, diag1, diag2) {\n    if (row === n) {\n        count++;\n        return;\n    }\n    for (let c = 0; c < n; c++) {\n        const d1 = row + c;\n        const d2 = row - c + n;\n        if (!col[c] && !diag1[d1] && !diag2[d2]) {\n            col[c] = true;\n            diag1[d1] = true;\n            diag2[d2] = true;\n            dfs(row + 1, col, diag1, diag2);\n            col[c] = false;\n            diag1[d1] = false;\n            diag2[d2] = false;\n        }\n    }\n}',NULL,1),
(141,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    count = 0\n    col = [False] * n\n    diag1 = [False] * (2 * n)\n    diag2 = [False] * (2 * n)\n\n    def dfs(row):\n        nonlocal count\n        if row == n:\n            count += 1\n            return\n        for c in range(n):\n            d1 = row + c\n            d2 = row - c + n\n            if not col[c] and not diag1[d1] and not diag2[d2]:\n                col[c] = True\n                diag1[d1] = True\n                diag2[d2] = True\n                dfs(row + 1)\n                col[c] = False\n                diag1[d1] = False\n                diag2[d2] = False\n\n    dfs(0)\n    print(count)\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(142,'C','#include <stdio.h>\n#include <string.h>\n\nint main() {\n    int m, n;\n    scanf(\"%d %d\", &m, &n);\n    getchar();\n\n    char matrix[m][n + 1];\n    for (int i = 0; i < m; i++) {\n        fgets(matrix[i], n + 2, stdin);\n        matrix[i][strcspn(matrix[i], \"\\r\\n\")] = \'\\0\';\n    }\n\n    int dp[m + 1][n + 1];\n    memset(dp, 0, sizeof(dp));\n    int maxSide = 0;\n\n    for (int i = 1; i <= m; i++) {\n        for (int j = 1; j <= n; j++) {\n            if (matrix[i - 1][j - 1] == \'1\') {\n                int min = dp[i - 1][j];\n                if (dp[i][j - 1] < min) min = dp[i][j - 1];\n                if (dp[i - 1][j - 1] < min) min = dp[i - 1][j - 1];\n                dp[i][j] = min + 1;\n                if (dp[i][j] > maxSide) maxSide = dp[i][j];\n            }\n        }\n    }\n\n    printf(\"%d\\n\", maxSide * maxSide);\n    return 0;\n}',NULL,1),
(142,'CPP','#include <iostream>\n#include <vector>\n#include <string>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int m, n;\n    cin >> m >> n;\n    cin.ignore();\n    vector<string> matrix(m);\n    for (int i = 0; i < m; i++) {\n        getline(cin, matrix[i]);\n    }\n\n    vector<vector<int>> dp(m + 1, vector<int>(n + 1, 0));\n    int maxSide = 0;\n\n    for (int i = 1; i <= m; i++) {\n        for (int j = 1; j <= n; j++) {\n            if (matrix[i - 1][j - 1] == \'1\') {\n                dp[i][j] = min({dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]}) + 1;\n                maxSide = max(maxSide, dp[i][j]);\n            }\n        }\n    }\n\n    cout << maxSide * maxSide << endl;\n    return 0;\n}',NULL,1),
(142,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n        sc.nextLine();\n        char[][] matrix = new char[m][n];\n        for (int i = 0; i < m; i++) {\n            String line = sc.nextLine().trim();\n            matrix[i] = line.toCharArray();\n        }\n\n        int[][] dp = new int[m + 1][n + 1];\n        int maxSide = 0;\n\n        for (int i = 1; i <= m; i++) {\n            for (int j = 1; j <= n; j++) {\n                if (matrix[i - 1][j - 1] == \'1\') {\n                    dp[i][j] = Math.min(Math.min(dp[i - 1][j], dp[i][j - 1]), dp[i - 1][j - 1]) + 1;\n                    maxSide = Math.max(maxSide, dp[i][j]);\n                }\n            }\n        }\n\n        System.out.println(maxSide * maxSide);\n    }\n}',NULL,1),
(142,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n});\n\nrl.on(\'close\', () => {\n    const [m, n] = lines[0].trim().split(/\\s+/).map(Number);\n    const matrix = [];\n    for (let i = 0; i < m; i++) {\n        matrix.push(lines[i + 1].trim().split(\'\'));\n    }\n\n    const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));\n    let maxSide = 0;\n\n    for (let i = 1; i <= m; i++) {\n        for (let j = 1; j <= n; j++) {\n            if (matrix[i - 1][j - 1] === \'1\') {\n                dp[i][j] = Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1;\n                maxSide = Math.max(maxSide, dp[i][j]);\n            }\n        }\n    }\n\n    console.log(maxSide * maxSide);\n});',NULL,1),
(142,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    m = int(data[0])\n    n = int(data[1])\n    matrix = data[2:2 + m]\n\n    dp = [[0] * (n + 1) for _ in range(m + 1)]\n    max_side = 0\n\n    for i in range(1, m + 1):\n        row = matrix[i - 1]\n        for j in range(1, n + 1):\n            if row[j - 1] == \'1\':\n                dp[i][j] = min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1\n                if dp[i][j] > max_side:\n                    max_side = dp[i][j]\n\n    print(max_side * max_side)\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(143,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int height[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &height[i]);\n    }\n\n    int left = 0, right = n - 1;\n    int leftMax = 0, rightMax = 0;\n    int ans = 0;\n\n    while (left < right) {\n        if (height[left] < height[right]) {\n            if (height[left] >= leftMax) {\n                leftMax = height[left];\n            } else {\n                ans += leftMax - height[left];\n            }\n            left++;\n        } else {\n            if (height[right] >= rightMax) {\n                rightMax = height[right];\n            } else {\n                ans += rightMax - height[right];\n            }\n            right--;\n        }\n    }\n\n    printf(\"%d\\n\", ans);\n    return 0;\n}',NULL,1),
(143,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> height(n);\n    for (int i = 0; i < n; i++) {\n        cin >> height[i];\n    }\n\n    int left = 0, right = n - 1;\n    int leftMax = 0, rightMax = 0;\n    int ans = 0;\n\n    while (left < right) {\n        if (height[left] < height[right]) {\n            if (height[left] >= leftMax) {\n                leftMax = height[left];\n            } else {\n                ans += leftMax - height[left];\n            }\n            left++;\n        } else {\n            if (height[right] >= rightMax) {\n                rightMax = height[right];\n            } else {\n                ans += rightMax - height[right];\n            }\n            right--;\n        }\n    }\n\n    cout << ans << endl;\n    return 0;\n}',NULL,1),
(143,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] height = new int[n];\n        for (int i = 0; i < n; i++) {\n            height[i] = sc.nextInt();\n        }\n\n        int left = 0, right = n - 1;\n        int leftMax = 0, rightMax = 0;\n        int ans = 0;\n\n        while (left < right) {\n            if (height[left] < height[right]) {\n                if (height[left] >= leftMax) {\n                    leftMax = height[left];\n                } else {\n                    ans += leftMax - height[left];\n                }\n                left++;\n            } else {\n                if (height[right] >= rightMax) {\n                    rightMax = height[right];\n                } else {\n                    ans += rightMax - height[right];\n                }\n                right--;\n            }\n        }\n\n        System.out.println(ans);\n    }\n}',NULL,1),
(143,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const height = lines[1].split(\' \').map(Number);\n\n    let left = 0, right = n - 1;\n    let leftMax = 0, rightMax = 0;\n    let ans = 0;\n\n    while (left < right) {\n        if (height[left] < height[right]) {\n            if (height[left] >= leftMax) {\n                leftMax = height[left];\n            } else {\n                ans += leftMax - height[left];\n            }\n            left++;\n        } else {\n            if (height[right] >= rightMax) {\n                rightMax = height[right];\n            } else {\n                ans += rightMax - height[right];\n            }\n            right--;\n        }\n    }\n\n    console.log(ans);\n});',NULL,1),
(143,'PYTHON','n = int(input())\nheight = list(map(int, input().split()))\n\nleft, right = 0, n - 1\nleftMax, rightMax = 0, 0\nans = 0\n\nwhile left < right:\n    if height[left] < height[right]:\n        if height[left] >= leftMax:\n            leftMax = height[left]\n        else:\n            ans += leftMax - height[left]\n        left += 1\n    else:\n        if height[right] >= rightMax:\n            rightMax = height[right]\n        else:\n            ans += rightMax - height[right]\n        right -= 1\n\nprint(ans)',NULL,1),
(144,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\nchar *map[] = {\"\", \"\", \"abc\", \"def\", \"ghi\", \"jkl\", \"mno\", \"pqrs\", \"tuv\", \"wxyz\"};\n\nvoid backtrack(char **result, int *count, char *path, int index, char *digits) {\n    if (index == (int)strlen(digits)) {\n        path[index] = \'\\0\';\n        result[*count] = (char *)malloc((strlen(path) + 1) * sizeof(char));\n        strcpy(result[*count], path);\n        (*count)++;\n        return;\n    }\n    char c = digits[index];\n    char *letters = map[c - \'0\'];\n    for (int i = 0; i < (int)strlen(letters); i++) {\n        path[index] = letters[i];\n        backtrack(result, count, path, index + 1, digits);\n    }\n}\n\nint main() {\n    char digits[100];\n    if (scanf(\"%s\", digits) != 1) {\n        return 0;\n    }\n    int len = strlen(digits);\n    if (len == 0) {\n        printf(\"[]\\n\");\n        return 0;\n    }\n    int maxCount = 1;\n    for (int i = 0; i < len; i++) {\n        maxCount *= strlen(map[digits[i] - \'0\']);\n    }\n    char **result = (char **)malloc(maxCount * sizeof(char *));\n    char *path = (char *)malloc((len + 1) * sizeof(char));\n    int count = 0;\n    backtrack(result, &count, path, 0, digits);\n    printf(\"[\");\n    for (int i = 0; i < count; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"\\\"%s\\\"\", result[i]);\n    }\n    printf(\"]\\n\");\n    for (int i = 0; i < count; i++) {\n        free(result[i]);\n    }\n    free(result);\n    free(path);\n    return 0;\n}',NULL,1),
(144,'CPP','#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nvoid backtrack(vector<string>& result, string& path, const string& digits, int index, const string map[]) {\n    if (index == (int)digits.length()) {\n        result.push_back(path);\n        return;\n    }\n    char c = digits[index];\n    string letters = map[c - \'0\'];\n    for (int i = 0; i < (int)letters.length(); i++) {\n        path.push_back(letters[i]);\n        backtrack(result, path, digits, index + 1, map);\n        path.pop_back();\n    }\n}\n\nint main() {\n    string digits;\n    getline(cin, digits);\n    while (!digits.empty() && (digits.back() == \'\\r\' || digits.back() == \'\\n\' || digits.back() == \' \' || digits.back() == \'\\t\')) {\n        digits.pop_back();\n    }\n    size_t start = 0;\n    while (start < digits.size() && (digits[start] == \' \' || digits[start] == \'\\t\')) {\n        start++;\n    }\n    if (start > 0) digits = digits.substr(start);\n\n    vector<string> result;\n    if (digits.empty()) {\n        cout << \"[]\" << endl;\n        return 0;\n    }\n    string map[10] = {\n        \"\", \"\", \"abc\", \"def\", \"ghi\", \"jkl\", \"mno\", \"pqrs\", \"tuv\", \"wxyz\"\n    };\n    string path;\n    backtrack(result, path, digits, 0, map);\n    cout << \"[\";\n    for (int i = 0; i < (int)result.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << \"\\\"\" << result[i] << \"\\\"\";\n    }\n    cout << \"]\" << endl;\n    return 0;\n}',NULL,1),
(144,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String digits = sc.nextLine().trim();\n        List<String> result = new ArrayList<>();\n        if (digits == null || digits.length() == 0) {\n            System.out.println(\"[]\");\n            return;\n        }\n        String[] map = {\n            \"\", \"\", \"abc\", \"def\", \"ghi\", \"jkl\", \"mno\", \"pqrs\", \"tuv\", \"wxyz\"\n        };\n        backtrack(result, new StringBuilder(), digits, 0, map);\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < result.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(\"\\\"\").append(result.get(i)).append(\"\\\"\");\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n\n    private static void backtrack(List<String> result, StringBuilder path, String digits, int index, String[] map) {\n        if (index == digits.length()) {\n            result.add(path.toString());\n            return;\n        }\n        char c = digits.charAt(index);\n        String letters = map[c - \'0\'];\n        for (int i = 0; i < letters.length(); i++) {\n            path.append(letters.charAt(i));\n            backtrack(result, path, digits, index + 1, map);\n            path.deleteCharAt(path.length() - 1);\n        }\n    }\n}',NULL,1),
(144,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const digits = line.trim();\n    const result = [];\n    if (!digits || digits.length === 0) {\n        console.log(\"[]\");\n        rl.close();\n        return;\n    }\n    const map = [\"\", \"\", \"abc\", \"def\", \"ghi\", \"jkl\", \"mno\", \"pqrs\", \"tuv\", \"wxyz\"];\n    backtrack(result, \"\", digits, 0, map);\n    let sb = \"[\";\n    for (let i = 0; i < result.length; i++) {\n        if (i > 0) sb += \",\";\n        sb += \"\\\"\" + result[i] + \"\\\"\";\n    }\n    sb += \"]\";\n    console.log(sb);\n    rl.close();\n});\n\nfunction backtrack(result, path, digits, index, map) {\n    if (index === digits.length) {\n        result.push(path);\n        return;\n    }\n    const c = digits.charAt(index);\n    const letters = map[c.charCodeAt(0) - \'0\'.charCodeAt(0)];\n    for (let i = 0; i < letters.length; i++) {\n        backtrack(result, path + letters.charAt(i), digits, index + 1, map);\n    }\n}',NULL,1),
(144,'PYTHON','import sys\n\ndef main():\n    digits = sys.stdin.readline().strip()\n    if not digits:\n        print(\"[]\")\n        return\n    mapping = [\"\", \"\", \"abc\", \"def\", \"ghi\", \"jkl\", \"mno\", \"pqrs\", \"tuv\", \"wxyz\"]\n    result = []\n    def backtrack(index, path):\n        if index == len(digits):\n            result.append(path)\n            return\n        letters = mapping[int(digits[index])]\n        for ch in letters:\n            backtrack(index + 1, path + ch)\n    backtrack(0, \"\")\n    print(\"[\" + \",\".join(f\'\"{s}\"\' for s in result) + \"]\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(145,'C','#include <stdio.h>\n#include <string.h>\n\nint strStr(const char *haystack, const char *needle) {\n    if (needle[0] == \'\\0\') {\n        return 0;\n    }\n    int n = (int)strlen(haystack);\n    int m = (int)strlen(needle);\n    for (int i = 0; i <= n - m; i++) {\n        if (strncmp(haystack + i, needle, m) == 0) {\n            return i;\n        }\n    }\n    return -1;\n}\n\nint main(void) {\n    char haystack[100005];\n    char needle[100005];\n\n    if (fgets(haystack, sizeof(haystack), stdin) == NULL) {\n        return 0;\n    }\n    if (fgets(needle, sizeof(needle), stdin) == NULL) {\n        return 0;\n    }\n\n    size_t len1 = strlen(haystack);\n    if (len1 > 0 && haystack[len1 - 1] == \'\\n\') {\n        haystack[len1 - 1] = \'\\0\';\n    }\n\n    size_t len2 = strlen(needle);\n    if (len2 > 0 && needle[len2 - 1] == \'\\n\') {\n        needle[len2 - 1] = \'\\0\';\n    }\n\n    printf(\"%d\\n\", strStr(haystack, needle));\n    return 0;\n}',NULL,1),
(145,'CPP','#include <iostream>\n#include <string>\nusing namespace std;\n\nint strStr(const string& haystack, const string& needle) {\n    if (needle.empty()) {\n        return 0;\n    }\n    int n = haystack.length();\n    int m = needle.length();\n    for (int i = 0; i <= n - m; i++) {\n        if (haystack.substr(i, m) == needle) {\n            return i;\n        }\n    }\n    return -1;\n}\n\nint main() {\n    string haystack, needle;\n    getline(cin, haystack);\n    getline(cin, needle);\n    cout << strStr(haystack, needle) << endl;\n    return 0;\n}',NULL,1),
(145,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        String haystack = scanner.nextLine();\n        String needle = scanner.nextLine();\n        System.out.println(strStr(haystack, needle));\n    }\n\n    public static int strStr(String haystack, String needle) {\n        if (needle.isEmpty()) {\n            return 0;\n        }\n        int n = haystack.length();\n        int m = needle.length();\n        for (int i = 0; i <= n - m; i++) {\n            if (haystack.substring(i, i + m).equals(needle)) {\n                return i;\n            }\n        }\n        return -1;\n    }\n}',NULL,1),
(145,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n    if (lines.length === 2) {\n        const haystack = lines[0];\n        const needle = lines[1];\n        console.log(strStr(haystack, needle));\n        rl.close();\n    }\n});\n\nfunction strStr(haystack, needle) {\n    if (needle.length === 0) {\n        return 0;\n    }\n    const n = haystack.length;\n    const m = needle.length;\n    for (let i = 0; i <= n - m; i++) {\n        if (haystack.substring(i, i + m) === needle) {\n            return i;\n        }\n    }\n    return -1;\n}',NULL,1),
(145,'PYTHON','haystack = input()\nneedle = input()\n\nif needle == \"\":\n    print(0)\nelse:\n    n = len(haystack)\n    m = len(needle)\n    result = -1\n    for i in range(n - m + 1):\n        if haystack[i:i + m] == needle:\n            result = i\n            break\n    print(result)',NULL,1),
(146,'C','#include <stdio.h>\n\nint main() {\n    int m, n;\n    scanf(\"%d %d\", &m, &n);\n    int matrix[m][n];\n    for (int i = 0; i < m; i++) {\n        for (int j = 0; j < n; j++) {\n            scanf(\"%d\", &matrix[i][j]);\n        }\n    }\n    int target;\n    scanf(\"%d\", &target);\n    int left = 0, right = m * n - 1;\n    int found = 0;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        int val = matrix[mid / n][mid % n];\n        if (val == target) {\n            found = 1;\n            break;\n        } else if (val < target) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    if (found) {\n        printf(\"true\\n\");\n    } else {\n        printf(\"false\\n\");\n    }\n    return 0;\n}',NULL,1),
(146,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int m, n;\n    cin >> m >> n;\n    vector<vector<int>> matrix(m, vector<int>(n));\n    for (int i = 0; i < m; i++) {\n        for (int j = 0; j < n; j++) {\n            cin >> matrix[i][j];\n        }\n    }\n    int target;\n    cin >> target;\n    int left = 0, right = m * n - 1;\n    bool found = false;\n    while (left <= right) {\n        int mid = left + (right - left) / 2;\n        int val = matrix[mid / n][mid % n];\n        if (val == target) {\n            found = true;\n            break;\n        } else if (val < target) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    cout << (found ? \"true\" : \"false\") << endl;\n    return 0;\n}',NULL,1),
(146,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n        int[][] matrix = new int[m][n];\n        for (int i = 0; i < m; i++) {\n            for (int j = 0; j < n; j++) {\n                matrix[i][j] = sc.nextInt();\n            }\n        }\n        int target = sc.nextInt();\n        int left = 0, right = m * n - 1;\n        boolean found = false;\n        while (left <= right) {\n            int mid = left + (right - left) / 2;\n            int val = matrix[mid / n][mid % n];\n            if (val == target) {\n                found = true;\n                break;\n            } else if (val < target) {\n                left = mid + 1;\n            } else {\n                right = mid - 1;\n            }\n        }\n        System.out.println(found);\n    }\n}',NULL,1),
(146,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    let idx = 0;\n    const [m, n] = lines[idx++].split(\' \').map(Number);\n    const matrix = [];\n    for (let i = 0; i < m; i++) {\n        matrix.push(lines[idx++].split(\' \').map(Number));\n    }\n    const target = Number(lines[idx++]);\n\n    let left = 0, right = m * n - 1;\n    let found = false;\n    while (left <= right) {\n        const mid = left + Math.floor((right - left) / 2);\n        const val = matrix[Math.floor(mid / n)][mid % n];\n        if (val === target) {\n            found = true;\n            break;\n        } else if (val < target) {\n            left = mid + 1;\n        } else {\n            right = mid - 1;\n        }\n    }\n    console.log(found);\n});',NULL,1),
(146,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    m = int(data[0])\n    n = int(data[1])\n    idx = 2\n    matrix = []\n    for i in range(m):\n        row = []\n        for j in range(n):\n            row.append(int(data[idx]))\n            idx += 1\n        matrix.append(row)\n    target = int(data[idx])\n    \n    left, right = 0, m * n - 1\n    found = False\n    while left <= right:\n        mid = left + (right - left) // 2\n        val = matrix[mid // n][mid % n]\n        if val == target:\n            found = True\n            break\n        elif val < target:\n            left = mid + 1\n        else:\n            right = mid - 1\n    print(\"true\" if found else \"false\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(147,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int *nums = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    int low = 0, mid = 0, high = n - 1;\n    while (mid <= high) {\n        if (nums[mid] == 0) {\n            int temp = nums[low];\n            nums[low] = nums[mid];\n            nums[mid] = temp;\n            low++;\n            mid++;\n        } else if (nums[mid] == 1) {\n            mid++;\n        } else {\n            int temp = nums[mid];\n            nums[mid] = nums[high];\n            nums[high] = temp;\n            high--;\n        }\n    }\n\n    for (int i = 0; i < n; i++) {\n        if (i > 0) printf(\" \");\n        printf(\"%d\", nums[i]);\n    }\n    printf(\"\\n\");\n\n    free(nums);\n    return 0;\n}',NULL,1),
(147,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n\n    int low = 0, mid = 0, high = n - 1;\n    while (mid <= high) {\n        if (nums[mid] == 0) {\n            swap(nums[low], nums[mid]);\n            low++;\n            mid++;\n        } else if (nums[mid] == 1) {\n            mid++;\n        } else {\n            swap(nums[mid], nums[high]);\n            high--;\n        }\n    }\n\n    for (int i = 0; i < n; i++) {\n        if (i > 0) cout << \' \';\n        cout << nums[i];\n    }\n    cout << endl;\n\n    return 0;\n}',NULL,1),
(147,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n\n        int low = 0, mid = 0, high = n - 1;\n        while (mid <= high) {\n            if (nums[mid] == 0) {\n                int temp = nums[low];\n                nums[low] = nums[mid];\n                nums[mid] = temp;\n                low++;\n                mid++;\n            } else if (nums[mid] == 1) {\n                mid++;\n            } else {\n                int temp = nums[mid];\n                nums[mid] = nums[high];\n                nums[high] = temp;\n                high--;\n            }\n        }\n\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < n; i++) {\n            if (i > 0) sb.append(\' \');\n            sb.append(nums[i]);\n        }\n        System.out.println(sb.toString());\n    }\n}',NULL,1),
(147,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n\n    let low = 0, mid = 0, high = n - 1;\n    while (mid <= high) {\n        if (nums[mid] === 0) {\n            let temp = nums[low];\n            nums[low] = nums[mid];\n            nums[mid] = temp;\n            low++;\n            mid++;\n        } else if (nums[mid] === 1) {\n            mid++;\n        } else {\n            let temp = nums[mid];\n            nums[mid] = nums[high];\n            nums[high] = temp;\n            high--;\n        }\n    }\n\n    console.log(nums.join(\' \'));\n});',NULL,1),
(147,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\n\nlow, mid, high = 0, 0, n - 1\nwhile mid <= high:\n    if nums[mid] == 0:\n        nums[low], nums[mid] = nums[mid], nums[low]\n        low += 1\n        mid += 1\n    elif nums[mid] == 1:\n        mid += 1\n    else:\n        nums[mid], nums[high] = nums[high], nums[mid]\n        high -= 1\n\nprint(\' \'.join(map(str, nums)))',NULL,1),
(148,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint cmp(const void *a, const void *b) {\n    return (*(int *)a - *(int *)b);\n}\n\nvoid backtrack(int *nums, int n, int start, int *path, int pathSize, int **res, int *returnSize, int **returnColumnSizes) {\n    res[*returnSize] = (int *)malloc(sizeof(int) * pathSize);\n    for (int i = 0; i < pathSize; i++) {\n        res[*returnSize][i] = path[i];\n    }\n    (*returnColumnSizes)[*returnSize] = pathSize;\n    (*returnSize)++;\n\n    for (int i = start; i < n; i++) {\n        if (i > start && nums[i] == nums[i - 1]) continue;\n        path[pathSize] = nums[i];\n        backtrack(nums, n, i + 1, path, pathSize + 1, res, returnSize, returnColumnSizes);\n    }\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int *nums = (int *)malloc(sizeof(int) * n);\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    qsort(nums, n, sizeof(int), cmp);\n\n    int maxRes = 1 << n;\n    int **res = (int **)malloc(sizeof(int *) * maxRes);\n    int *returnColumnSizes = (int *)malloc(sizeof(int) * maxRes);\n    int returnSize = 0;\n    int *path = (int *)malloc(sizeof(int) * n);\n\n    backtrack(nums, n, 0, path, 0, res, &returnSize, &returnColumnSizes);\n\n    printf(\"[\");\n    for (int i = 0; i < returnSize; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"[\");\n        for (int j = 0; j < returnColumnSizes[i]; j++) {\n            if (j > 0) printf(\",\");\n            printf(\"%d\", res[i][j]);\n        }\n        printf(\"]\");\n    }\n    printf(\"]\\n\");\n\n    for (int i = 0; i < returnSize; i++) {\n        free(res[i]);\n    }\n    free(res);\n    free(returnColumnSizes);\n    free(path);\n    free(nums);\n\n    return 0;\n}',NULL,1),
(148,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nvoid backtrack(vector<int>& nums, int start, vector<int>& path, vector<vector<int>>& res) {\n    res.push_back(path);\n    for (int i = start; i < (int)nums.size(); i++) {\n        if (i > start && nums[i] == nums[i - 1]) continue;\n        path.push_back(nums[i]);\n        backtrack(nums, i + 1, path, res);\n        path.pop_back();\n    }\n}\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    sort(nums.begin(), nums.end());\n    vector<vector<int>> res;\n    vector<int> path;\n    backtrack(nums, 0, path, res);\n\n    cout << \"[\";\n    for (int i = 0; i < (int)res.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << \"[\";\n        for (int j = 0; j < (int)res[i].size(); j++) {\n            if (j > 0) cout << \",\";\n            cout << res[i][j];\n        }\n        cout << \"]\";\n    }\n    cout << \"]\" << endl;\n    return 0;\n}',NULL,1),
(148,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        Arrays.sort(nums);\n        List<List<Integer>> res = new ArrayList<>();\n        backtrack(nums, 0, new ArrayList<>(), res);\n        System.out.println(format(res));\n    }\n\n    private static void backtrack(int[] nums, int start, List<Integer> path, List<List<Integer>> res) {\n        res.add(new ArrayList<>(path));\n        for (int i = start; i < nums.length; i++) {\n            if (i > start && nums[i] == nums[i - 1]) continue;\n            path.add(nums[i]);\n            backtrack(nums, i + 1, path, res);\n            path.remove(path.size() - 1);\n        }\n    }\n\n    private static String format(List<List<Integer>> res) {\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < res.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(\"[\");\n            List<Integer> list = res.get(i);\n            for (int j = 0; j < list.size(); j++) {\n                if (j > 0) sb.append(\",\");\n                sb.append(list.get(j));\n            }\n            sb.append(\"]\");\n        }\n        sb.append(\"]\");\n        return sb.toString();\n    }\n}',NULL,1),
(148,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    nums.sort((a, b) => a - b);\n    const res = [];\n    backtrack(nums, 0, [], res);\n    console.log(format(res));\n});\n\nfunction backtrack(nums, start, path, res) {\n    res.push([...path]);\n    for (let i = start; i < nums.length; i++) {\n        if (i > start && nums[i] === nums[i - 1]) continue;\n        path.push(nums[i]);\n        backtrack(nums, i + 1, path, res);\n        path.pop();\n    }\n}\n\nfunction format(res) {\n    let sb = \'\';\n    sb += \'[\';\n    for (let i = 0; i < res.length; i++) {\n        if (i > 0) sb += \',\';\n        sb += \'[\';\n        const list = res[i];\n        for (let j = 0; j < list.length; j++) {\n            if (j > 0) sb += \',\';\n            sb += list[j];\n        }\n        sb += \']\';\n    }\n    sb += \']\';\n    return sb;\n}',NULL,1),
(148,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    nums = list(map(int, data[1:1+n]))\n    nums.sort()\n    res = []\n    \n    def backtrack(start, path):\n        res.append(path[:])\n        for i in range(start, len(nums)):\n            if i > start and nums[i] == nums[i-1]:\n                continue\n            path.append(nums[i])\n            backtrack(i + 1, path)\n            path.pop()\n    \n    backtrack(0, [])\n    \n    parts = []\n    for subset in res:\n        parts.append(\"[\" + \",\".join(map(str, subset)) + \"]\")\n    print(\"[\" + \",\".join(parts) + \"]\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(149,'C','#include <stdio.h>\n#include <string.h>\n\nint main() {\n    char s[100005];\n    if (scanf(\"%s\", s) != 1) return 0;\n    int n = strlen(s);\n    if (n == 0) {\n        printf(\"0\\n\");\n        return 0;\n    }\n    int dp[100005];\n    dp[0] = 1;\n    dp[1] = (s[0] == \'0\') ? 0 : 1;\n    for (int i = 2; i <= n; i++) {\n        dp[i] = 0;\n        int one = s[i - 1] - \'0\';\n        int two = (s[i - 2] - \'0\') * 10 + (s[i - 1] - \'0\');\n        if (one >= 1 && one <= 9) {\n            dp[i] += dp[i - 1];\n        }\n        if (two >= 10 && two <= 26) {\n            dp[i] += dp[i - 2];\n        }\n    }\n    printf(\"%d\\n\", dp[n]);\n    return 0;\n}',NULL,1),
(149,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n\nint main() {\n    std::string s;\n    std::getline(std::cin, s);\n    while (!s.empty() && (s.back() == \'\\n\' || s.back() == \'\\r\' || s.back() == \' \' || s.back() == \'\\t\')) {\n        s.pop_back();\n    }\n    size_t start = 0;\n    while (start < s.size() && (s[start] == \' \' || s[start] == \'\\t\')) {\n        ++start;\n    }\n    s = s.substr(start);\n\n    int n = static_cast<int>(s.size());\n    if (n == 0) {\n        std::cout << 0 << std::endl;\n        return 0;\n    }\n\n    std::vector<int> dp(n + 1, 0);\n    dp[0] = 1;\n    dp[1] = (s[0] == \'0\') ? 0 : 1;\n\n    for (int i = 2; i <= n; ++i) {\n        int one = s[i - 1] - \'0\';\n        int two = (s[i - 2] - \'0\') * 10 + (s[i - 1] - \'0\');\n\n        if (one >= 1 && one <= 9) {\n            dp[i] += dp[i - 1];\n        }\n        if (two >= 10 && two <= 26) {\n            dp[i] += dp[i - 2];\n        }\n    }\n\n    std::cout << dp[n] << std::endl;\n    return 0;\n}',NULL,1),
(149,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.nextLine().trim();\n        int n = s.length();\n        if (n == 0) {\n            System.out.println(0);\n            return;\n        }\n        int[] dp = new int[n + 1];\n        dp[0] = 1;\n        dp[1] = s.charAt(0) == \'0\' ? 0 : 1;\n        for (int i = 2; i <= n; i++) {\n            int one = s.charAt(i - 1) - \'0\';\n            int two = Integer.parseInt(s.substring(i - 2, i));\n            if (one >= 1 && one <= 9) {\n                dp[i] += dp[i - 1];\n            }\n            if (two >= 10 && two <= 26) {\n                dp[i] += dp[i - 2];\n            }\n        }\n        System.out.println(dp[n]);\n    }\n}',NULL,1),
(149,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const s = line.trim();\n    const n = s.length;\n    if (n === 0) {\n        console.log(0);\n        rl.close();\n        return;\n    }\n    const dp = new Array(n + 1).fill(0);\n    dp[0] = 1;\n    dp[1] = s.charAt(0) === \'0\' ? 0 : 1;\n    for (let i = 2; i <= n; i++) {\n        const one = s.charCodeAt(i - 1) - \'0\'.charCodeAt(0);\n        const two = parseInt(s.substring(i - 2, i), 10);\n        if (one >= 1 && one <= 9) {\n            dp[i] += dp[i - 1];\n        }\n        if (two >= 10 && two <= 26) {\n            dp[i] += dp[i - 2];\n        }\n    }\n    console.log(dp[n]);\n    rl.close();\n});',NULL,1),
(149,'PYTHON','s = input().strip()\nn = len(s)\nif n == 0:\n    print(0)\nelse:\n    dp = [0] * (n + 1)\n    dp[0] = 1\n    dp[1] = 0 if s[0] == \'0\' else 1\n    for i in range(2, n + 1):\n        one = int(s[i - 1])\n        two = int(s[i - 2:i])\n        if 1 <= one <= 9:\n            dp[i] += dp[i - 1]\n        if 10 <= two <= 26:\n            dp[i] += dp[i - 2]\n    print(dp[n])',NULL,1),
(150,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    long long dp[n + 1];\n    dp[0] = 1;\n    for (int i = 1; i <= n; i++) {\n        dp[i] = 0;\n        for (int j = 1; j <= i; j++) {\n            dp[i] += dp[j - 1] * dp[i - j];\n        }\n    }\n    printf(\"%lld\\n\", dp[n]);\n    return 0;\n}',NULL,1),
(150,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<long long> dp(n + 1, 0);\n    dp[0] = 1;\n    for (int i = 1; i <= n; i++) {\n        for (int j = 1; j <= i; j++) {\n            dp[i] += dp[j - 1] * dp[i - j];\n        }\n    }\n    cout << dp[n] << endl;\n    return 0;\n}',NULL,1),
(150,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        long[] dp = new long[n + 1];\n        dp[0] = 1;\n        for (int i = 1; i <= n; i++) {\n            for (int j = 1; j <= i; j++) {\n                dp[i] += dp[j - 1] * dp[i - j];\n            }\n        }\n        System.out.println(dp[n]);\n    }\n}',NULL,1),
(150,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const n = parseInt(line.trim(), 10);\n    const dp = new Array(n + 1).fill(0);\n    dp[0] = 1;\n    for (let i = 1; i <= n; i++) {\n        for (let j = 1; j <= i; j++) {\n            dp[i] += dp[j - 1] * dp[i - j];\n        }\n    }\n    console.log(dp[n]);\n    rl.close();\n});',NULL,1),
(150,'PYTHON','n = int(input())\ndp = [0] * (n + 1)\ndp[0] = 1\nfor i in range(1, n + 1):\n    for j in range(1, i + 1):\n        dp[i] += dp[j - 1] * dp[i - j]\nprint(dp[n])',NULL,1),
(151,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int **triangle = (int **)malloc(n * sizeof(int *));\n    for (int i = 0; i < n; i++) {\n        triangle[i] = (int *)malloc(n * sizeof(int));\n        for (int j = 0; j <= i; j++) {\n            scanf(\"%d\", &triangle[i][j]);\n        }\n    }\n    int *dp = (int *)malloc(n * sizeof(int));\n    for (int j = 0; j < n; j++) {\n        dp[j] = triangle[n - 1][j];\n    }\n    for (int i = n - 2; i >= 0; i--) {\n        for (int j = 0; j <= i; j++) {\n            int min = dp[j] < dp[j + 1] ? dp[j] : dp[j + 1];\n            dp[j] = triangle[i][j] + min;\n        }\n    }\n    printf(\"%d\\n\", dp[0]);\n    for (int i = 0; i < n; i++) {\n        free(triangle[i]);\n    }\n    free(triangle);\n    free(dp);\n    return 0;\n}',NULL,1),
(151,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<vector<int>> triangle(n, vector<int>(n));\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j <= i; j++) {\n            cin >> triangle[i][j];\n        }\n    }\n    vector<int> dp(n);\n    for (int j = 0; j < n; j++) {\n        dp[j] = triangle[n - 1][j];\n    }\n    for (int i = n - 2; i >= 0; i--) {\n        for (int j = 0; j <= i; j++) {\n            dp[j] = triangle[i][j] + min(dp[j], dp[j + 1]);\n        }\n    }\n    cout << dp[0] << endl;\n    return 0;\n}',NULL,1),
(151,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[][] triangle = new int[n][n];\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j <= i; j++) {\n                triangle[i][j] = sc.nextInt();\n            }\n        }\n        int[] dp = new int[n];\n        for (int j = 0; j < n; j++) {\n            dp[j] = triangle[n - 1][j];\n        }\n        for (int i = n - 2; i >= 0; i--) {\n            for (int j = 0; j <= i; j++) {\n                dp[j] = triangle[i][j] + Math.min(dp[j], dp[j + 1]);\n            }\n        }\n        System.out.println(dp[0]);\n    }\n}',NULL,1),
(151,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    let idx = 0;\n    const n = parseInt(lines[idx++]);\n    const triangle = [];\n    for (let i = 0; i < n; i++) {\n        const row = lines[idx++].split(\' \').map(Number);\n        triangle.push(row);\n    }\n    const dp = new Array(n);\n    for (let j = 0; j < n; j++) {\n        dp[j] = triangle[n - 1][j];\n    }\n    for (let i = n - 2; i >= 0; i--) {\n        for (let j = 0; j <= i; j++) {\n            dp[j] = triangle[i][j] + Math.min(dp[j], dp[j + 1]);\n        }\n    }\n    console.log(dp[0]);\n});',NULL,1),
(151,'PYTHON','n = int(input())\ntriangle = []\nfor i in range(n):\n    row = list(map(int, input().split()))\n    triangle.append(row)\n\ndp = triangle[-1][:]\n\nfor i in range(n - 2, -1, -1):\n    for j in range(i + 1):\n        dp[j] = triangle[i][j] + min(dp[j], dp[j + 1])\n\nprint(dp[0])',NULL,1),
(152,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdbool.h>\n\nint main() {\n    char s[10005];\n    if (fgets(s, sizeof(s), stdin) == NULL) return 0;\n    s[strcspn(s, \"\\r\\n\")] = \'\\0\';\n\n    char line[10005];\n    if (fgets(line, sizeof(line), stdin) == NULL) return 0;\n    int n = atoi(line);\n\n    char **wordDict = (char **)malloc(n * sizeof(char *));\n    for (int i = 0; i < n; i++) {\n        wordDict[i] = (char *)malloc(10005 * sizeof(char));\n        if (fgets(wordDict[i], 10005, stdin) == NULL) {\n            wordDict[i][0] = \'\\0\';\n        }\n        wordDict[i][strcspn(wordDict[i], \"\\r\\n\")] = \'\\0\';\n    }\n\n    int len = strlen(s);\n    bool *dp = (bool *)calloc(len + 1, sizeof(bool));\n    dp[0] = true;\n\n    for (int i = 1; i <= len; i++) {\n        for (int j = 0; j < i; j++) {\n            if (dp[j]) {\n                int subLen = i - j;\n                char *sub = (char *)malloc((subLen + 1) * sizeof(char));\n                strncpy(sub, s + j, subLen);\n                sub[subLen] = \'\\0\';\n\n                bool found = false;\n                for (int k = 0; k < n; k++) {\n                    if (strcmp(sub, wordDict[k]) == 0) {\n                        found = true;\n                        break;\n                    }\n                }\n                free(sub);\n\n                if (found) {\n                    dp[i] = true;\n                    break;\n                }\n            }\n        }\n    }\n\n    if (dp[len]) {\n        printf(\"true\\n\");\n    } else {\n        printf(\"false\\n\");\n    }\n\n    for (int i = 0; i < n; i++) {\n        free(wordDict[i]);\n    }\n    free(wordDict);\n    free(dp);\n\n    return 0;\n}',NULL,1),
(152,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <unordered_set>\n\nusing namespace std;\n\nint main() {\n    string s;\n    getline(cin, s);\n\n    string nLine;\n    getline(cin, nLine);\n    int n = stoi(nLine);\n\n    unordered_set<string> wordDict;\n    for (int i = 0; i < n; ++i) {\n        string word;\n        getline(cin, word);\n        wordDict.insert(word);\n    }\n\n    int len = s.length();\n    vector<bool> dp(len + 1, false);\n    dp[0] = true;\n\n    for (int i = 1; i <= len; ++i) {\n        for (int j = 0; j < i; ++j) {\n            if (dp[j] && wordDict.count(s.substr(j, i - j))) {\n                dp[i] = true;\n                break;\n            }\n        }\n    }\n\n    cout << (dp[len] ? \"true\" : \"false\") << endl;\n\n    return 0;\n}',NULL,1),
(152,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.nextLine();\n        int n = Integer.parseInt(sc.nextLine().trim());\n        Set<String> wordDict = new HashSet<>();\n        for (int i = 0; i < n; i++) {\n            wordDict.add(sc.nextLine().trim());\n        }\n\n        int len = s.length();\n        boolean[] dp = new boolean[len + 1];\n        dp[0] = true;\n\n        for (int i = 1; i <= len; i++) {\n            for (int j = 0; j < i; j++) {\n                if (dp[j] && wordDict.contains(s.substring(j, i))) {\n                    dp[i] = true;\n                    break;\n                }\n            }\n        }\n\n        System.out.println(dp[len]);\n    }\n}',NULL,1),
(152,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n});\n\nrl.on(\'close\', () => {\n    const s = lines[0];\n    const n = parseInt(lines[1].trim());\n    const wordDict = new Set();\n    for (let i = 0; i < n; i++) {\n        wordDict.add(lines[2 + i].trim());\n    }\n\n    const len = s.length;\n    const dp = new Array(len + 1).fill(false);\n    dp[0] = true;\n\n    for (let i = 1; i <= len; i++) {\n        for (let j = 0; j < i; j++) {\n            if (dp[j] && wordDict.has(s.substring(j, i))) {\n                dp[i] = true;\n                break;\n            }\n        }\n    }\n\n    console.log(dp[len]);\n});',NULL,1),
(152,'PYTHON','s = input()\nn = int(input().strip())\nwordDict = set()\nfor _ in range(n):\n    wordDict.add(input().strip())\n\nlength = len(s)\ndp = [False] * (length + 1)\ndp[0] = True\n\nfor i in range(1, length + 1):\n    for j in range(i):\n        if dp[j] and s[j:i] in wordDict:\n            dp[i] = True\n            break\n\nprint(str(dp[length]).lower())',NULL,1),
(153,'C','#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct {\n    int num;\n    int freq;\n} Pair;\n\nint cmp(const void *a, const void *b) {\n    Pair *p1 = (Pair *)a;\n    Pair *p2 = (Pair *)b;\n    if (p1->freq != p2->freq) {\n        return p2->freq - p1->freq;\n    }\n    return p1->num - p2->num;\n}\n\nint main() {\n    int n, k;\n    scanf(\"%d %d\", &n, &k);\n    int *nums = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    Pair *pairs = (Pair *)malloc(n * sizeof(Pair));\n    int size = 0;\n    for (int i = 0; i < n; i++) {\n        int found = 0;\n        for (int j = 0; j < size; j++) {\n            if (pairs[j].num == nums[i]) {\n                pairs[j].freq++;\n                found = 1;\n                break;\n            }\n        }\n        if (!found) {\n            pairs[size].num = nums[i];\n            pairs[size].freq = 1;\n            size++;\n        }\n    }\n\n    qsort(pairs, size, sizeof(Pair), cmp);\n\n    printf(\"[\");\n    for (int i = 0; i < k; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"%d\", pairs[i].num);\n    }\n    printf(\"]\\n\");\n\n    free(nums);\n    free(pairs);\n    return 0;\n}',NULL,1),
(153,'CPP','#include <iostream>\n#include <vector>\n#include <unordered_map>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n, k;\n    cin >> n >> k;\n    vector<int> nums(n);\n    for (int i = 0; i < n; ++i) {\n        cin >> nums[i];\n    }\n\n    unordered_map<int, int> freq;\n    for (int num : nums) {\n        freq[num]++;\n    }\n\n    vector<int> list;\n    for (auto &p : freq) {\n        list.push_back(p.first);\n    }\n\n    sort(list.begin(), list.end(), [&](int a, int b) {\n        int fa = freq[a];\n        int fb = freq[b];\n        if (fa != fb) return fa > fb;\n        return a < b;\n    });\n\n    cout << \"[\";\n    for (int i = 0; i < k; ++i) {\n        if (i > 0) cout << \",\";\n        cout << list[i];\n    }\n    cout << \"]\" << endl;\n\n    return 0;\n}',NULL,1),
(153,'JAVA','import java.util.*;\nimport java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        String[] first = br.readLine().trim().split(\"\\\\s+\");\n        int n = Integer.parseInt(first[0]);\n        int k = Integer.parseInt(first[1]);\n        int[] nums = new int[n];\n        String[] second = br.readLine().trim().split(\"\\\\s+\");\n        for (int i = 0; i < n; i++) {\n            nums[i] = Integer.parseInt(second[i]);\n        }\n\n        Map<Integer, Integer> freq = new HashMap<>();\n        for (int num : nums) {\n            freq.put(num, freq.getOrDefault(num, 0) + 1);\n        }\n\n        List<Integer> list = new ArrayList<>(freq.keySet());\n        list.sort((a, b) -> {\n            int fa = freq.get(a);\n            int fb = freq.get(b);\n            if (fa != fb) {\n                return fb - fa;\n            }\n            return a - b;\n        });\n\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < k; i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(list.get(i));\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n}',NULL,1),
(153,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const [n, k] = lines[0].split(/\\s+/).map(Number);\n        const nums = lines[1].split(/\\s+/).map(Number);\n\n        const freq = new Map();\n        for (const num of nums) {\n            freq.set(num, (freq.get(num) || 0) + 1);\n        }\n\n        const list = Array.from(freq.keys());\n        list.sort((a, b) => {\n            const fa = freq.get(a);\n            const fb = freq.get(b);\n            if (fa !== fb) {\n                return fb - fa;\n            }\n            return a - b;\n        });\n\n        const result = list.slice(0, k);\n        console.log(\'[\' + result.join(\',\') + \']\');\n        rl.close();\n    }\n});',NULL,1),
(153,'PYTHON','import sys\nfrom collections import Counter\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    k = int(data[1])\n    nums = list(map(int, data[2:2+n]))\n    \n    freq = Counter(nums)\n    items = sorted(freq.keys(), key=lambda x: (-freq[x], x))\n    \n    result = items[:k]\n    print(\"[\" + \",\".join(map(str, result)) + \"]\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(154,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <ctype.h>\n\n#define MAXN 100000\n\ntypedef struct {\n    int count;\n    char *str;\n} StackItem;\n\nchar *decodeString(const char *s) {\n    int len = strlen(s);\n    StackItem countStack[MAXN];\n    int top = 0;\n    char *current = (char *)malloc(MAXN * sizeof(char));\n    int curLen = 0;\n    current[0] = \'\\0\';\n    int k = 0;\n\n    for (int i = 0; i < len; i++) {\n        char c = s[i];\n        if (isdigit(c)) {\n            k = k * 10 + (c - \'0\');\n        } else if (c == \'[\') {\n            countStack[top].count = k;\n            countStack[top].str = (char *)malloc((curLen + 1) * sizeof(char));\n            strcpy(countStack[top].str, current);\n            top++;\n            curLen = 0;\n            current[0] = \'\\0\';\n            k = 0;\n        } else if (c == \']\') {\n            top--;\n            int repeat = countStack[top].count;\n            char *prev = countStack[top].str;\n            int prevLen = strlen(prev);\n            int newLen = prevLen + curLen * repeat;\n            char *newStr = (char *)malloc((newLen + 1) * sizeof(char));\n            strcpy(newStr, prev);\n            for (int j = 0; j < repeat; j++) {\n                strcat(newStr, current);\n            }\n            free(prev);\n            free(current);\n            current = newStr;\n            curLen = newLen;\n        } else {\n            current[curLen++] = c;\n            current[curLen] = \'\\0\';\n        }\n    }\n\n    return current;\n}\n\nint main() {\n    char s[MAXN];\n    if (fgets(s, sizeof(s), stdin)) {\n        size_t len = strlen(s);\n        if (len > 0 && s[len - 1] == \'\\n\') {\n            s[len - 1] = \'\\0\';\n        }\n        char *result = decodeString(s);\n        printf(\"%s\\n\", result);\n        free(result);\n    }\n    return 0;\n}',NULL,1),
(154,'CPP','#include <iostream>\n#include <string>\n#include <stack>\nusing namespace std;\n\nstring decodeString(const string& s) {\n    stack<int> countStack;\n    stack<string> stringStack;\n    string current;\n    int k = 0;\n\n    for (char c : s) {\n        if (isdigit(c)) {\n            k = k * 10 + (c - \'0\');\n        } else if (c == \'[\') {\n            countStack.push(k);\n            stringStack.push(current);\n            current.clear();\n            k = 0;\n        } else if (c == \']\') {\n            int repeat = countStack.top();\n            countStack.pop();\n            string prev = stringStack.top();\n            stringStack.pop();\n            for (int i = 0; i < repeat; i++) {\n                prev += current;\n            }\n            current = prev;\n        } else {\n            current += c;\n        }\n    }\n\n    return current;\n}\n\nint main() {\n    string s;\n    if (getline(cin, s)) {\n        cout << decodeString(s) << endl;\n    }\n    return 0;\n}',NULL,1),
(154,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        if (sc.hasNextLine()) {\n            String s = sc.nextLine();\n            System.out.println(decodeString(s));\n        }\n    }\n\n    public static String decodeString(String s) {\n        Deque<Integer> countStack = new ArrayDeque<>();\n        Deque<StringBuilder> stringStack = new ArrayDeque<>();\n        StringBuilder current = new StringBuilder();\n        int k = 0;\n\n        for (char c : s.toCharArray()) {\n            if (Character.isDigit(c)) {\n                k = k * 10 + (c - \'0\');\n            } else if (c == \'[\') {\n                countStack.push(k);\n                stringStack.push(current);\n                current = new StringBuilder();\n                k = 0;\n            } else if (c == \']\') {\n                int repeat = countStack.pop();\n                StringBuilder prev = stringStack.pop();\n                for (int i = 0; i < repeat; i++) {\n                    prev.append(current);\n                }\n                current = prev;\n            } else {\n                current.append(c);\n            }\n        }\n\n        return current.toString();\n    }\n}',NULL,1),
(154,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    console.log(decodeString(line));\n    rl.close();\n});\n\nfunction decodeString(s) {\n    const countStack = [];\n    const stringStack = [];\n    let current = \'\';\n    let k = 0;\n\n    for (const c of s) {\n        if (c >= \'0\' && c <= \'9\') {\n            k = k * 10 + (c.charCodeAt(0) - \'0\'.charCodeAt(0));\n        } else if (c === \'[\') {\n            countStack.push(k);\n            stringStack.push(current);\n            current = \'\';\n            k = 0;\n        } else if (c === \']\') {\n            const repeat = countStack.pop();\n            const prev = stringStack.pop();\n            current = prev + current.repeat(repeat);\n        } else {\n            current += c;\n        }\n    }\n\n    return current;\n}',NULL,1),
(154,'PYTHON','import sys\n\ndef decodeString(s: str) -> str:\n    count_stack = []\n    string_stack = []\n    current = []\n    k = 0\n\n    for c in s:\n        if c.isdigit():\n            k = k * 10 + int(c)\n        elif c == \'[\':\n            count_stack.append(k)\n            string_stack.append(current)\n            current = []\n            k = 0\n        elif c == \']\':\n            repeat = count_stack.pop()\n            prev = string_stack.pop()\n            for _ in range(repeat):\n                prev.extend(current)\n            current = prev\n        else:\n            current.append(c)\n\n    return \'\'.join(current)\n\nif __name__ == \"__main__\":\n    line = sys.stdin.readline()\n    if line:\n        s = line.rstrip(\'\\n\')\n        print(decodeString(s))',NULL,1),
(155,'C','#include <stdio.h>\n#include <stdbool.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[n];\n    int sum = 0;\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n        sum += nums[i];\n    }\n    if (sum % 2 != 0) {\n        printf(\"false\\n\");\n        return 0;\n    }\n    int target = sum / 2;\n    bool dp[target + 1];\n    for (int i = 0; i <= target; i++) {\n        dp[i] = false;\n    }\n    dp[0] = true;\n    for (int i = 0; i < n; i++) {\n        int num = nums[i];\n        for (int j = target; j >= num; j--) {\n            dp[j] = dp[j] || dp[j - num];\n        }\n    }\n    if (dp[target]) {\n        printf(\"true\\n\");\n    } else {\n        printf(\"false\\n\");\n    }\n    return 0;\n}',NULL,1),
(155,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    int sum = 0;\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n        sum += nums[i];\n    }\n    if (sum % 2 != 0) {\n        cout << \"false\" << endl;\n        return 0;\n    }\n    int target = sum / 2;\n    vector<bool> dp(target + 1, false);\n    dp[0] = true;\n    for (int num : nums) {\n        for (int j = target; j >= num; j--) {\n            dp[j] = dp[j] || dp[j - num];\n        }\n    }\n    cout << (dp[target] ? \"true\" : \"false\") << endl;\n    return 0;\n}',NULL,1),
(155,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        int sum = 0;\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n            sum += nums[i];\n        }\n        if (sum % 2 != 0) {\n            System.out.println(false);\n            return;\n        }\n        int target = sum / 2;\n        boolean[] dp = new boolean[target + 1];\n        dp[0] = true;\n        for (int num : nums) {\n            for (int j = target; j >= num; j--) {\n                dp[j] = dp[j] || dp[j - num];\n            }\n        }\n        System.out.println(dp[target]);\n    }\n}',NULL,1),
(155,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    let sum = 0;\n    for (let i = 0; i < n; i++) {\n        sum += nums[i];\n    }\n    if (sum % 2 !== 0) {\n        console.log(false);\n        return;\n    }\n    const target = sum / 2;\n    const dp = new Array(target + 1).fill(false);\n    dp[0] = true;\n    for (const num of nums) {\n        for (let j = target; j >= num; j--) {\n            dp[j] = dp[j] || dp[j - num];\n        }\n    }\n    console.log(dp[target]);\n});',NULL,1),
(155,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\ntotal = sum(nums)\nif total % 2 != 0:\n    print(\"false\")\nelse:\n    target = total // 2\n    dp = [False] * (target + 1)\n    dp[0] = True\n    for num in nums:\n        for j in range(target, num - 1, -1):\n            dp[j] = dp[j] or dp[j - num]\n    print(\"true\" if dp[target] else \"false\")',NULL,1),
(156,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int *nums = (int *)malloc((n + 1) * sizeof(int));\n    for (int i = 0; i <= n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    int slow = nums[0];\n    int fast = nums[0];\n    do {\n        slow = nums[slow];\n        fast = nums[nums[fast]];\n    } while (slow != fast);\n    slow = nums[0];\n    while (slow != fast) {\n        slow = nums[slow];\n        fast = nums[fast];\n    }\n    printf(\"%d\\n\", slow);\n    free(nums);\n    return 0;\n}',NULL,1),
(156,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n + 1);\n    for (int i = 0; i <= n; i++) {\n        cin >> nums[i];\n    }\n    int slow = nums[0];\n    int fast = nums[0];\n    do {\n        slow = nums[slow];\n        fast = nums[nums[fast]];\n    } while (slow != fast);\n    slow = nums[0];\n    while (slow != fast) {\n        slow = nums[slow];\n        fast = nums[fast];\n    }\n    cout << slow << endl;\n    return 0;\n}',NULL,1),
(156,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n + 1];\n        for (int i = 0; i <= n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        int slow = nums[0];\n        int fast = nums[0];\n        do {\n            slow = nums[slow];\n            fast = nums[nums[fast]];\n        } while (slow != fast);\n        slow = nums[0];\n        while (slow != fast) {\n            slow = nums[slow];\n            fast = nums[fast];\n        }\n        System.out.println(slow);\n    }\n}',NULL,1),
(156,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n\n    let slow = nums[0];\n    let fast = nums[0];\n\n    do {\n        slow = nums[slow];\n        fast = nums[nums[fast]];\n    } while (slow !== fast);\n\n    slow = nums[0];\n    while (slow !== fast) {\n        slow = nums[slow];\n        fast = nums[fast];\n    }\n\n    console.log(slow);\n});',NULL,1),
(156,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\nslow = nums[0]\nfast = nums[0]\nwhile True:\n    slow = nums[slow]\n    fast = nums[nums[fast]]\n    if slow == fast:\n        break\nslow = nums[0]\nwhile slow != fast:\n    slow = nums[slow]\n    fast = nums[fast]\nprint(slow)',NULL,1),
(157,'C','#include <stdio.h>\n#include <limits.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int dp[n + 1];\n    dp[0] = 0;\n    for (int i = 1; i <= n; i++) {\n        dp[i] = INT_MAX;\n        for (int j = 1; j * j <= i; j++) {\n            if (dp[i - j * j] + 1 < dp[i]) {\n                dp[i] = dp[i - j * j] + 1;\n            }\n        }\n    }\n    printf(\"%d\\n\", dp[n]);\n    return 0;\n}',NULL,1),
(157,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <climits>\n\nint main() {\n    int n;\n    std::cin >> n;\n    std::vector<int> dp(n + 1);\n    for (int i = 1; i <= n; i++) {\n        dp[i] = INT_MAX;\n        for (int j = 1; j * j <= i; j++) {\n            dp[i] = std::min(dp[i], dp[i - j * j] + 1);\n        }\n    }\n    std::cout << dp[n] << std::endl;\n    return 0;\n}',NULL,1),
(157,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] dp = new int[n + 1];\n        for (int i = 1; i <= n; i++) {\n            dp[i] = Integer.MAX_VALUE;\n            for (int j = 1; j * j <= i; j++) {\n                dp[i] = Math.min(dp[i], dp[i - j * j] + 1);\n            }\n        }\n        System.out.println(dp[n]);\n    }\n}',NULL,1),
(157,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const n = parseInt(line.trim(), 10);\n    const dp = new Array(n + 1).fill(0);\n    for (let i = 1; i <= n; i++) {\n        dp[i] = Number.MAX_SAFE_INTEGER;\n        for (let j = 1; j * j <= i; j++) {\n            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);\n        }\n    }\n    console.log(dp[n]);\n    rl.close();\n});',NULL,1),
(157,'PYTHON','n = int(input())\ndp = [0] * (n + 1)\nfor i in range(1, n + 1):\n    dp[i] = float(\'inf\')\n    j = 1\n    while j * j <= i:\n        dp[i] = min(dp[i], dp[i - j * j] + 1)\n        j += 1\nprint(dp[n])',NULL,1),
(158,'C','#include <stdio.h>\n#include <string.h>\n\nint main() {\n    char s[1005];\n    if (scanf(\"%s\", s) != 1) return 0;\n    int n = (int)strlen(s);\n    if (n == 0) {\n        printf(\"0\\n\");\n        return 0;\n    }\n\n    static int dp[1005][1005];\n    for (int i = 0; i < n; i++) {\n        dp[i][i] = 1;\n    }\n\n    for (int len = 2; len <= n; len++) {\n        for (int i = 0; i + len - 1 < n; i++) {\n            int j = i + len - 1;\n            if (s[i] == s[j]) {\n                if (len == 2) dp[i][j] = 2;\n                else dp[i][j] = dp[i + 1][j - 1] + 2;\n            } else {\n                int a = dp[i + 1][j];\n                int b = dp[i][j - 1];\n                dp[i][j] = a > b ? a : b;\n            }\n        }\n    }\n\n    printf(\"%d\\n\", dp[0][n - 1]);\n    return 0;\n}',NULL,1),
(158,'CPP','#include <iostream>\n#include <string>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    string s;\n    getline(cin, s);\n    int n = s.length();\n    vector<vector<int>> dp(n, vector<int>(n, 0));\n    for (int i = 0; i < n; i++) {\n        dp[i][i] = 1;\n    }\n    for (int len = 2; len <= n; len++) {\n        for (int i = 0; i + len - 1 < n; i++) {\n            int j = i + len - 1;\n            if (s[i] == s[j]) {\n                dp[i][j] = dp[i + 1][j - 1] + 2;\n            } else {\n                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1]);\n            }\n        }\n    }\n    cout << dp[0][n - 1] << endl;\n    return 0;\n}',NULL,1),
(158,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.nextLine();\n        int n = s.length();\n        int[][] dp = new int[n][n];\n        for (int i = 0; i < n; i++) {\n            dp[i][i] = 1;\n        }\n        for (int len = 2; len <= n; len++) {\n            for (int i = 0; i + len - 1 < n; i++) {\n                int j = i + len - 1;\n                if (s.charAt(i) == s.charAt(j)) {\n                    dp[i][j] = dp[i + 1][j - 1] + 2;\n                } else {\n                    dp[i][j] = Math.max(dp[i + 1][j], dp[i][j - 1]);\n                }\n            }\n        }\n        System.out.println(dp[0][n - 1]);\n    }\n}',NULL,1),
(158,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (s) => {\n    const n = s.length;\n    const dp = Array.from({ length: n }, () => new Array(n).fill(0));\n    for (let i = 0; i < n; i++) {\n        dp[i][i] = 1;\n    }\n    for (let len = 2; len <= n; len++) {\n        for (let i = 0; i + len - 1 < n; i++) {\n            const j = i + len - 1;\n            if (s[i] === s[j]) {\n                dp[i][j] = dp[i + 1][j - 1] + 2;\n            } else {\n                dp[i][j] = Math.max(dp[i + 1][j], dp[i][j - 1]);\n            }\n        }\n    }\n    console.log(dp[0][n - 1]);\n    rl.close();\n});',NULL,1),
(158,'PYTHON','s = input().strip()\nn = len(s)\ndp = [[0] * n for _ in range(n)]\nfor i in range(n):\n    dp[i][i] = 1\nfor length in range(2, n + 1):\n    for i in range(n - length + 1):\n        j = i + length - 1\n        if s[i] == s[j]:\n            dp[i][j] = dp[i + 1][j - 1] + 2\n        else:\n            dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])\nprint(dp[0][n - 1])',NULL,1),
(159,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint cmp(const void *a, const void *b) {\n    return (*(int *)a - *(int *)b);\n}\n\nint main() {\n    int n1, n2;\n    scanf(\"%d\", &n1);\n    int *nums1 = (int *)malloc(n1 * sizeof(int));\n    for (int i = 0; i < n1; i++) {\n        scanf(\"%d\", &nums1[i]);\n    }\n    scanf(\"%d\", &n2);\n    int *nums2 = (int *)malloc(n2 * sizeof(int));\n    for (int i = 0; i < n2; i++) {\n        scanf(\"%d\", &nums2[i]);\n    }\n\n    qsort(nums1, n1, sizeof(int), cmp);\n    qsort(nums2, n2, sizeof(int), cmp);\n\n    int *res = (int *)malloc((n1 < n2 ? n1 : n2) * sizeof(int));\n    int i = 0, j = 0, k = 0;\n    while (i < n1 && j < n2) {\n        if (nums1[i] < nums2[j]) {\n            i++;\n        } else if (nums1[i] > nums2[j]) {\n            j++;\n        } else {\n            res[k++] = nums1[i];\n            i++;\n            j++;\n        }\n    }\n\n    printf(\"[\");\n    for (int t = 0; t < k; t++) {\n        printf(\"%d\", res[t]);\n        if (t != k - 1) {\n            printf(\",\");\n        }\n    }\n    printf(\"]\\n\");\n\n    free(nums1);\n    free(nums2);\n    free(res);\n    return 0;\n}',NULL,1),
(159,'CPP','#include <iostream>\n#include <vector>\n#include <unordered_map>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n1;\n    cin >> n1;\n    vector<int> nums1(n1);\n    for (int i = 0; i < n1; i++) {\n        cin >> nums1[i];\n    }\n\n    int n2;\n    cin >> n2;\n    vector<int> nums2(n2);\n    for (int i = 0; i < n2; i++) {\n        cin >> nums2[i];\n    }\n\n    unordered_map<int, int> map;\n    for (int num : nums1) {\n        map[num]++;\n    }\n\n    vector<int> res;\n    for (int num : nums2) {\n        if (map[num] > 0) {\n            res.push_back(num);\n            map[num]--;\n        }\n    }\n\n    sort(res.begin(), res.end());\n\n    cout << \"[\";\n    for (int i = 0; i < (int)res.size(); i++) {\n        cout << res[i];\n        if (i != (int)res.size() - 1) {\n            cout << \",\";\n        }\n    }\n    cout << \"]\" << endl;\n\n    return 0;\n}',NULL,1),
(159,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n1 = sc.nextInt();\n        int[] nums1 = new int[n1];\n        for (int i = 0; i < n1; i++) {\n            nums1[i] = sc.nextInt();\n        }\n        int n2 = sc.nextInt();\n        int[] nums2 = new int[n2];\n        for (int i = 0; i < n2; i++) {\n            nums2[i] = sc.nextInt();\n        }\n\n        Map<Integer, Integer> map = new HashMap<>();\n        for (int num : nums1) {\n            map.put(num, map.getOrDefault(num, 0) + 1);\n        }\n\n        List<Integer> res = new ArrayList<>();\n        for (int num : nums2) {\n            if (map.getOrDefault(num, 0) > 0) {\n                res.add(num);\n                map.put(num, map.get(num) - 1);\n            }\n        }\n\n        Collections.sort(res);\n\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < res.size(); i++) {\n            sb.append(res.get(i));\n            if (i != res.size() - 1) {\n                sb.append(\",\");\n            }\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n}',NULL,1),
(159,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n1 = parseInt(lines[0]);\n    const nums1 = lines[1].split(\' \').map(Number);\n    const n2 = parseInt(lines[2]);\n    const nums2 = lines[3].split(\' \').map(Number);\n\n    const map = new Map();\n    for (const num of nums1) {\n        map.set(num, (map.get(num) || 0) + 1);\n    }\n\n    const res = [];\n    for (const num of nums2) {\n        if ((map.get(num) || 0) > 0) {\n            res.push(num);\n            map.set(num, map.get(num) - 1);\n        }\n    }\n\n    res.sort((a, b) => a - b);\n\n    let sb = \'[\';\n    for (let i = 0; i < res.length; i++) {\n        sb += res[i];\n        if (i !== res.length - 1) {\n            sb += \',\';\n        }\n    }\n    sb += \']\';\n    console.log(sb);\n});',NULL,1),
(159,'PYTHON','import sys\nfrom collections import Counter\n\ndef main():\n    data = sys.stdin.read().split()\n    if not data:\n        return\n    idx = 0\n    n1 = int(data[idx]); idx += 1\n    nums1 = list(map(int, data[idx:idx+n1])); idx += n1\n    n2 = int(data[idx]); idx += 1\n    nums2 = list(map(int, data[idx:idx+n2])); idx += n2\n\n    count = Counter(nums1)\n    res = []\n    for num in nums2:\n        if count.get(num, 0) > 0:\n            res.append(num)\n            count[num] -= 1\n\n    res.sort()\n    print(\"[\" + \",\".join(map(str, res)) + \"]\")\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(160,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n\ntypedef struct ListNode {\n    int val;\n    struct ListNode *next;\n} ListNode;\n\nListNode* parseList(const char *s) {\n    if (s == NULL || s[0] == \'\\0\' || strcmp(s, \"NULL\") == 0) {\n        return NULL;\n    }\n    char *copy = strdup(s);\n    ListNode dummy = {0, NULL};\n    ListNode *cur = &dummy;\n    char *token = strtok(copy, \"->\");\n    while (token != NULL) {\n        if (strcmp(token, \"NULL\") == 0) {\n            break;\n        }\n        ListNode *node = (ListNode*)malloc(sizeof(ListNode));\n        node->val = atoi(token);\n        node->next = NULL;\n        cur->next = node;\n        cur = cur->next;\n        token = strtok(NULL, \"->\");\n    }\n    free(copy);\n    return dummy.next;\n}\n\nchar* formatList(ListNode *head) {\n    char *buf = (char*)malloc(100000);\n    buf[0] = \'\\0\';\n    ListNode *cur = head;\n    char temp[32];\n    while (cur != NULL) {\n        sprintf(temp, \"%d->\", cur->val);\n        strcat(buf, temp);\n        cur = cur->next;\n    }\n    strcat(buf, \"NULL\");\n    return buf;\n}\n\nListNode* addTwoNumbers(ListNode *l1, ListNode *l2) {\n    ListNode dummy = {0, NULL};\n    ListNode *cur = &dummy;\n    int carry = 0;\n    while (l1 != NULL || l2 != NULL || carry != 0) {\n        int x = (l1 != NULL) ? l1->val : 0;\n        int y = (l2 != NULL) ? l2->val : 0;\n        int sum = x + y + carry;\n        carry = sum / 10;\n        ListNode *node = (ListNode*)malloc(sizeof(ListNode));\n        node->val = sum % 10;\n        node->next = NULL;\n        cur->next = node;\n        cur = cur->next;\n        if (l1 != NULL) l1 = l1->next;\n        if (l2 != NULL) l2 = l2->next;\n    }\n    return dummy.next;\n}\n\nint main() {\n    char line1[100000];\n    char line2[100000];\n    if (fgets(line1, sizeof(line1), stdin) == NULL) return 0;\n    if (fgets(line2, sizeof(line2), stdin) == NULL) return 0;\n    line1[strcspn(line1, \"\\r\\n\")] = \'\\0\';\n    line2[strcspn(line2, \"\\r\\n\")] = \'\\0\';\n\n    ListNode *l1 = parseList(line1);\n    ListNode *l2 = parseList(line2);\n\n    ListNode *result = addTwoNumbers(l1, l2);\n    char *out = formatList(result);\n    printf(\"%s\\n\", out);\n\n    free(out);\n    return 0;\n}',NULL,1),
(160,'CPP','#include <iostream>\n#include <string>\n#include <sstream>\nusing namespace std;\n\nstruct ListNode {\n    int val;\n    ListNode* next;\n    ListNode(int x) : val(x), next(nullptr) {}\n};\n\nListNode* parseList(const string& s) {\n    if (s.empty() || s == \"NULL\") return nullptr;\n    string str = s;\n    string token;\n    stringstream ss(str);\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    while (getline(ss, token, \'-\')) {\n        if (token.empty() || token == \">\") continue;\n        if (token == \">NULL\" || token == \"NULL\") break;\n        if (token[0] == \'>\') token = token.substr(1);\n        if (token == \"NULL\") break;\n        cur->next = new ListNode(stoi(token));\n        cur = cur->next;\n    }\n    return dummy.next;\n}\n\nstring formatList(ListNode* head) {\n    string res;\n    ListNode* cur = head;\n    while (cur) {\n        res += to_string(cur->val) + \"->\";\n        cur = cur->next;\n    }\n    res += \"NULL\";\n    return res;\n}\n\nListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {\n    ListNode dummy(0);\n    ListNode* cur = &dummy;\n    int carry = 0;\n    while (l1 || l2 || carry) {\n        int x = l1 ? l1->val : 0;\n        int y = l2 ? l2->val : 0;\n        int sum = x + y + carry;\n        carry = sum / 10;\n        cur->next = new ListNode(sum % 10);\n        cur = cur->next;\n        if (l1) l1 = l1->next;\n        if (l2) l2 = l2->next;\n    }\n    return dummy.next;\n}\n\nint main() {\n    string line1, line2;\n    getline(cin, line1);\n    getline(cin, line2);\n\n    ListNode* l1 = parseList(line1);\n    ListNode* l2 = parseList(line2);\n\n    ListNode* result = addTwoNumbers(l1, l2);\n    cout << formatList(result) << endl;\n\n    return 0;\n}',NULL,1),
(160,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    static class ListNode {\n        int val;\n        ListNode next;\n        ListNode(int val) { this.val = val; }\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String line1 = sc.nextLine().trim();\n        String line2 = sc.nextLine().trim();\n\n        ListNode l1 = parseList(line1);\n        ListNode l2 = parseList(line2);\n\n        ListNode result = addTwoNumbers(l1, l2);\n        System.out.println(formatList(result));\n    }\n\n    private static ListNode parseList(String s) {\n        if (s == null || s.isEmpty() || s.equals(\"NULL\")) {\n            return null;\n        }\n        String[] parts = s.split(\"->\");\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        for (String part : parts) {\n            if (part.equals(\"NULL\")) {\n                break;\n            }\n            cur.next = new ListNode(Integer.parseInt(part.trim()));\n            cur = cur.next;\n        }\n        return dummy.next;\n    }\n\n    private static String formatList(ListNode head) {\n        StringBuilder sb = new StringBuilder();\n        ListNode cur = head;\n        while (cur != null) {\n            sb.append(cur.val).append(\"->\");\n            cur = cur.next;\n        }\n        sb.append(\"NULL\");\n        return sb.toString();\n    }\n\n    private static ListNode addTwoNumbers(ListNode l1, ListNode l2) {\n        ListNode dummy = new ListNode(0);\n        ListNode cur = dummy;\n        int carry = 0;\n        while (l1 != null || l2 != null || carry != 0) {\n            int x = (l1 != null) ? l1.val : 0;\n            int y = (l2 != null) ? l2.val : 0;\n            int sum = x + y + carry;\n            carry = sum / 10;\n            cur.next = new ListNode(sum % 10);\n            cur = cur.next;\n            if (l1 != null) l1 = l1.next;\n            if (l2 != null) l2 = l2.next;\n        }\n        return dummy.next;\n    }\n}',NULL,1),
(160,'JAVASCRIPT','const readline = require(\'readline\');\n\nclass ListNode {\n    constructor(val) {\n        this.val = val;\n        this.next = null;\n    }\n}\n\nfunction parseList(s) {\n    if (!s || s === \'NULL\') return null;\n    const parts = s.split(\'->\');\n    const dummy = new ListNode(0);\n    let cur = dummy;\n    for (const part of parts) {\n        if (part === \'NULL\') break;\n        cur.next = new ListNode(parseInt(part.trim(), 10));\n        cur = cur.next;\n    }\n    return dummy.next;\n}\n\nfunction formatList(head) {\n    let sb = \'\';\n    let cur = head;\n    while (cur !== null) {\n        sb += cur.val + \'->\';\n        cur = cur.next;\n    }\n    sb += \'NULL\';\n    return sb;\n}\n\nfunction addTwoNumbers(l1, l2) {\n    const dummy = new ListNode(0);\n    let cur = dummy;\n    let carry = 0;\n    while (l1 !== null || l2 !== null || carry !== 0) {\n        const x = l1 !== null ? l1.val : 0;\n        const y = l2 !== null ? l2.val : 0;\n        const sum = x + y + carry;\n        carry = Math.floor(sum / 10);\n        cur.next = new ListNode(sum % 10);\n        cur = cur.next;\n        if (l1 !== null) l1 = l1.next;\n        if (l2 !== null) l2 = l2.next;\n    }\n    return dummy.next;\n}\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nconst lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const l1 = parseList(lines[0]);\n        const l2 = parseList(lines[1]);\n        const result = addTwoNumbers(l1, l2);\n        console.log(formatList(result));\n        rl.close();\n    }\n});',NULL,1),
(160,'PYTHON','import sys\n\nclass ListNode:\n    def __init__(self, val=0):\n        self.val = val\n        self.next = None\n\ndef parse_list(s):\n    if s is None or s == \"\" or s == \"NULL\":\n        return None\n    parts = s.split(\"->\")\n    dummy = ListNode(0)\n    cur = dummy\n    for part in parts:\n        if part == \"NULL\":\n            break\n        cur.next = ListNode(int(part.strip()))\n        cur = cur.next\n    return dummy.next\n\ndef format_list(head):\n    sb = []\n    cur = head\n    while cur is not None:\n        sb.append(str(cur.val))\n        sb.append(\"->\")\n        cur = cur.next\n    sb.append(\"NULL\")\n    return \"\".join(sb)\n\ndef add_two_numbers(l1, l2):\n    dummy = ListNode(0)\n    cur = dummy\n    carry = 0\n    while l1 is not None or l2 is not None or carry != 0:\n        x = l1.val if l1 is not None else 0\n        y = l2.val if l2 is not None else 0\n        total = x + y + carry\n        carry = total // 10\n        cur.next = ListNode(total % 10)\n        cur = cur.next\n        if l1 is not None:\n            l1 = l1.next\n        if l2 is not None:\n            l2 = l2.next\n    return dummy.next\n\ndef main():\n    lines = sys.stdin.read().strip().splitlines()\n    line1 = lines[0].strip()\n    line2 = lines[1].strip()\n\n    l1 = parse_list(line1)\n    l2 = parse_list(line2)\n\n    result = add_two_numbers(l1, l2)\n    print(format_list(result))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(161,'C','#include <stdio.h>\n#include <stdlib.h>\n\ntypedef struct {\n    int *data;\n    int size;\n    int capacity;\n} HashSet;\n\nunsigned int hash(int x) {\n    return (unsigned int)x * 2654435761u;\n}\n\nHashSet* createHashSet(int capacity) {\n    HashSet *set = (HashSet*)malloc(sizeof(HashSet));\n    set->capacity = capacity;\n    set->size = 0;\n    set->data = (int*)calloc(capacity, sizeof(int));\n    for (int i = 0; i < capacity; i++) {\n        set->data[i] = 0;\n    }\n    return set;\n}\n\nvoid freeHashSet(HashSet *set) {\n    free(set->data);\n    free(set);\n}\n\nint contains(HashSet *set, int x) {\n    unsigned int h = hash(x) % set->capacity;\n    while (set->data[h] != 0) {\n        if (set->data[h] == x) return 1;\n        h = (h + 1) % set->capacity;\n    }\n    return 0;\n}\n\nvoid add(HashSet *set, int x) {\n    if (contains(set, x)) return;\n    unsigned int h = hash(x) % set->capacity;\n    while (set->data[h] != 0) {\n        h = (h + 1) % set->capacity;\n    }\n    set->data[h] = x;\n    set->size++;\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int *nums = (int*)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    HashSet *set = createHashSet(n * 2 + 1);\n    for (int i = 0; i < n; i++) {\n        add(set, nums[i]);\n    }\n\n    int maxLength = 0;\n    for (int i = 0; i < n; i++) {\n        int num = nums[i];\n        if (!contains(set, num - 1)) {\n            int currentNum = num;\n            int currentLength = 1;\n            while (contains(set, currentNum + 1)) {\n                currentNum++;\n                currentLength++;\n            }\n            if (currentLength > maxLength) {\n                maxLength = currentLength;\n            }\n        }\n    }\n\n    printf(\"%d\\n\", maxLength);\n\n    freeHashSet(set);\n    free(nums);\n    return 0;\n}',NULL,1),
(161,'CPP','#include <iostream>\n#include <vector>\n#include <unordered_set>\n#include <algorithm>\n\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n\n    unordered_set<int> set(nums.begin(), nums.end());\n\n    int maxLength = 0;\n    for (int num : set) {\n        if (set.find(num - 1) == set.end()) {\n            int currentNum = num;\n            int currentLength = 1;\n            while (set.find(currentNum + 1) != set.end()) {\n                currentNum++;\n                currentLength++;\n            }\n            maxLength = max(maxLength, currentLength);\n        }\n    }\n\n    cout << maxLength << endl;\n\n    return 0;\n}',NULL,1),
(161,'JAVA','import java.util.HashSet;\nimport java.util.Scanner;\nimport java.util.Set;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        int n = scanner.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = scanner.nextInt();\n        }\n        scanner.close();\n\n        Set<Integer> set = new HashSet<>();\n        for (int num : nums) {\n            set.add(num);\n        }\n\n        int maxLength = 0;\n        for (int num : set) {\n            if (!set.contains(num - 1)) {\n                int currentNum = num;\n                int currentLength = 1;\n                while (set.contains(currentNum + 1)) {\n                    currentNum++;\n                    currentLength++;\n                }\n                maxLength = Math.max(maxLength, currentLength);\n            }\n        }\n\n        System.out.println(maxLength);\n    }\n}',NULL,1),
(161,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n\n    const set = new Set(nums);\n\n    let maxLength = 0;\n    for (const num of set) {\n        if (!set.has(num - 1)) {\n            let currentNum = num;\n            let currentLength = 1;\n            while (set.has(currentNum + 1)) {\n                currentNum++;\n                currentLength++;\n            }\n            maxLength = Math.max(maxLength, currentLength);\n        }\n    }\n\n    console.log(maxLength);\n});',NULL,1),
(161,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\n\nnum_set = set(nums)\nmax_length = 0\n\nfor num in num_set:\n    if num - 1 not in num_set:\n        current_num = num\n        current_length = 1\n        while current_num + 1 in num_set:\n            current_num += 1\n            current_length += 1\n        max_length = max(max_length, current_length)\n\nprint(max_length)',NULL,1),
(162,'C','#include <stdio.h>\n\nint main() {\n    int m, n;\n    scanf(\"%d %d\", &m, &n);\n    int nums1[m + n];\n    int nums2[n];\n    for (int i = 0; i < m; i++) {\n        scanf(\"%d\", &nums1[i]);\n    }\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums2[i]);\n    }\n    int i = m - 1, j = n - 1, k = m + n - 1;\n    while (i >= 0 && j >= 0) {\n        if (nums1[i] > nums2[j]) {\n            nums1[k--] = nums1[i--];\n        } else {\n            nums1[k--] = nums2[j--];\n        }\n    }\n    while (j >= 0) {\n        nums1[k--] = nums2[j--];\n    }\n    for (int x = 0; x < m + n; x++) {\n        if (x > 0) printf(\" \");\n        printf(\"%d\", nums1[x]);\n    }\n    printf(\"\\n\");\n    return 0;\n}',NULL,1),
(162,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int m, n;\n    cin >> m >> n;\n    vector<int> nums1(m + n);\n    vector<int> nums2(n);\n    for (int i = 0; i < m; i++) {\n        cin >> nums1[i];\n    }\n    for (int i = 0; i < n; i++) {\n        cin >> nums2[i];\n    }\n    int i = m - 1, j = n - 1, k = m + n - 1;\n    while (i >= 0 && j >= 0) {\n        if (nums1[i] > nums2[j]) {\n            nums1[k--] = nums1[i--];\n        } else {\n            nums1[k--] = nums2[j--];\n        }\n    }\n    while (j >= 0) {\n        nums1[k--] = nums2[j--];\n    }\n    for (int x = 0; x < m + n; x++) {\n        if (x > 0) cout << \' \';\n        cout << nums1[x];\n    }\n    cout << endl;\n    return 0;\n}',NULL,1),
(162,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n        int[] nums1 = new int[m + n];\n        int[] nums2 = new int[n];\n        for (int i = 0; i < m; i++) {\n            nums1[i] = sc.nextInt();\n        }\n        for (int i = 0; i < n; i++) {\n            nums2[i] = sc.nextInt();\n        }\n        int i = m - 1, j = n - 1, k = m + n - 1;\n        while (i >= 0 && j >= 0) {\n            if (nums1[i] > nums2[j]) {\n                nums1[k--] = nums1[i--];\n            } else {\n                nums1[k--] = nums2[j--];\n            }\n        }\n        while (j >= 0) {\n            nums1[k--] = nums2[j--];\n        }\n        StringBuilder sb = new StringBuilder();\n        for (int x = 0; x < m + n; x++) {\n            if (x > 0) sb.append(\' \');\n            sb.append(nums1[x]);\n        }\n        System.out.println(sb.toString());\n    }\n}',NULL,1),
(162,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const [m, n] = lines[0].split(\' \').map(Number);\n    const nums1 = new Array(m + n).fill(0);\n    const nums2 = new Array(n).fill(0);\n\n    if (m > 0) {\n        const arr1 = lines[1].split(\' \').map(Number);\n        for (let i = 0; i < m; i++) {\n            nums1[i] = arr1[i];\n        }\n    }\n\n    if (n > 0) {\n        const arr2 = lines[2].split(\' \').map(Number);\n        for (let i = 0; i < n; i++) {\n            nums2[i] = arr2[i];\n        }\n    }\n\n    let i = m - 1, j = n - 1, k = m + n - 1;\n    while (i >= 0 && j >= 0) {\n        if (nums1[i] > nums2[j]) {\n            nums1[k--] = nums1[i--];\n        } else {\n            nums1[k--] = nums2[j--];\n        }\n    }\n    while (j >= 0) {\n        nums1[k--] = nums2[j--];\n    }\n\n    let result = \'\';\n    for (let x = 0; x < m + n; x++) {\n        if (x > 0) result += \' \';\n        result += nums1[x];\n    }\n    console.log(result);\n});',NULL,1),
(162,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().split()\n    if not data:\n        return\n    m = int(data[0])\n    n = int(data[1])\n    nums1 = [0] * (m + n)\n    nums2 = [0] * n\n    idx = 2\n    for i in range(m):\n        nums1[i] = int(data[idx])\n        idx += 1\n    for i in range(n):\n        nums2[i] = int(data[idx])\n        idx += 1\n\n    i = m - 1\n    j = n - 1\n    k = m + n - 1\n    while i >= 0 and j >= 0:\n        if nums1[i] > nums2[j]:\n            nums1[k] = nums1[i]\n            i -= 1\n        else:\n            nums1[k] = nums2[j]\n            j -= 1\n        k -= 1\n    while j >= 0:\n        nums1[k] = nums2[j]\n        j -= 1\n        k -= 1\n\n    print(\' \'.join(map(str, nums1)))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(163,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n\n    int **matrix = (int **)malloc(n * sizeof(int *));\n    for (int i = 0; i < n; i++) {\n        matrix[i] = (int *)malloc(n * sizeof(int));\n    }\n\n    int top = 0, bottom = n - 1, left = 0, right = n - 1;\n    int num = 1;\n\n    while (num <= n * n) {\n        for (int i = left; i <= right; i++) {\n            matrix[top][i] = num++;\n        }\n        top++;\n        for (int i = top; i <= bottom; i++) {\n            matrix[i][right] = num++;\n        }\n        right--;\n        for (int i = right; i >= left; i--) {\n            matrix[bottom][i] = num++;\n        }\n        bottom--;\n        for (int i = bottom; i >= top; i--) {\n            matrix[i][left] = num++;\n        }\n        left++;\n    }\n\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < n; j++) {\n            printf(\"%d\", matrix[i][j]);\n            if (j < n - 1) {\n                printf(\" \");\n            }\n        }\n        printf(\"\\n\");\n    }\n\n    for (int i = 0; i < n; i++) {\n        free(matrix[i]);\n    }\n    free(matrix);\n\n    return 0;\n}',NULL,1),
(163,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<vector<int>> matrix(n, vector<int>(n));\n    int top = 0, bottom = n - 1, left = 0, right = n - 1;\n    int num = 1;\n    while (num <= n * n) {\n        for (int i = left; i <= right; i++) {\n            matrix[top][i] = num++;\n        }\n        top++;\n        for (int i = top; i <= bottom; i++) {\n            matrix[i][right] = num++;\n        }\n        right--;\n        for (int i = right; i >= left; i--) {\n            matrix[bottom][i] = num++;\n        }\n        bottom--;\n        for (int i = bottom; i >= top; i--) {\n            matrix[i][left] = num++;\n        }\n        left++;\n    }\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < n; j++) {\n            cout << matrix[i][j];\n            if (j < n - 1) {\n                cout << \' \';\n            }\n        }\n        cout << \'\\n\';\n    }\n    return 0;\n}',NULL,1),
(163,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[][] matrix = new int[n][n];\n        int top = 0, bottom = n - 1, left = 0, right = n - 1;\n        int num = 1;\n        while (num <= n * n) {\n            for (int i = left; i <= right; i++) {\n                matrix[top][i] = num++;\n            }\n            top++;\n            for (int i = top; i <= bottom; i++) {\n                matrix[i][right] = num++;\n            }\n            right--;\n            for (int i = right; i >= left; i--) {\n                matrix[bottom][i] = num++;\n            }\n            bottom--;\n            for (int i = bottom; i >= top; i--) {\n                matrix[i][left] = num++;\n            }\n            left++;\n        }\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < n; i++) {\n            for (int j = 0; j < n; j++) {\n                sb.append(matrix[i][j]);\n                if (j < n - 1) {\n                    sb.append(\' \');\n                }\n            }\n            sb.append(\'\\n\');\n        }\n        System.out.print(sb);\n    }\n}',NULL,1),
(163,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (line) => {\n    const n = parseInt(line.trim());\n    const matrix = Array.from({ length: n }, () => new Array(n).fill(0));\n    let top = 0, bottom = n - 1, left = 0, right = n - 1;\n    let num = 1;\n    while (num <= n * n) {\n        for (let i = left; i <= right; i++) {\n            matrix[top][i] = num++;\n        }\n        top++;\n        for (let i = top; i <= bottom; i++) {\n            matrix[i][right] = num++;\n        }\n        right--;\n        for (let i = right; i >= left; i--) {\n            matrix[bottom][i] = num++;\n        }\n        bottom--;\n        for (let i = bottom; i >= top; i--) {\n            matrix[i][left] = num++;\n        }\n        left++;\n    }\n    let sb = \'\';\n    for (let i = 0; i < n; i++) {\n        for (let j = 0; j < n; j++) {\n            sb += matrix[i][j];\n            if (j < n - 1) {\n                sb += \' \';\n            }\n        }\n        sb += \'\\n\';\n    }\n    process.stdout.write(sb);\n    rl.close();\n});',NULL,1),
(163,'PYTHON','n = int(input())\nmatrix = [[0] * n for _ in range(n)]\ntop, bottom, left, right = 0, n - 1, 0, n - 1\nnum = 1\nwhile num <= n * n:\n    for i in range(left, right + 1):\n        matrix[top][i] = num\n        num += 1\n    top += 1\n    for i in range(top, bottom + 1):\n        matrix[i][right] = num\n        num += 1\n    right -= 1\n    for i in range(right, left - 1, -1):\n        matrix[bottom][i] = num\n        num += 1\n    bottom -= 1\n    for i in range(bottom, top - 1, -1):\n        matrix[i][left] = num\n        num += 1\n    left += 1\n\nfor i in range(n):\n    print(\' \'.join(map(str, matrix[i])))',NULL,1),
(164,'C','#include <stdio.h>\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int nums[n];\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n    int jumps = 0;\n    int currentEnd = 0;\n    int farthest = 0;\n    for (int i = 0; i < n - 1; i++) {\n        if (i + nums[i] > farthest) {\n            farthest = i + nums[i];\n        }\n        if (i == currentEnd) {\n            jumps++;\n            currentEnd = farthest;\n        }\n    }\n    printf(\"%d\\n\", jumps);\n    return 0;\n}',NULL,1),
(164,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n    int jumps = 0;\n    int currentEnd = 0;\n    int farthest = 0;\n    for (int i = 0; i < n - 1; i++) {\n        farthest = max(farthest, i + nums[i]);\n        if (i == currentEnd) {\n            jumps++;\n            currentEnd = farthest;\n        }\n    }\n    cout << jumps << endl;\n    return 0;\n}',NULL,1),
(164,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n        int jumps = 0;\n        int currentEnd = 0;\n        int farthest = 0;\n        for (int i = 0; i < n - 1; i++) {\n            farthest = Math.max(farthest, i + nums[i]);\n            if (i == currentEnd) {\n                jumps++;\n                currentEnd = farthest;\n            }\n        }\n        System.out.println(jumps);\n    }\n}',NULL,1),
(164,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0]);\n    const nums = lines[1].split(\' \').map(Number);\n    let jumps = 0;\n    let currentEnd = 0;\n    let farthest = 0;\n    for (let i = 0; i < n - 1; i++) {\n        farthest = Math.max(farthest, i + nums[i]);\n        if (i === currentEnd) {\n            jumps++;\n            currentEnd = farthest;\n        }\n    }\n    console.log(jumps);\n});',NULL,1),
(164,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\njumps = 0\ncurrent_end = 0\nfarthest = 0\nfor i in range(n - 1):\n    farthest = max(farthest, i + nums[i])\n    if i == current_end:\n        jumps += 1\n        current_end = farthest\nprint(jumps)',NULL,1),
(165,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint cmp(const void *a, const void *b) {\n    return (*(int *)a - *(int *)b);\n}\n\nint main() {\n    int n;\n    scanf(\"%d\", &n);\n    int *nums = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &nums[i]);\n    }\n\n    int cand1 = 0, cand2 = 0;\n    int count1 = 0, count2 = 0;\n\n    for (int i = 0; i < n; i++) {\n        int num = nums[i];\n        if (num == cand1) {\n            count1++;\n        } else if (num == cand2) {\n            count2++;\n        } else if (count1 == 0) {\n            cand1 = num;\n            count1 = 1;\n        } else if (count2 == 0) {\n            cand2 = num;\n            count2 = 1;\n        } else {\n            count1--;\n            count2--;\n        }\n    }\n\n    count1 = 0;\n    count2 = 0;\n    for (int i = 0; i < n; i++) {\n        if (nums[i] == cand1) count1++;\n        else if (nums[i] == cand2) count2++;\n    }\n\n    int result[2];\n    int size = 0;\n    if (count1 > n / 3) result[size++] = cand1;\n    if (count2 > n / 3) result[size++] = cand2;\n\n    qsort(result, size, sizeof(int), cmp);\n\n    printf(\"[\");\n    for (int i = 0; i < size; i++) {\n        if (i > 0) printf(\",\");\n        printf(\"%d\", result[i]);\n    }\n    printf(\"]\\n\");\n\n    free(nums);\n    return 0;\n}',NULL,1),
(165,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n;\n    cin >> n;\n    vector<int> nums(n);\n    for (int i = 0; i < n; i++) {\n        cin >> nums[i];\n    }\n\n    int cand1 = 0, cand2 = 0;\n    int count1 = 0, count2 = 0;\n\n    for (int num : nums) {\n        if (num == cand1) {\n            count1++;\n        } else if (num == cand2) {\n            count2++;\n        } else if (count1 == 0) {\n            cand1 = num;\n            count1 = 1;\n        } else if (count2 == 0) {\n            cand2 = num;\n            count2 = 1;\n        } else {\n            count1--;\n            count2--;\n        }\n    }\n\n    count1 = 0;\n    count2 = 0;\n    for (int num : nums) {\n        if (num == cand1) count1++;\n        else if (num == cand2) count2++;\n    }\n\n    vector<int> result;\n    if (count1 > n / 3) result.push_back(cand1);\n    if (count2 > n / 3) result.push_back(cand2);\n\n    sort(result.begin(), result.end());\n\n    cout << \"[\";\n    for (int i = 0; i < (int)result.size(); i++) {\n        if (i > 0) cout << \",\";\n        cout << result[i];\n    }\n    cout << \"]\" << endl;\n\n    return 0;\n}',NULL,1),
(165,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int n = sc.nextInt();\n        int[] nums = new int[n];\n        for (int i = 0; i < n; i++) {\n            nums[i] = sc.nextInt();\n        }\n\n        int cand1 = 0, cand2 = 0;\n        int count1 = 0, count2 = 0;\n\n        for (int num : nums) {\n            if (num == cand1) {\n                count1++;\n            } else if (num == cand2) {\n                count2++;\n            } else if (count1 == 0) {\n                cand1 = num;\n                count1 = 1;\n            } else if (count2 == 0) {\n                cand2 = num;\n                count2 = 1;\n            } else {\n                count1--;\n                count2--;\n            }\n        }\n\n        count1 = 0;\n        count2 = 0;\n        for (int num : nums) {\n            if (num == cand1) count1++;\n            else if (num == cand2) count2++;\n        }\n\n        List<Integer> result = new ArrayList<>();\n        if (count1 > n / 3) result.add(cand1);\n        if (count2 > n / 3) result.add(cand2);\n\n        Collections.sort(result);\n\n        StringBuilder sb = new StringBuilder();\n        sb.append(\"[\");\n        for (int i = 0; i < result.size(); i++) {\n            if (i > 0) sb.append(\",\");\n            sb.append(result.get(i));\n        }\n        sb.append(\"]\");\n        System.out.println(sb.toString());\n    }\n}',NULL,1),
(165,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n  input: process.stdin,\n  output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n  lines.push(line.trim());\n});\n\nrl.on(\'close\', () => {\n  const n = parseInt(lines[0]);\n  const nums = lines[1].split(/\\s+/).map(Number);\n\n  let cand1 = 0, cand2 = 0;\n  let count1 = 0, count2 = 0;\n\n  for (let num of nums) {\n    if (num === cand1) {\n      count1++;\n    } else if (num === cand2) {\n      count2++;\n    } else if (count1 === 0) {\n      cand1 = num;\n      count1 = 1;\n    } else if (count2 === 0) {\n      cand2 = num;\n      count2 = 1;\n    } else {\n      count1--;\n      count2--;\n    }\n  }\n\n  count1 = 0;\n  count2 = 0;\n  for (let num of nums) {\n    if (num === cand1) count1++;\n    else if (num === cand2) count2++;\n  }\n\n  let result = [];\n  if (count1 > Math.floor(n / 3)) result.push(cand1);\n  if (count2 > Math.floor(n / 3)) result.push(cand2);\n\n  result.sort((a, b) => a - b);\n\n  console.log(\'[\' + result.join(\',\') + \']\');\n});',NULL,1),
(165,'PYTHON','n = int(input())\nnums = list(map(int, input().split()))\n\ncand1, cand2 = 0, 0\ncount1, count2 = 0, 0\n\nfor num in nums:\n    if num == cand1:\n        count1 += 1\n    elif num == cand2:\n        count2 += 1\n    elif count1 == 0:\n        cand1 = num\n        count1 = 1\n    elif count2 == 0:\n        cand2 = num\n        count2 = 1\n    else:\n        count1 -= 1\n        count2 -= 1\n\ncount1 = 0\ncount2 = 0\nfor num in nums:\n    if num == cand1:\n        count1 += 1\n    elif num == cand2:\n        count2 += 1\n\nresult = []\nif count1 > n // 3:\n    result.append(cand1)\nif count2 > n // 3:\n    result.append(cand2)\n\nresult.sort()\n\nprint(\"[\" + \",\".join(map(str, result)) + \"]\")',NULL,1),
(166,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint main() {\n    int m, n;\n    scanf(\"%d %d\", &m, &n);\n    \n    int **board = (int **)malloc(m * sizeof(int *));\n    for (int i = 0; i < m; i++) {\n        board[i] = (int *)malloc(n * sizeof(int));\n    }\n    \n    char *line = (char *)malloc((n + 2) * sizeof(char));\n    for (int i = 0; i < m; i++) {\n        scanf(\"%s\", line);\n        for (int j = 0; j < n; j++) {\n            board[i][j] = line[j] - \'0\';\n        }\n    }\n    \n    int **next = (int **)malloc(m * sizeof(int *));\n    for (int i = 0; i < m; i++) {\n        next[i] = (int *)malloc(n * sizeof(int));\n    }\n    \n    int dx[] = {-1, -1, -1, 0, 0, 1, 1, 1};\n    int dy[] = {-1, 0, 1, -1, 1, -1, 0, 1};\n    \n    for (int i = 0; i < m; i++) {\n        for (int j = 0; j < n; j++) {\n            int liveNeighbors = 0;\n            for (int k = 0; k < 8; k++) {\n                int ni = i + dx[k];\n                int nj = j + dy[k];\n                if (ni >= 0 && ni < m && nj >= 0 && nj < n) {\n                    liveNeighbors += board[ni][nj];\n                }\n            }\n            if (board[i][j] == 1) {\n                if (liveNeighbors == 2 || liveNeighbors == 3) {\n                    next[i][j] = 1;\n                } else {\n                    next[i][j] = 0;\n                }\n            } else {\n                if (liveNeighbors == 3) {\n                    next[i][j] = 1;\n                } else {\n                    next[i][j] = 0;\n                }\n            }\n        }\n    }\n    \n    for (int i = 0; i < m; i++) {\n        for (int j = 0; j < n; j++) {\n            printf(\"%d\", next[i][j]);\n        }\n        if (i < m - 1) {\n            printf(\"\\n\");\n        }\n    }\n    \n    for (int i = 0; i < m; i++) {\n        free(board[i]);\n        free(next[i]);\n    }\n    free(board);\n    free(next);\n    free(line);\n    \n    return 0;\n}',NULL,1),
(166,'CPP','#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\n\nint main() {\n    int m, n;\n    cin >> m >> n;\n    cin.ignore();\n    vector<vector<int>> board(m, vector<int>(n));\n    for (int i = 0; i < m; i++) {\n        string line;\n        getline(cin, line);\n        while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\' || line.back() == \' \')) {\n            line.pop_back();\n        }\n        for (int j = 0; j < n; j++) {\n            board[i][j] = line[j] - \'0\';\n        }\n    }\n\n    vector<vector<int>> next(m, vector<int>(n));\n    int dx[8] = {-1, -1, -1, 0, 0, 1, 1, 1};\n    int dy[8] = {-1, 0, 1, -1, 1, -1, 0, 1};\n\n    for (int i = 0; i < m; i++) {\n        for (int j = 0; j < n; j++) {\n            int liveNeighbors = 0;\n            for (int k = 0; k < 8; k++) {\n                int ni = i + dx[k];\n                int nj = j + dy[k];\n                if (ni >= 0 && ni < m && nj >= 0 && nj < n) {\n                    liveNeighbors += board[ni][nj];\n                }\n            }\n            if (board[i][j] == 1) {\n                if (liveNeighbors == 2 || liveNeighbors == 3) {\n                    next[i][j] = 1;\n                } else {\n                    next[i][j] = 0;\n                }\n            } else {\n                if (liveNeighbors == 3) {\n                    next[i][j] = 1;\n                } else {\n                    next[i][j] = 0;\n                }\n            }\n        }\n    }\n\n    for (int i = 0; i < m; i++) {\n        for (int j = 0; j < n; j++) {\n            cout << next[i][j];\n        }\n        if (i < m - 1) {\n            cout << \'\\n\';\n        }\n    }\n    return 0;\n}',NULL,1),
(166,'JAVA','import java.util.Scanner;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n        sc.nextLine();\n        int[][] board = new int[m][n];\n        for (int i = 0; i < m; i++) {\n            String line = sc.nextLine().trim();\n            for (int j = 0; j < n; j++) {\n                board[i][j] = line.charAt(j) - \'0\';\n            }\n        }\n\n        int[][] next = new int[m][n];\n        int[] dx = {-1, -1, -1, 0, 0, 1, 1, 1};\n        int[] dy = {-1, 0, 1, -1, 1, -1, 0, 1};\n\n        for (int i = 0; i < m; i++) {\n            for (int j = 0; j < n; j++) {\n                int liveNeighbors = 0;\n                for (int k = 0; k < 8; k++) {\n                    int ni = i + dx[k];\n                    int nj = j + dy[k];\n                    if (ni >= 0 && ni < m && nj >= 0 && nj < n) {\n                        liveNeighbors += board[ni][nj];\n                    }\n                }\n                if (board[i][j] == 1) {\n                    if (liveNeighbors == 2 || liveNeighbors == 3) {\n                        next[i][j] = 1;\n                    } else {\n                        next[i][j] = 0;\n                    }\n                } else {\n                    if (liveNeighbors == 3) {\n                        next[i][j] = 1;\n                    } else {\n                        next[i][j] = 0;\n                    }\n                }\n            }\n        }\n\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < m; i++) {\n            for (int j = 0; j < n; j++) {\n                sb.append(next[i][j]);\n            }\n            if (i < m - 1) {\n                sb.append(\'\\n\');\n            }\n        }\n        System.out.print(sb.toString());\n    }\n}',NULL,1),
(166,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n});\n\nrl.on(\'close\', () => {\n    const firstLine = lines[0].trim().split(/\\s+/);\n    const m = parseInt(firstLine[0], 10);\n    const n = parseInt(firstLine[1], 10);\n\n    const board = [];\n    for (let i = 0; i < m; i++) {\n        const line = lines[i + 1].trim();\n        const row = [];\n        for (let j = 0; j < n; j++) {\n            row.push(line.charCodeAt(j) - 48);\n        }\n        board.push(row);\n    }\n\n    const next = [];\n    for (let i = 0; i < m; i++) {\n        next.push(new Array(n).fill(0));\n    }\n\n    const dx = [-1, -1, -1, 0, 0, 1, 1, 1];\n    const dy = [-1, 0, 1, -1, 1, -1, 0, 1];\n\n    for (let i = 0; i < m; i++) {\n        for (let j = 0; j < n; j++) {\n            let liveNeighbors = 0;\n            for (let k = 0; k < 8; k++) {\n                const ni = i + dx[k];\n                const nj = j + dy[k];\n                if (ni >= 0 && ni < m && nj >= 0 && nj < n) {\n                    liveNeighbors += board[ni][nj];\n                }\n            }\n            if (board[i][j] === 1) {\n                if (liveNeighbors === 2 || liveNeighbors === 3) {\n                    next[i][j] = 1;\n                } else {\n                    next[i][j] = 0;\n                }\n            } else {\n                if (liveNeighbors === 3) {\n                    next[i][j] = 1;\n                } else {\n                    next[i][j] = 0;\n                }\n            }\n        }\n    }\n\n    let sb = \'\';\n    for (let i = 0; i < m; i++) {\n        for (let j = 0; j < n; j++) {\n            sb += next[i][j];\n        }\n        if (i < m - 1) {\n            sb += \'\\n\';\n        }\n    }\n    process.stdout.write(sb);\n});',NULL,1),
(166,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().splitlines()\n    if not data:\n        return\n    m, n = map(int, data[0].split())\n    board = []\n    for i in range(1, m + 1):\n        line = data[i].strip()\n        board.append([int(c) for c in line])\n\n    next_board = [[0] * n for _ in range(m)]\n    dx = [-1, -1, -1, 0, 0, 1, 1, 1]\n    dy = [-1, 0, 1, -1, 1, -1, 0, 1]\n\n    for i in range(m):\n        for j in range(n):\n            live_neighbors = 0\n            for k in range(8):\n                ni = i + dx[k]\n                nj = j + dy[k]\n                if 0 <= ni < m and 0 <= nj < n:\n                    live_neighbors += board[ni][nj]\n            if board[i][j] == 1:\n                if live_neighbors == 2 or live_neighbors == 3:\n                    next_board[i][j] = 1\n                else:\n                    next_board[i][j] = 0\n            else:\n                if live_neighbors == 3:\n                    next_board[i][j] = 1\n                else:\n                    next_board[i][j] = 0\n\n    output = []\n    for i in range(m):\n        output.append(\'\'.join(str(x) for x in next_board[i]))\n    sys.stdout.write(\'\\n\'.join(output))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(167,'C','#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <ctype.h>\n\nint main() {\n    char s[1000005];\n    if (fgets(s, sizeof(s), stdin) == NULL) return 0;\n    int len = strlen(s);\n    while (len > 0 && (s[len-1] == \'\\n\' || s[len-1] == \'\\r\')) {\n        s[--len] = \'\\0\';\n    }\n\n    int *stack = (int *)malloc(sizeof(int) * (len + 1));\n    int top = 0;\n    int num = 0;\n    char op = \'+\';\n\n    for (int i = 0; i < len; i++) {\n        char c = s[i];\n        if (isdigit((unsigned char)c)) {\n            num = num * 10 + (c - \'0\');\n        }\n        if ((!isdigit((unsigned char)c) && c != \' \') || i == len - 1) {\n            if (op == \'+\') {\n                stack[top++] = num;\n            } else if (op == \'-\') {\n                stack[top++] = -num;\n            } else if (op == \'*\') {\n                stack[top - 1] *= num;\n            } else if (op == \'/\') {\n                stack[top - 1] /= num;\n            }\n            op = c;\n            num = 0;\n        }\n    }\n\n    int res = 0;\n    for (int i = 0; i < top; i++) {\n        res += stack[i];\n    }\n    printf(\"%d\\n\", res);\n\n    free(stack);\n    return 0;\n}',NULL,1),
(167,'CPP','#include <iostream>\n#include <string>\n#include <stack>\nusing namespace std;\n\nint main() {\n    string s;\n    getline(cin, s);\n    stack<int> st;\n    int num = 0;\n    char op = \'+\';\n    for (int i = 0; i < (int)s.length(); i++) {\n        char c = s[i];\n        if (isdigit(c)) {\n            num = num * 10 + (c - \'0\');\n        }\n        if ((!isdigit(c) && c != \' \') || i == (int)s.length() - 1) {\n            if (op == \'+\') {\n                st.push(num);\n            } else if (op == \'-\') {\n                st.push(-num);\n            } else if (op == \'*\') {\n                int top = st.top();\n                st.pop();\n                st.push(top * num);\n            } else if (op == \'/\') {\n                int top = st.top();\n                st.pop();\n                st.push(top / num);\n            }\n            op = c;\n            num = 0;\n        }\n    }\n    int res = 0;\n    while (!st.empty()) {\n        res += st.top();\n        st.pop();\n    }\n    cout << res << endl;\n    return 0;\n}',NULL,1),
(167,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        String s = sc.nextLine();\n        Deque<Integer> stack = new ArrayDeque<>();\n        int num = 0;\n        char op = \'+\';\n        for (int i = 0; i < s.length(); i++) {\n            char c = s.charAt(i);\n            if (Character.isDigit(c)) {\n                num = num * 10 + (c - \'0\');\n            }\n            if ((!Character.isDigit(c) && c != \' \') || i == s.length() - 1) {\n                if (op == \'+\') {\n                    stack.push(num);\n                } else if (op == \'-\') {\n                    stack.push(-num);\n                } else if (op == \'*\') {\n                    stack.push(stack.pop() * num);\n                } else if (op == \'/\') {\n                    stack.push(stack.pop() / num);\n                }\n                op = c;\n                num = 0;\n            }\n        }\n        int res = 0;\n        while (!stack.isEmpty()) {\n            res += stack.pop();\n        }\n        System.out.println(res);\n    }\n}',NULL,1),
(167,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nrl.on(\'line\', (s) => {\n    const stack = [];\n    let num = 0;\n    let op = \'+\';\n    for (let i = 0; i < s.length; i++) {\n        const c = s[i];\n        if (c >= \'0\' && c <= \'9\') {\n            num = num * 10 + (c.charCodeAt(0) - \'0\'.charCodeAt(0));\n        }\n        if ((!(c >= \'0\' && c <= \'9\') && c !== \' \') || i === s.length - 1) {\n            if (op === \'+\') {\n                stack.push(num);\n            } else if (op === \'-\') {\n                stack.push(-num);\n            } else if (op === \'*\') {\n                stack.push(stack.pop() * num);\n            } else if (op === \'/\') {\n                stack.push(Math.trunc(stack.pop() / num));\n            }\n            op = c;\n            num = 0;\n        }\n    }\n    let res = 0;\n    while (stack.length > 0) {\n        res += stack.pop();\n    }\n    console.log(res);\n    rl.close();\n});',NULL,1),
(167,'PYTHON','s = input()\nstack = []\nnum = 0\nop = \'+\'\nfor i, c in enumerate(s):\n    if c.isdigit():\n        num = num * 10 + int(c)\n    if (not c.isdigit() and c != \' \') or i == len(s) - 1:\n        if op == \'+\':\n            stack.append(num)\n        elif op == \'-\':\n            stack.append(-num)\n        elif op == \'*\':\n            stack.append(stack.pop() * num)\n        elif op == \'/\':\n            stack.append(int(stack.pop() / num))\n        op = c\n        num = 0\nprint(sum(stack))',NULL,1),
(168,'C','#include <stdio.h>\n#include <stdlib.h>\n\nlong long countInversions(int arr[], int left, int right);\nlong long mergeAndCount(int arr[], int left, int mid, int right);\n\nint main(void) {\n    int n;\n    if (scanf(\"%d\", &n) != 1) return 0;\n    int *arr = (int *)malloc(sizeof(int) * n);\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &arr[i]);\n    }\n    printf(\"%lld\\n\", countInversions(arr, 0, n - 1));\n    free(arr);\n    return 0;\n}\n\nlong long countInversions(int arr[], int left, int right) {\n    if (left >= right) return 0;\n    int mid = left + (right - left) / 2;\n    long long count = 0;\n    count += countInversions(arr, left, mid);\n    count += countInversions(arr, mid + 1, right);\n    count += mergeAndCount(arr, left, mid, right);\n    return count;\n}\n\nlong long mergeAndCount(int arr[], int left, int mid, int right) {\n    int *temp = (int *)malloc(sizeof(int) * (right - left + 1));\n    int i = left, j = mid + 1, k = 0;\n    long long count = 0;\n    while (i <= mid && j <= right) {\n        if (arr[i] <= arr[j]) {\n            temp[k++] = arr[i++];\n        } else {\n            temp[k++] = arr[j++];\n            count += mid - i + 1;\n        }\n    }\n    while (i <= mid) temp[k++] = arr[i++];\n    while (j <= right) temp[k++] = arr[j++];\n    for (int t = 0; t < k; t++) {\n        arr[left + t] = temp[t];\n    }\n    free(temp);\n    return count;\n}',NULL,1),
(168,'CPP','#include <iostream>\n#include <vector>\nusing namespace std;\n\nlong long mergeAndCount(vector<int>& arr, int left, int mid, int right) {\n    vector<int> temp(right - left + 1);\n    int i = left, j = mid + 1, k = 0;\n    long long count = 0;\n    while (i <= mid && j <= right) {\n        if (arr[i] <= arr[j]) {\n            temp[k++] = arr[i++];\n        } else {\n            temp[k++] = arr[j++];\n            count += mid - i + 1;\n        }\n    }\n    while (i <= mid) temp[k++] = arr[i++];\n    while (j <= right) temp[k++] = arr[j++];\n    for (int p = 0; p < temp.size(); ++p) {\n        arr[left + p] = temp[p];\n    }\n    return count;\n}\n\nlong long countInversions(vector<int>& arr, int left, int right) {\n    if (left >= right) return 0;\n    int mid = left + (right - left) / 2;\n    long long count = 0;\n    count += countInversions(arr, left, mid);\n    count += countInversions(arr, mid + 1, right);\n    count += mergeAndCount(arr, left, mid, right);\n    return count;\n}\n\nint main() {\n    int n;\n    if (!(cin >> n)) return 0;\n    vector<int> arr(n);\n    for (int i = 0; i < n; ++i) {\n        cin >> arr[i];\n    }\n    cout << countInversions(arr, 0, n - 1) << endl;\n    return 0;\n}',NULL,1),
(168,'JAVA','import java.io.BufferedReader;\nimport java.io.IOException;\nimport java.io.InputStreamReader;\nimport java.util.StringTokenizer;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        String line = br.readLine();\n        if (line == null) return;\n        int n = Integer.parseInt(line.trim());\n        int[] arr = new int[n];\n        StringTokenizer st = new StringTokenizer(br.readLine());\n        for (int i = 0; i < n; i++) {\n            arr[i] = Integer.parseInt(st.nextToken());\n        }\n        System.out.println(countInversions(arr, 0, n - 1));\n    }\n\n    private static long countInversions(int[] arr, int left, int right) {\n        if (left >= right) return 0;\n        int mid = left + (right - left) / 2;\n        long count = 0;\n        count += countInversions(arr, left, mid);\n        count += countInversions(arr, mid + 1, right);\n        count += mergeAndCount(arr, left, mid, right);\n        return count;\n    }\n\n    private static long mergeAndCount(int[] arr, int left, int mid, int right) {\n        int[] temp = new int[right - left + 1];\n        int i = left, j = mid + 1, k = 0;\n        long count = 0;\n        while (i <= mid && j <= right) {\n            if (arr[i] <= arr[j]) {\n                temp[k++] = arr[i++];\n            } else {\n                temp[k++] = arr[j++];\n                count += mid - i + 1;\n            }\n        }\n        while (i <= mid) temp[k++] = arr[i++];\n        while (j <= right) temp[k++] = arr[j++];\n        System.arraycopy(temp, 0, arr, left, temp.length);\n        return count;\n    }\n}',NULL,1),
(168,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n    if (lines.length === 2) {\n        rl.close();\n    }\n});\n\nrl.on(\'close\', () => {\n    const n = parseInt(lines[0].trim());\n    const arr = lines[1].trim().split(/\\s+/).map(Number);\n    console.log(countInversions(arr, 0, n - 1));\n});\n\nfunction countInversions(arr, left, right) {\n    if (left >= right) return 0;\n    const mid = left + Math.floor((right - left) / 2);\n    let count = 0;\n    count += countInversions(arr, left, mid);\n    count += countInversions(arr, mid + 1, right);\n    count += mergeAndCount(arr, left, mid, right);\n    return count;\n}\n\nfunction mergeAndCount(arr, left, mid, right) {\n    const temp = new Array(right - left + 1);\n    let i = left, j = mid + 1, k = 0;\n    let count = 0;\n    while (i <= mid && j <= right) {\n        if (arr[i] <= arr[j]) {\n            temp[k++] = arr[i++];\n        } else {\n            temp[k++] = arr[j++];\n            count += mid - i + 1;\n        }\n    }\n    while (i <= mid) temp[k++] = arr[i++];\n    while (j <= right) temp[k++] = arr[j++];\n    for (let p = 0; p < temp.length; p++) {\n        arr[left + p] = temp[p];\n    }\n    return count;\n}',NULL,1),
(168,'PYTHON','import sys\n\ndef count_inversions(arr, left, right):\n    if left >= right:\n        return 0\n    mid = left + (right - left) // 2\n    count = 0\n    count += count_inversions(arr, left, mid)\n    count += count_inversions(arr, mid + 1, right)\n    count += merge_and_count(arr, left, mid, right)\n    return count\n\ndef merge_and_count(arr, left, mid, right):\n    temp = [0] * (right - left + 1)\n    i, j, k = left, mid + 1, 0\n    count = 0\n    while i <= mid and j <= right:\n        if arr[i] <= arr[j]:\n            temp[k] = arr[i]\n            i += 1\n        else:\n            temp[k] = arr[j]\n            j += 1\n            count += mid - i + 1\n        k += 1\n    while i <= mid:\n        temp[k] = arr[i]\n        i += 1\n        k += 1\n    while j <= right:\n        temp[k] = arr[j]\n        j += 1\n        k += 1\n    arr[left:right + 1] = temp\n    return count\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    arr = list(map(int, data[1:1 + n]))\n    print(count_inversions(arr, 0, n - 1))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(169,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint cmp(const void *a, const void *b) {\n    return (*(int *)a - *(int *)b);\n}\n\nint main() {\n    int n, k;\n    scanf(\"%d %d\", &n, &k);\n    int *arr = (int *)malloc(n * sizeof(int));\n    for (int i = 0; i < n; i++) {\n        scanf(\"%d\", &arr[i]);\n    }\n    qsort(arr, n, sizeof(int), cmp);\n    for (int i = 0; i < k; i++) {\n        if (i > 0) printf(\" \");\n        printf(\"%d\", arr[i]);\n    }\n    printf(\"\\n\");\n    free(arr);\n    return 0;\n}',NULL,1),
(169,'CPP','#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nint main() {\n    int n, k;\n    cin >> n >> k;\n    vector<int> arr(n);\n    for (int i = 0; i < n; i++) {\n        cin >> arr[i];\n    }\n    sort(arr.begin(), arr.end());\n    for (int i = 0; i < k; i++) {\n        if (i > 0) cout << \' \';\n        cout << arr[i];\n    }\n    cout << endl;\n    return 0;\n}',NULL,1),
(169,'JAVA','import java.util.*;\nimport java.io.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));\n        String[] first = br.readLine().trim().split(\"\\\\s+\");\n        int n = Integer.parseInt(first[0]);\n        int k = Integer.parseInt(first[1]);\n        int[] arr = new int[n];\n        String[] second = br.readLine().trim().split(\"\\\\s+\");\n        for (int i = 0; i < n; i++) {\n            arr[i] = Integer.parseInt(second[i]);\n        }\n        Arrays.sort(arr);\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < k; i++) {\n            if (i > 0) sb.append(\' \');\n            sb.append(arr[i]);\n        }\n        System.out.println(sb.toString());\n    }\n}',NULL,1),
(169,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line.trim());\n    if (lines.length === 2) {\n        const [n, k] = lines[0].split(/\\s+/).map(Number);\n        const arr = lines[1].split(/\\s+/).map(Number);\n        arr.sort((a, b) => a - b);\n        const result = arr.slice(0, k).join(\' \');\n        console.log(result);\n        rl.close();\n    }\n});',NULL,1),
(169,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    n = int(data[0])\n    k = int(data[1])\n    arr = list(map(int, data[2:2 + n]))\n    arr.sort()\n    print(\' \'.join(map(str, arr[:k])))\n\nif __name__ == \"__main__\":\n    main()',NULL,1),
(170,'C','#include <stdio.h>\n#include <stdlib.h>\n\nint dfs(int **grid, int m, int n, int i, int j) {\n    if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] == 0) {\n        return 0;\n    }\n    grid[i][j] = 0;\n    int area = 1;\n    area += dfs(grid, m, n, i + 1, j);\n    area += dfs(grid, m, n, i - 1, j);\n    area += dfs(grid, m, n, i, j + 1);\n    area += dfs(grid, m, n, i, j - 1);\n    return area;\n}\n\nint main(void) {\n    int m, n;\n    scanf(\"%d %d\", &m, &n);\n\n    int **grid = (int **)malloc(m * sizeof(int *));\n    for (int i = 0; i < m; i++) {\n        grid[i] = (int *)malloc(n * sizeof(int));\n    }\n\n    char *line = (char *)malloc((n + 2) * sizeof(char));\n    for (int i = 0; i < m; i++) {\n        scanf(\"%s\", line);\n        for (int j = 0; j < n; j++) {\n            grid[i][j] = line[j] - \'0\';\n        }\n    }\n\n    int maxArea = 0;\n    for (int i = 0; i < m; i++) {\n        for (int j = 0; j < n; j++) {\n            if (grid[i][j] == 1) {\n                int area = dfs(grid, m, n, i, j);\n                if (area > maxArea) {\n                    maxArea = area;\n                }\n            }\n        }\n    }\n\n    printf(\"%d\\n\", maxArea);\n\n    for (int i = 0; i < m; i++) {\n        free(grid[i]);\n    }\n    free(grid);\n    free(line);\n\n    return 0;\n}',NULL,1),
(170,'CPP','#include <iostream>\n#include <vector>\n#include <string>\n#include <algorithm>\n\nusing namespace std;\n\nint dfs(vector<vector<int>>& grid, int i, int j) {\n    int m = grid.size();\n    int n = grid[0].size();\n    if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] == 0) {\n        return 0;\n    }\n    grid[i][j] = 0;\n    int area = 1;\n    area += dfs(grid, i + 1, j);\n    area += dfs(grid, i - 1, j);\n    area += dfs(grid, i, j + 1);\n    area += dfs(grid, i, j - 1);\n    return area;\n}\n\nint main() {\n    int m, n;\n    cin >> m >> n;\n    cin.ignore();\n    vector<vector<int>> grid(m, vector<int>(n));\n    for (int i = 0; i < m; i++) {\n        string line;\n        getline(cin, line);\n        while (!line.empty() && (line.back() == \'\\r\' || line.back() == \'\\n\')) {\n            line.pop_back();\n        }\n        for (int j = 0; j < n; j++) {\n            grid[i][j] = line[j] - \'0\';\n        }\n    }\n\n    int maxArea = 0;\n    for (int i = 0; i < m; i++) {\n        for (int j = 0; j < n; j++) {\n            if (grid[i][j] == 1) {\n                maxArea = max(maxArea, dfs(grid, i, j));\n            }\n        }\n    }\n\n    cout << maxArea << endl;\n    return 0;\n}',NULL,1),
(170,'JAVA','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        int m = sc.nextInt();\n        int n = sc.nextInt();\n        sc.nextLine();\n        int[][] grid = new int[m][n];\n        for (int i = 0; i < m; i++) {\n            String line = sc.nextLine().trim();\n            for (int j = 0; j < n; j++) {\n                grid[i][j] = line.charAt(j) - \'0\';\n            }\n        }\n\n        int maxArea = 0;\n        for (int i = 0; i < m; i++) {\n            for (int j = 0; j < n; j++) {\n                if (grid[i][j] == 1) {\n                    maxArea = Math.max(maxArea, dfs(grid, i, j));\n                }\n            }\n        }\n\n        System.out.println(maxArea);\n    }\n\n    private static int dfs(int[][] grid, int i, int j) {\n        int m = grid.length;\n        int n = grid[0].length;\n        if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] == 0) {\n            return 0;\n        }\n        grid[i][j] = 0;\n        int area = 1;\n        area += dfs(grid, i + 1, j);\n        area += dfs(grid, i - 1, j);\n        area += dfs(grid, i, j + 1);\n        area += dfs(grid, i, j - 1);\n        return area;\n    }\n}',NULL,1),
(170,'JAVASCRIPT','const readline = require(\'readline\');\n\nconst rl = readline.createInterface({\n    input: process.stdin,\n    output: process.stdout\n});\n\nlet lines = [];\nrl.on(\'line\', (line) => {\n    lines.push(line);\n});\n\nrl.on(\'close\', () => {\n    const [m, n] = lines[0].trim().split(/\\s+/).map(Number);\n    const grid = [];\n    for (let i = 0; i < m; i++) {\n        const row = [];\n        const line = lines[i + 1].trim();\n        for (let j = 0; j < n; j++) {\n            row.push(line.charCodeAt(j) - 48);\n        }\n        grid.push(row);\n    }\n\n    let maxArea = 0;\n    for (let i = 0; i < m; i++) {\n        for (let j = 0; j < n; j++) {\n            if (grid[i][j] === 1) {\n                maxArea = Math.max(maxArea, dfs(grid, i, j));\n            }\n        }\n    }\n\n    console.log(maxArea);\n});\n\nfunction dfs(grid, i, j) {\n    const m = grid.length;\n    const n = grid[0].length;\n    if (i < 0 || i >= m || j < 0 || j >= n || grid[i][j] === 0) {\n        return 0;\n    }\n    grid[i][j] = 0;\n    let area = 1;\n    area += dfs(grid, i + 1, j);\n    area += dfs(grid, i - 1, j);\n    area += dfs(grid, i, j + 1);\n    area += dfs(grid, i, j - 1);\n    return area;\n}',NULL,1),
(170,'PYTHON','import sys\n\ndef main():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    m = int(data[0])\n    n = int(data[1])\n    grid = []\n    idx = 2\n    for i in range(m):\n        line = data[idx]\n        idx += 1\n        grid.append([int(c) for c in line])\n\n    def dfs(i, j):\n        if i < 0 or i >= m or j < 0 or j >= n or grid[i][j] == 0:\n            return 0\n        grid[i][j] = 0\n        area = 1\n        area += dfs(i + 1, j)\n        area += dfs(i - 1, j)\n        area += dfs(i, j + 1)\n        area += dfs(i, j - 1)\n        return area\n\n    max_area = 0\n    for i in range(m):\n        for j in range(n):\n            if grid[i][j] == 1:\n                max_area = max(max_area, dfs(i, j))\n\n    print(max_area)\n\nif __name__ == \"__main__\":\n    main()',NULL,1)
