-- =============================================
-- 题库整卷留档（题目编号已改为从 1 开始）
-- =============================================
-- 说明：
--   1. 这份是「当前数据库」的完整快照：分类 / 企业 / 题目 / 知识点关联 /
--      企业关联 / 多语言已验证答案。所有 INSERT 都带 ON DUPLICATE KEY UPDATE，
--      可以重复执行，不会破坏已有数据。
--   2. 题目 id 已重编号为 1~170（原来是从 206 开始），所有关联表同步平移，
--      所以下面这些 id 和旧文件（05/06/07/08/10/11）里的编号对不上——
--      以本文件为准。
--   3. 依赖 00-init.sql 建好的表结构。
-- =============================================

-- ---------- 分类（21）----------
ON DUPLICATE KEY UPDATE `name`=VALUES(`name`), `description`=VALUES(`description`), `sort_order`=VALUES(`sort_order`);

-- ---------- 企业（14）----------
ON DUPLICATE KEY UPDATE `name`=VALUES(`name`), `name_en`=VALUES(`name_en`), `description`=VALUES(`description`), `sort_order`=VALUES(`sort_order`), `status`=VALUES(`status`);

-- ---------- 题目（170）----------
ON DUPLICATE KEY UPDATE `title`=VALUES(`title`), `description`=VALUES(`description`), `input_description`=VALUES(`input_description`), `output_description`=VALUES(`output_description`), `sample_input`=VALUES(`sample_input`), `sample_output`=VALUES(`sample_output`), `difficulty`=VALUES(`difficulty`), `category_id`=VALUES(`category_id`), `template_code`=VALUES(`template_code`), `answer_code`=VALUES(`answer_code`), `solution`=VALUES(`solution`), `status`=VALUES(`status`);

-- ---------- 题目↔知识点（289）----------
ON DUPLICATE KEY UPDATE `problem_id`=VALUES(`problem_id`);

-- ---------- 题目↔企业（1315）----------
ON DUPLICATE KEY UPDATE `problem_id`=VALUES(`problem_id`);

-- ---------- 已验证答案（650）----------
ON DUPLICATE KEY UPDATE `code`=VALUES(`code`), `note`=VALUES(`note`), `verified`=VALUES(`verified`);

